INSERT INTO "mytable" ("conversation","result","id_conversation")
VALUES
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc váy này nhưng không thấy size S đâu cả. Có còn không vậy?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, size S vừa hết hàng hôm qua. Chị thông cảm nha, size M thì vẫn còn 3 cái."},{"speaker":"client","text":"Hơi tiếc quá, mình chỉ mặc vừa size S thôi. Chị có thể check size khác không? L hay XL ấy."},{"speaker":"salebot","text":"Dạ em vừa check rồi ạ, size L và XL cũng hết sạch từ sáng nay rồi chị ơi. Chị để lại số điện thoại không ạ? Em sẽ thông báo nếu có hàng trở lại."},{"speaker":"client","text":"Thôi được, mình để lại số 0987654321 nhé. Nhưng mà chắc chắn khi nào có size S em phải nhắn tin cho mình đấy!"},{"speaker":"salebot","text":"Dạ vâng ạ, em cảm ơn chị đã ủng hộ shop. Chúc chị ngày mới vui vẻ!"}]','fail',0),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Chúng em vừa nhập lô mới hôm nay, còn đầy đủ màu sắc: đen, xanh dương, cream. Anh/chị muốn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu đen, nhưng giá niêm yết 27 triệu hơi cao. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ em có thể hỗ trợ anh/chị ưu đãi 3% khi thanh toán qua ví MoMo, còn 26.190.000đ thôi ạ. Kèm quà tặng là bộ sạc nhanh chính hãng nữa."},{"speaker":"client","text":"Ok, mình chọn màu đen và thanh toán bằng MoMo. Giao hàng nội thành hôm nay được chứ?"},{"speaker":"salebot","text":"Dạ được ạ! Đơn hàng sẽ được xử lý trong 30 phút và giao tận nơi trước 20h tối nay. Anh/chị để lại số điện thoại và địa chỉ chi tiết giúp em nha."}]','successs',1),
('[{"speaker":"client","text":"Chào shop, mình thấy đôi giày thể thao Nike Air Max 90 đang khuyến mại 30% trên web. Còn size 42 không vậy?"},{"speaker":"salebot","text":"Dạ còn ạ! Size 42 vẫn còn 3 đôi. Bạn muốn mình giữ hàng hay thanh toán luôn ạ?"},{"speaker":"client","text":"Mình thấy giá 2.500k còn hơi cao, có thể giảm thêm không? 2.200k được không?"},{"speaker":"salebot","text":"Dạ không ạ, giá đã là ưu đãi nhất rồi ạ. Nếu bạn mua kèm tất thể thao, mình có thể tặng kèm 1 đôi."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',2),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn làm việc để bàn gỗ thông minh này. Nó có hỗ trợ điều chỉnh chiều cao không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Bàn có thể điều chỉnh từ 65cm đến 120cm, phù hợp cho cả làm việc và chơi game. Mình gửi link sản phẩm kèm video demo nhé?"},{"speaker":"client","text":"Ồ hay quá! Mình thấy giá niêm yết 5 triệu, có thể giảm cho mình không? Mình mua luôn nếu được 4,5 triệu."},{"speaker":"salebot","text":"Dạ em kiểm tra được ưu đãi hôm nay nè: giảm 10% cho đơn hàng đầu tiên, cộng thêm quà tặng là bàn chải vệ sinh. Còn 4,5 triệu là được ạ!"},{"speaker":"client","text":"Thế thì mình quyết định mua luôn! Bạn gửi link thanh toán qua momo đi nhé. Địa chỉ giao là 123 Lê Lợi, quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ cảm ơn chị! Đơn hàng #SH12345678 sẽ giao trong 2 giờ tới ạ. Chúc chị một ngày tốt lành!"}]','successs',3),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc đồng hồ Casio G-Shock GA-2100-1A, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào anh, đồng hồ Casio G-Shock GA-2100-1A hiện có giá 2.890.000đ, anh có muốn đặt không?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm được không? Mình thấy bên shop khác bán 2.6 triệu thôi."},{"speaker":"salebot","text":"Dạ anh thông cảm, đây là giá niêm yết từ hãng ạ. Nhưng nếu anh mua kèm dây da tặng kèm thì mình giảm còn 2.75 triệu được không ạ?"},{"speaker":"client","text":"Thế không được, mình không cần phụ kiện. Thôi thôi, cảm ơn bot nhé!"}]','fail',4),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác da này. Có size M không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size M vẫn còn 2 chiếc. Bạn thích màu đen hay nâu?"},{"speaker":"client","text":"Mình thích màu đen nhưng hơi lo lắm vì hay bị trầy xước. Bạn có bảo hành không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi bảo hành miễn phí 12 tháng cho lớp da. Giá niêm yết 2.999k, mình giảm còn 2.799k cho bạn nha!"},{"speaker":"client","text":"Ồ, giảm nhiều đấy! Mình lấy 1 chiếc. Ship tận nhà không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ có ạ! Ship nội thành 25k, giao trong 2 giờ. Bạn xác nhận địa chỉ gửi luôn nhé!"}]','successs',5),
('[{"speaker":"client","text":"Chào bot! Mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có giảm giá không thế?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại Oral-B Pro 3000 đang khuyến mại 30% còn 1.290.000đ thôi ạ. Bao gồm 2 đầu chải và hộp sạc."},{"speaker":"client","text":"1.29 tr hơi đắt nhỉ, có thể giảm thêm không? Mình thấy bên kia bán 1.1tr thôi."},{"speaker":"salebot","text":"Dạ em kiểm tra lại ạ, nếu bạn mua trong hôm nay thì em có thể giảm xuống 1.15tr, giao tận nhà miễn phí luôn ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Địa chỉ giao là 123 Đường Lê Lợi, Quận 1, TP.HCM nhé."},{"speaker":"salebot","text":"Dạ em ghi nhận đơn hàng rồi ạ! Cảm ơn bạn đã mua sắm cùng chúng tôi, chúc bạn một ngày tốt lành!"}]','successs',6),
('[{"speaker":"client","text":"Chào em, mình đang tìm mua chiếc áo khoác mùa đông này cho bé gái 5 tuổi. Size 100 có không em?"},{"speaker":"salebot","text":"Dạ chào chị! Size 100 cho bé gái 5 tuổi vẫn còn ạ. Áo có màu hồng nhạt và xanh dương, chị thích màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương. Giá bao nhiêu thế em?"},{"speaker":"salebot","text":"Dạ giá niêm yết 599k, nhưng hôm nay có khuyến mại giảm còn 499k chị nhé. Đi kèm là quà tặng mũ len nhỏ xinh."},{"speaker":"client","text":"Ồ, giảm nhiều thế. Thế mình đặt trước 1 cái rồi, giao trong tuần này được chứ?"},{"speaker":"salebot","text":"Dạ được chị! Chúng em sẽ giao trong 3 ngày làm việc. Chị cung cấp địa chỉ để em xác nhận ạ."}]','successs',7),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc bàn phím cơ cho công việc văn phòng. Bàn phím nào tốt và bền nhất tầm dưới 2 triệu vậy?"},{"speaker":"salebot","text":"Dạ, mình giới thiệu bạn chiếc Keychron K6 có giá 1.990.000đ, switch Blue siêu êm, bảo hành 12 tháng nhé!"},{"speaker":"client","text":"Mình thấy giá hơi cao so với ngân sách, có thể giảm không? Tầm 1.8 triệu được không?"},{"speaker":"salebot","text":"Dạ, mình có thể giảm xuống 1.850.000đ cho bạn, giao hàng miễn phí trong nội thành luôn ạ!"},{"speaker":"client","text":"Ok, mình chọn màu bạc nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM. Bao lâu nhận được hàng?"},{"speaker":"salebot","text":"Dạ, đơn hàng sẽ giao trong 2 giờ tới ạ! Cảm ơn bạn đã mua sắm cùng shop."}]','successs',8),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại đang khuyến mại 20% nếu mua trong hôm nay, giá gốc 2.490.000đ còn 1.992.000đ thôi."},{"speaker":"client","text":"Ồ, vậy có kèm pin sạc không? Mình thấy trên web ghi chưa rõ."},{"speaker":"salebot","text":"Dạ có kèm pin sạc đầy đủ ạ! Sản phẩm còn nguyên seal, bảo hành 24 tháng."},{"speaker":"client","text":"Thế giao hàng tận nơi miễn phí chứ? Mình ở quận 9."},{"speaker":"salebot","text":"Dạ không ạ, phí ship 30.000đ nếu đơn dưới 500.000đ. Nhưng nếu bạn mua kèm kem đánh răng trị giá 150.000đ thì free ship luôn."},{"speaker":"client","text":"Hmm, mình chỉ cần bàn chải thôi. Để mình suy nghĩ lại vậy, cảm ơn nhé!"}]','fail',9),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc áo khoác này cute quá! Màu xanh dương size M có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập 5 cái hôm qua. Bạn muốn mua không?"},{"speaker":"client","text":"Àh, mình đang cân nhắc. Giá bao nhiêu vậy? Có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 899k, nhưng bây giờ đang khuyến mại 10% cho sản phẩm mới. Còn 809k thôi ạ!"},{"speaker":"client","text":"Hơi mắc quá. Bạn giảm thêm được không? 700k đi nha!"},{"speaker":"salebot","text":"Dạ 700k hơi thấp so với giá sỉ ạ. Chúng mình có thể giảm còn 750k được không? Đi kèm là quà tặng 1 móc khóa mini nữa ạ!"},{"speaker":"client","text":"Thôi được, mình lấy. Nhưng giao trong 2 ngày được không? Mình cần gấp."},{"speaker":"salebot","text":"Dạ không ạ! Hiện tại mình chỉ giao trong ngày hoặc hôm sau thôi. Nếu bạn chịu chờ thì 2 ngày nữa sẽ có ạ."},{"speaker":"client","text":"Thôi thôi, mai mình qua lấy luôn. Cảm ơn bạn nha!"}]','fail',10),
('[{"speaker":"client","text":"Chào bạn ơi, mình thấy chiếc áo khoác denim này đẹp quá! Màu xanh navy có size L không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size L còn 2 chiếc, bạn muốn đặt luôn không? Đang có khuyến mại 10% cho sản phẩm mới."},{"speaker":"client","text":"Ồ, giá gốc bao nhiêu vậy? Mình thấy hơi đắt so với mình nghĩ."},{"speaker":"salebot","text":"Dạ giá gốc 990k, nhưng hôm nay giảm còn 890k thôi ạ. Nếu bạn mua kèm quần jeans nữa thì free ship luôn!"},{"speaker":"client","text":"Thế nếu mình chỉ lấy áo thôi thì ship bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ ship nội thành 30k, ngoại thành 50k ạ. Nhưng nếu bạn đặt trong 2h nữa thì giảm còn 20k thôi!"},{"speaker":"client","text":"Ok, thế mình lấy luôn áo này đi. Bạn gửi mình link thanh toán nhé!"},{"speaker":"salebot","text":"Dạ vâng ạ! Đây là link thanh toán: [link]. Cảm ơn bạn đã ủng hộ shop ạ! Chúc bạn 1 ngày tốt lành."}]','successs',11),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra. Mình thấy trên web giá 25 triệu, nhưng mình thấy nơi khác rẻ hơn 2 triệu. Bạn có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em xin lỗi vì giá trên web là niêm yết, nhưng nếu anh/chị mua ngay hôm nay, em có thể giảm cho 24 triệu 500k thôi ạ! Có kèm quà tặng là ốp lưng cao cấp luôn."},{"speaker":"client","text":"24 triệu 500k à? Được rồi, mình lấy luôn. Ship nhanh trong ngày được không?"},{"speaker":"salebot","text":"Dạ vâng ạ! Anh/chị ở quận nào để em check đơn vị vận chuyển ạ? Nếu trong nội thành sẽ giao trong 2-3 tiếng thôi."},{"speaker":"client","text":"Mình ở quận 10, TP.HCM. Cảm ơn bạn nhiều nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Anh/chị có thể thanh toán bằng tiền mặt hay chuyển khoản đều được ạ. Em sẽ gửi mã tracking qua Zalo ngay khi đơn hàng được xác nhận!"}]','successs',12),
('[{"speaker":"client","text":"Chào! Mình đang tìm mua bàn chải điện Oral-B Genius X, nhưng giá trên web có vẻ hơi cao so với mình nghĩ. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại Oral-B Genius X đang khuyến mại 10% cho đơn hàng đầu tiên, chị có thể nhập mã ''ORAL10'' để được giảm giá nhé!"},{"speaker":"client","text":"Thế giao hàng mất bao lâu vậy? Mình cần dùng sớm lắm rồi."},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày trong nội thành, chị có thể chọn thanh toán khi nhận hàng để tiện hơn."},{"speaker":"client","text":"Vậy thôi, mình không mua nữa. Cảm ơn nhé!"}]','fail',13),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc túi xách da thật của thương hiệu Coach. Bạn có size nhỏ không?"},{"speaker":"salebot","text":"Dạ có ạ! Size S còn 1 chiếc màu nâu, giá niêm yết 8.500.000đ. Bạn muốn mình giữ hàng không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình thấy bên kia bán 7.800.000đ đấy."},{"speaker":"salebot","text":"Dạ chúng em không được phép giảm giá ạ, nhưng nếu bạn mua kèm phụ kiện như dây đeo dự phòng thì tặng kèm khăn lau da miễn phí nè."},{"speaker":"client","text":"Thế à, mình suy nghĩ lại rồi. Cảm ơn nha!"}]','fail',14),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác này nhưng thấy giá hơi cao so với mình mong muốn. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chị đang xem mẫu áo khoác mùa đông chống nước hiệu The North Face đúng không ạ? Hiện tại shop đang có chương trình giảm 20% cho đơn hàng từ 2 triệu trở lên đó chị!"},{"speaker":"client","text":"À vậy à? Thế nếu mình mua 2 cái thì có được giảm thêm không?"},{"speaker":"salebot","text":"Dạ có chị ơi! Nếu chị mua 2 cái, shop sẽ giảm thêm 5% nữa cho chị. Như vậy tổng cộng là 25% luôn ạ. Giá gốc 3 triệu 5, giờ chỉ còn 2 triệu 625 chị nhé!"},{"speaker":"client","text":"Ồ tốt quá! Vậy mình chọn size M cho cả 2 cái nha. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được chị ạ! Ship nội thành trong 2-4 tiếng. Chị để lại địa chỉ chi tiết giúp shop nhé!"}]','successs',15),
('[{"speaker":"client","text":"Chào! Mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra trên web có khuyến mãi không vậy? Mình muốn mua nhưng chưa biết giá thế nào."},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại sản phẩm đang giảm 10% còn 25 triệu cho phiên bản 256GB, chị có muốn mình hỗ trợ thanh toán trả góp không ạ?"},{"speaker":"client","text":"25 triệu à? Mình thấy trên shopee còn rẻ hơn 1 triệu nữa đó. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ thưa chị, mình không thể giảm thêm nhưng nếu chị mua kèm ốp lưng chính hãng thì mình tặng luôn 1 triệu phí ship ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM. Bao lâu thì nhận được hàng?"},{"speaker":"salebot","text":"Dạ chị yên tâm, hàng giao trong 2 giờ nếu chị ở nội thành nhé! Em sẽ gửi link thanh toán qua zalo ạ."}]','successs',16),
('[{"speaker":"client","text":"Chào shop! Mình thấy chiếc điện thoại Samsung Galaxy S23 5G trên web có khuyến mãi gì không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại sản phẩm đang giảm 5% cho đơn hàng đầu tiên, kèm quà tặng là tai nghe không dây trị giá 1 triệu đồng ạ!"},{"speaker":"client","text":"Thế giá cuối cùng là bao nhiêu vậy? Mình thấy trên web ghi 25 triệu nhưng không biết đã giảm chưa?"},{"speaker":"salebot","text":"Dạ giá niêm yết 25 triệu, sau khi giảm 5% còn 23.75 triệu ạ. Bạn có muốn mình giữ hàng hay đặt ngay nhé?"},{"speaker":"client","text":"Ok, mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Phường Bến Thành, Quận 1, TP.HCM. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ trong 2 giờ sẽ giao đến tận nơi ạ! Bạn vui lòng thanh toán trước 50% để xác nhận đơn hàng nhé?"},{"speaker":"client","text":"Được thôi, mình chuyển khoản nha. Cảm ơn bạn nhiều!"}]','successs',17),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua chiếc bàn làm việc gỗ óc chó cho phòng ngủ. Có mẫu nào vừa tầm 5 triệu không?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu bàn gỗ óc chó 120x60cm đang khuyến mại 4.8 triệu, giao hàng tận nơi miễn phí trong 3 ngày."},{"speaker":"client","text":"Ồ, thế có thể giảm thêm chút không? Mình thấy quảng cáo có ưu đãi 500k nữa mà."},{"speaker":"salebot","text":"Dạ 5 triệu là giá tốt nhất rồi ạ, nhưng nếu bạn đặt ngay hôm nay thì mình hỗ trợ thêm 150k voucher cho đơn hàng tiếp theo nhé!"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Bao giờ nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ đơn hàng sẽ giao trong 2 ngày ạ, mình gửi kèm hướng dẫn lắp ráp và bảo hành 1 năm cho bàn. Cảm ơn bạn đã mua sắm!"}]','successs',18),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác này nhưng thấy giá hơi cao so với mong đợi. Có thể giảm giá cho mình không?"},{"speaker":"salebot","text":"Dạ, sản phẩm này là hàng mới về ạ, chất liệu premium nên giá hơi cao. Nhưng shop có voucher 5% cho đơn hàng từ 1 triệu trở lên, bạn có muốn sử dụng không?"},{"speaker":"client","text":"5% thôi à? Mình thấy bên shop kia có giảm 10% cho sản phẩm tương tự. Không biết shop có thể cạnh tranh hơn không?"},{"speaker":"salebot","text":"Dạ, mình xin lỗi vì không thể giảm thêm ạ. Nhưng sản phẩm này có bảo hành 2 năm và đổi trả trong 14 ngày, đảm bảo chất lượng hơn hẳn shop kia."},{"speaker":"client","text":"Thế à... ừm, mình suy nghĩ thêm vậy. Cảm ơn bạn nhé!"}]','fail',19),
