('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một đôi giày thể thao cho bé gái 10 tuổi, size 30-31. Bạn có loại nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào chị! Chúng tôi có dòng giày thể thao cho bé gái size 30-31 của thương hiệu ABC, giá niêm yết 799.000đ. Màu sắc chị thích thì chị có thể chọn: hồng, xanh dương hoặc đen."},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm giá cho mình không? Mình mua 2 đôi cùng lúc ấy."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá đã được niêm yết theo chính sách của hãng. Nhưng chị mua 2 đôi, mình có thể tặng kèm 1 đôi tất thể thao cho bé nhé!"},{"speaker":"client","text":"Thế thôi, mình lấy 2 đôi hồng size 30 đi. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ chị chọn size 30 cho cả 2 đôi ạ? Giao trong 2-3 ngày làm việc chị nhé! Chị có thể thanh toán qua chuyển khoản hoặc COD đều được."},{"speaker":"client","text":"Cảm ơn nhé, mình sẽ suy nghĩ thêm. Tạm biệt!"},{"speaker":"salebot","text":"Dạ chào chị ạ, chúc chị ngày tốt lành!"}]','fail',35),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn phím cơ Keychron K8 trên web có giá 1.799.000đ, bây giờ có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện tại sản phẩm đang khuyến mại 10% nên giá chỉ còn 1.619.100đ thôi ạ."},{"speaker":"client","text":"Mà mình thấy chỗ khác bán 1.550.000đ kìa, sao của bạn đắt thế?"},{"speaker":"salebot","text":"Dạ mình xin lỗi vì giá không cạnh tranh được ạ. Tuy nhiên sản phẩm của mình có bảo hành chính hãng 2 năm và giao hàng tận nơi miễn phí ạ."},{"speaker":"client","text":"Ừm, thế giao hàng trong bao lâu vậy?"},{"speaker":"salebot","text":"Dạ trong thành phố thì 1-2 ngày, tỉnh xa 3-5 ngày ạ. Bạn có muốn mình hỗ trợ đặt hàng luôn không ạ?"},{"speaker":"client","text":"Thôi, mình nghĩ để cân nhắc thêm vậy. Cảm ơn nhé!"}]','fail',36),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua một chiếc điện thoại thông minh tầm 10 triệu thôi. Có loại nào tốt không?"},{"speaker":"salebot","text":"Dạ có ạ! Samsung Galaxy A34 5G đang giảm giá còn 9,9 triệu, cấu hình khỏe lắm ạ: chip Dimensity 1080, màn hình AMOLED 120Hz, pin 5000mAh. Bạn thấy sao?"},{"speaker":"client","text":"Màn hình 120Hz nghe được nhưng mình thích iPhone hơn. Có iPhone cũ tầm 10 triệu không?"},{"speaker":"salebot","text":"Dạ có ạ! iPhone 11 64GB chỉ 9,5 triệu, còn nguyên hộp, pin khỏe lắm. Trả góp 0% nếu bạn muốn ạ!"},{"speaker":"client","text":"Ok, mình lấy iPhone 11 đi. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao ngay trong ngày nếu bạn ở Hà Nội ạ! Hoặc ngày mai cho toàn quốc. Bạn chọn hình thức thanh toán nào ạ?"},{"speaker":"client","text":"Mình thanh toán online luôn nhé. Cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn một ngày vui vẻ. Đơn hàng #12345 sẽ được giao vào 14h hôm nay. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',37),
('[{"speaker":"client","text":"Chào! Mình thấy cái nồi chống dính Tefal có khuyến mãi không vậy? Mình muốn mua 1 cái size 24cm."},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang giảm 30% còn 1.2 triệu, giao hàng miễn phí trong 3 ngày."},{"speaker":"client","text":"Ồ giá hơi cao, mình thấy bên shopee bán 950k thôi, có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ không ạ, mức giá này đã là ưu đãi nhất rồi ạ. Nồi Tefal chính hãng 100%, bảo hành 2 năm."},{"speaker":"client","text":"Thôi được, mình cân nhắc đã. Cảm ơn nha!"}]','fail',38),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo khoác mùa đông. Giá khoảng 1 triệu rưỡi thôi nhé, có không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình đang có mẫu áo khoác dạ siêu nhẹ giá 1.6 triệu, ưu đãi 10% nếu thanh toán online. Bạn thấy sao?"},{"speaker":"client","text":"Hơi đắt quá, có giảm nữa không? 1.4 triệu được không?"},{"speaker":"salebot","text":"Dạ, mình có thể giảm xuống 1.5 triệu cho bạn, đây là giá tốt nhất rồi ạ. Màu nào bạn thích? Đen, nâu hay xanh?"},{"speaker":"client","text":"Ok, mình chọn màu đen vậy. Giao hàng miễn phí chứ?"},{"speaker":"salebot","text":"Dạ miễn phí giao trong nội thành ạ, bạn nhập địa chỉ để mình xác nhận nhé!"}]','successs',39),
('[{"speaker":"client","text":"Chào bạn! Mình thấy chiếc túi xách da này khá đẹp, nhưng giá 3 triệu hơi đắt nhỉ? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ em hiểu ạ! Đây là sản phẩm da thật nên giá hơi cao chút, nhưng chất lượng tốt lắm. Chúng em có coupon 10% nếu bạn mua trong hôm nay."},{"speaker":"client","text":"10% thôi à? Mình thấy shop khác có giảm 20% cho mẫu tương tự."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, nhưng đây là mức giảm tối đa rồi. Nếu bạn mua 2 sản phẩm trở lên, em có thể giảm thêm 5% nữa."},{"speaker":"client","text":"Vậy thôi, mình không mua nữa. Cảm ơn nhé!"}]','fail',40),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua bộ quần áo thể thao cho con gái 12 tuổi. Bạn có size 140 không?"},{"speaker":"salebot","text":"Dạ có ạ! Size 140 còn 3 chiếc. Màu sắc có xanh dương, hồng và tím. Bạn muốn chọn màu nào?"},{"speaker":"client","text":"Mình thích màu xanh dương. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ bộ này giá 499k, nhưng hôm nay sale còn 399k nếu bạn đặt trong 2 giờ nữa."},{"speaker":"client","text":"Ok, vậy mình lấy 1 bộ. Ship tận nhà luôn chứ?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn vui lòng để lại địa chỉ và số điện thoại để mình xử lý đơn hàng nhé."}]','successs',41),
('[{"speaker":"client","text":"Chào bạn, mình thấy mẫu áo khoác chống nước này đẹp quá! Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Áo khoác chống nước này đang khuyến mại 499k thôi chị nhé (giá gốc 799k)."},{"speaker":"client","text":"Ui, đắt quá! Có giảm nữa không? Mình thấy bên khác bán 450k thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, bên mình có voucher 5% cho chị nếu mua trong hôm nay nha. Như vậy là 474k, rẻ hơn nhiều rồi ạ!"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Bao ship thế nào?"},{"speaker":"salebot","text":"Dạ ship nội thành 25k, chị có thể nhận hàng trong 2h. Mình gửi mã giảm ship 10k nếu chị thanh toán online nha!"},{"speaker":"client","text":"Ok, mình chọn ship COD nhé. Cảm ơn bạn!"}]','successs',42),
