('[{"speaker":"client","text":"Chào shop, mình đang muốn mua chiếc áo khoác này nhưng thấy giá hơi cao so với dự định. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào bạn! Áo khoác này đang giảm 15% trong đợt khuyến mại tuần này, giá chỉ còn 1.299.000đ thôi ạ!"},{"speaker":"client","text":"Vậy mình lấy luôn nha! Nhưng giao hàng trong 2 ngày được không? Mình cần gấp."},{"speaker":"salebot","text":"Dạ ổn ạ! Chúng mình sẽ giao tận nơi trong 2 ngày, phí ship miễn phí cho đơn trên 500k. Bạn để lại địa chỉ cụ thể nhé!"}]','successs',50),
('[{"speaker":"client","text":"Chào! Mình muốn mua chiếc áo khoác da này, nhưng giá 2 triệu hơi đắt quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, ạ hiện không có chương trình khuyến mãi trực tiếp, nhưng nếu bạn mua kèm quần jeans bên shop thì được giảm 10% ạ."},{"speaker":"client","text":"Mình chỉ mua áo thôi, không mua kèm. Thế có thể giao hàng miễn phí không?"},{"speaker":"salebot","text":"Dạ, phí ship 30k ạ. Nếu bạn không muốn thì có thể chọn nhận hàng tại cửa hàng để tiết kiệm ạ."},{"speaker":"client","text":"Thôi được, mình chọn nhận tại cửa hàng vậy. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ. Hẹn gặp bạn tại shop!"}]','fail',51),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác phao cho mùa đông này. Bạn có size từ M tới XL không?"},{"speaker":"salebot","text":"Chào bạn! Dạ có đủ size M, L, XL ạ. Màu sắc có đen, xanh dương và đỏ. Bạn muốn chọn màu nào?"},{"speaker":"client","text":"Mình thích màu đen, nhưng giá có hơi cao so với dự định. Bạn có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ shop đang có chương trình khuyến mại 10% cho sản phẩm mùa đông ạ. Nếu bạn mua kèm 1 chiếc quần thể thao, mình sẽ giảm thêm 5% nữa nhé!"},{"speaker":"client","text":"Ok, vậy mình chọn size L. Bao nhiêu tiền tổng thế?"},{"speaker":"salebot","text":"Dạ tổng cộng 1.890.000đ cho áo khoác + quần thể thao ạ. Bạn có thể thanh toán COD hoặc chuyển khoản đều được ạ!"},{"speaker":"client","text":"Cảm ơn bạn, mình chuyển khoản nhé. Mình gửi địa chỉ ở phần bình luận nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn bạn đã mua sắm ạ! Chúc bạn một ngày tốt lành!"}]','successs',52),
('[{"speaker":"client","text":"Chào bạn, mình thấy nồi chống dính Tefal 32cm giá 1 triệu rưỡi, có khuyến mãi gì không vậy?"},{"speaker":"salebot","text":"Dạ em chào ạ, sản phẩm hiện đang giảm 20% còn 1 triệu 2 cho bạn nè, giao hàng miễn phí trong 24h."},{"speaker":"client","text":"Ồ vậy à, nhưng mình thấy bên shopee giá 1 triệu 1 thôi, có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ em thật tình xin lỗi ạ, giá web chúng em đã ưu đãi hết mức rồi ạ. Nếu bạn mua kèm lò vi sóng mini 300k thì được tặng nắp nồi luôn nè!"},{"speaker":"client","text":"Thế à, thôi mình để dành dịp sale khác vậy. Cảm ơn bạn nhé!"}]','fail',53),
('[{"speaker":"client","text":"Chào bot, mình muốn mua bộ quần áo thể thao cho bé gái 12 tuổi, size S. Có mẫu nào đẹp không?"},{"speaker":"salebot","text":"Dạ có ạ! Bé nhà mình thích màu gì? Mẫu này đang sale 30% nè: áo thun năng động + quần short phối màu xanh dương."},{"speaker":"client","text":"Màu xanh dương được đấy. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ combo 499k ạ (giá gốc 715k), giao tận nhà miễn phí nếu trên 500k."},{"speaker":"client","text":"Hơi đắt, có thể giảm thêm không? Mình thấy chỗ khác 450k thôi."},{"speaker":"salebot","text":"Dạ em check lại nha! Được 470k ạ, tặng luôn miếng lót vai cho bé nữa nè!"},{"speaker":"client","text":"Ok, mình chọn size S. Địa chỉ giao là 123 Lê Lợi, Quận 1."},{"speaker":"salebot","text":"Dạ cám ơn chị! Đơn hàng sẽ giao vào 14h hôm nay ạ. Chúc chị ngủ ngon!"}]','successs',54),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua bộ quần áo thể thao nữ của Nike. Size S thì còn không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Size S của bộ đồ thể thao Nike chị xem đang hết size rồi chị nhé. Chị có thể tham khảo bộ đồ khác không ạ?"},{"speaker":"client","text":"Hết rồi à? Chán thật! Mà giá bộ đó bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ bộ đồ chị định mua giá 1.290.000đ, chị ơi. Nếu chị mua bộ khác thì có thể giảm còn 1.150.000đ chị nhé."},{"speaker":"client","text":"1.150k à? Mình nghĩ đắt quá, có giảm thêm được không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, đây là giá sốc cuối rồi ạ. Chị có thể chọn màu khác hoặc chờ sale tháng sau cũng được ạ."},{"speaker":"client","text":"Thôi vậy, thôi vậy. Để mình suy nghĩ thêm nhé. Cảm ơn bot!"}]','fail',55),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một đôi giày thể thao nam, có size 42 không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại bên mình có mẫu Nike Air Max 270 size 42 vừa nhập về tuần trước, anh thích màu gì không?"},{"speaker":"client","text":"Mình thích màu xanh dương, nhưng giá bao nhiêu rồi nhỉ? Đắt quá thì mình không mua đâu."},{"speaker":"salebot","text":"Dạ giá niêm yết 2.590.000đ, nhưng hôm nay có ưu đãi giảm 10% cho khách hàng mới, còn 2.331.000đ thôi ạ!"},{"speaker":"client","text":"Hơi đắt so với mình, 2 triệu 1 được không? Mua luôn nếu được!"},{"speaker":"salebot","text":"Dạ anh thông cảm, 2 triệu 1 hơi thấp so với giá sàn, nhưng nếu anh mua luôn thì mình hỗ trợ ship miễn phí trong nội thành luôn nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Cho mình địa chỉ ship là 123 Lê Lợi, Q.1 nhé."},{"speaker":"salebot","text":"Dạ cảm ơn anh! Đơn hàng sẽ được xử lý trong 30 phút, anh kiểm tra điện thoại để nhận mã OTP thanh toán nhé."}]','successs',56),
('[{"speaker":"client","text":"Chào bạn! Mình thấy chiếc đồng hồ Casio Edifice EFR-S567D-1A2VN khá đẹp, nhưng giá trên web là 3.800.000đ hơi cao so với dự định. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ em xin lỗi vì giá trên web chưa cập nhật khuyến mãi nhé! Hiện tại sản phẩm đang giảm còn 3.400.000đ thôi ạ, giao hàng miễn phí trong hôm nay nếu bạn đặt ngay."},{"speaker":"client","text":"Thế à, thế mình đặt tạm 1 cái vậy. Nhưng mình muốn đổi màu đen thay vì bạc được không?"},{"speaker":"salebot","text":"Dạ sản phẩm màu đen (EFR-S567D-1A7VN) cũng đang có sẵn ạ, giá tương tự luôn. Em sẽ thêm vào đơn hàng nhé?"},{"speaker":"client","text":"Ok, mình chọn luôn. Cảm ơn bạn nhé!"}]','successs',57),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện sản phẩm đang có chương trình giảm 15% cho đơn hàng đầu tiên trong tuần này đó ạ. Nếu chị đặt luôn bây giờ sẽ còn 1.299.000đ thôi!"},{"speaker":"client","text":"Ồ, vậy có tặng kèm gì không? Mình nghe nói bàn chải này đi kèm đầu bàn chải dự phòng phải không?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Mỗi bộ gồm 2 đầu bàn chải dự phòng + hộp đựng di động tặng kèm luôn chị nhé. Còn chần chừ gì nữa, lượng hàng có hạn đó!"},{"speaker":"client","text":"Thế giao hàng trong bao lâu vậy? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Dạ giao nội thành Hà Nội trong 2-4 giờ, ngoại thành 1 ngày thôi chị ơi! Em sẽ ưu tiên gửi đơn sớm nhất có thể ạ."},{"speaker":"client","text":"Ok, vậy mình đặt luôn nhé. Bao gồm cả phí ship luôn chứ?"},{"speaker":"salebot","text":"Dạ đúng rồi chị! Đơn hàng của chị đã được ghi nhận, em gửi link thanh toán qua Zalo cho chị nhé. Cảm ơn chị đã mua sắm cùng chúng em!"}]','successs',58),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Size M có không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập 100 chiếc size M tuần trước. Bạn muốn màu gì?"},{"speaker":"client","text":"Màu xanh navy nhé. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 1.299.000đ ạ, đang giảm 20% từ 1.599.000đ. Có thể giao trong 2 ngày."},{"speaker":"client","text":"Hơi đắt, có thể giảm nữa không? Mình thấy bên kia bán 1.100.000đ."},{"speaker":"salebot","text":"Dạ chúng mình miễn phí ship toàn quốc ạ, bên kia có thể tính phí ship cao hơn. Còn 1.200.000đ được không?"},{"speaker":"client","text":"Thôi vậy, mình lấy 1 cái. Địa chỉ giao là 123 Lê Lợi, Phường 1, Quận 3."},{"speaker":"salebot","text":"Dạ cám ơn bạn! Đơn hàng sẽ được giao vào ngày mai ạ. Chúc bạn vui vẻ!"}]','fail',59),
('[{"speaker":"client","text":"Chào! Mình thấy cái bàn học gỗ sồi này đẹp quá, nhưng giá 3 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ, đây là sản phẩm cao cấp 100% gỗ sồi nhập khẩu, giá niêm yết là 3,2 triệu nhưng hôm nay ưu đãi giảm còn 2,8 triệu thôi ạ!"},{"speaker":"client","text":"2,8 triệu vẫn hơi cao, mình thấy trên shopee có vài chỗ bán 2,5 triệu thôi. Bạn giảm được nữa không?"},{"speaker":"salebot","text":"Dạ, 2,5 triệu thì hơi khó chị ơi. Chị mua kèm ghế văn phòng giảm thêm 100k, mình deal 2,7 triệu nhé?"},{"speaker":"client","text":"2,7 triệu vậy thôi, nhưng phải giao hàng tận nơi miễn phí đấy nhé. Nếu không thì thôi!"},{"speaker":"salebot","text":"Dạ, 2,7 triệu giao tận nơi miễn phí ạ! Chị để lại số điện thoại và địa chỉ nhé, mình xác nhận đơn ngay!"}]','fail',60),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ chăn ga gối đệm cho phòng ngủ mới. Bạn tư vấn giúp mình với ạ!"},{"speaker":"salebot","text":"Dạ chào chị ạ! Em thấy chị có thể tham khảo bộ chăn ga gối đệm cotton 100% siêu mềm, thoáng khí, giá 1.200.000đ. Chị muốn màu gì ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương nhạt. Có giảm giá gì không ạ?"},{"speaker":"salebot","text":"Dạ có chị ơi! Nếu chị mua trọn bộ hôm nay thì giảm còn 1.100.000đ thôi ạ. Kèm theo quà tặng là gối nhỏ trị giá 150.000đ."},{"speaker":"client","text":"Ok, mình lấy trọn bộ luôn. Giao hàng trong ngày được không?"},{"speaker":"salebot","text":"Dạ được chị ạ! Em sẽ gửi đơn hàng ngay bây giờ. Chị vui lòng cung cấp địa chỉ và số điện thoại để em xác nhận ạ."}]','successs',61),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác này nhưng thấy giá hơi cao quá. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn, sản phẩm này đang khuyến mại 10% cho đơn hàng đầu tiên đó ạ. Nếu bạn mua 2 cái trở lên sẽ giảm thêm 5% nữa!"},{"speaker":"client","text":"Thế 15% thì mình mới cân nhắc. Đơn hàng mình chỉ có 1 cái thôi, không sao chứ?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, chính sách chỉ áp dụng từ 2 sản phẩm trở lên. Bạn có thể ghép thêm 1 sản phẩm khác 500k để được giảm giá không?"},{"speaker":"client","text":"Không được đâu, mình chỉ cần chiếc áo này thôi. Thôi thì thôi, cảm ơn shop nhé!"}]','fail',62),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái nồi chống dính Kangaroo 28cm có giá 890k, bây giờ có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện tại sản phẩm đang có chương trình khuyến mại 10% nếu mua kèm dụng cụ nấu nướng, bạn có quan tâm không?"},{"speaker":"client","text":"Mình chỉ mua cái nồi thôi, không mua kèm gì cả. Giảm giá trực tiếp được không?"},{"speaker":"salebot","text":"Dạ không ạ, chương trình khuyến mại chỉ áp dụng khi mua kèm thôi. Bạn có thể theo dõi trang web để nhận thông báo giảm giá khác nhé!"},{"speaker":"client","text":"Thôi được, dù sao cũng 890k hơi đắt. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ, chúc bạn một ngày tốt lành!"}]','fail',63),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến bàn chải điện Oral-B Genius X. Có chương trình khuyến mại gì không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hôm nay giảm 20% cho sản phẩm này, kèm quà tặng là 2 đầu bàn chải thay thế. Bạn muốn mua không?"},{"speaker":"client","text":"Mình thấy giá vẫn hơi cao, có thể giảm thêm được không? Mình thấy bên kia bán rẻ hơn 50k."},{"speaker":"salebot","text":"Dạ, nếu bạn mua ngay hôm nay thì mình có thể giảm thêm 10% nữa thành 2.199.000đ cho bạn. Bao gồm quà tặng luôn nha!"},{"speaker":"client","text":"Ok, mình đồng ý. Bạn gửi link thanh toán qua Zalo cho mình nhé."},{"speaker":"salebot","text":"Dạ vâng ạ! Link thanh toán đã gửi vào Zalo của bạn. Cảm ơn bạn đã mua hàng, chúc bạn sức khỏe!"}]','successs',64),
('[{"speaker":"client","text":"Chào shop, mình muốn mua điện thoại Samsung Galaxy S23 Ultra 5G. Bạn có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Máy còn mới 100%, giao tận nơi trong 2 giờ. Bạn cần màu nào? Đen hay xanh?"},{"speaker":"client","text":"Mình thích màu xanh. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ giá niêm yết 28.990.000đ, nhưng hôm nay có giảm 10% cho khách online đầu tiên, còn 26.091.000đ thôi ạ!"},{"speaker":"client","text":"Đắt quá nhỉ, mình thấy chỗ khác giá 25 triệu?"},{"speaker":"salebot","text":"Dạ chỗ kia chắc là hàng cũ hoặc không chính hãng ạ. Máy mình đảm bảo hàng mới nguyên seal, bảo hành 2 năm. Nếu bạn mua bây giờ, mình tặng luôn ốp lưng cao cấp nữa!"},{"speaker":"client","text":"Thôi được, mình lấy. Địa chỉ giao là 123 Lê Lợi, phường Bến Nghé, quận 1. Bao lâu nhận được?"},{"speaker":"salebot","text":"Dạ trong 2 giờ nữa là tới nơi ạ! Bạn vui lòng thanh toán online hoặc COD đều được. Cảm ơn bạn đã mua hàng!"}]','successs',65),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc đồng hồ Casio Edifice EFR-S567D-1A2V. Bao nhiêu tiền vậy?"},{"speaker":"salebot","text":"Dạ chào anh, chiếc này niêm yết 4.200.000đ ạ. Hiện shop đang có khuyến mại 10% cho đơn hàng đầu tiên."},{"speaker":"client","text":"Ơ, sao giá cao thế? Mấy shop khác bán có 3.800.000đ thôi mà."},{"speaker":"salebot","text":"Dạ anh thông cảm ạ, sản phẩm chính hãng từ Nhật, bảo hành 5 năm 100% ạ. Nếu anh mua combo pin dự phòng thì giảm thêm 50k nha."},{"speaker":"client","text":"Thế giao hàng ngoài giờ hành chính có được không? Mình bận lắm."},{"speaker":"salebot","text":"Dạ không ạ, shipper chỉ làm giờ hành chính thôi. Còn nếu anh nhận hàng tại shop thì khỏi phí vận chuyển luôn."},{"speaker":"client","text":"Ôi, thế thôi. Mình không tiện đi shop đâu. Thôi thôi, thôi nhé."}]','fail',66),
('[{"speaker":"client","text":"Chào bạn, mình đang muốn mua chiếc bàn ủi hơi nước Philips GC9680/80. Giá trên web có 4.5 triệu, có thể giảm được không ạ?"},{"speaker":"salebot","text":"Dạ chào bạn! Chúng tôi có chương trình khuyến mại hôm nay, bàn ủi giảm còn 4.2 triệu thôi ạ. Bạn có muốn mình hỗ trợ đặt hàng luôn không?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Ship trong ngày được không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Bạn để lại số điện thoại để mình gửi mã giảm giá 10% cho lần mua sau nhé. Cảm ơn bạn đã mua hàng!"}]','successs',67),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua nồi cơm điện Tefal 10L cho gia đình đông người. Có loại nào tốt không?"},{"speaker":"salebot","text":"Dạ có ạ! Tefal FZ701030 là mẫu phổ biến nhất, dung tích 10L, nấu được 20 bát cơm. Giá niêm yết 2.990.000đ, em có thể giảm xuống 2.750.000đ nếu mua kèm nắp thủy tinh tặng."},{"speaker":"client","text":"Mình thấy giá hơi cao, có thể giảm thêm không? Mình thấy bên đối thủ bán 2.600.000đ thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi, mức giảm này đã là ưu đãi cuối rồi ạ. Nếu anh chị mua kèm 2 nắp thủy tinh nữa thì em có thể giảm xuống 2.650.000đ thôi ạ."},{"speaker":"client","text":"Thế không được thì thôi, mình xem tầm giá 2.500.000đ trở xuống thôi. Cảm ơn nhé!"}]','fail',68),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái bàn chải điện Oral-B Pro 3000 trên web có khuyến mãi gì không? Mình đang muốn mua cho mẹ dùng."},{"speaker":"salebot","text":"Dạ chào chị! Hiện sản phẩm đang giảm 10% còn 1.890.000đ, giao hàng tận nơi trong 2 ngày ạ."},{"speaker":"client","text":"Ủa, em ơi, 1.890.000 vẫn hơi đắt so với túi tiền mình. Có thể giảm thêm nữa không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, đây là mức giá sốc nhất rồi ạ. Nếu chị mua kèm kem đánh răng Oral-B thì mình có thể tặng thêm 1 tuýp nhé?"},{"speaker":"client","text":"Thôi em ơi, cảm ơn nha. Mình sẽ suy nghĩ thêm rồi quay lại sau."}]','fail',69),
('[{"speaker":"client","text":"Chào! Mình thấy cái điện thoại Samsung Galaxy S24 Ultra 5G trên web, mình muốn hỏi giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Chiếc S24 Ultra 5G hiện đang giảm giá còn 32 triệu 500 nghìn, giao hàng trong 2 giờ nếu bạn ở TPHCM ạ."},{"speaker":"client","text":"Ồ, đắt quá! Có thể giảm xuống 30 triệu không? Mình thấy ở chỗ khác giá thấp hơn."},{"speaker":"salebot","text":"Dạ không ạ, đây là giá sốc cuối tuần rồi ạ. Nhưng nếu bạn mua kèm ốp lưng và màn hình cường lực, mình có thể tặng bạn 1 triệu giảm giá!"},{"speaker":"client","text":"Thế à... Mình nghĩ mình sẽ suy nghĩ lại đã. Cảm ơn nhé!"}]','fail',70),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc điện thoại Samsung Galaxy S24 Ultra 5G, có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Hiện tại sản phẩm đang có chương trình khuyến mại ưu đãi 10% cho đơn hàng đầu tiên trong tháng này ạ."},{"speaker":"client","text":"Vậy giá cuối cùng là bao nhiêu? Mình thấy trên mạng giá chênh lệch nhiều quá."},{"speaker":"salebot","text":"Dạ giá niêm yết 32.990.000đ, sau khi giảm còn 29.691.000đ thôi ạ. Đi kèm còn tặng ốp lưng chính hãng nữa!"},{"speaker":"client","text":"Ok, mình lấy luôn. Đóng gói cẩn thận nhé, mình sợ trầy xước."},{"speaker":"salebot","text":"Dạ yên tâm ạ! Shop cam kết giao hàng nguyên seal, bọc chống sốc kỹ càng. Anh/chị để lại địa chỉ và số điện thoại để mình xử lý đơn hàng nhé!"}]','successs',71),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn làm việc này đẹp quá! Mình muốn mua nhưng chưa rõ chất liệu gỗ thế nào?"},{"speaker":"salebot","text":"Dạ, bàn này làm từ gỗ thông cao cấp, chống ẩm tốt lắm ạ! Bạn có thể yên tâm sử dụng lâu dài."},{"speaker":"client","text":"Vậy giá bao nhiêu vậy? Mình thấy hơi đắt so với dự tính."},{"speaker":"salebot","text":"Dạ, giá niêm yết là 3.500.000đ, nhưng hôm nay có khuyến mại giảm còn 3.000.000đ thôi ạ! Kèm quà tặng là ghế massage mini."},{"speaker":"client","text":"Ừm, vậy mình lấy luôn nhé! Ship tận nhà không? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ có ạ! Ship nội thành miễn phí nếu đơn trên 2 triệu, còn quý khách chỉ mất 20.000đ thôi. Đơn sẽ giao trong 2-3 ngày."}]','successs',72),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác da này. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc áo da này hiện có giá 2.500.000đ, chị có thể chọn màu đen hoặc nâu."},{"speaker":"client","text":"Ôi đắt quá, có giảm giá không? Chị thấy trên mạng rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, đây là giá niêm yết từ nhà sản xuất. Nhưng nếu chị mua kèm mũ bảo hiểm thì giảm 5% nhé!"},{"speaker":"client","text":"Thế à, nhưng mình chỉ cần áo thôi. Thôi vậy, để mình suy nghĩ lại rồi quay lại sau vậy."}]','fail',73),
('[{"speaker":"client","text":"Chào bot, mình đang cần mua một chiếc bàn làm việc gỗ tự nhiên. Bên mình có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi có bàn gỗ óc chó 120x60cm giá 3.500.000đ, giao trong 3-5 ngày."},{"speaker":"client","text":"Đắt quá, em có thể giảm không? 3 triệu được không?"},{"speaker":"salebot","text":"Dạ 3 triệu thì hơi khó ạ, tối đa 3.200.000đ được không? Chất lượng gỗ nguyên khối luôn."},{"speaker":"client","text":"3.100.000đ thôi, mình lấy luôn nếu được. Không thì thôi."},{"speaker":"salebot","text":"Dạ không được ạ, 3.200.000đ là giá cuối rồi ạ. Để em báo lại sếp nhé?"},{"speaker":"client","text":"Thôi, lần sau vậy. Cảm ơn!"}]','fail',74),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc váy đầm công sở này nhưng nhìn hơi mỏng, có thể gửi mẫu vải đến tận nhà để mình kiểm tra không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn để lại thông tin địa chỉ, em sẽ sắp xếp ship mẫu vải miễn phí trong 1-2 ngày tới. Chất liệu vải là cotton thoáng mát, phù hợp văn phòng nha!"},{"speaker":"client","text":"Ừm, vậy giá chiếc váy này bao nhiêu? Có giảm giá cho khách mới không?"},{"speaker":"salebot","text":"Dạ 990k ạ, nhưng hôm nay có giảm 10% cho khách mới, còn 891k thôi! Nếu bạn mua kèm giày cao gót bên shop, giảm thêm 50k nữa."},{"speaker":"client","text":"Ok, mình lấy váy thôi. Địa chỉ mình là 123 Phố Chùa Láng, giao vào chiều mai được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em xác nhận đơn hàng rồi, cảm ơn bạn đã mua sắm cùng shop! Chúc bạn một ngày vui vẻ."}]','successs',75),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn phím cơ Keychron K8 có giá 2.500.000đ, hơi đắt so với mình. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ, hôm nay có chương trình khuyến mại 5% cho đơn hàng đầu tiên ạ. Nếu bạn mua thêm mousepad thì được thêm 3% nữa."},{"speaker":"client","text":"Mình chỉ mua bàn phím thôi. Được 2.375.000đ thôi à? Còn giảm nữa không?"},{"speaker":"salebot","text":"Dạ, mình xin lỗi ạ, mức giá đã là ưu đãi nhất rồi. Bạn có thể chọn trả góp 0% để tiện hơn không?"},{"speaker":"client","text":"Thôi vậy, cảm ơn nhé. Mình sẽ suy nghĩ thêm."}]','fail',76),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác thể thao này nhưng nhìn hơi rộng, có size nhỏ hơn không?"},{"speaker":"salebot","text":"Dạ có ạ! Size S và M đều còn, mình gửi link size chart để bạn tham khảo nhé. Bạn thích màu nào?"},{"speaker":"client","text":"Màu xanh dương ấy. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 1.290.000đ, đang khuyến mại 10% còn 1.161.000đ thôi ạ. Giao hàng miễn phí trên 500k."},{"speaker":"client","text":"Vậy mình lấy size S nhé. Thanh toán online được chứ?"},{"speaker":"salebot","text":"Dạ được ạ! Mình gửi link thanh toán qua ZaloPay ngay đây. Cảm ơn bạn đã mua hàng!"}]','successs',77),
('[{"speaker":"client","text":"Chào shop, mình muốn mua điện thoại Samsung Galaxy A54 5G. Bạn có giảm giá không vậy? Mình thấy trên mạng nhiều chỗ bán rẻ hơn."},{"speaker":"salebot","text":"Chào bạn ạ! Dạ Galaxy A54 5G của shop đang có khuyến mại 10% cho đơn từ 2 triệu trở lên ạ. Nếu bạn lấy luôn hôm nay mình còn tặng ốp lưng miễn phí nữa!"},{"speaker":"client","text":"10% thôi à? Mình thấy nơi khác giảm 15% luôn ấy. À mà mình ở xa quá, giao hàng tận nơi có mất phí không?"},{"speaker":"salebot","text":"Dạ phí ship ngoài khu vực là 30k ạ. Nhưng nếu bạn lấy luôn hôm nay mình có thể giảm thêm 5% cho bạn nhé! Còn 15% là khuyến mại cuối tuần thôi ạ."},{"speaker":"client","text":"Thế 15% + ship miễn phí luôn đi. Mình không lấy hôm nay thì thôi."},{"speaker":"salebot","text":"Dạ thật tiếc ạ, shop không thể giảm thêm được nữa ạ. Cảm ơn bạn đã quan tâm ạ!"}]','fail',78),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác da của hãng này, có size L không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Size L vẫn còn 2 cái. Màu đen và nâu thưa chị."},{"speaker":"client","text":"Mình thích màu đen nhưng giá hơi đắt, có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ hôm nay có chương trình khuyến mại 10% cho khách hàng mới. Nếu chị đặt ngay thì còn 1.299.000đ thôi ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ cảm ơn chị! Đơn hàng sẽ giao trong 2h tới ạ. Chúc chị vui vẻ!"}]','successs',79),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000. Mấy giờ giao hàng được ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc này còn hàng rồi, giao trong 2-3 ngày ạ. Nếu chị ở TP.HCM thì giao nhanh hơn nha."},{"speaker":"client","text":"Ồ vậy à, mình thấy trên web có ghi giảm giá 20% nhưng giờ mình vào lại không thấy nữa. Mình mua giờ có được giảm không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, chương trình giảm giá vừa hết. Nhưng nếu chị mua combo 2 sản phẩm Oral-B thì được tặng 1 đầu bàn chải thay thế ạ!"},{"speaker":"client","text":"Thế combo ấy giá bao nhiêu vậy? Mình chỉ cần cái bàn chải thôi, không mua combo đâu."},{"speaker":"salebot","text":"Dạ combo 2 sản phẩm tặng kèm chỉ 1.299.000đ chị ạ, rẻ hơn mua lẻ 200k. Chị cân nhắc nha!"},{"speaker":"client","text":"Thôi không mua nữa, mình thấy giá trên web không rõ ràng. Bye nhé!"}]','fail',80),
('[{"speaker":"client","text":"Chào! Mình muốn mua chiếc áo khoác này, nhưng nhìn ảnh màu hơi khác so với thực tế vậy?"},{"speaker":"salebot","text":"Dạ mình xin lỗi vì hình ảnh chưa chuẩn ạ! Áo khoác này có màu xanh navy, rất hợp với các set đồ tối giản. Bạn có thể đổi màu khác trong cùng bộ sưu tập nếu muốn ạ."},{"speaker":"client","text":"À vậy à, giá bao nhiêu vậy? Mình thấy hơi đắt so với shop khác."},{"speaker":"salebot","text":"Dạ 1.299.000đ ạ, nhưng hiện có mã giảm 10% cho đơn đầu tiên và phí ship miễn phí trên 800k. Nếu bạn lấy thêm quần thì còn ưu đãi hơn ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn áo này + quần jeans đi. Ship trong 2 ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Đơn hàng sẽ giao vào ngày mai nếu bạn ở HN, mình gửi link thanh toán qua ZaloPay cho tiện ạ. Cảm ơn bạn đã ủng hộ!"}]','successs',81),
('[{"speaker":"client","text":"Chào shop, mình thấy chiếc bàn chải điện Oral-B Pro 3000 đang giảm giá 30%. Còn hàng không?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại sản phẩm còn 5 sản phẩm cuối, nhưng giá gốc 2.590.000đ, khuyến mại chỉ còn 1.790.000đ thôi ạ."},{"speaker":"client","text":"Ủa, sao giảm có 30% thôi vậy? Em thấy trên web ghi 50% mà?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, do lỗi hệ thống hiển thị sai. Thực tế chỉ giảm 30% thôi ạ, em có thể check lại cho bạn."},{"speaker":"client","text":"Thế à... vậy thôi, mình không mua nữa. Cảm ơn nhé!"}]','fail',82),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác kiểu này nhưng nhìn hơi mỏng, có ấm không vậy?"},{"speaker":"salebot","text":"Dạ, sản phẩm này là vải cotton dày 2 lớp, phù hợp mùa xuân thu ạ. Mình gửi link chi tiết kèm review khách hàng nhé!"},{"speaker":"client","text":"Mình thấy 1,2 triệu hơi đắt, có giảm giá không? Mua 2 cái thì sao?"},{"speaker":"salebot","text":"Dạ, hôm nay có sale 10% cho đơn 2 sản phẩm ạ. Giá sau giảm còn 2,16 triệu/cặp, giao tận nơi miễn phí!"},{"speaker":"client","text":"Ok, mình lấy 2 cái luôn. Địa chỉ: 123 Lê Lợi, quận 1. Thanh toán COD nhé!"},{"speaker":"salebot","text":"Dạ, đã ghi nhận đơn hàng 2 chiếc áo khoác cotton dày. Cảm ơn bạn đã mua sắm cùng shop!"}]','successs',83),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng nhìn nó hơi rộng, có size nào nhỏ hơn không?"},{"speaker":"salebot","text":"Dạ chào bạn! Chúng mình có size S vừa vặn hơn đấy ạ. Bạn muốn mình check sẵn sàng size S cho bạn không?"},{"speaker":"client","text":"Ừ, mình chọn size S nhé. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ size S giá 899.000đ thôi ạ, đã bao gồm phí ship trong nội thành. Bạn có muốn mình gửi mã giảm giá 5% không?"},{"speaker":"client","text":"Mình thấy được đấy, nhận hàng rồi mới thanh toán được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn cứ yên tâm nhận hàng kiểm tra rồi thanh toán sau. Mình sẽ gửi đơn ngay bây giờ cho bạn."}]','successs',84),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo khoác mùa đông. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Mình có sẵn mẫu áo khoác nữ chống gió, có lớp lót ấm, giá 1.200.000đ. Bạn muốn màu gì ạ?"},{"speaker":"client","text":"Màu be hoặc xám nhạt được không? Mình thích kiểu đơn giản ấy."},{"speaker":"salebot","text":"Dạ có đủ 2 màu đó ạ! Màu be 1.200.000đ, xám nhạt 1.150.000đ (khuyến mại tuần này). Bạn chọn size nào ạ?"},{"speaker":"client","text":"Size S thôi. Có thể giảm giá thêm không? Mình thấy bên kia bán rẻ hơn 100k đấy."},{"speaker":"salebot","text":"Dạ mình có thể giảm 50k cho bạn, thành 1.100.000đ ạ! Nếu mua kèm khăn len, mình tặng bạn 10% nữa. Bạn thấy sao?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn áo + khăn đi. Bao lâu nhận được hàng?"},{"speaker":"salebot","text":"Dạ giao trong 2 ngày ạ! Bạn để lại số điện thoại và địa chỉ, mình gửi mã vận đơn ngay."}]','successs',85),
('[{"speaker":"client","text":"Chào bạn! Mình đang quan tâm đến chiếc áo khoác chống nước này, nhưng giá 1.200k hơi cao nhỉ?"},{"speaker":"salebot","text":"Dạ, 1.200k là giá niêm yết ạ, nhưng hôm nay có chương trình giảm 10% cho đơn đầu tiên đó!"},{"speaker":"client","text":"Thế thì có miễn phí ship không? Mình ở tỉnh xa."},{"speaker":"salebot","text":"Dạ có ạ, miễn phí ship cho đơn từ 500k trở lên. Nếu bạn mua luôn thì mình gửi mã giảm thêm 50k nữa nha!"},{"speaker":"client","text":"Ok, thế mình lấy size M nhé. Bao lâu nhận được hàng?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, mình sẽ gửi mã tracking sau khi thanh toán xong!"}]','successs',86),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao cho bé nhà mình. Bé 8 tuổi, cần size 120. Có hàng không?"},{"speaker":"salebot","text":"Dạ chào bạn, shop có sẵn ạ! Bộ áo thun + quần ngắn thể thao màu xanh dương, giá 399k. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình thấy shop khác bán 350k thôi."},{"speaker":"salebot","text":"Dạ giá gốc 450k, giờ đang khuyến mãi 399k ạ. Nếu bạn đặt 2 bộ trở lên sẽ giảm thêm 10% nữa ạ!"},{"speaker":"client","text":"Thế thì mình lấy 2 bộ luôn. Ship tận nhà không? Miễn phí ship chứ?"},{"speaker":"salebot","text":"Dạ free ship nội thành ạ! Bạn cung cấp địa chỉ để shop check ship phí nha. Cảm ơn bạn đã mua hàng!"}]','successs',87),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc bàn chải điện Oral-B Genius X. Mình thấy nó khá đắt, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Bàn chải Oral-B Genius X đang có chương trình khuyến mại 20% cho đơn hàng đầu tiên hôm nay nè. Giá gốc 2.500.000đ giờ chỉ còn 2.000.000đ thôi ạ!"},{"speaker":"client","text":"Ồ, giá tốt quá! Mình thấy trên web ghi là giao trong 3-5 ngày, có nhanh hơn không?"},{"speaker":"salebot","text":"Dạ có nha! Nếu bạn chọn giao trong ngày (áp dụng nội thành HCM, HN) thì phí ship chỉ 20k thay vì miễn phí ship thường ạ. Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình chọn màu trắng nhé. Đặt luôn thôi! Cảm ơn bạn nhé."},{"speaker":"salebot","text":"Dạ cảm ơn bạn đã tin tưởng! Đơn hàng của bạn đã được xác nhận. Chúc bạn có trải nghiệm chăm sóc răng miệng tuyệt vời cùng Oral-B ạ!"}]','successs',88),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua chiếc áo khoác này trên web, nhưng giá 1.299.000đ hơi đắt nhỉ. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện sản phẩm đang có chương trình khuyến mại 15% cho đơn hàng đầu tiên, chị chỉ cần nhập mã ''AO2024'' là được giảm ngay 194.850đ, xuống còn 1.104.150đ thôi ạ!"},{"speaker":"client","text":"Ồ, hay quá! Mà mình mặc size M, áo còn size M không bot?"},{"speaker":"salebot","text":"Dạ size M vẫn còn 3 chiếc chị ạ! Chị muốn mình check kho và gửi link thanh toán luôn nhé?"},{"speaker":"client","text":"Ok, mình chọn size M và thanh toán luôn đây. Cảm ơn bot nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc chị mua sắm vui vẻ, hàng sẽ giao trong 2 giờ tới ạ!"}]','successs',89),
('[{"speaker":"client","text":"Chào shop! Mình đang quan tâm chiếc điện thoại Samsung Galaxy S24 Ultra 5G, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Máy Samsung Galaxy S24 Ultra 5G đang có giá 32 triệu 990k, anh/chị quan tâm màu nào ạ?"},{"speaker":"client","text":"Màu đen thôi. Có giảm giá gì không? Mình thấy bên kia bán rẻ hơn 2 triệu đấy!"},{"speaker":"salebot","text":"Dạ, em có thể giảm xuống 31 triệu 500k cho anh/chị nếu mua kèm ốp lưng chính hãng nhé! Còn giao hàng miễn phí trong 2 giờ."},{"speaker":"client","text":"Ok, mình lấy luôn nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1 nhé."},{"speaker":"salebot","text":"Dạ em đã ghi nhận đơn hàng ạ! Cảm ơn anh/chị đã ủng hộ shop. Chúc anh/chị một ngày tốt lành!"}]','successs',90),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác denim nữ hiệu Levi''s 501, size M có không vậy?"},{"speaker":"salebot","text":"Chào bạn! Rất tiếc ạ, size M của mẫu này đã hết hàng rồi. Bạn có thể chọn size L hoặc S không ạ?"},{"speaker":"client","text":"Size L thì hơi rộng, mình mặc vừa size M thôi. Có màu nào khác không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh navy và đen vẫn còn size M. Bạn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh navy nhưng giá hơi cao. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, shop đang có combo giảm 10% nếu mua 2 sản phẩm trở lên ạ. Hoặc bạn có thể nhận voucher 5% nếu thanh toán qua ví điện tử."},{"speaker":"client","text":"Mình chỉ mua 1 cái thôi. Vậy giá cuối là bao nhiêu?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.290.000đ, sau giảm 5% còn 1.225.500đ ạ. Bạn có muốn đặt không?"},{"speaker":"client","text":"Mình nghĩ 1.150.000đ được không? Mình thấy bên khác rẻ hơn."},{"speaker":"salebot","text":"Dạ, 1.150.000đ hơi thấp so với giá gốc rồi ạ. Shop không thể giảm thêm được ạ. Bạn xem có hứng thú mẫu khác không?"},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',91),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác giống mẫu của mẫu mới nhất của Nike, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Mẫu áo Nike Air Jacket mới nhất hiện có giá 1.990.000đ, có 3 màu xanh dương, đen và xám."},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình mua 1 cái thôi."},{"speaker":"salebot","text":"Dạ thôi ạ, do mình đang có chương trình khuyến mại giảm 10% cho đơn hàng đầu tiên, vậy còn 1.791.000đ thôi bạn nhé!"},{"speaker":"client","text":"Ok, mình chọn màu xanh dương nhé. Địa chỉ giao là 123 Lê Lợi, phường Bến Nghé, quận 1."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng của bạn đã được xác nhận, giao dự kiến trong 2-3 ngày. Chúc bạn mua sắm vui vẻ!"}]','successs',92),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua bộ quần áo thể thao cho bé gái 10 tuổi. Size 140 có không?"},{"speaker":"salebot","text":"Dạ có ạ! Bé nhà mình thích màu gì? Màu hồng hay xanh dương?"},{"speaker":"client","text":"Màu hồng đi, nhưng giá có đắt quá không? Mình thấy trên mạng rẻ hơn."},{"speaker":"salebot","text":"Dạ giá niêm yết 499k, nhưng hôm nay giảm còn 399k ạ! Còn giao hàng miễn phí trong 2h nếu mua trong hôm nay."},{"speaker":"client","text":"Ừ, vậy mình lấy 1 bộ thôi. Nhưng mình muốn đổi size nếu không vừa."},{"speaker":"salebot","text":"Dạ được ạ! Miễn phí đổi size trong 7 ngày nếu sản phẩm còn nguyên tem mác. Cảm ơn bạn đã mua sắm!"}]','fail',93),
('[{"speaker":"client","text":"Chào bạn, mình nhìn thấy chiếc điện thoại Samsung Galaxy S23 Ultra 5G màu đen trên web. Có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại sản phẩm đang có chương trình khuyến mại 10% cho phiên mua sớm hôm nay, giao hàng miễn phí trong 2 giờ nếu anh/chị đặt ngay."},{"speaker":"client","text":"10% thôi à? Mà mình thấy giá niêm yết vẫn cao hơn chỗ khác 2 triệu. Bán thế này có lời không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, sản phẩm này nhập khẩu chính hãng nên giá đã ổn định, nhưng ưu đãi hôm nay là tốt nhất rồi ạ. Nếu anh/chị mua kèm phụ kiện như ốp lưng + sạc nhanh thì mình giảm thêm 500k nữa nhé!"},{"speaker":"client","text":"Thế à? Vậy mình lấy luôn chiếc điện thoại + ốp lưng đi. Bao giờ nhận được hàng?"},{"speaker":"salebot","text":"Dạ vui lắm ạ! Anh/chị để lại số điện thoại và địa chỉ, mình sẽ gửi mã vận đơn ngay. Hàng sẽ đến trong 1-2 giờ ạ. Cảm ơn anh/chị đã mua sắm cùng shop!"}]','successs',94),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác này nhưng thấy giá hơi cao quá. Có thể giảm giá cho mình được không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc áo này đang có khuyến mại 20% cho khách mới, giá còn 899k thôi ạ. Nếu chị mua combo 2 sản phẩm sẽ giảm thêm 50k nữa!"},{"speaker":"client","text":"Mình chỉ mua 1 áo thôi, 899k vẫn hơi đắt. Bán 800k đi, mình lấy luôn bây giờ."},{"speaker":"salebot","text":"Dạ thật tiếc ạ, giá sàn của shop là 850k nên không thể giảm thêm được ạ. Nếu chị thích em có thể gửi link sản phẩm khác tầm 700k-800k ạ?"},{"speaker":"client","text":"Thôi vậy, cảm ơn nhé! Mình qua shop khác xem thử."}]','fail',95),
('[{"speaker":"client","text":"Chào bot! Mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Máy vẫn còn sẵn ạ, chị muốn màu đen hay xanh dương ạ? Còn ưu đãi giảm 5% cho đơn đầu tiên trong hôm nay nè!"},{"speaker":"client","text":"Ui, mình thích màu đen nhưng giá hơi cao so với dự định. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Chị thông cảm, giá đã ưu đãi rồi ạ. Nhưng chị mua kèm ốp lưng chính hãng giảm 50% nha, thế thì tiện hơn!"},{"speaker":"client","text":"Thôi được, mình lấy luôn đi. Bao lâu giao tới?"},{"speaker":"salebot","text":"Dạ giao trong 2 tiếng ạ, chị vui lòng để lại địa chỉ và số điện thoại để shop xác nhận ạ!"}]','successs',96),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, nhưng giá trên web hơi cao so với mình nghĩ. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại Oral-B Pro 3000 đang khuyến mại 15% cho đơn hàng đầu tiên, cộng thêm quà tặng là 2 đầu bàn chải thay thế nha!"},{"speaker":"client","text":"15% thì cũng được, nhưng mình thấy bên đối thủ giá rẻ hơn 50k. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, mức giá đã ưu đãi nhất rồi. Nếu bạn mua kèm 1 hộp kem đánh răng Colgate 360 thì mình có thể tặng thêm 10k nữa nhé!"},{"speaker":"client","text":"Thế à... thôi được, mình lấy luôn đi. Nhưng giao hàng chậm thì mình hủy đơn nhé!"},{"speaker":"salebot","text":"Dạ không ạ, giao trong 2 giờ nếu bạn ở Hà Nội. Cảm ơn bạn đã ủng hộ shop!"}]','fail',97),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật của thương hiệu Coach. Mẫu này có màu nâu nào không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng em vừa nhập mẫu Coach Classic Carryall màu nâu hạt dẻ mới về hôm nay, chị có thể nhận hàng ngay trong ngày nếu đặt trước 16h."},{"speaker":"client","text":"Mình thấy giá hơi cao so với dự định, có thể giảm giá không? Mình thấy trên web ghi 12 triệu."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, đây là hàng chính hãng nên giá niêm yết là 12 triệu. Nhưng nếu chị đặt mua hôm nay, chúng em sẽ tặng kèm 1 chiếc ví da mini trị giá 500k chị nhé!"},{"speaker":"client","text":"Vậy có miễn phí vận chuyển không? Mình ở xa trung tâm."},{"speaker":"salebot","text":"Dạ nếu chị đặt trên 10 triệu, chúng em sẽ miễn phí ship toàn quốc chị nhé! Chị cứ yên tâm đặt hàng, em sẽ hỗ trợ xác nhận đơn ngay."},{"speaker":"client","text":"Ok, vậy mình chọn màu nâu hạt dẻ nhé. Bao lâu thì nhận được hàng?"},{"speaker":"salebot","text":"Dạ chị đặt trong 10 phút nữa là em xác nhận đơn thành công, hàng sẽ giao tới tận nhà chị vào ngày mai ạ. Em gửi link thanh toán luôn cho chị nhé!"}]','successs',98),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua áo khoác mùa đông cho bé gái 10 tuổi. Loại vải dày một chút, chống rét tốt ấy."},{"speaker":"salebot","text":"Dạ, em gợi ý dòng áo khoác cotton dày ấm 500g/m² của thương hiệu Kid’s World ạ. Màu hồng và xanh dương đang hot lắm đó!"},{"speaker":"client","text":"Màu hồng nhìn được đấy. Size 130 thì giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ size 130 giá 799k ạ, nhưng hôm nay có mã giảm 10% cho đơn từ 500k trở lên nè!"},{"speaker":"client","text":"Ủa vậy mình lấy luôn! Ship nội thành bao lâu vậy?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 tiếng ạ, em sẽ gửi tracking qua Zalo cho bạn ngay khi xuất hàng nha!"}]','successs',99),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác da này nhưng giá hơi cao so với mình mong đợi. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ, sản phẩm này đang có chương trình khuyến mại 10% cho đơn hàng đầu tiên, kèm theo miễn phí ship trong 14 ngày."},{"speaker":"client","text":"10% thì vẫn hơi cao, mình thấy trên shopee có cùng mẫu nhưng giá rẻ hơn 300k. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ, mình xin lỗi ạ, mức giảm này là mức tối đa từ cửa hàng rồi ạ. Nếu bạn muốn, mình có thể tặng bạn 1 chiếc khăn da miễn phí kèm theo."},{"speaker":"client","text":"Thôi được, mình sẽ cân nhắc thêm. Cảm ơn bạn nhé!"}]','fail',100),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc áo khoác thể thao Nike Air Versitile, size M có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Còn 3 chiếc size M, màu xanh navy và đen. Bạn muốn giao trong ngày hay nhận tại cửa hàng?"},{"speaker":"client","text":"Mình ở xa nên giao tận nơi thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 2.490.000đ, nhưng hôm nay mình có khuyến mại 10% nếu đặt ngay ạ!"},{"speaker":"client","text":"10% à? Vậy còn 2.241.000đ thôi nhỉ? Được rồi, mình lấy 1 cái xanh navy nhé."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Địa chỉ nhận hàng là gì ạ? Mình sẽ gửi đơn hàng ngay."}]','successs',101),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua quần jean nam size 32. Bạn có size này không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập mẫu quần jean nam hiệu Levi’s size 32 hôm qua. Bạn muốn chọn màu xanh navy hay đen?"},{"speaker":"client","text":"Mình thích màu đen nhưng giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 999.000đ, nhưng hôm nay có chương trình giảm còn 899.000đ nếu bạn mua online ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy 1 cái. Bao ship phí thế?"},{"speaker":"salebot","text":"Dạ ship nội thành miễn phí ạ, chỉ cần thanh toán trước 30% là được ạ!"}]','successs',102),
('[{"speaker":"client","text":"Chào shop, mình đang quan tâm đến bộ bàn ghế gỗ óc chó 6 chỗ ngồi. Bạn có thể tư vấn cho mình về chất liệu và giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Bộ bàn ghế gỗ óc chó nguyên khối 100% nhập khẩu từ Mỹ, chống mối mọt và bền theo thời gian. Giá niêm yết là 15 triệu, nhưng hôm nay shop có ưu đãi giảm 10% nếu anh/chị đặt ngay."},{"speaker":"client","text":"15 triệu à? Mình thấy hơi đắt so với những nơi khác. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, gỗ óc chó nguyên khối thì giá thế này là ổn rồi. Nhưng nếu anh/chị chịu khó đợi 3 ngày nữa, shop sẽ có chương trình giảm giá 15% cho khách hàng mới."},{"speaker":"client","text":"Thế à? Thôi được, mình nghĩ kĩ đã. Cảm ơn nhé!"}]','fail',103),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác thể thao này, nhưng thấy giá hơi cao so với mình mong đợi."},{"speaker":"salebot","text":"Dạ, sản phẩm đang khuyến mại 20% cho tuần lễ này, giá chỉ còn 999k thôi ạ!"},{"speaker":"client","text":"Vậy có màu đỏ không? Mình thích màu đó."},{"speaker":"salebot","text":"Dạ xin lỗi, màu đỏ đã hết hàng rồi ạ. Còn lại màu xanh dương, đen và xám."},{"speaker":"client","text":"Thế à, tiếc quá. Mình không thích mấy màu kia lắm. Cảm ơn bạn nhé!"}]','fail',104),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc túi xách da này. Đơn giá 1.200.000đ có đúng không?"},{"speaker":"salebot","text":"Dạ đúng ạ! Đây là sản phẩm da thật, bảo hành 1 năm. Bạn muốn màu nâu hay đen ạ?"},{"speaker":"client","text":"Mình thích màu nâu nhưng thấy hơi đắt. Có giảm giá không? Giá 1 triệu được không?"},{"speaker":"salebot","text":"Dạ 1.100.000đ là giá tốt nhất rồi ạ! Nếu bạn đặt 2 sản phẩm sẽ giảm thêm 50k nữa."},{"speaker":"client","text":"Ok, mình lấy 1 cái thôi. Ship tận nhà không? Phí bao nhiêu?"},{"speaker":"salebot","text":"Dạ ship nội thành 20k, ngoại thành 30k ạ! Bạn có thể thanh toán online hoặc COD."},{"speaker":"client","text":"Ship COD đi, mình để sẵn địa chỉ ở hồ tây. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Đơn hàng của bạn đã được ghi nhận, chúc bạn ngày tốt lành!"}]','successs',105),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng nhìn hình thấy hơi đen quá, có màu khác không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh navy và xám bạc vẫn còn hàng, mình gửi link cho bạn nhé."},{"speaker":"client","text":"À, giá 1.299k vậy à? Đắt quá, có giảm giá không?"},{"speaker":"salebot","text":"Dạ thôi ạ, giá niêm yết rồi, nhưng nếu bạn nhận hàng trong 2h nữa thì free ship 50k nhé!"},{"speaker":"client","text":"Thôi vậy, để mình suy nghĩ lại. Cảm ơn nhé!"}]','fail',106),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một bộ quần áo thể thao cho bé nhà mình. Bé 8 tuổi, mình thấy bộ đồ tập chạy màu xanh dương trên web có không?"},{"speaker":"salebot","text":"Dạ có ạ! Size 8-10 tuổi vẫn còn 3 chiếc. Bé nhà bạn cao bao nhiêu, mình check size chuẩn cho nhé?"},{"speaker":"client","text":"Bé cao 1m35, mình thấy size 10 sẽ vừa hơn. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 599k, nhưng hôm nay có mã giảm 20% cho đơn hàng đầu tiên. Còn 479k thôi ạ!"},{"speaker":"client","text":"Hơi cao so với dự định, mình thấy trên shopee giá rẻ hơn. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ em thông báo với sếp ạ, 449k nha chị! Đóng gói quà tặng luôn cho bé nhé?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Chị cung cấp địa chỉ và số điện thoại để nhân viên giao nhận liên hệ nhé!"}]','successs',107),
('[{"speaker":"client","text":"Ui, mình thấy cái bàn ghế gỗ óc chó này đẹp quá, nhưng giá 12 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ ạ, sản phẩm này được làm từ gỗ óc chó nhập khẩu 100%, bền đẹp theo năm tháng ạ. Nếu bạn mua kèm bàn trà kia, em có thể giảm xuống còn 11 triệu 500k cho bạn nè!"},{"speaker":"client","text":"Thế giao trong bao lâu vậy? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Dạ giao trong 24h trong nội thành, miễn phí ship cho đơn trên 5 triệu ạ. Bạn có muốn mình check mã giảm giá cho bạn không?"},{"speaker":"client","text":"Ừ, vậy mình đặt luôn nhé. Ship đến địa chỉ cũ nhé!"},{"speaker":"salebot","text":"Dạ em đã ghi nhận đơn hàng ạ! Cảm ơn bạn đã tin tưởng mua sắm cùng shop. Chúc bạn ngày mới vui vẻ!"}]','successs',108),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Mẫu này có size M không nhỉ?"},{"speaker":"salebot","text":"Dạ có ạ! Size M vẫn còn 5 chiếc, màu đen và xám. Bạn muốn mình giữ hàng hay order luôn?"},{"speaker":"client","text":"Mình thích màu xám nhưng giá hơi cao so với dự định. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ shop đang có chương trình giảm 10% cho đơn từ 500k, bạn có thể thêm phụ kiện để đạt nhé!"},{"speaker":"client","text":"Tiếc quá, mình chỉ mua áo thôi. Thôi thôi, để sau vậy. Cảm ơn nhé!"}]','fail',109),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bàn chải điện Philips Sonicare DiamondClean, có giảm giá gì không thế?"},{"speaker":"salebot","text":"Dạ chào chị! Hiện tại bàn chải này đang giảm 20% cho đơn hàng đầu tiên, chị có muốn mình hỗ trợ đặt luôn không ạ?"},{"speaker":"client","text":"À, mình thấy giá trên web vẫn là 3 triệu, sao giảm vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 3.750.000đ, chị ơi! Giảm 20% tức còn 3 triệu thôi, kèm tặng kèm bàn chải thay đầu nữa ạ."},{"speaker":"client","text":"Thế nếu mình mua 2 cái thì sao? Có ưu đãi hơn không?"},{"speaker":"salebot","text":"Dạ nếu chị mua 2, mình có thể giảm thêm 5% nữa, tức 2.85 triệu/cái, chị thấy thế nào?"},{"speaker":"client","text":"Hmm, mình suy nghĩ thêm chút nhé. Cảm ơn bạn!"}]','fail',110),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua đôi giày thể thao Nike Air Force 1, nhưng giá hơi cao so với túi tiền của mình. Có chương trình giảm giá nào không ạ?"},{"speaker":"salebot","text":"Dạ chào chị! Hiện tại shop có ưu đãi 10% cho đơn hàng từ 2 triệu, và em có thể giảm thêm 5% nếu chị thanh toán qua ví MoMo ạ."},{"speaker":"client","text":"Mình chỉ có 1,5 triệu thôi, liệu có cách nào khác không? Mình thấy giá gốc đã 1,8 triệu rồi."},{"speaker":"salebot","text":"Dạ nếu chị chọn size 40 trở xuống, shop có thể giảm xuống 1,4 triệu ạ. Size 41 thì 1,5 triệu là giá rẻ nhất rồi ạ."},{"speaker":"client","text":"Ôi tiếc quá, mình cần size 42. Thôi vậy mình đi xem nơi khác vậy. Cảm ơn bạn nhé!"}]','fail',111),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng thấy giá hơi cao quá, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ, sản phẩm này đang khuyến mại 10% cho khách hàng mới đó ạ! Nếu mua kèm với quần jeans nữa thì được thêm 5% nữa."},{"speaker":"client","text":"15% vậy à? Mình thấy trên mạng rẻ hơn nhiều, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ, mình xin lỗi ạ, mức khuyến mại đã là mức tối đa rồi. Nếu bạn muốn, mình có thể gửi link sản phẩm để bạn tham khảo thêm ạ."},{"speaker":"client","text":"Thôi được, mình sẽ suy nghĩ lại. Cảm ơn nhé!"}]','fail',112),
