('[{"speaker":"client","text":"Chào shop! Mình thấy đôi giày thể thao Nike Air Max 90 trắng-đen đang giảm giá 30% thế à? Mình mua size 40 thôi."},{"speaker":"salebot","text":"Dạ chào bạn ạ! Size 40 vẫn còn 2 đôi, nhưng giá giảm chỉ còn 2.2 triệu thôi ạ (giảm từ 3.1 triệu). Bạn muốn mình giữ hàng không?"},{"speaker":"client","text":"Hơi cao vậy... 2 triệu thôi được không? Mình thấy bên kia bán rẻ hơn."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã là ưu đãi cuối cùng rồi ạ. Nếu bạn mua kèm tất thể thao thì em giảm thêm 50k nha!"},{"speaker":"client","text":"Thôi vậy... thế giao hàng trong bao lâu? Mình cần gấp."},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ. Em sẽ gửi mã tracking qua Zalo ngay khi hàng lên xe ạ. Cảm ơn bạn đã quan tâm!"}]','fail',119),
('[{"speaker":"client","text":"Chào shop! Mình thấy điện thoại Samsung Galaxy S23 128GB đang khuyến mại 15 triệu, có sẵn không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Nhưng hiện tại chỉ còn phiên bản 256GB thôi ạ, giá 17 triệu. Bạn có nhu cầu thì mình check kho ngay nhé!"},{"speaker":"client","text":"Hơi đắt so với quảng cáo... Mình thấy chỗ khác bán 16 triệu luôn ấy?"},{"speaker":"salebot","text":"Dạ 16 triệu là giá cũ ạ, giờ khuyến mại hết rồi ạ. Nếu bạn mua bây giờ thì mình có thể giảm thêm 200k cho bạn nhé!"},{"speaker":"client","text":"Thế à... Vậy thôi, mình không mua nữa. Cảm ơn nhé!"}]','fail',120),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn làm việc này có màu gỗ óc chó đẹp quá. Còn size 120x60cm không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu óc chó phiên bản mới vừa về, giá niêm yết 3.500.000đ. Bạn muốn đặt ngay không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá được không? Mình thấy bên kia bán 3.200.000đ luôn ấy."},{"speaker":"salebot","text":"Dạ thưa bạn, đây là sản phẩm nhập khẩu nguyên chiếc nên giá đã ưu đãi lắm rồi. Để mình hỏi quản lý xem có thể giảm thêm 5% không nhé?"},{"speaker":"client","text":"Thế à, vậy mình đợi 10 phút rồi trả lời sau. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ, chúc bạn một ngày tốt lành!"}]','fail',121),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S24 Ultra. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Em xin giới thiệu chiếc Galaxy S24 Ultra 5G 256GB, màn hình Dynamic AMOLED 2X 6.8\" siêu mỏng, camera 200MP cực nét. Hiện có ưu đãi 10% cho đơn hàng đầu tiên trong hôm nay chị nhé!"},{"speaker":"client","text":"Mình thấy giá niêm yết 28 triệu, vậy giảm còn 25 triệu được không? Mình thấy bên kia bán rẻ hơn."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá niêm yết đã là giá tốt nhất rồi ạ. Nhưng nếu chị đặt ngay hôm nay, em có thể giảm thêm 500k cho chị, thành 27.5 triệu nhé! Kèm theo tặng kèm sạc nhanh 45W nữa ạ."},{"speaker":"client","text":"Ok, vậy mình lấy luôn chiếc này đi. Địa chỉ giao là 123 Lê Lợi, Phường Bến Thành, Quận 1, TP.HCM. Bao lâu thì nhận được hàng?"},{"speaker":"salebot","text":"Dạ chị yên tâm ạ! Đơn hàng sẽ được giao trong 2 tiếng tới nếu chị ở nội thành. Em sẽ gửi mã tracking qua tin nhắn cho chị ngay sau khi xác nhận đơn ạ. Cảm ơn chị đã ủng hộ ạ!"}]','successs',122),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác thể thao này nhưng nhìn giá hơi cao so với mình dự định. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Áo khoác thể thao này đang có chương trình khuyến mại 15% cho đơn hàng đầu tiên hôm nay đó ạ. Nếu chị mua 2 sản phẩm trở lên thì tặng kèm mũ thể thao luôn nè!"},{"speaker":"client","text":"Thế giá cuối cùng là bao nhiêu thế? Mình chỉ mua 1 cái thôi."},{"speaker":"salebot","text":"Dạ giá gốc 1.290.000đ, sau giảm 15% còn 1.096.500đ chị nhé. Giao hàng miễn phí trong 2h nếu chị ở TP.HCM."},{"speaker":"client","text":"Okay, mình chọn size M nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM."},{"speaker":"salebot","text":"Dạ chị vui lòng chuyển khoản 1.096.500đ vào số TK 123456789 (Techcombank) hoặc ấn vào link thanh toán dưới đây ạ. Sau khi nhận được tiền, shop sẽ giao ngay trong 30 phút!"}]','successs',123),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc máy xay sinh tố Xiaomi có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại sản phẩm đang khuyến mại 20% cho đơn từ 1 triệu trở lên. Bạn muốn đặt luôn không ạ?"},{"speaker":"client","text":"Mình thấy giá gốc 1.5 triệu, giờ 20% là 1.2 triệu. Có thể giảm thêm không? Mình thấy nơi khác có 1.1 triệu."},{"speaker":"salebot","text":"Dạ chúng em đã ưu đãi tối đa rồi ạ, 1.2 triệu là giá rẻ nhất trong tuần này. Miễn phí ship cho đơn trên 2 triệu ạ."},{"speaker":"client","text":"Thôi được, mình chọn màu trắng nhé. Nhưng mà giao trong 2 tiếng được không? Mình cần gấp."},{"speaker":"salebot","text":"Dạ rất tiếc ạ, hôm nay giao hàng muộn hơn do trời mưa to. Chúng em giao sớm nhất là 4 tiếng ạ. Có thể nhận vào buổi tối không ạ?"},{"speaker":"client","text":"Ôi tiếc quá, mình không thể đợi lâu. Thôi thôi, mình hủy đơn vậy. Cảm ơn nhé!"}]','fail',124),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc váy công sở này. Màu nude size 36 có không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Size 36 còn 2 chiếc màu nude, giá niêm yết 1.200.000đ. Bạn muốn đặt trước không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình là sinh viên nên ngân sách hạn hẹp."},{"speaker":"salebot","text":"Dạ em xin lỗi, giá đã chiết khấu 10% cho sinh viên rồi ạ. Nếu bạn mua kèm áo blazer cùng hãng thì được thêm 5% nữa."},{"speaker":"client","text":"Ok, vậy mình lấy váy + blazer luôn. Ship tận nơi được không? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ được ạ! Tổng cộng 2.100.000đ, giao trong 2 giờ. Bạn để lại số điện thoại để shop xác nhận đơn hàng nhé!"}]','successs',125),
('[{"speaker":"client","text":"Chào em, mình muốn mua chiếc áo khoác thể thao này của Nike, nhưng thấy trên web ghi size S hết rồi. Size M có không em?"},{"speaker":"salebot","text":"Dạ size M vẫn còn ạ! Nhưng em xin lỗi, hiện tại chỉ còn màu xanh dương thôi ạ."},{"speaker":"client","text":"À, mình thích màu đen cơ. Thôi được, mình lấy size M màu xanh vậy. Giá bao nhiêu em nhỉ?"},{"speaker":"salebot","text":"Dạ 1.250.000 đồng ạ, nhưng hiện tại em có mã giảm giá 10% cho khách hàng mới đó ạ!"},{"speaker":"client","text":"Ồ, thế còn 1.125.000 đúng không? Nhưng mình thấy trên web ghi 1.190.000, sao lại khác vậy?"},{"speaker":"salebot","text":"Dạ em xin lỗi, em nhầm ạ! Giá chuẩn là 1.190.000, mã giảm giá chỉ áp dụng khi thanh toán qua ví điện tử ạ."},{"speaker":"client","text":"Thế à, mình không có ví điện tử. Vậy thôi, cảm ơn em nhé!"}]','fail',126),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái bàn học gỗ thông 4 chân kia trông đẹp quá, nhưng giá 2 triệu 500k sao mắc thế? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Bàn gỗ thông này chất liệu tốt, bền lắm chị nhé. Đồ handmade nên giá hơi cao, chị thông cảm!"},{"speaker":"client","text":"Thế à... Chị thấy trên mạng cùng loại rẻ hơn nhiều. Có thể giảm còn 1 triệu 800k không? Mình nhận hàng ngay hôm nay luôn."},{"speaker":"salebot","text":"Dạ không được chị ơi, giá gốc đã sát rồi ạ. Chị mua 2 bàn thì giảm 100k thôi, chị thấy sao?"},{"speaker":"client","text":"Thôi được, nhưng giao hàng muộn quá thì mình không nhận đâu nhé! Cám ơn nha."},{"speaker":"salebot","text":"Dạ em hứa giao trong 3 tiếng chị nhé! Em gửi link thanh toán ngay đây ạ."}]','fail',127),
