('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé gái 10 tuổi. Có size 120 không?"},{"speaker":"salebot","text":"Dạ chào chị, size 120 vẫn còn 2 mẫu ạ: áo thun + quần short combo 399k và bộ thể thao 2 mảnh 599k. Chị muốn xem ảnh trước không ạ?"},{"speaker":"client","text":"Mình thấy combo 399k hơi đắt, có thể giảm giá không? Mình mua 2 bộ luôn đó."},{"speaker":"salebot","text":"Dạ chị mua 2 bộ combo 399k thì em giảm còn 360k/bộ thôi ạ. Giao tận nhà miễn phí trong 3 ngày."},{"speaker":"client","text":"Thế à, nhưng mình thấy trên web ghi giá 320k/bộ. Bạn có thể match giá không?"},{"speaker":"salebot","text":"Dạ em xin lỗi chị, combo này không có chính sách giá sàn ạ. Em có thể tặng kèm 1 chiếc tất thể thao nếu chị mua 2 bộ luôn nhé?"},{"speaker":"client","text":"Thôi được, mình lấy vậy đi. Nhưng giao trong 2 ngày thôi nhé, mình cần gấp."},{"speaker":"salebot","text":"Dạ em cảm ơn chị! Đơn hàng của chị sẽ giao vào chiều mai ạ. Chúc chị một ngày tốt lành!"}]','fail',133),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang khuyến mại 20% cho sản phẩm này, chỉ còn 1.990.000đ thay vì 2.490.000đ thôi ạ."},{"speaker":"client","text":"Thế có tặng kèm gì không? Mình thấy đồ điện gia dụng hay có quà tặng lắm."},{"speaker":"salebot","text":"Dạ ạ! Bạn sẽ nhận được 3 đầu chải thay thế miễn phí kèm theo ạ. Còn giao hàng tận nơi miễn phí trong 24h nữa."},{"speaker":"client","text":"Ok, mình đặt luôn vậy. Nhưng mình ở xa nội thành, giao có chậm không?"},{"speaker":"salebot","text":"Dạ không ạ! Chúng tôi cam kết giao trong 3 ngày trên toàn quốc. Bạn có thể theo dõi đơn hàng qua link mình gửi nhé!"}]','successs',134),
('[{"speaker":"client","text":"Chào bot, mình muốn mua điện thoại Samsung Galaxy A34, bạn có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen đều còn, bạn muốn chọn màu nào?"},{"speaker":"client","text":"Mình thích xanh dương nhưng giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ 7.990.000đ thôi ạ, giao ngay trong ngày!"},{"speaker":"client","text":"Hơi đắt, có giảm được không? Mình thấy bên khác bán 7.500.000đ thôi."},{"speaker":"salebot","text":"Dạ không ạ, giá niêm yết rồi. Nhưng nếu bạn mua kèm ốp lưng thì tặng miễn phí!"},{"speaker":"client","text":"Thôi không mua nữa, cảm ơn."}]','fail',135),
('[{"speaker":"client","text":"Chào bạn, mình nhìn thấy chiếc váy dạ hội màu xanh dương trên web, size M có không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Size M vừa hết hàng, nhưng size L và S vẫn còn. Bạn muốn mình gửi mẫu ảnh lên điện thoại không?"},{"speaker":"client","text":"Ôh vậy à? Mình thích size M lắm, có cách nào đổi size nhanh không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn chọn size L hoặc S, mình sẽ giao trong 2h, nếu không vừa mình đổi miễn phí trong 3 ngày. Giá gốc 2.990.000đ, mình giảm còn 2.490.000đ thôi!"},{"speaker":"client","text":"Thế à? Được đấy, mình lấy size L đi. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ 1 tiếng nữa ạ! Bạn để lại số điện thoại và địa chỉ, mình gửi xác nhận đơn hàng ngay!"}]','successs',136),
('[{"speaker":"client","text":"Chào bot, mình thấy cái điện thoại Samsung Galaxy S23 Ultra 256GB trên web có giảm giá không vậy? Mình thấy nó hơi đắt."},{"speaker":"salebot","text":"Dạ chào chị! Hiện tại sản phẩm đang giảm 10% cho đơn hàng đầu tiên, chị có thể check mã giảm giá ''SALE10'' nhé!"},{"speaker":"client","text":"Vậy giao hàng trong bao lâu ạ? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Chị ở đâu vậy ạ? Nếu trong nội thành HN thì giao trong 2h, ngoài khu vực thì 1-2 ngày thôi ạ."},{"speaker":"client","text":"Mình ở quận 1, HN. Vậy mình đặt luôn nhé, thanh toán online được không?"},{"speaker":"salebot","text":"Dạ được chị! Chị chọn phương thức thanh toán COD hay chuyển khoản ạ? Mình sẽ gửi link thanh toán ngay."},{"speaker":"client","text":"Chuyển khoản đi, mình gửi tiền trước. Cảm ơn bot nhé!"}]','successs',137),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc bàn học gỗ cho bé nhà mình. Bạn có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng tôi có bàn học gỗ thông minh cho bé 6-12 tuổi, giá niêm yết 2.500.000đ, chị có muốn xem ảnh không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình thấy giá trên Shopee rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá niêm yết của chúng tôi đã bao gồm phí vận chuyển và bảo hành 2 năm. Nhưng nếu chị đặt ngay hôm nay, mình có thể giảm 5% cho chị nhé?"},{"speaker":"client","text":"5% vẫn hơi cao, mình chỉ trả 2.000.000đ thôi. Được thì mình mua luôn."},{"speaker":"salebot","text":"Dạ thật xin lỗi chị, giá sỉ tối thiểu của chúng tôi là 2.200.000đ ạ. Nếu chị không vừa lòng, mình có thể giới thiệu sản phẩm khác giá rẻ hơn không?"},{"speaker":"client","text":"Thôi vậy, cảm ơn bạn nhé! Mình sẽ tìm chỗ khác vậy."}]','fail',138),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn ghế gỗ óc chó này đẹp quá. Mình muốn mua nhưng giá hơi cao so với dự định."},{"speaker":"salebot","text":"Dạ, sản phẩm này chất liệu óc chó 100%, chịu lực tốt lắm ạ. Em có thể giảm 5% nếu bạn mua đủ 2 bộ."},{"speaker":"client","text":"5% thôi à? Mình thấy bên shop khác bán rẻ hơn 10% luôn."},{"speaker":"salebot","text":"Dạ shop em cam kết chất lượng chuẩn, giá cả cạnh tranh lắm ạ. Nếu bạn không ưng, em sẽ hỗ trợ đổi trả trong 7 ngày."},{"speaker":"client","text":"Thôi được, mình lấy 1 bộ thôi. Nhưng giao hàng chậm là mình hủy nhé!"},{"speaker":"salebot","text":"Dạ em hứa giao trong 3 ngày làm việc ạ. Cảm ơn bạn đã ủng hộ!"}]','fail',139),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy A54 5G. Bạn có thể tư vấn giá và khuyến mãi không?"},{"speaker":"salebot","text":"Dạ có ạ! Giá niêm yết là 9.990.000đ nhưng hôm nay em có mã giảm 5% cho khách hàng online, còn 9.490.000đ. Bạn có muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy giá vẫn hơi cao, có thể giảm thêm không? Bên mình hay có chương trình ưu đãi hơn thế."},{"speaker":"salebot","text":"Dạ em sẽ kiểm tra lại ạ! Hiện tại em có thể giảm xuống 9.290.000đ kèm quà tặng là tai nghe không dây trị giá 500.000đ. Bạn thấy thế nào?"},{"speaker":"client","text":"Cảm ơn nhưng vẫn hơi đắt. Thôi mình nghĩ sẽ mua sau vậy."}]','fail',140),
('[{"speaker":"client","text":"Chào shop, mình đang tìm mua chiếc áo khoác nữ mùa đông. Mẫu áo có màu gì vậy?"},{"speaker":"salebot","text":"Dạ có đủ màu ạ: đen, xám, hồng pastel, xanh navy. Mình thích mẫu nào vậy?"},{"speaker":"client","text":"Mình thích màu xanh navy. Size S còn không? Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Size S còn 3 cái ạ! Giá niêm yết 899k, nhưng hôm nay sale 10% nên còn 809k thôi. Bạn lấy luôn không?"},{"speaker":"client","text":"Ừ, mình lấy. Bao ship phí thế? Giao trong 3 ngày được không?"},{"speaker":"salebot","text":"Ship nội thành 30k, ngoại thành 50k. Giao trong 2 ngày ạ, mình sẽ gửi link thanh toán qua Zalo ngay!"}]','successs',141),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại tầm trung khoảng 5 triệu thôi. Có sản phẩm nào gợi ý không?"},{"speaker":"salebot","text":"Dạ có ạ! Realme 9i 4GB/64GB vừa ra mắt, giá 4,99 triệu, cấu hình ổn định lắm ạ. Bạn muốn xem ảnh hay thông số không?"},{"speaker":"client","text":"Thế có giảm giá không? Mình thấy trên shopee có khuyến mại 500k nữa."},{"speaker":"salebot","text":"Dạ nếu bạn mua ngay hôm nay, mình sẽ hỗ trợ giảm thêm 200k cho đơn hàng đầu tiên ạ! Tổng còn 4,79 triệu thôi."},{"speaker":"client","text":"Ok, mình lấy vậy. Ship có nhanh không? Mình đang cần gấp."},{"speaker":"salebot","text":"Dạ giao trong 2-3h nếu bạn ở Hà Nội ạ! Mình gửi link thanh toán luôn nhé?"}]','successs',142),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm một chiếc bàn học gỗ cho phòng con trai. Có mẫu nào vừa túi tiền không? Mình ngại ngùng khi hỏi giá lắm."},{"speaker":"salebot","text":"Chào chị! Em hiểu ạ, bàn gỗ thông thường giá từ 1.500.000đ đến 3.000.000đ. Chị muốn mẫu nào? Em sẽ gửi ảnh và giá cụ thể nhé!"},{"speaker":"client","text":"Mình thích mẫu gỗ thông, nhưng 2 triệu thôi có được không? Mua online có giảm giá không?"},{"speaker":"salebot","text":"Dạ, mẫu gỗ thông 2.200.000đ chị nhé! Nếu chị đặt hôm nay, em giảm ngay 200k, thành 2.000.000đ luôn ạ. Giao hàng tận nơi miễn phí trong 3 ngày."},{"speaker":"client","text":"Thế à? Được đó! Mình chọn màu gỗ tự nhiên nhé. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ giỏi quá ạ! Em xác nhận đơn hàng nhé. Chị vui lòng gửi địa chỉ và số điện thoại để nhân viên liên hệ giao hàng ngay tối nay ạ!"}]','successs',143),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đầm len cho mùa đông này. Có size 38 không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen vẫn còn size 38, giao trong 2-3 ngày."},{"speaker":"client","text":"Màu xanh dương thôi, nhưng giá hơi cao so với mình. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ hôm nay có khuyến mại 10% cho sản phẩm len, chỉ còn 899k thôi ạ!"},{"speaker":"client","text":"Ok, mình lấy vậy. Địa chỉ giao là 123 Lê Lợi, Phường 1, Quận 10, TPHCM nhé."},{"speaker":"salebot","text":"Dạ cảm ơn chị! Đơn hàng đã được xác nhận, chúc chị đẹp nhé!"}]','successs',144),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé gái 10 tuổi. Bên mình có size 12-14 không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Bộ áo thun + quần thể thao cho bé gái size 13-14 vẫn còn hàng nhé. Màu hồng và xanh dương."},{"speaker":"client","text":"Mình thấy giá 450k hơi đắt. Có thể giảm còn 400k không? Mình mua 2 bộ luôn đó."},{"speaker":"salebot","text":"Dạ 450k là giá niêm yết rồi ạ, nhưng nếu bạn mua 2 bộ thì mình có thể giảm xuống 430k/1 bộ thôi ạ."},{"speaker":"client","text":"Thế à... 430k cũng hơi cao. Mình chỉ mua 1 bộ thôi, có thể 410k không?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, nếu không ưng thì mình thông cảm nhé. Cảm ơn đã quan tâm ạ!"}]','fail',145),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn ghế gỗ óc chó này đẹp quá! Mình muốn mua nhưng giá hơi cao so với dự định của mình, có thể giảm giá cho mình không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Chúng mình đang có chương trình khuyến mại 10% cho đơn hàng đầu tiên hôm nay đó ạ. Nếu bạn đặt luôn thì có thể giảm thêm 5% nữa nè!"},{"speaker":"client","text":"Thế thì mình lấy luôn bộ bàn ghế này luôn! Để mình check thông tin thanh toán nhé."},{"speaker":"salebot","text":"Dạ tuyệt vời ạ! Mình sẽ gửi mã giảm giá 15% vào email của bạn ngay bây giờ. Bạn có thể thanh toán qua chuyển khoản hoặc ví điện tử đều được ạ!"}]','successs',146),
('[{"speaker":"client","text":"Chào shop, mình thấy bộ quần áo thể thao Adidas có mã giảm giá không vậy? Mình đang cần gấp cho buổi tập ngày mai."},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại đang có mã giảm 20% cho đơn từ 500k. Bạn chọn size nào vậy?"},{"speaker":"client","text":"Size M thôi. Nhưng mình thấy trên web ghi giá 890k, vậy sau giảm giá hết bao nhiêu?"},{"speaker":"salebot","text":"Dạ sau giảm giá còn 712k thôi ạ. Bạn nhập mã ''SPORT20'' vào giỏ hàng nhé!"},{"speaker":"client","text":"Ui, vậy là 712k à? Mà mình thấy trên shopee bán cùng sản phẩm chỉ 680k kìa..."},{"speaker":"salebot","text":"Dạ bên em giao tận nơi trong 2h, shopee có thể giao muộn hơn hoặc hàng kém chất lượng ạ. Bạn cân nhắc nhé!"},{"speaker":"client","text":"Thôi vậy thì thôi, mình để dành tiền mua cái khác. Cảm ơn nhé!"}]','fail',147),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc bàn phím cơ Keychron K8, nhưng giá 2 triệu hơi đắt quá nhỉ?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại shop đang có ưu đãi giảm 10% cho đơn hàng đầu tiên, còn 1.8 triệu thôi ạ!"},{"speaker":"client","text":"Ồ, thế giao hàng trong bao lâu vậy? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ở nội thành, phí ship 30k ạ. Bạn có muốn đặt luôn không?"},{"speaker":"client","text":"Ok, mình lấy luôn chiếc K8 màu ghi ấy nhé. Địa chỉ là 123 Lê Lợi, Q.1, TP.HCM."},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Shop sẽ gửi xác nhận đơn hàng qua Zalo ngay ạ."}]','successs',148),
('[{"speaker":"client","text":"Chào bạn! Mình đang quan tâm đến chiếc điện thoại Samsung Galaxy S23 Ultra 5G, có hàng không ạ? Mình thấy giá trên web hơi cao so với lúc trước."},{"speaker":"salebot","text":"Dạ chào bạn ạ! Chúng mình vừa cập nhật phiên bản mới nhất, vẫn còn hàng ạ. Hiện tại đang có chương trình khuyến mãi giảm 10% cho khách hàng mới, bạn có muốn mình hỗ trợ đặt hàng luôn không ạ?"},{"speaker":"client","text":"À vậy à? Mình nghe nói giá giảm nhiều hơn lúc trước, có đúng không? Mình sẵn sàng mua nếu giá tốt."},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Thường thì giá gốc là 32 triệu, nhưng giờ chỉ còn 28 triệu thôi ạ. Ngoài ra còn tặng kèm ốp lưng chính hãng nữa. Bạn muốn mình hỗ trợ thanh toán online hay trả góp không?"},{"speaker":"client","text":"Tuyệt vời! Mình chọn trả góp 6 tháng đi. Cảm ơn bạn nhiều nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn có trải nghiệm mua sắm tuyệt vời. Đơn hàng của bạn sẽ được xử lý trong 15 phút nữa. Bạn vui lòng kiểm tra email để xác nhận thông tin thanh toán nhé!"}]','successs',149),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc bàn phím cơ cho công việc, nhưng ngại chi phí quá cao. Bạn có mẫu nào tầm 1 triệu không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Chúng em có bàn phím cơ Keychron K3 tầm 1.2 triệu, nhưng mẫu này hay hết hàng lắm. Có thể thay thế bằng Keychron K6 tầm 1.5 triệu không ạ?"},{"speaker":"client","text":"Hơi vượt ngân sách rồi, mình chỉ có 1 triệu thôi. Có mẫu nào khác không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, mẫu tầm 1 triệu của em thì chất lượng không ổn lắm, chỉ phù hợp cho học sinh thôi. Em có thể giới thiệu mẫu refurbished của Keychron K2 tầm 900k không ạ?"},{"speaker":"client","text":"Refurbished à? Có đảm bảo chất lượng không? Mình sợ dùng lâu hỏng."},{"speaker":"salebot","text":"Dạ sản phẩm refurbished của em đều được test kỹ lưỡng, bảo hành 6 tháng ạ. Anh/chị có thể yên tâm sử dụng!"},{"speaker":"client","text":"Thế à... nhưng mình vẫn phân vân. Để mình suy nghĩ thêm nhé!"}]','fail',150),
('[{"speaker":"client","text":"Chào! Mình muốn mua chiếc túi xách da màu nâu này, nhưng thấy giá 2 triệu hơi cao so với túi cùng loại ngoài kia. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, sản phẩm này bằng da thật nhập khẩu, giá niêm yết 2 triệu nhưng hôm nay có chương trình khuyến mại 10% cho đơn hàng đầu tiên. Bạn có muốn đặt không?"},{"speaker":"client","text":"10% thì vẫn còn 1,8 triệu, mình thấy ngoài kia có cái tương tự 1,5 triệu thôi. Đừng lo, mình sẽ cân nhắc kỹ hơn."},{"speaker":"salebot","text":"Dạ, ạ! Chúc bạn sớm tìm được sản phẩm ưng ý ạ. Cảm ơn đã ghé thăm shop!"}]','fail',151),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Genius X. Giá trên web ghi 2.590.000, vậy có thể giảm giá được không?"},{"speaker":"salebot","text":"Dạ, 2.590.000 là giá niêm yết ạ. Nếu mua kèm kem đánh răng Oral-B Pro-Expert, mình giảm 10% nhé!"},{"speaker":"client","text":"Chà, mình chỉ mua bàn chải thôi, không cần kem. Vậy 2.300.000 được không?"},{"speaker":"salebot","text":"Dạ, mình xin lỗi vì không thể giảm giá thêm ạ. Nếu bạn mua 2 sản phẩm trở lên sẽ có ưu đãi khác."},{"speaker":"client","text":"Thôi được, cảm ơn nhé. Mình quay lại sau vậy."}]','fail',152),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm chiếc áo khoác mùa đông cho bé nhà mình. Bé 5 tuổi, cao 1m10. Bạn có size nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng mình có size 12-13 (tương đương 5-6 tuổi) cho bé 1m10. Mẫu áo khoác lông vũ chống gió màu xanh dương đang hot chị nhé!"},{"speaker":"client","text":"Màu xanh dương à? Mình thích màu xanh lá hơn. Có không vậy?"},{"speaker":"salebot","text":"Dạ màu xanh lá chị ơi! Chúng mình vừa nhập mẫu mới hôm qua, còn 3 cái size 12-13 ạ. Giá 890k/chiếc, chị thấy sao?"},{"speaker":"client","text":"890k hơi đắt quá nhỉ? Bạn giảm được không? 750k mình lấy luôn."},{"speaker":"salebot","text":"Dạ chị thông cảm, giá gốc của nhà sản xuất là 1.2tr nên chúng mình không thể giảm nhiều hơn 850k ạ. Nếu chị lấy 2 cái thì 800k/chiếc nhé?"},{"speaker":"client","text":"Thôi vậy, mình chỉ lấy 1 cái thôi. 850k nhé, mình gửi địa chỉ bây giờ."},{"speaker":"salebot","text":"Dạ vâng chị, nhưng do giao hàng tận nơi phí ship 30k chị nhé. Tổng 880k ạ. Chị có thể thanh toán COD hoặc chuyển khoản ạ!"},{"speaker":"client","text":"Ui, thế à? Mình không thích ship COD lắm. Thôi thôi, thôi mình không mua nữa đâu. Thông cảm nhé!"}]','fail',153),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G. Bạn có thể tư vấn cho mình không?"},{"speaker":"salebot","text":"Dạ chào bạn! Chúng tôi có sẵn Galaxy S23 Ultra 5G màu đen và xanh dương ạ. Bạn muốn chọn màu nào?"},{"speaker":"client","text":"Mình thích màu xanh dương. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 32 triệu, nhưng hôm nay có khuyến mại giảm còn 30 triệu 500 ngàn thôi ạ."},{"speaker":"client","text":"Có bảo hành không? Bảo hành bao lâu?"},{"speaker":"salebot","text":"Dạ có ạ, bảo hành chính hãng 24 tháng. Giao hàng miễn phí trong 2h nếu bạn ở nội thành."},{"speaker":"client","text":"Ok, mình chọn màu xanh dương nhé. Địa chỉ nhận hàng là 123 Nguyễn Huệ, Quận 1."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng đã được ghi nhận. Bạn vui lòng thanh toán online hoặc COD đều được ạ. Chúc bạn mua sắm vui vẻ!"}]','successs',154),
('[{"speaker":"client","text":"Chào! Mình muốn mua bộ quần áo thể thao cho con gái 12 tuổi, size S. Bên mình có loại nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào chị! Chúng tôi có bộ áo thun + quần thể thao size S màu xanh dương, giá 499k. Nếu chị muốn xem mẫu khác, mình có thêm màu hồng và trắng."},{"speaker":"client","text":"Màu xanh được rồi. Nhưng 499k hơi đắt, bên mình có giảm giá không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, đây là giá niêm yết. Nhưng nếu chị mua kèm giày thể thao bên mình, mình giảm 50k cho bộ quần áo ạ."},{"speaker":"client","text":"Thế không mua giày thì sao? Mình chỉ cần quần áo thôi."},{"speaker":"salebot","text":"Dạ vậy chị thông cảm, chúng tôi không thể giảm thêm ạ. Nếu chị quan tâm, mình có thể thông báo khi có chương trình khuyến mại sắp tới."},{"speaker":"client","text":"Thôi vậy, cảm ơn bạn nhé. Mình nghĩ sẽ tìm nơi khác giá tốt hơn."}]','fail',155),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật của thương hiệu Coach, nhưng giá trên web hơi cao so với mình mong đợi. Cậu có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Túi Coach hiện có chương trình khuyến mại 10% cho đơn hàng trên 10 triệu, chị có thể chọn màu đen hoặc nâu nhé!"},{"speaker":"client","text":"10% thôi à? Mình thấy trên Shopee có chương trình 15% nữa, cậu có thể nâng lên được không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, mức chiết khấu của chúng em đã được quy định rồi. Nhưng nếu chị mua kèm phụ kiện như dây đeo da thì em có thể tặng chị 1 chiếc ví nhỏ ạ!"},{"speaker":"client","text":"Ok, vậy mình chọn túi màu nâu kèm phụ kiện luôn. Giao hàng trong ngày được không? Mình cần gấp!"},{"speaker":"salebot","text":"Dạ được ạ! Chị vui lòng cung cấp địa chỉ và số điện thoại để em xác nhận đơn hàng nhé. Cảm ơn chị đã ủng hộ!"}]','successs',156),
('[{"speaker":"client","text":"Chào em, mình muốn mua chiếc điện thoại Samsung Galaxy S24 Ultra. Giá trên web là 32 triệu, có giảm được không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại sản phẩm còn khuyến mại 5% nếu thanh toán bằng thẻ ngân hàng liên kết, vậy là 30.4 triệu nhé!"},{"speaker":"client","text":"5% à? Mình thấy bên shopee có giá 29 triệu luôn kìa, có đỡ hơn không?"},{"speaker":"salebot","text":"Dạ anh/chị ơi, sản phẩm trên shopee là hàng xách tay không có bảo hành chính hãng như mình nha. Còn mình bảo hành 2 năm tận nơi ạ!"},{"speaker":"client","text":"Thế à... thôi mình nghĩ lại đã. Cảm ơn nhé!"}]','fail',157),
('[{"speaker":"client","text":"Chào shop! Mình thấy áo sơ mi kẻ sọc này đẹp quá, nhưng giá 890k hơi đắt so với mình nghĩ. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện tại shop đang có chương trình giảm 10% cho khách hàng mới đó ạ. Vậy 801k là giá cuối cùng cho bạn nhé!"},{"speaker":"client","text":"Ồ, vậy thì cũng được. Nhưng mình thấy trên shopee giá rẻ hơn, có ship miễn phí không?"},{"speaker":"salebot","text":"Dạ shop mình không hỗ trợ ship miễn phí ạ, nhưng giá mình đưa đã bao gồm phí vận chuyển rồi ạ. Nếu bạn muốn ship nhanh thì phí thêm 20k thôi!"},{"speaker":"client","text":"Thế à... ừm, mình nghĩ mình sẽ suy nghĩ thêm. Cảm ơn bạn nha!"}]','fail',158),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái áo thun cotton dày của shop có size M không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen size M còn 3 cái. Bạn muốn mua không?"},{"speaker":"client","text":"Mình thích màu xanh dương nhưng giá 499k hơi đắt quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ shop có coupon 10% cho đơn từ 500k trở lên ạ. Hoặc bạn có thể chọn combo 2 áo giảm còn 850k."},{"speaker":"client","text":"Combo 2 áo thì mình lấy luôn! Nhưng giao hàng tận nơi có mất phí không?"},{"speaker":"salebot","text":"Dạ giao nội thành miễn phí ạ, ngoại thành 30k. Bạn có thể chọn nhận hàng tại nhà hoặc ship cod."},{"speaker":"client","text":"Thôi mình không mua nữa, cái áo này không hợp phong cách mình. Cảm ơn!"}]','fail',159),
('[{"speaker":"client","text":"Chào bot, mình thấy cái điện thoại Samsung Galaxy S24 Ultra trên web có khuyến mãi gì không vậy? Mình đang phân vân mua."},{"speaker":"salebot","text":"Dạ chào anh! Hiện giờ Galaxy S24 Ultra đang giảm 5 triệu từ 29.990.000 xuống 24.990.000, kèm quà tặng là tai nghe Galaxy Buds2 Pro trị giá 3 triệu. Anh có muốn mình check kho gần nhất không ạ?"},{"speaker":"client","text":"Ồ, vậy thì rẻ quá! Nhưng mình nghe nói sản phẩm này hay hết hàng lắm, có chắc chắn giao được trong tuần này không?"},{"speaker":"salebot","text":"Dạ yên tâm anh! Kho mình còn 5 chiếc, giao hàng nội thành trong 24h. Anh muốn chọn màu nào ạ? Đen hay tím?"},{"speaker":"client","text":"Mình thích màu đen. Đóng gói cẩn thận nhé, mình sợ hàng xước."},{"speaker":"salebot","text":"Dạ không vấn đề gì ạ! Anh vui lòng để lại số điện thoại và địa chỉ, mình sẽ gửi mã giảm giá 50k vận chuyển ngay cho anh luôn."}]','successs',160),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy S23 Ultra. Bạn có thể tư vấn cho mình không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Chúng mình đang có Galaxy S23 Ultra phiên bản 256GB giá 22 triệu, còn mới 100%. Anh/chị muốn đặt luôn không ạ?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có thể giảm được không? Mình thấy bên khác bán 20 triệu thôi."},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, giá niêm yết của hãng là vậy, nhưng nếu anh/chị đặt ngay hôm nay thì mình có thể giảm còn 21 triệu bao gồm quà tặng như ốp lưng và dán màn hình luôn ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị vui lòng cung cấp địa chỉ để mình báo shipper. Cảm ơn anh/ch chị đã mua hàng ạ!"}]','successs',161),
('[{"speaker":"client","text":"Chào shop, mình là Lan, đang tìm mua một chiếc điện thoại chống nước cho con trai mình. Có mẫu nào tốt không vậy?"},{"speaker":"salebot","text":"Dạ chào chị Lan ạ! Em giới thiệu Samsung Galaxy A54 5G vừa chống nước chuẩn IP67, pin khỏe, giao ngay hôm nay được chị nhé?"},{"speaker":"client","text":"À mình thấy giá hơi cao, có giảm giá không? Mà có bảo hành không?"},{"speaker":"salebot","text":"Dạ chị ơi, em đang có chương trình khuyến mại 5% cho khách hàng mới, còn bảo hành chính hãng 2 năm luôn chị nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn nhé! Địa chỉ giao là 123 Lê Lợi, Phường Bến Thành, Quận 1, TPHCM. Bao lâu nhận được hàng?"},{"speaker":"salebot","text":"Dạ chị cứ yên tâm, giao trong 2-4 tiếng trong giờ hành chính chị nhé! Em sẽ gửi tin nhắn xác nhận đơn hàng ngay sau khi chị thanh toán ạ."}]','successs',162),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái bàn chải điện Philips Sonicare DiamondClean 9000 trên web, giá 3.500.000đ quá đắt luôn. Có giảm được không?"},{"speaker":"salebot","text":"Dạ chào bạn! Cảm ơn đã quan tâm ạ! Đúng rồi, giá niêm yết là 3.500.000đ nhưng shop đang có khuyến mại giảm còn 2.990.000đ thôi, kèm theo quà tặng là 2 đầu bàn chải thay thế nữa ạ!"},{"speaker":"client","text":"À vậy à? Được đấy, mình lấy luôn 1 cái. Ship có nhanh không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ siêu tốc ạ, chỉ 2 giờ giao tận nơi! Bạn chọn màu trắng hay đen ạ?"},{"speaker":"client","text":"Trắng nhé! Cảm ơn nha."},{"speaker":"salebot","text":"Dạ không có gì ạ! Cảm ơn bạn đã mua sắm cùng shop, chúc bạn một ngày tốt lành ạ!"}]','successs',163),
('[{"speaker":"client","text":"Chào shop! Mình thấy bộ quần áo thể thao Nike Essential mới ra mắt, nhưng giá 2,999k quá đắt so với mình. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn! Bộ này đang khuyến mại 10% cho đơn từ 1,5tr, nhưng bạn có thể chọn size khác rẻ hơn 200k/chiếc ạ."},{"speaker":"client","text":"Mình chỉ cần size M thôi, size khác không vừa. Thế có cách nào khác giảm giá không?"},{"speaker":"salebot","text":"Dạ thôi tiếc quá ạ! Nếu bạn mua thêm 1 sản phẩm phụ kiện bất kỳ, shop giảm thêm 5% cho combo. Chẳng hạn như tất thể thao 199k ạ."},{"speaker":"client","text":"Không, mình không cần phụ kiện. Thôi để lúc khác vậy, cảm ơn!"}]','fail',164),
('[{"speaker":"client","text":"Chào bot! Mình đang tìm mua nồi cơm điện tử Cuckoo CMC-IH0510F, có còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Giá niêm yết 5.990.000đ, đang khuyến mại 10% nếu mua trong hôm nay."},{"speaker":"client","text":"Mình thấy giá hơi cao, có thể giảm thêm không? Mình sẵn sàng trả 5.200.000đ thôi."},{"speaker":"salebot","text":"Dạ 5.200.000đ hơi thấp so với giá sàn, em có thể giảm xuống 5.500.000đ được không ạ?"},{"speaker":"client","text":"5.500.000đ vẫn cao, mình không mua nữa đâu. Cảm ơn!"}]','fail',165),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn ghế gỗ óc chó này đẹp quá, nhưng giá 12 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ em hiểu ạ, nhưng đây là sản phẩm gỗ óc chó nguyên khối, bền gấp 3 lần gỗ công nghiệp, giá hợp lý lắm ạ!"},{"speaker":"client","text":"Mà mình thấy bên kia bán rẻ hơn 2 triệu, có cách nào giảm giá được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã ưu đãi nhất rồi ạ. Nhưng nếu bạn mua combo ghế + bàn, em giảm 500k cho bạn nhé?"},{"speaker":"client","text":"Thế à, combo có đủ size không? Mình cần bàn rộng 1m80."},{"speaker":"salebot","text":"Dạ combo có sẵn size 1m80 ạ, giao hàng tận nơi trong 3 ngày. Bạn nhận không ạ?"},{"speaker":"client","text":"Thôi mình nghĩ lại, chắc không mua nữa. Cảm ơn nhé!"}]','fail',166),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc váy dạ hội màu đỏ size M. Bên mình có size này không vậy?"},{"speaker":"salebot","text":"Dạ chào chị, váy dạ hội màu đỏ size M hiện đã hết hàng rồi chị ạ. Chị có thể chọn size L hoặc xem mẫu khác không?"},{"speaker":"client","text":"Ôi tiếc quá... Mình thích màu đỏ lắm. Có mẫu nào tương tự không? Giá khoảng 1 triệu thôi."},{"speaker":"salebot","text":"Dạ có ạ! Mẫu váy màu burgundy size M giá 1.2 triệu, giao ngay trong hôm nay. Chị xem thử nhé?"},{"speaker":"client","text":"Không được, 1.2 triệu hơi đắt. Có thể giảm còn 900k không?"},{"speaker":"salebot","text":"Dạ chị ơi, 900k hơi thấp so với giá niêm yết rồi ạ. Nếu chị lấy kèm phụ kiện thì mình giảm 100k thôi nhé?"},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn bạn nhé!"}]','fail',167),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác da nữ hiệu Calvin Klein, size S. Bạn có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Size S còn 1 chiếc thôi, màu đen và nâu. Bạn muốn đặt giữ không ạ?"},{"speaker":"client","text":"Mình thích màu nâu, nhưng giá niêm yết 2.5 triệu hơi cao quá. Bạn giảm được không?"},{"speaker":"salebot","text":"Dạ, shop mình đang có chương trình giảm 10% cho đơn hàng đầu tiên trong hôm nay ạ. Còn 2.25 triệu thôi!"},{"speaker":"client","text":"Ok, mình lấy luôn nhé. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 ngày ạ, miễn phí ship nội thành. Bạn để lại số điện thoại để shop xác nhận đơn nhé!"}]','successs',168),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc bàn chải điện Oral-B Pro 3000. Mình thấy giá hơi cao so với túi tiền, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào ạ! Chúng tôi đang có chương trình khuyến mại 10% cho sản phẩm này trong tuần này, chỉ còn 1.800.000đ thôi ạ!"},{"speaker":"client","text":"1.8 triệu vẫn hơi đắt, mình thấy trên Shopee có bán 1.5 triệu. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ giá của chúng tôi đã ưu đãi nhất rồi ạ, nếu bạn mua kèm 1 lọ kem đánh răng Oral-B Pro-Expert, mình có thể tặng kèm 1 bộ lông bàn chải thay thế ạ!"},{"speaker":"client","text":"Thôi vậy, mình không cần nữa. Cảm ơn nhé!"}]','fail',169),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách Gucci nhỏ màu đen. Có size vừa không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size vừa (23cm) đang có 3 chiếc, giao trong 2-3 ngày. Bạn muốn đặt không?"},{"speaker":"client","text":"Mình thấy giá 25 triệu hơi đắt nhỉ, có giảm giá không?"},{"speaker":"salebot","text":"Dạ ạ, nếu bạn đặt ngay hôm nay thì mình giảm 5% xuống 23,75 triệu thôi ạ!"},{"speaker":"client","text":"Ok, mình lấy vậy. Giao vào ngày mai được chứ?"},{"speaker":"salebot","text":"Dạ được ạ! Mình sẽ gửi mã vận đơn qua email sau khi thanh toán. Cảm ơn bạn đã mua sắm!"}]','successs',170),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn làm việc này đẹp quá. Mẫu này còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ còn ạ! Mẫu này đang khuyến mại 20% nè, giá chỉ còn 1.990.000đ thôi!"},{"speaker":"client","text":"Ồ, thế à? Nhưng mình thấy trên mạng giá rẻ hơn, tầm 1.700.000đ ấy."},{"speaker":"salebot","text":"Dạ thiệt tình em cũng không thể giảm thêm được rồi ạ, vì giá đã chiết khấu tối đa rồi. Nếu bạn mua kèm ghế văn phòng thì mình giảm thêm 50k nha!"},{"speaker":"client","text":"Thế à... thôi mình suy nghĩ lại rồi. Cảm ơn bạn nhé!"}]','fail',171),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một bộ quần áo thể thao cho mùa hè. Bạn có thể giới thiệu cho mình vài mẫu không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Bộ đồ thể thao thương hiệu Nike vừa nhập về mẫu mới, chị có thể tham khảo nhé. Màu sắc đa dạng: xanh dương, cam, đen. Giá từ 890.000đ - 1.200.000đ."},{"speaker":"client","text":"Mấy cái mẫu xanh dương có size S không? Mình cao 1m65, nặng 55kg."},{"speaker":"salebot","text":"Dạ có ạ! Size S vẫn còn 2 cái, chị có thể kèm theo áo thun không? Giảm 10% nếu mua bộ."},{"speaker":"client","text":"Thế áo thun ấy giá bao nhiêu? Mình chỉ mua quần thôi."},{"speaker":"salebot","text":"Dạ quần thôi ạ, giá 890.000đ. Nếu chị mua thêm áo thun thì 1.500.000đ thôi, tiết kiệm 10% luôn ạ."},{"speaker":"client","text":"Ok, mình lấy luôn bộ nhé. Bao gồm quần xanh dương size S và áo trắng. Địa chỉ giao là 123 Lê Lợi, phường Bến Thành, quận 1."},{"speaker":"salebot","text":"Dạ chị vui lòng thanh toán trước 30% ạ. Ship nội thành 30.000đ, giao trong 2 giờ. Cảm ơn chị đã mua sắm!"}]','successs',172),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua chiếc áo khoác mùa đông này. Size M có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size M vẫn còn 2 chiếc, màu xanh dương và đen. Bạn thích màu nào hơn?"},{"speaker":"client","text":"Mình thích màu xanh dương. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.299.000đ, nhưng hôm nay có khuyến mại 15% nên còn 1.104.150đ thôi ạ!"},{"speaker":"client","text":"Hơi đắt nhỉ, có thể giảm thêm không? Mình mua luôn đó."},{"speaker":"salebot","text":"Dạ, vì bạn mua sớm nên mình có thể giảm thêm 5% nữa, còn 1.039.200đ. Bao ship có 25k ạ."},{"speaker":"client","text":"Ok, mình lấy vậy. Địa chỉ giao là 123 Lê Lợi, Q.1, TP.HCM. Bao giờ nhận được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ ạ! Cảm ơn bạn đã mua hàng, chúc bạn ngày tốt lành!"}]','successs',173),
('[{"speaker":"client","text":"Chào shop, mình muốn mua đôi giày thể thao Nike Air Max 97, size 42 có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size 42 vẫn còn 2 đôi, màu đen và trắng. Bạn muốn màu nào?"},{"speaker":"client","text":"Màu đen đi, nhưng giá trên web là 3.500.000, có giảm được không?"},{"speaker":"salebot","text":"Dạ shop có ưu đãi giảm 10% cho đơn hàng đầu tiên hôm nay, còn 3.150.000 thôi ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy. Địa chỉ giao là 123 Lê Lợi, quận 1, TPHCM. Ship nhanh không?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ ạ, phí ship 20k nếu bạn không lấy hàng tại shop. Bạn có muốn thanh toán online không?"},{"speaker":"client","text":"Ok, mình thanh toán online luôn. Cảm ơn nha!"}]','successs',174),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện có 2 màu là trắng và hồng, giao hàng miễn phí nếu trên 500k."},{"speaker":"client","text":"Mình thích màu hồng nhưng giá 2 triệu rưỡi, có giảm được không?"},{"speaker":"salebot","text":"Dạ xin lỗi ạ, giá niêm yết không giảm được. Nhưng nếu bạn nhận vào cuối tuần này, mình tặng kèm 1 bộ đầu bàn chải thay thế ạ!"},{"speaker":"client","text":"Thế à... 2 triệu rưỡi hơi cao, mình thấy nơi khác bán 2 triệu 100k thôi. Giữa chừng mình không mua nữa đâu."}]','fail',175),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao cho bé gái 10 tuổi. Cỡ 140-150 có không?"},{"speaker":"salebot","text":"Dạ có ạ! Bộ quần áo thể thao cho bé gái cỡ 140-150 vẫn còn 3 màu: hồng, xanh dương và vàng. Bạn muốn chọn màu nào?"},{"speaker":"client","text":"Mình thấy cái màu hồng nhìn ngon nhất. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 599k, nhưng hôm nay có khuyến mại giảm còn 479k thôi ạ. Nếu bạn mua 2 bộ trở lên sẽ giảm thêm 10% nữa."},{"speaker":"client","text":"Hơi đắt quá, mình thấy shop khác bán 420k thôi. Bớt xuống 400k đi, mình lấy luôn 2 bộ."},{"speaker":"salebot","text":"Dạ không được ạ, mức thấp nhất shop mình bán là 450k thôi. Nếu bạn lấy 2 bộ thì mình giảm còn 450k/1 bộ nhé?"},{"speaker":"client","text":"Thôi được, vậy mình lấy 2 bộ màu hồng. Giao hàng trong ngày hôm nay được không?"},{"speaker":"salebot","text":"Dạ không ạ, do đơn hàng hơi nhiều nên giao chậm nhất là ngày mai ạ. Mình sẽ gửi mã tracking ngay khi giao hàng."},{"speaker":"client","text":"Thôi được, mình đặt vậy. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn bạn đã ủng hộ shop ạ! Chúc bạn mua sắm vui vẻ."}]','fail',176),
('[{"speaker":"client","text":"Chào bạn, mình thấy sản phẩm túi xách da cá sấu này đẹp quá. Mình là sinh viên nên có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn! Túi xách da cá sấu thật sự rất chất lượng ạ. Hiện có chương trình giảm 10% cho sinh viên, bạn chỉ cần gửi ảnh thẻ sinh viên là được ạ."},{"speaker":"client","text":"Ồ, vậy giá cuối cùng là bao nhiêu vậy? Mình thấy trên web ghi 5 triệu."},{"speaker":"salebot","text":"Dạ giá gốc 5 triệu, sau khi giảm 10% còn 4.5 triệu ạ. Ngoài ra, nếu bạn mua kèm dây đeo phụ kiện thì tặng luôn 1 hộp vệ sinh da miễn phí."},{"speaker":"client","text":"Ok, mình lấy luôn nhé! Mà giao hàng trong 2 ngày có được không? Mình cần gấp."},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng gửi ảnh thẻ sinh viên vào zalo 0987654321 để mình xử lý đơn hàng ngay. Cảm ơn bạn đã ủng hộ!"}]','successs',177),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc áo khoác mùa đông. Loại nào bền và giữ ấm tốt nhất vậy?"},{"speaker":"salebot","text":"Dạ chào anh chị! Em giới thiệu mẫu áo khoác chống gió, chống thấm của thương hiệu The North Face ạ. Loại này giữ ấm tới -10 độ và có lớp chống nước, giá 2.500.000đ."},{"speaker":"client","text":"Ồ, đắt quá nhỉ. Có giảm giá không? Mình thấy bên shop khác bán rẻ hơn."},{"speaker":"salebot","text":"Dạ em có thể giảm 5% cho anh chị nếu mua ngay hôm nay ạ! Còn tặng kèm mũ len nữa. Chỉ 2.375.000đ thôi ạ."},{"speaker":"client","text":"Ok, vậy mình lấy màu đen nhé. Ship có mất phí không?"},{"speaker":"salebot","text":"Dạ ship nội thành miễn phí chị nhé! Anh chị để lại địa chỉ và số điện thoại, em sẽ gửi thông tin xác nhận đơn hàng luôn ạ."}]','successs',178),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác mùa đông này nhưng nhìn hơi mắc quá. Có giảm giá gì không ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại shop có chương trình giảm 15% cho đơn hàng đầu tiên trong hôm nay đó ạ. Nếu chị mua 2 sản phẩm trở lên sẽ tặng kèm khăn len nữa!"},{"speaker":"client","text":"Thế áo màu ghi có size L không nhỉ? Mình thấy trên web ghi hết size rồi."},{"speaker":"salebot","text":"Dạ size L vẫn còn ạ! Chị vui lòng cung cấp địa chỉ giao hàng để mình check phí ship ưu đãi nhé?"},{"speaker":"client","text":"Mình ở quận 10, TPHCM. Ship trong ngày được không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ được ạ! Ship nội thành trong 4-6 tiếng, phí ship chỉ 20k thôi chị nhé. Chị có muốn mình gửi mã giảm giá qua zalo luôn không?"},{"speaker":"client","text":"Okie, vậy mình lấy luôn nhé! Bao gồm cả khăn len ấy nhỉ?"},{"speaker":"salebot","text":"Dạ đúng rồi chị ơi! Tổng tiền sau giảm giá là 1.280.000đ (giá gốc 1.600.000đ). Chị thanh toán COD hay chuyển khoản ạ?"}]','successs',179),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy S23 Ultra, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại Galaxy S23 Ultra phiên bản 12GB/256GB giá 25 triệu, bạn có nhu cầu mua không ạ?"},{"speaker":"client","text":"25 triệu hơi đắt quá, có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ chúng tôi có chương trình khuyến mại giảm còn 23 triệu nếu bạn thanh toán qua VNPay hoặc chuyển khoản ngân hàng ạ!"},{"speaker":"client","text":"Tốt, mình chọn màu đen, giao hàng trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng cung cấp địa chỉ nhận hàng và số điện thoại để nhân viên liên hệ giao nhận nhé."}]','successs',180),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm bàn chải đánh răng điện Philips Sonicare DiamondClean 9000. Bên mình có hàng không ạ? Mình thấy giá trên web khá cao."},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi có sẵn phiên bản trắng và đen. Giá niêm yết là 4.990.000đ, nhưng hôm nay nếu thanh toán qua VNPay sẽ giảm còn 4.750.000đ thôi ạ."},{"speaker":"client","text":"Ồ, giảm khá nhiều đấy. Còn giao hàng trong ngày không vậy?"},{"speaker":"salebot","text":"Dạ có ạ, nếu bạn ở Hà Nội hoặc TPHCM thì giao trong 2-4 tiếng. Bên mình hỗ trợ miễn phí ship cho đơn từ 2 triệu trở lên luôn ạ."},{"speaker":"client","text":"Ok, mình chọn màu trắng và thanh toán VNPay luôn nhé. Địa chỉ là 123 Lê Lợi, Quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng #SH1234567 đã được ghi nhận. Chúng tôi sẽ gửi mã OTP qua tin nhắn để xác nhận thanh toán ạ."}]','successs',181),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé nhà mình. Bé 5 tuổi, ra size 120. Có loại nào phù hợp không ạ?"},{"speaker":"salebot","text":"Dạ chào chị, bé 5 tuổi thì size 120 ạ! Hiện bên mình có bộ quần áo thể thao cotton thoáng mát, màu xanh dương và hồng, giá 350k/chiếc. Màu nào chị thích?"},{"speaker":"client","text":"Màu xanh dương được. Nhưng mình thấy giá hơi cao, có giảm giá không? Mua 2 bộ thì sao?"},{"speaker":"salebot","text":"Dạ, nếu chị mua 2 bộ thì mình giảm còn 320k/chiếc ạ. Tổng hết 640k, giao hàng miễn phí trong ngày nếu chị ở TPHCM."},{"speaker":"client","text":"Ừ, vậy mình lấy 2 bộ xanh dương nhé. Nhưng giao hàng muộn quá thì sao? Mình cần gấp."},{"speaker":"salebot","text":"Dạ, chị cứ yên tâm ạ! Nếu giao muộn quá 2 tiếng so với hẹn, bên mình sẽ hoàn tiền 10% phí ship ạ."},{"speaker":"client","text":"Ok, vậy mình đặt luôn. Nhưng mình không có thẻ ngân hàng, chuyển khoản thế nào?"},{"speaker":"salebot","text":"Dạ, chị có thể trả tiền khi nhận hàng (COD) ạ. Hoặc nếu chị có tài khoản MoMo, mình hỗ trợ thanh toán online cũng được!"},{"speaker":"client","text":"Cảm ơn nhé, mình chọn COD vậy. Địa chỉ là 123 Đường Lê Lợi, Phường 1, Quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ chị vui lòng kiểm tra kỹ sản phẩm khi nhận hàng ạ! Nếu có lỗi hay không vừa size, chị cứ phản hồi lại để mình đổi trả miễn phí trong 7 ngày ạ."},{"speaker":"client","text":"Ừ, cảm ơn bạn nhiều nhé. Hẹn gặp sau!"},{"speaker":"salebot","text":"Dạ chúc chị một ngày tốt lành ạ! Cảm ơn chị đã mua sắm cùng shop."}]','fail',182),
('[{"speaker":"client","text":"Chào bạn, mình nhìn thấy chiếc bàn chải điện Oral-B Pro 3000 trên web, nhưng giá hơi cao so với túi mình. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại sản phẩm đang khuyến mại 10% khi đặt trong hôm nay, chị có thể nhận thêm quà tặng là 2 đầu bàn chải thay thế nữa."},{"speaker":"client","text":"10% thôi à? Mình thấy bên kia bán rẻ hơn 500k nữa. Không thể giảm thêm được không?"},{"speaker":"salebot","text":"Dạ thật tiếc là chúng tôi không thể giảm thêm ạ. Nhưng chị sẽ được miễn phí vận chuyển và bảo hành 2 năm trọn gói, rất tiết kiệm chi phí lâu dài đó ạ."},{"speaker":"client","text":"Thế à... thôi thì cũng tạm được. Mà mình ở xa, giao hàng trong bao lâu vậy?"},{"speaker":"salebot","text":"Dạ trong 3-5 ngày làm việc chị nhé! Chị có thể thanh toán khi nhận hàng hoặc chuyển khoản trước đều được."},{"speaker":"client","text":"Ok, mình chọn thanh toán khi nhận. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn chị đã ủng hộ ạ! Chúc chị một ngày tốt lành."}]','fail',183),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé gái 10 tuổi. Có size 120 không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Bọn em vừa nhập về bộ Adidas 3 mảnh, màu hồng và xanh dương. Giá niêm yết 499k, giảm còn 399k nếu mua trong hôm nay."},{"speaker":"client","text":"Ồ, thế có giảm nữa không? Mình thấy bên kia bán 350k thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá này đã là ưu đãi nhất rồi ạ. Nếu bạn mua kèm giày thể thao, em có thể giảm thêm 10k nữa ạ."},{"speaker":"client","text":"Thế à, tiếc quá. Mình không cần giày đâu. Cảm ơn nhé!"}]','fail',184),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái áo khoác da này đẹp quá. Mình mặc size L, bạn kiểm tra còn size không?"},{"speaker":"salebot","text":"Dạ size L vẫn còn 1 chiếc ạ! Màu đen và nâu. Bạn muốn màu nào?"},{"speaker":"client","text":"Màu đen đi. Giá bao nhiêu vậy? Mình thấy trên mạng rẻ hơn 1 chút."},{"speaker":"salebot","text":"Dạ giá niêm yết 2.990.000đ, nhưng hôm nay giảm còn 2.690.000đ thôi ạ. Free ship nữa!"},{"speaker":"client","text":"Thế không giảm nữa à? 2.5 triệu được không?"},{"speaker":"salebot","text":"Dạ không ạ, mức này đã là giá tốt nhất rồi. Bạn lấy luôn không?"},{"speaker":"client","text":"Thôi tiếc quá, mình mua sau vậy. Cảm ơn bạn nhé!"}]','fail',185),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác denim nữ hiệu Levi''s 501, size S có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size S còn 3 chiếc, giao trong 2-3 ngày. Bạn muốn màu nào? Màu xanh classic hay màu đen?"},{"speaker":"client","text":"Màu xanh classic đi. Giá bao nhiêu thế? Mình thấy trên web ghi 1.299.000đ nhưng hay có sale không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.299.000đ, nhưng hôm nay có khuyến mãi 15% cho đơn hàng đầu tiên. Chốt 1.100.000đ thôi ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn. Bao ship phí thế? Nội thành Hà Nội nhé."},{"speaker":"salebot","text":"Ship nội thành 35k, miễn phí ship từ 1 triệu ạ. Tổng cộng 1.135.000đ. Bạn để lại địa chỉ và số điện thoại nhận hàng nhé!"}]','successs',186),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua bộ quần áo thể thao cho bé gái 10 tuổi, size 130. Bên shop có không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập lô mới bộ đồ thể thao 2 mảnh có họa tiết hoa hồng, màu hồng và xanh dương. Bạn muốn xem ảnh mẫu không?"},{"speaker":"client","text":"Ừ, gửi ảnh đi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 399.000đ, nhưng hôm nay khuyến mại còn 299.000đ thôi ạ!"},{"speaker":"client","text":"Ồ, đắt quá. Bán 250.000đ được không? Mình lấy luôn 2 bộ"},{"speaker":"salebot","text":"Dạ xin lỗi bạn, giá sốc thế này rồi ạ. Chúng mình không thể giảm thêm được ạ."},{"speaker":"client","text":"Thế à... Thôi để mình nghĩ lại vậy. Cảm ơn nhé!"}]','fail',187),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua chiếc điện thoại Samsung Galaxy A55 5G, bạn có thể tư vấn cho mình không? Mình thấy giá trên web hơi cao so với những cửa hàng khác."},{"speaker":"salebot","text":"Chào bạn ạ! Dạ Galaxy A55 5G của mình đang có giá 11.990.000đ, nhưng nếu bạn mua trong hôm nay thì mình có thể giảm xuống 11.500.000đ kèm theo quà tặng là ốp lưng chính hãng nha!"},{"speaker":"client","text":"Ồ, vậy có kèm theo sạc nhanh không ạ? Mình nghe nói sản phẩm này không đi kèm sạc."},{"speaker":"salebot","text":"Dạ có ạ! Gói quà tặng bao gồm cả sạc nhanh 25W chính hãng luôn nè. Nếu đồng ý mình sẽ hỗ trợ giao hàng miễn phí trong 2 giờ tới cho bạn."},{"speaker":"client","text":"Ok, vậy mình chọn màu đen nhé! Bao lâu thì nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ màu đen vừa hết hàng, nhưng màu xanh dương vẫn còn và giao ngay trong 1 giờ. Bạn có thể đổi màu không ạ?"},{"speaker":"client","text":"Thôi được, mình chọn xanh dương vậy. Cảm ơn bạn nhiều nha!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Đơn hàng của bạn đã được xác nhận. Chúc bạn một ngày vui vẻ!"}]','successs',188),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua một chiếc điện thoại thông minh tầm 10 triệu. Có mẫu nào mới và tốt không?"},{"speaker":"salebot","text":"Dạ chào chị! Em giới thiệu chị mẫu OPPO Reno11 vừa ra mắt ạ, giá chỉ 9,99 triệu thôi ạ. Chị thích màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương. Còn có khuyến mãi gì không? Giảm giá hay quà tặng?"},{"speaker":"salebot","text":"Dạ có ạ! Chị đặt trong hôm nay sẽ được tặng ốp lưng chống sốc và giảm thêm 200k nữa ạ. Tổng còn 9,79 triệu thôi!"},{"speaker":"client","text":"Thế giao hàng trong bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao nhanh trong 2 giờ nếu chị ở TP.HCM ạ! Chị có thể thanh toán COD hoặc chuyển khoản đều được ạ."},{"speaker":"client","text":"Ok, mình đặt luôn nhé! Bao gồm cả quà tặng luôn chứ?"},{"speaker":"salebot","text":"Dạ tất nhiên rồi chị! Em sẽ gửi đơn hàng ngay cho chị ạ. Cảm ơn chị đã tin tưởng mua sắm cùng chúng tôi!"}]','successs',189),
('[{"speaker":"client","text":"Chào shop! Mình thấy áo sơ mi linen của shop có mẫu đẹp lắm, nhưng giá 1.200k hơi đắt so với mình dự định 1 triệu thôi. Có thể giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, sản phẩm linen chất lượng cao nên giá thế ạ. Nhưng nếu bạn mua 2 cái, shop giảm 5% cho ạ!"},{"speaker":"client","text":"Thế à, nhưng mình chỉ cần 1 cái. Để mình suy nghĩ lại rồi quay lại ạ. Cảm ơn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ, hẹn gặp lại sau."}]','fail',190),
('[{"speaker":"client","text":"Chào bạn ơi, mình đang tìm mua chiếc áo khoác nữ mùa đông này. Size M có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu áo này đang khuyến mãi 30% cho tuần lễ đầu tiên. Bạn muốn mình gửi link thanh toán luôn không?"},{"speaker":"client","text":"Ồ, giá tốt quá! Nhưng mình thấy trên mạng có nơi bán rẻ hơn 100k nữa. Bạn có thể giảm giá thêm không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, mức khuyến mãi này đã là ưu đãi lớn nhất rồi ạ. Nhưng nếu bạn mua ngay trong hôm nay, mình sẽ tặng kèm bạn 1 đôi tất len trị giá 150k luôn ạ!"},{"speaker":"client","text":"Thế à? Được rồi, mình chọn size M luôn. Bạn gửi link thanh toán cho mình nhé!"}]','successs',191),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bàn chải điện Philips Sonicare, có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại đang khuyến mại 20% cho sản phẩm này, chỉ còn 2 triệu 6 trăm ngàn thôi ạ."},{"speaker":"client","text":"Ồ, vậy có tặng kèm gì không? Mình thấy quảng cáo tặng kem đánh răng nữa chứ?"},{"speaker":"salebot","text":"Dạ có ạ! Bao gồm 1 hộp kem đánh răng trị giá 150k, free ship toàn quốc luôn nha."},{"speaker":"client","text":"Tốt quá, mình lấy luôn 1 cái. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, bạn có thể chọn giờ nhận hàng trong app để tiện nha!"}]','successs',192),
