('[{"speaker":"client","text":"Chào shop, mình thấy cái bàn phím cơ Keychron K8 giá 2.500.000 có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn, hôm nay shop đang có khuyến mãi 10% cho sản phẩm này, chỉ còn 2.250.000 thôi ạ!"},{"speaker":"client","text":"Mà mình nghe nói bàn phím này hay bị lỗi switch, có đúng không vậy?"},{"speaker":"salebot","text":"Dạ không ạ, sản phẩm chính hãng 100%, bảo hành 2 năm, lỗi switch rất hiếm gặp. Bạn yên tâm nhé!"},{"speaker":"client","text":"Thế bảo hành bao lâu cho switch vậy? Mình thấy nhiều nơi bảo hành chỉ 3 tháng."},{"speaker":"salebot","text":"Dạ bảo hành switch full 2 năm ạ, shop cam kết chất lượng. Nếu lỗi gì shop hỗ trợ đổi trả miễn phí luôn."},{"speaker":"client","text":"Ok, thế mình đặt tạm 1 cái thôi. Nhưng giao hàng chậm thì mình hủy nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn của bạn đã được xử lý, giao dự kiến 3-5 ngày. Shop sẽ gửi mã tracking qua Zalo ngay khi ship."},{"speaker":"client","text":"Thôi được, mình chờ vậy. Nhưng nếu giao chậm quá mình sẽ không nhận đâu nhé!"},{"speaker":"salebot","text":"Dạ xin lỗi vì sự bất tiện ạ, shop cam kết giao đúng hẹn. Cảm ơn bạn đã ủng hộ!"}]','fail',199),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác nữ hiệu Zara, size M có không vậy?"},{"speaker":"salebot","text":"Dạ có đủ size M ạ, màu xanh lá và đen nè. Bạn thích màu nào hơn?"},{"speaker":"client","text":"Mình thích màu đen nhưng giá hơi cao so với dự tính. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ hôm nay đang khuyến mãi 10% cho sản phẩm này, chỉ còn 990k thôi ạ!"},{"speaker":"client","text":"990k vẫn hơi đắt, mình thấy bên shop khác bán 850k thôi..."},{"speaker":"salebot","text":"Dạ shop mình không thể giảm thêm ạ, nhưng giao hàng miễn phí toàn quốc và đổi trả thoải mái 30 ngày nè."},{"speaker":"client","text":"Thôi vậy thì thôi, mình qua shop khác xem rồi quay lại sau. Cảm ơn nha!"}]','fail',200),
