('[{"speaker":"client","text":"Chào anh, mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra 5G trên web có khuyến mại gì không vậy? Mình muốn mua tặng vợ."},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện sản phẩm đang giảm 5 triệu, kèm quà tặng là tai nghe Galaxy Buds2 Pro trị giá 3 triệu. Nếu chị mua trong hôm nay, giao hàng miễn phí trong 2 tiếng."},{"speaker":"client","text":"Ồ, vậy giá cuối là bao nhiêu vậy? Mình thấy trên mạng bên khác còn rẻ hơn."},{"speaker":"salebot","text":"Dạ giá niêm yết 32 triệu, sau giảm còn 27 triệu, kèm quà tặng nữa ạ. Chị có thể trả góp 0% trong 12 tháng nếu muốn."},{"speaker":"client","text":"Vậy thôi, mình lấy. Ship tận nhà luôn nhé, địa chỉ mình là 123 Lê Lợi, Quận 1."},{"speaker":"salebot","text":"Dạ vâng chị! Đơn hàng của chị đã được ghi nhận. Chúc chị một ngày tốt lành ạ!"}]','successs',202),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho con gái 12 tuổi. Size 140-146 thôi. Bạn có không?"},{"speaker":"salebot","text":"Dạ có ạ! Em vừa kiểm tra thấy bộ đồ thể thao màu hồng size 140-146 còn 3 cái. Màu xanh dương size 146 hết rồi ạ."},{"speaker":"client","text":"Màu hồng thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 499.000đ ạ, đã bao gồm VAT. Nếu bạn mua 2 bộ trở lên sẽ giảm 5% ạ."},{"speaker":"client","text":"Ồ, đắt quá. Bạn giảm còn 450k được không? Mình lấy luôn 2 bộ."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá sàn không thể giảm hơn nữa ạ. Nhưng nếu bạn lấy 2 bộ, em có thể tặng kèm 1 đôi vớ thể thao ạ."},{"speaker":"client","text":"Thôi vậy, mình lấy 2 bộ đi. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ ạ, em đã ghi nhận đơn hàng! Giao trong 2 giờ nếu bạn ở Hà Nội ạ. Cảm ơn bạn đã ủng hộ ạ!"}]','fail',203),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc áo khoác này đẹp nhưng giá 1.500.000 đồng hơi cao so với mình. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ, ạ có chương trình khuyến mại 10% nếu bạn mua trong hôm nay, còn 1.350.000 đồng thôi ạ!"},{"speaker":"client","text":"Mình chỉ có 1.200.000 thôi, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ, ạ xin lỗi ạ, mức giá thấp nhất là 1.300.000 ạ. Nếu bạn không hài lòng, mình có thể giới thiệu mẫu khác ạ."},{"speaker":"client","text":"Thôi vậy, cảm ơn bạn nhé. Mình sẽ suy nghĩ thêm."}]','fail',204),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn gỗ óc chó này đẹp quá, nhưng giá 5 triệu hơi đắt nhỉ? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh chị ạ! Bàn này nhập khẩu 100%, giá niêm yết 5 triệu nhưng hôm nay ưu đãi chỉ còn 4,5 triệu thôi ạ!"},{"speaker":"client","text":"4,5 triệu vẫn hơi cao, em có thể giảm thêm không? Mình thấy trên shopee giá 4 triệu rưỡi thôi."},{"speaker":"salebot","text":"Dạ anh chị thông cảm ạ, giá sỉ 4,5 triệu rồi ạ, em không thể giảm thêm được ạ. Nhưng giao hàng tận nơi miễn phí trong nội thành ạ!"},{"speaker":"client","text":"Thôi được, thế giao vào ngày mai được không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ ạ! Em sẽ sắp xếp giao vào sáng mai sớm nhất có thể ạ. Anh chị để lại số điện thoại và địa chỉ chi tiết nhé!"}]','fail',205),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé gái 7 tuổi. Có size 120 không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập mẫu mới với giá 399k/bộ. Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Màu xanh dương đi. Nhưng giá hơi cao, có giảm không?"},{"speaker":"salebot","text":"Dạ thưa bạn, đây là giá niêm yết ạ. Nếu bạn mua 2 bộ trở lên thì giảm 10% nha!"},{"speaker":"client","text":"Hôm nay mình chỉ mua 1 bộ thôi. Thôi để lần sau vậy, cảm ơn bạn."}]','fail',206),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn ghế gỗ óc chó này đẹp quá! Mình muốn mua nhưng giá có hơi cao so với ngân sách của mình. Bạn có thể giảm giá được không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc bàn ghế này đang được khuyến mại 10% cho đơn hàng đầu tiên, chị có thể nhập mã SALE10 để nhận ngay nhé!"},{"speaker":"client","text":"À vậy à? Thế nếu mình mua kèm theo bộ rèm cửa thì có ưu đãi gì thêm không?"},{"speaker":"salebot","text":"Dạ nếu chị mua kèm rèm cửa (giá 800k) thì mình sẽ tặng luôn dịch vụ lắp đặt miễn phí luôn chị nhé! Còn nếu chị chọn combo trọn gói bàn ghế + rèm + lắp đặt thì được giảm thêm 5% nữa!"},{"speaker":"client","text":"Ok, mình chọn combo trọn gói luôn đi! Địa chỉ giao là 123 Đường Lê Lợi, Phường 1, Quận 3, TP.HCM. Bao lâu thì nhận hàng được?"},{"speaker":"salebot","text":"Dạ chị yên tâm, đơn hàng sẽ giao trong vòng 3-5 ngày làm việc ạ! Em xin phép gửi mã đơn hàng qua email chị nhé. Cảm ơn chị đã ủng hộ!"}]','successs',207),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác thể thao này. Size S còn hàng không nhỉ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Size S vẫn còn 5 cái, chị mặc size gì thường vậy ạ?"},{"speaker":"client","text":"Mình mặc size S thôi. Giá niêm yết 1.299k, có giảm được không? Mua 1 cái thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, giá đã niêm yết rồi ạ. Nhưng nếu chị thanh toán online giờ, mình giảm 5% cho chị nhé!"},{"speaker":"client","text":"Ok, vậy mình chọn màu đen nhé. Ship tận nơi luôn đúng không?"},{"speaker":"salebot","text":"Dạ đúng rồi chị! Giao trong 2-3 ngày, phí ship 20k chị nhé. Chị để lại địa chỉ đi ạ!"},{"speaker":"client","text":"Mình ở quận 1, địa chỉ 123 Lê Lợi. Nhận tiền mặt luôn nhé."},{"speaker":"salebot","text":"Dạ em ghi nhận đơn hàng rồi ạ! Chị kiểm tra lại: áo khoác thể thao size S màu đen, 1.234k (giảm 5%), ship 20k. Tổng 1.254k. Đúng không chị?"},{"speaker":"client","text":"Đúng rồi, cảm ơn bạn nhé!"}]','successs',208),
