('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ Casio Edifice mới, có loại nào đang khuyến mại không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! EFR-S567D-1A2V đang giảm 20% chỉ còn 2.400.000đ, giao hàng miễn phí trong 2 ngày."},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm thêm không? Mình thấy nơi khác bán 2.200.000đ thôi."},{"speaker":"salebot","text":"Dạ, nếu bạn mua kèm dây da phụ kiện thì mình có thể giảm xuống 2.300.000đ, giao luôn hôm nay luôn ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn cái này đi. Bao giờ nhận được hàng?"},{"speaker":"salebot","text":"Dạ, đơn hàng đã được xử lý, bạn sẽ nhận trong tối nay ạ. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',218),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập lô mới hôm qua, giao tận nơi trong 2 ngày. Bạn muốn màu xanh dương hay xám?"},{"speaker":"client","text":"Mình thích xanh dương. Giá bao nhiêu vậy? Có khuyến mại gì không?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 2.490.000đ, nhưng hôm nay giảm còn 1.990.000đ thôi ạ! Đi kèm còn tặng 2 đầu bàn chải thay thế nữa."},{"speaker":"client","text":"Hơi đắt so với mình mong đợi, có thể giảm thêm không? Mình thấy bên kia bán 1.850.000đ."},{"speaker":"salebot","text":"Dạ, mình có thể giảm xuống 1.950.000đ được ạ. Đây là mức giá tốt nhất rồi vì sản phẩm mới nhập và đảm bảo chính hãng 100%."},{"speaker":"client","text":"Ok, mình mua vậy. Bao gồm phí ship không?"},{"speaker":"salebot","text":"Dạ bao gồm phí ship nội thành ạ! Bạn để lại địa chỉ và số điện thoại để mình xử lý đơn hàng nhé."}]','successs',219),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không nhỉ?"},{"speaker":"salebot","text":"Dạ có ạ! Màu trắng và đen đều có sẵn. Bạn muốn giao trong ngày hay lịch hẹn cụ thể?"},{"speaker":"client","text":"Mình thấy giá niêm yết 2.500.000đ, có giảm giá không vậy? Mình thấy chỗ khác có giá 2.200.000đ."},{"speaker":"salebot","text":"Dạ, giá niêm yết là 2.500.000đ nhưng nếu bạn mua hôm nay thì mình giảm còn 2.350.000đ thôi ạ. Đi kèm còn tặng bàn chải thay đầu mới nữa!"},{"speaker":"client","text":"Ok, mình lấy vậy. Nhưng giao trong 2 tiếng được không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng cung cấp địa chỉ và số điện thoại để mình xác nhận đơn hàng nhé. Cảm ơn bạn đã mua sắm cùng shop!"}]','successs',220),
('[{"speaker":"client","text":"Chào em, mình muốn mua một chiếc điện thoại thông minh tầm 10 triệu thôi. Có gì giới thiệu không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em giới thiệu anh/chị chiếc Xiaomi Redmi Note 12 Pro 5G giá 9,99 triệu, màn hình 6.67AMOLED, pin 5000mAh, camera 108MP – rất ổn cho nhu cầu hằng ngày ạ!"},{"speaker":"client","text":"Ui, camera 108MP nghe cũng ổn. Nhưng 10 triệu là trần rồi, em giảm giá được không?"},{"speaker":"salebot","text":"Dạ anh/chị đăng ký nhận voucher 500k ngay hôm nay là em có thể giảm xuống 9,49 triệu ạ! Kèm quà tặng là ốp lưng chống sốc luôn nha."},{"speaker":"client","text":"Ok, vậy mình chọn màu xanh dương nhé. Giao hàng trong ngày được không em?"},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị để lại số điện thoại và địa chỉ, em sẽ xác nhận đơn hàng ngay ạ. Cảm ơn anh/chị đã mua sắm cùng shop!"}]','successs',221),
