('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc váy dạ hội màu đỏ size 36, shop có không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ, em vừa kiểm tra thấy vẫn còn 2 sản phẩm size 36 trong kho. Chị muốn giao trong ngày hôm nay hay mai ạ?"},{"speaker":"client","text":"Hôm nay giao được không? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Được ạ, chị chọn giao thường hay tiết kiệm? Nếu giao thường phí ship 30k, tiết kiệm 20k ạ."},{"speaker":"client","text":"Tiết kiệm thôi. Giá chiếc váy bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.890.000đ, nhưng hôm nay em có khuyến mại giảm 10% cho chị ạ. Còn 1.701.000đ thôi."},{"speaker":"client","text":"Ok, mình lấy luôn. Địa chỉ giao là 123 Nguyễn Huệ, Quận 1, TPHCM. Nhớ bọc hàng cẩn thận nhé!"},{"speaker":"salebot","text":"Dạ chị yên tâm ạ! Em sẽ giao trong 2 tiếng nữa. Chúc chị vui vẻ."}]','successs',232),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua một chiếc túi xách da thật, có size vừa phải thôi nhé, tầm 2-3 triệu thôi ấy."},{"speaker":"salebot","text":"Dạ chào chị ạ! Túi da thật chị ưng hãng nào ạ? Nếu chị thích phong cách cổ điển thì em có mẫu túi da bò nguyên miếng của Ý, size 25x30cm, giá 2,9 triệu ạ."},{"speaker":"client","text":"Ôi hay quá! Mình thích màu nâu đậm ấy. Nhưng giá hơi cao so với dự định, có giảm được không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, đây là da thật nguyên miếng nên giá hơi cao. Nhưng nếu chị mua trong hôm nay, em giảm 100k cho chị nhé! Còn 2,8 triệu thôi ạ."},{"speaker":"client","text":"Thế thì mình lấy luôn! Giao trong ngày được không? Mình ở Quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ gửi mã giảm giá vào tin nhắn cho chị, chị check điện thoại nhé. Cảm ơn chị đã ủng hộ!"}]','successs',233),
('[{"speaker":"client","text":"Chào em, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G. Bạn có thể tư vấn giá tốt nhất cho mình không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Máy Galaxy S23 Ultra 5G hiện có giá 29.990.000đ, nhưng nếu anh/chị mua trong hôm nay thì em có thể giảm còn 28.500.000đ kèm quà tặng là tai nghe không dây trị giá 1 triệu."},{"speaker":"client","text":"Ồ, giá tốt đấy! Nhưng mình thấy trên shopee giá thấp hơn 500k, sao ở đây lại cao vậy?"},{"speaker":"salebot","text":"Dạ anh/chị ơi, giá trên shopee có thể là hàng cũ hoặc trôi nổi, còn bên em cam kết hàng chính hãng mới 100%, bảo hành 24 tháng đầy đủ. Nếu anh/chị lo giá thì em có thể giảm thêm 200k nữa, còn 28.300.000đ thôi ạ!"},{"speaker":"client","text":"Được rồi, mình chọn màu đen đi. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Dạ anh/chị vui lòng để lại địa chỉ, em sẽ giao trong vòng 2 giờ nếu ở nội thành Hà Nội ạ! Em gửi link thanh toán qua zalo cho anh/chị nhé."}]','successs',234),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho con trai 12 tuổi. Size 150-152 thôi nhé."},{"speaker":"salebot","text":"Dạ chào ạ! Bộ đồ thể thao nam size 150-152 của thương hiệu Nike có sẵn ạ. Màu xanh dương và đen, bạn muốn xem ảnh không?"},{"speaker":"client","text":"Mình thích màu xanh dương nhưng giá bao nhiêu thế? Đắt quá thì thôi."},{"speaker":"salebot","text":"Dạ giá niêm yết 499k ạ, nhưng hôm nay có khuyến mại 20% nên còn 399k thôi ạ. Giao tận nhà miễn phí luôn."},{"speaker":"client","text":"399k à? Mà mình thấy trên shopee bán cùng sản phẩm chỉ 350k có khi mình qua đó mua cho tiện."},{"speaker":"salebot","text":"Dạ shopee có thể rẻ hơn nhưng mình cam kết sản phẩm chính hãng 100% ạ. Nếu không vừa size, mình đổi trả miễn phí trong 7 ngày."},{"speaker":"client","text":"Thế à... thôi mình suy nghĩ đã. Cảm ơn nhé!"}]','fail',235),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua chiếc áo khoác nữ hiệu The North Face, size M có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu áo khoác nữ The North Face size M còn 5 cái, màu xanh dương và đen. Bạn muốn xem ảnh chi tiết không ạ?"},{"speaker":"client","text":"À mình thích màu đen nhưng nhìn ảnh thấy hơi rộng, không chặt vừa. Có size S không?"},{"speaker":"salebot","text":"Dạ size S còn 2 cái ạ, nhưng màu đen hết hàng rồi. Mình gửi link sản phẩm size S màu xanh dương nhé? Giá vẫn thế ạ."},{"speaker":"client","text":"Thế ạ, mình không thích màu xanh. Bao giờ size S màu đen về?"},{"speaker":"salebot","text":"Dạ theo thông báo từ hãng thì tuần sau size S màu đen mới về ạ. Bạn có thể đặt trước không? Mình cam kết giao đúng hẹn."},{"speaker":"client","text":"À tuần sau mình bận rồi, thôi không mua nữa. Cảm ơn bạn nhé."}]','fail',236),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật của thương hiệu Coach. Có size nhỏ không nhỉ?"},{"speaker":"salebot","text":"Dạ có ạ! Size nhỏ nhất là 25cm, màu nâu hạt dẻ đang giảm 15% nè bạn. Bạn muốn order luôn không?"},{"speaker":"client","text":"Mình thích nhưng giá 12 triệu hơi cao, có thể giảm thêm không? Mình thấy bên kia bán giá 10 triệu đó."},{"speaker":"salebot","text":"Dạ thật tình ạ, 12 triệu là giá niêm yết nhưng nếu bạn mua kèm phụ kiện da (giá 300k) thì mình giảm còn 11 triệu 500k nha!"},{"speaker":"client","text":"Ok vậy đi, mình lấy luôn cái túi size 25cm nâu hạt dẻ kèm phụ kiện. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Mình gửi link thanh toán qua Zalo cho bạn nhé. Cảm ơn bạn đã mua sắm cùng shop!"}]','successs',237),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra. Bạn có khuyến mại gì không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Hiện tại chúng mình đang có combo S23 Ultra kèm ốp lưng + sạc nhanh chính hãng, giảm 2 triệu so với giá niêm yết ạ!"},{"speaker":"client","text":"2 triệu à? Vậy mình lấy luôn đi. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu anh/chị ở Hà Nội, 1 ngày cho các tỉnh khác ạ. Anh/chị để lại địa chỉ và số điện thoại để shop liên hệ nhé!"},{"speaker":"client","text":"Ok, mình để địa chỉ: 123 Phố Huế, Hai Bà Trưng, HN. Số điện thoại: 0987654321. Tiền ship bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ ship nội thành 25k, tỉnh xa 35k ạ. Tổng cộng sau giảm giá là 29,99 triệu, ship 25k. Thanh toán COD được ạ!"},{"speaker":"client","text":"Được rồi, mình chọn COD. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn anh/chị đã mua sắm! Shop sẽ giao hàng nhanh nhất có thể ạ. Chúc anh/chị một ngày tốt lành!"}]','successs',238),
('[{"speaker":"client","text":"Chào bạn! Mình thấy cái bàn làm việc gỗ óc chó này đẹp quá, nhưng giá 5 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ, sản phẩm có ưu đãi 10% nếu thanh toán bằng thẻ ngân hàng ạ, còn 4.5 triệu thôi!"},{"speaker":"client","text":"Hmm, mình không có thẻ ngân hàng đâu. Có giảm giá khác không?"},{"speaker":"salebot","text":"Dạ không ạ, đây là giá tốt nhất rồi ạ. Bên mình cam kết chất lượng gỗ 100% óc chó nhập khẩu ạ!"},{"speaker":"client","text":"Thôi được, mình mua vậy. Nhưng giao hàng tận nơi chứ?"},{"speaker":"salebot","text":"Dạ có ạ! Phí ship 50k, tổng 4.55 triệu ạ. Địa chỉ nhận hàng là?"},{"speaker":"client","text":"À mình đổi ý rồi, thôi không mua nữa. Cảm ơn nha!"}]','fail',239),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật của thương hiệu Gucci, nhưng giá trên web hơi cao quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Túi Gucci hiện tại đang khuyến mại 10% cho đơn hàng đầu tiên, chị có thể nhập mã: GIAM10 khi thanh toán."},{"speaker":"client","text":"10% thì vẫn còn khá cao so với giá niêm yết. Mà túi này có bảo hành không? Bảo hành bao lâu vậy?"},{"speaker":"salebot","text":"Chị yên tâm ạ! Túi có bảo hành chính hãng 2 năm, nhưng giá gốc đã bao gồm VAT nên không thể giảm thêm được nữa ạ."},{"speaker":"client","text":"Thế à... thế mình cân nhắc thêm chút. Cảm ơn nhé!"}]','fail',240),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc đồng hồ Casio Edifice EFR-S567D-1A2V. Giá trên web mình thấy hơi cao, có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Đồng hồ này hiện đang khuyến mại 10% cho đơn hàng đầu tiên trong hôm nay. Anh/chị có muốn mình check mã giảm giá không?"},{"speaker":"client","text":"Mình thấy giá vẫn còn hơi cao so với dự định. Có thể giảm thêm được không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, mức giảm 10% là mức tối đa mình có thể hỗ trợ. Nếu anh/chị mua kèm phụ kiện (dây da hoặc hộp cứng) thì mình có thể tặng kèm 1 món nhỏ."},{"speaker":"client","text":"Thôi vậy, mình không quan tâm phụ kiện nữa. Cảm ơn nhé!"}]','fail',241),
('[{"speaker":"client","text":"Chào shop, mình đang muốn mua chiếc áo khoác len nữ hiệu Zara, size M còn không ạ? Mình thấy trên web ghi giảm giá 30% nhưng không biết còn hiệu lực không?"},{"speaker":"salebot","text":"Dạ chào chị, áo khoác len Zara size M vẫn còn ạ! Giảm giá 30% chỉ áp dụng đến hết hôm nay thôi chị nhé. Chị muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu ghi nhưng hơi lo là len dễ bị xù lông quá. Mà giá 1.299k sau giảm còn 909k, hơi chát so với mình mong đợi. Có cách nào giảm thêm không?"},{"speaker":"salebot","text":"Dạ chị ơi, shop có voucher giảm thêm 5% cho đơn từ 800k chị nhé! Như vậy giá cuối còn 863k thôi. Hoặc chị có thể chọn màu khác rẻ hơn 1 chút ạ?"},{"speaker":"client","text":"Thế à? Vậy mình chọn màu ghi vậy. Nhưng 863k vẫn hơi cao so với túi tiền mình. Có thể ship COD được không? Mình sợ lừa đảo lắm..."},{"speaker":"salebot","text":"Dạ shop có COD ạ! Nhưng chị phải thanh toán trước 50% để xác nhận đơn thôi chị nhé. Hoặc chị có thể qua cửa hàng mình xem trực tiếp ạ?"},{"speaker":"client","text":"Thế à... mình nghĩ rồi nhé. Cảm ơn shop nhiều!"}]','fail',242),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc bàn chải điện Oral-B Genius X, có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu trắng và hồng đều còn, giao trong 2 giờ nếu bạn ở TP.HCM."},{"speaker":"client","text":"Mình thấy giá niêm yết 2.590.000đ, có giảm giá không thế?"},{"speaker":"salebot","text":"Dạ hôm nay có chương trình khuyến mại 10% cho đơn hàng đầu tiên, còn 2.331.000đ thôi ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Phường Bến Nghé, Quận 1."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng sẽ được giao trong 1 giờ nữa ạ. Chúc bạn một ngày tốt lành!"}]','successs',243),
('[{"speaker":"client","text":"Chào bạn, mình nhìn thấy chiếc laptop gaming Acer Nitro 5 trên web. Nó có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại đang khuyến mãi 15% cho phiên bản i5-12450H, giá chỉ còn 18 triệu thôi!"},{"speaker":"client","text":"18 triệu hơi cao, mình thấy nơi khác bán 17 triệu thôi. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ nếu bạn đặt ngay hôm nay thì mình có thể giảm xuống 17.5 triệu ạ, kèm quà tặng là chuột gaming!"},{"speaker":"client","text":"Ok, mình lấy luôn vậy. Bao lâu giao được ạ?"},{"speaker":"salebot","text":"Dạ giao tận nơi trong 2 tiếng ạ, anh check địa chỉ giúp mình nhé!"}]','successs',244),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn làm việc này đẹp quá! Còn màu nâu gỗ kia có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Bàn gỗ óc chó màu nâu hiện còn 2 chiếc. Bạn muốn đặt giữ hay giao tận nhà?"},{"speaker":"client","text":"Giao tận nhà thôi. Giá niêm yết 3.500.000, có giảm được không? Mình thấy bên kia bán 3.200.000"},{"speaker":"salebot","text":"Dạ em check lại giá cho bạn nhé! Được 3.300.000 ạ, giao miễn phí tận nhà luôn. Còn nếu bạn lấy kèm ghế văn phòng thì giảm thêm 100k."},{"speaker":"client","text":"Ok, mình lấy luôn cái bàn + ghế vậy. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ trong ngày giờ ạ, từ 14h-17h. Bạn để số điện thoại cho nhân viên giao hàng nhé?"}]','successs',245),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc túi xách da thật chất lượng, giá dưới 3 triệu thôi."},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng em có túi da bò nhập khẩu từ Ý, mẫu đơn giản này chỉ 2.8 triệu thôi chị."},{"speaker":"client","text":"Ừ, nhìn được đấy. Nhưng mình thấy trên mạng có nhiều chỗ rẻ hơn, 2.5 triệu thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, sản phẩm nhập khẩu nên giá hơi cao hơn chút. Nhưng chị yên tâm chất lượng đảm bảo, bảo hành 1 năm ạ."},{"speaker":"client","text":"Thế nếu mình lấy 2 chiếc thì có giảm giá không?"},{"speaker":"salebot","text":"Dạ nếu chị lấy 2 chiếc, em giảm cho 2.6 triệu/chiếc luôn nhé! Giao tận nơi miễn phí nữa."},{"speaker":"client","text":"Ok, mình lấy 2 chiếc vậy. Địa chỉ giao là 123 Lê Lợi, quận 1 nhé."},{"speaker":"salebot","text":"Dạ em ghi nhận đơn hàng rồi ạ! Chị check mail để nhận thông tin xác nhận nhé. Cảm ơn chị đã ủng hộ!"}]','successs',246),
('[{"speaker":"client","text":"Chào! Mình đang tìm mua chiếc áo khoác mùa đông này. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc áo này đang khuyến mại 40% chỉ còn 899.000đ thôi chị nhé."},{"speaker":"client","text":"Ôi, đắt quá! Mình thấy trên shopee có giá 750k mà?"},{"speaker":"salebot","text":"Dạ shopee có nhiều shop lắm ạ, của em đảm bảo hàng chính hãng, giao tận nhà miễn phí nữa chị."},{"speaker":"client","text":"Thế nếu mình mua 2 áo thì có giảm nữa không? Mình cần size M và L."},{"speaker":"salebot","text":"Dạ nếu chị mua 2 áo trở lên thì được giảm thêm 5% nữa ạ, tổng cộng 1.700.000đ thôi."},{"speaker":"client","text":"Hmm, thôi vậy mình nghĩ lại đã. Cảm ơn nhé!"}]','fail',247),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác này nhưng giá 1.800k hơi đắt nhỉ. Có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ em rất tiếc ạ, sản phẩm này đang sale 20% rồi nên giá đã là ưu đãi nhất. Nếu bạn mua 2 sản phẩm cùng loại sẽ giảm thêm 5% nha!"},{"speaker":"client","text":"Thế à... mình chỉ lấy 1 cái thôi. Chốt luôn nhé, mình gửi địa chỉ dưới này."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, đơn hàng của bạn đã vượt quá số lượng có thể giao trong ngày. Bạn có thể chọn giao vào ngày mai hoặc hủy đơn không?"}]','fail',248),
('[{"speaker":"client","text":"Chào! Mình thấy trên web có bán bàn chải điện Oral-B iO Series 8, nhưng không biết có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu trắng và đen đều sẵn, giao hàng miễn phí trong 24h nếu bạn đặt hôm nay."},{"speaker":"client","text":"Ồ, thế giá bao nhiêu vậy? Có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 4.990.000đ, nhưng hôm nay có khuyến mại giảm 10% cho đơn hàng đầu tiên, còn 4.491.000đ thôi ạ!"},{"speaker":"client","text":"Vậy có tặng kèm gì không? Mình thấy quảng cáo có kèm hộp đựng nữa chứ?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Bạn sẽ được tặng kèm hộp đựng xách tay trị giá 500.000đ miễn phí luôn ạ."},{"speaker":"client","text":"Ok, vậy mình lấy luôn đi. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ giao trong ngày hôm nay nếu bạn ở Hà Nội hoặc TP. HCM, muộn nhất là 18h. Bạn nhập địa chỉ để mình xử lý đơn nhé!"}]','successs',249),
('[{"speaker":"client","text":"Chào! Mình thấy cái bàn ghế gỗ óc chó này đẹp quá, nhưng giá 12 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ, 12 triệu là giá niêm yết của sản phẩm ạ, nhưng mình có thể giảm 5% nếu bạn đặt ngay hôm nay!"},{"speaker":"client","text":"5% thì vẫn còn 11.4 triệu, mình nghĩ 10 triệu thôi được không?"},{"speaker":"salebot","text":"Dạ, mình xin lỗi ạ, mức giảm tối đa là 5% theo chính sách. Bạn có thể chọn trả góp 0% không ạ?"},{"speaker":"client","text":"Thôi vậy, cảm ơn nhé. Mình suy nghĩ thêm rồi quay lại!"}]','fail',250),
