('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra 256GB giảm giá 5 triệu trên web, có đúng không vậy?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Đơn hàng từ 10 triệu trở lên sẽ được freeship nội thành, bạn muốn mua không?"},{"speaker":"client","text":"Mình thấy giá vẫn hơi cao, có thể giảm thêm không? Mình thấy bên kia bán rẻ hơn 2 triệu đấy."},{"speaker":"salebot","text":"Dạ em kiểm tra lại ạ, nếu bạn mua trong hôm nay thì em có thể giảm thêm 1 triệu cho bạn nhé! Giá cuối là 22 triệu kèm quà tặng là tai nghe không dây."},{"speaker":"client","text":"Được thôi, mình chọn màu đen. Bao lâu thì nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu bạn ở Hà Nội ạ! Em sẽ gửi link thanh toán qua zalo ngay đây nhé."}]','successs',269),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc bàn chải điện Oral-B Pro 3, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Chiếc này đang khuyến mại 30% nè, còn 2 ngày nữa thôi. Bạn muốn màu xanh hay hồng?"},{"speaker":"client","text":"Mình thích xanh. Nhưng giá 1.800k hơi đắt, có giảm nữa không?"},{"speaker":"salebot","text":"Dạ thôi 1.750k cho bạn luôn, kèm quà tặng là 1 tuýp kem đánh răng trị giá 50k nè!"},{"speaker":"client","text":"Thế giao hàng mất bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao nhanh trong 2 tiếng nếu bạn ở TP.HCM, nhưng hôm nay hết phiên giao buổi chiều rồi ạ."},{"speaker":"client","text":"Vậy mai giao được không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ mai giao được ạ, nhưng ưu đãi 30% chỉ còn hôm nay thôi. Bạn có muốn đặt luôn không?"},{"speaker":"client","text":"Thôi không mua nữa, mai mình đi siêu thị mua cũng được. Cảm ơn nhé!"}]','fail',270),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn chải điện Philips Sonicare DiamondClean 9000 trên web, có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Còn 5 sản phẩm, giao trong 2 ngày. Bạn muốn màu trắng hay xanh dương?"},{"speaker":"client","text":"Mình thích xanh dương nhưng giá 5 triệu hơi đắt, có giảm giá không?"},{"speaker":"salebot","text":"Dạ thôi ạ, giá niêm yết rồi. Nếu bạn mua kèm kem đánh răng trị giá 200k thì giảm 300k nhé!"},{"speaker":"client","text":"Thế à... mình nghĩ không cần nữa, cảm ơn bot nhé!"}]','fail',271),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc laptop gaming ASUS TUF F15. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Máy đang có giá 18 triệu 500k, cấu hình mạnh mẽ cho gaming thoải mái ạ."},{"speaker":"client","text":"Đắt quá! Có giảm được không? Mình thấy bên kia bán 17 triệu thôi."},{"speaker":"salebot","text":"Dạ anh/chị thông cảm, giá này đã ưu đãi nhất rồi ạ. Nhưng nếu mua kèm chuột gaming giảm 200k, tặng luôn túi xách nữa ạ!"},{"speaker":"client","text":"Thế à? Được đấy, mình lấy luôn đi. Ship có nhanh không?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu anh/chị ở nội thành, miễn phí ship ạ. Anh/chị để lại địa chỉ và số điện thoại nhé!"}]','successs',272),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua chiếc áo khoác thể thao cho bé 12 tuổi. Loại nào bền, dễ giặt và giá phải chăng?"},{"speaker":"salebot","text":"Dạ chào chị, em gợi ý mẫu áo khoác thể thao chống thấm cho bé 12 tuổi ạ. Giá niêm yết 599k, nhưng hôm nay giảm còn 450k nếu chị mua kèm quần thể thao ạ!"},{"speaker":"client","text":"450k hơi đắt, có giảm nữa không? Mình thấy bên shop khác bán 380k thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, em check lại thì do sản phẩm này đang khuyến mại theo chương trình của hãng nên không thể giảm thêm ạ. Nhưng nếu chị mua 2 sản phẩm trở lên sẽ tặng 10% phí ship ạ!"},{"speaker":"client","text":"Thôi vậy, mình chỉ mua 1 thôi. Để mình suy nghĩ đã nhé."}]','fail',273),
('[{"speaker":"client","text":"Chào shop, mình muốn mua nồi cơm điện tử này. Mình thấy giá 2.500.000 VNĐ, có giảm được không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Nồi này đang khuyến mại 10% nên giá chỉ còn 2.250.000 VNĐ thôi ạ."},{"speaker":"client","text":"Hơi đắt, mình thấy bên kia bán 2.000.000 VNĐ. Bạn có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ không ạ, giá này đã là ưu đãi nhất rồi. Nếu bạn mua thêm phụ kiện tặng kèm như nồi hấp, mình có thể giảm thêm 50.000 VNĐ."},{"speaker":"client","text":"Thế thôi, mình không cần phụ kiện. Cảm ơn nhé!"}]','fail',274),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo sơ mi kẻ sọc xanh dương của hãng đó. Còn size S không vậy?"},{"speaker":"salebot","text":"Dạ chào chị, size S vẫn còn ạ! Nhưng chị vui lòng kiểm tra lại xem có phù hợp không nhé, vì sản phẩm này hay bị khách phản hồi là rộng quá."},{"speaker":"client","text":"Ồ, vậy giá bao nhiêu vậy? Mình thấy trên web ghi 599k nhưng có giảm giá không?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 599k chị ạ, nhưng hôm nay mình có ưu đãi 10% cho đơn hàng đầu tiên, vậy còn 539k thôi ạ."},{"speaker":"client","text":"539k à? Đắt quá, mình thấy bên kia bán có 490k kèm free ship luôn. Không thể giảm hơn được à?"},{"speaker":"salebot","text":"Dạ em rất tiếc ạ, mức này đã là ưu đãi nhất rồi. Nếu chị muốn, em có thể check kho size S bên chi nhánh khác xem có rẻ hơn không ạ?"},{"speaker":"client","text":"Thôi không cần đâu, mình đi xem chỗ khác vậy. Cảm ơn nhé!"}]','fail',275),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến bàn chải điện Oral-B Pro 3000. Có khuyến mãi gì không thế?"},{"speaker":"salebot","text":"Chào chị ạ! Hiện tại bàn chải có chương trình tặng kèm 2 đầu chải thay thế + 1 tuýp kem đánh răng trị giá 200k. Chỉ còn 1 ngày nữa là hết khuyến mãi ạ."},{"speaker":"client","text":"Ôi mình thấy giá hơi cao so với thường, có giảm được không?"},{"speaker":"salebot","text":"Dạ thưa chị, đây là mức giá ưu đãi nhất trong tuần chị ạ. Nếu chị đặt 2 sản phẩm trở lên sẽ được free ship nữa đó!"},{"speaker":"client","text":"Thôi vậy mình nghĩ lại đã, cảm ơn bạn nhé!"}]','fail',276),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc bàn phím cơ Keychron K8. Mình thấy giá trên web là 1.500.000đ, có được giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại Keychron K8 có ưu đãi giảm 5% nếu bạn mua kèm chuột không dây, còn 1.425.000đ thôi ạ. Bạn có muốn thêm không?"},{"speaker":"client","text":"Ừ, mình lấy luôn cả chuột đi. Nhưng mình thấy bên shop khác bán với giá 1.350.000đ không kèm chuột, bạn có thể bằng giá không?"},{"speaker":"salebot","text":"Dạ thật tiếc, giá mình đã chiết khấu tối đa rồi ạ. Nếu bạn lấy combo bàn phím + chuột thì mình tặng luôn miếng lót cổ tay trị giá 100.000đ nữa nhé!"},{"speaker":"client","text":"Thế à, hay quá! Vậy mình đặt luôn. Bạn gửi mình link thanh toán đi."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đây là link thanh toán ạ: [link]. Sau khi thanh toán xong, đơn sẽ giao trong 2 giờ nếu bạn ở nội thành. Chúc bạn mua sắm vui vẻ!"}]','successs',277),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại tầm trung. Nghe nói iPhone 13 cũ giá rẻ lắm, có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! iPhone 13 128GB còn mới 95% giá chỉ 12 triệu thôi, bạn muốn xem ảnh sản phẩm không?"},{"speaker":"client","text":"12 triệu hơi đắt, có giảm được không? Mình thấy nơi khác rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ, em check lại cho bạn nhé! Nếu bạn mua ngay hôm nay, em giảm xuống 11 triệu 500k luôn, kèm bảo hành 12 tháng ạ."},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, quận 1, TPHCM. Giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ gửi đơn hàng ngay, cám ơn bạn đã mua sắm cùng shop!"}]','successs',278),
('[{"speaker":"client","text":"Chào shop, mình đang muốn mua cái nồi cơm điện tử này. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Em thấy chị đang xem nồi cơm điện tử Philips HD3128 1.8L. Chị thích màu nào ạ? Đen hay trắng?"},{"speaker":"client","text":"Mình thích màu trắng. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.890.000đ, nhưng hôm nay em có khuyến mãi giảm còn 1.690.000đ thôi chị ạ!"},{"speaker":"client","text":"Hơi đắt quá, mình thấy bên kia bán 1.550.000đ có kèm tặng quạt nữa. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ em xin lỗi chị ạ, giá đã là ưu đãi nhất rồi. Nếu chị mua kèm nồi chống dính 2L nữa thì em giảm thêm 50k cho chị nhé?"},{"speaker":"client","text":"Thế à, không được thì thôi. Cảm ơn bạn nhé!"}]','fail',279),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc bàn chải điện Oral-B Genius X, nhưng giá hơi cao so với mình. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện sản phẩm đang có khuyến mại 10% cho đơn hàng đầu tiên, nếu bạn mua kèm kem đánh răng Oral-B Pro 3 thì được thêm 5% nữa."},{"speaker":"client","text":"Mình chỉ mua bàn chải thôi, giá 2.490.000đ vậy có được giảm nữa không? Mình thấy nơi khác rẻ hơn."},{"speaker":"salebot","text":"Dạ thật tiếc ạ, giá đã ưu đãi nhất rồi ạ. Nếu bạn lấy 2 chiếc cùng lúc thì mình có thể hỗ trợ bạn 2.200.000đ mỗi chiếc ạ."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',280),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra trên web có khuyến mãi không vậy? Mình đang cân nhắc mua."},{"speaker":"salebot","text":"Dạ chào anh, hiện tại Galaxy S23 Ultra đang giảm 2 triệu nữa là 25 triệu ạ! Anh có muốn mình check mã giảm giá thêm không?"},{"speaker":"client","text":"À, vậy là 25 triệu thôi à? Mà mình nghe nói sản phẩm này hay bị hết hàng, bây giờ còn không?"},{"speaker":"salebot","text":"Dạ còn ạ! Anh đặt trước 1 tiếng là giao tận nhà trong ngày luôn. Anh muốn màu đen hay xanh dương ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương. Vậy giao trong ngày hôm nay được chứ? Mình cần gấp."},{"speaker":"salebot","text":"Dạ được ạ! Anh chỉ cần thanh toán trước 30% là em xử lý đơn ngay. Anh chọn phương thức thanh toán nào ạ?"},{"speaker":"client","text":"Ok, mình thanh toán online luôn. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc anh một ngày tốt lành. Đơn hàng sẽ có trong 2-3 tiếng nữa."}]','successs',281),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo sơ mi trắng của thương hiệu Zara, size M có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Áo sơ mi trắng Zara size M còn 3 sản phẩm, bạn muốn chọn màu nào? Màu trắng chuẩn hay trắng sữa?"},{"speaker":"client","text":"Màu trắng chuẩn thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ sản phẩm hiện đang khuyến mãi 20% nên chỉ còn 799.000đ thôi ạ. Nếu bạn đặt ngay hôm nay sẽ được free ship nội thành."},{"speaker":"client","text":"Ủa, mắc quá! Bán 750.000đ được không? Giao hàng trong ngày luôn nhé."},{"speaker":"salebot","text":"Dạ thật tiếc ạ, mức giá tốt nhất chúng tôi có thể hỗ trợ là 770.000đ thôi. Nếu bạn đồng ý, mình sẽ check kho ngay và gửi mã giảm giá 5% cho đơn hàng tiếp theo nhé!"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Địa chỉ giao là 123 Lê Lợi, phường Bến Thành, quận 1 nha."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng của bạn đã được xác nhận. Vui lòng thanh toán trong vòng 15 phút để giữ chỗ ạ. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',282),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác da nam hiệu Levi’s, size L có không vậy?"},{"speaker":"salebot","text":"Dạ chào anh, áo Levi’s size L vẫn còn ạ! Giá niêm yết 2.990.000đ, giao tận nhà trong 2 ngày."},{"speaker":"client","text":"Ủa, mắc thế! Em có giảm được không? Mình thấy bên kia bán 2.500.000đ thôi."},{"speaker":"salebot","text":"Dạ anh thông cảm ạ, đây là hàng chính hãng nên giá đã thế rồi. Nhưng nếu anh đặt ngay hôm nay, em có thể giảm 5% cho anh nhé!"},{"speaker":"client","text":"5% cũng được, nhưng 2.700.000đ thôi nhé! Mình không có thời gian chờ lâu đâu."},{"speaker":"salebot","text":"Dạ anh ơi, em xin lỗi nhưng mức giảm 5% là tối đa rồi ạ. Nếu anh không hài lòng, em có thể tư vấn mẫu khác nhé?"}]','fail',283),
