('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc bàn chải điện Oral-B Pro 3000. Mấy nay mình bị đau răng nên muốn đổi sang loại này. Bên mình còn hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi vừa nhập đợt mới về hôm qua. Bạn muốn màu xanh dương hay xám nhỉ?"},{"speaker":"client","text":"Màu xanh dương đi. Giá bao nhiêu vậy? Mình thấy trên mạng rẻ hơn 100k ấy."},{"speaker":"salebot","text":"Dạ giá niêm yết của hãng là 2.990.000đ, nhưng do ưu đãi cuối tháng nên mình giảm còn 2.790.000đ ạ. Có kèm quà tặng là 2 đầu bàn chải thay thế nữa."},{"speaker":"client","text":"Ủa, mình thấy trên Shopee cùng sản phẩm có 2.550.000đ kìa. Bên mình không giảm được nữa à?"},{"speaker":"salebot","text":"Dạ em thật lòng xin lỗi ạ, do đây là giá sỉ nên không thể giảm thêm được. Nhưng bên mình giao hàng tận nơi miễn phí trong 2h cho nội thành, tiết kiệm được phí ship nữa."},{"speaker":"client","text":"Thôi được, mình cân nhắc đã. Cảm ơn bạn nhé!"}]','fail',302),
('[{"speaker":"client","text":"Chào bot, mình thấy chiếc áo khoác da này đẹp quá! Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị, sản phẩm này chị đang xem là mẫu thời thượng năm nay ạ! Giá niêm yết 2.990.000đ, nhưng hôm nay có khuyến mại giảm còn 2.490.000đ thôi chị nhé."},{"speaker":"client","text":"Ôi, đắt quá! Mình thấy trên shopee cùng mẫu giảm còn 2.200.000đ kìa, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá web mình đã ưu đãi nhất rồi ạ. Nhưng nếu chị mua kèm khăn da thì mình giảm thêm 100.000đ nha chị."},{"speaker":"client","text":"Thôi được, nhưng giao hàng muộn quá mình không lấy đâu. Mấy giờ nhận được vậy?"},{"speaker":"salebot","text":"Dạ chị yên tâm, đơn hàng chị sẽ giao trong 2-3 tiếng nữa ạ. Cảm ơn chị đã quan tâm ạ!"}]','fail',303),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái bàn làm việc này đẹp quá, nhưng giá 5 triệu hơi đắt nhỉ? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn! Bàn này đang khuyến mại 5% cho đơn hàng đầu tiên đó ạ, còn 4.75 triệu thôi!"},{"speaker":"client","text":"4.75 triệu vẫn hơi cao, mình thấy trên Shopee có cùng mẫu 4.2 triệu. Bạn có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, mức giá này đã là ưu đãi nhất rồi ạ. Nếu bạn mua kèm ghế văn phòng thì em có thể giảm thêm 100k nữa!"},{"speaker":"client","text":"Thế à... thôi mình không mua nữa, cảm ơn nhé!"}]','fail',304),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc laptop cho con gái học đại học. Gợi ý cho mình mẫu nào phù hợp với mức giá dưới 15 triệu đi nhé!"},{"speaker":"salebot","text":"Dạ, mình gợi ý cho bạn mẫu Acer Aspire 3 A315-58-324B ạ! Giá niêm yết 14.990.000đ, cấu hình ổn định cho học tập: Core i3 1215U, RAM 8GB, SSD 512GB, màn hình 15.6 inch. Có giảm 5% nếu thanh toán online ạ."},{"speaker":"client","text":"Mình thấy nó hơi chậm khi mở nhiều tab lắm đúng không? Có mẫu nào mạnh hơn chút nhưng vẫn trong tầm giá không?"},{"speaker":"salebot","text":"Dạ, mình có mẫu Lenovo IdeaPad 5 Pro 14ARP7 ạ! Giá 16.5 triệu nhưng giảm còn 15.9 triệu nếu bạn nhận hàng trong hôm nay. Chip Ryzen 5 7520U, RAM 16GB, SSD 512GB, mỏng nhẹ và pin khỏe hơn ạ."},{"speaker":"client","text":"15.9 triệu hơi sát rồi, mình trả 15.5 triệu được không? Mình thấy nó cũng đủ dùng rồi."},{"speaker":"salebot","text":"Dạ, mình trao đổi với quản lý ạ! Được đó, bạn nhận hàng trong 2 tiếng nữa nhé! Chúng mình sẽ giao tận nơi và hỗ trợ setup miễn phí ạ."},{"speaker":"client","text":"Ok, mình đặt luôn! Cảm ơn bạn nhiều nhé!"}]','successs',305),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng nhìn hơi đắt quá. Bên mình có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ, áo khoác này hiện đang khuyến mại 20% cho khách hàng mới ạ. Giá gốc 1.200.000đ giờ chỉ còn 960.000đ thôi ạ."},{"speaker":"client","text":"960k vẫn hơi cao so với mong đợi. Mình thấy bên kia bán cùng mẫu chỉ 850k thôi. Bên mình có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ, thật tiếc ạ, mức giá đã là ưu đãi nhất rồi. Nhưng nếu bạn mua 2 sản phẩm trở lên, mình có thể tặng kèm 1 chiếc khăn len ạ!"},{"speaker":"client","text":"Thế à? Mà mình chỉ cần 1 cái thôi. Không tiện mua thêm đâu. Cảm ơn bạn nhé, mình nghĩ sẽ tìm chỗ khác."}]','fail',306),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Máy màu đen và xanh lá vẫn còn sẵn. Bạn muốn mua bản nào?"},{"speaker":"client","text":"Mình thích màu đen. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 28.990.000đ ạ, nhưng hôm nay có chương trình giảm còn 26.990.000đ nếu bạn thanh toán bằng ví MoMo."},{"speaker":"client","text":"Ồ, vậy mình lấy luôn. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Giao trong ngày nếu bạn ở Hà Nội ạ. Còn tỉnh thành khác thì 2-3 ngày thôi!"},{"speaker":"client","text":"Tuyệt, mình chọn giao trong ngày. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn một ngày tốt lành. Đơn hàng của bạn sẽ được xử lý ngay."}]','successs',307),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng nhìn hơi đắt, có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ chào chị ạ, sản phẩm này đang khuyến mại 20% cho đơn hàng đầu tiên, chị có thể nhập mã SALE20 khi thanh toán."},{"speaker":"client","text":"Mình thấy giá vẫn còn cao, có thể giảm thêm không? Mình mua luôn bây giờ."},{"speaker":"salebot","text":"Dạ thật tiếc chị ơi, đây đã là mức giá tốt nhất rồi ạ. Nếu chị mua 2 sản phẩm trở lên sẽ được tặng quà nhỏ nha."},{"speaker":"client","text":"Thế thôi, mình không mua nữa. Cảm ơn bạn nhé!"}]','fail',308),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua một chiếc điện thoại tầm 10 triệu thôi. Có máy nào xịn xịn không?"},{"speaker":"salebot","text":"Dạ có ạ! Samsung Galaxy A54 5G giá 9,99 triệu, cấu hình mạnh mẽ, màn hình Super AMOLED 120Hz, pin trâu nữa ạ!"},{"speaker":"client","text":"Ui, nghe cũng ổn đấy. Nhưng mình thấy trên web có ghi giá 9,5 triệu, sao bây giờ 9,99 triệu?"},{"speaker":"salebot","text":"Dạ, giá niêm yết là 9,99 triệu, nhưng hôm nay có chương trình khuyến mại giảm 500k cho đơn hàng đầu tiên ạ. Để mình check lại cho bạn nhé!"},{"speaker":"client","text":"Ok, vậy mình chọn màu xanh dương nhé. Giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng để lại địa chỉ và số điện thoại để mình xử lý đơn hàng luôn nhé!"}]','successs',309),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S24 Ultra trên trang web, mình có thể mua trả góp không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn có thể chọn trả góp 0% lãi suất từ 3-12 tháng tùy ngân hàng. Bạn muốn chọn gói nào không ạ?"},{"speaker":"client","text":"Mình muốn trả góp 6 tháng được không? Giá niêm yết 29.990.000, mình được giảm giá không?"},{"speaker":"salebot","text":"Dạ có chương trình khuyến mại tặng kèm sạc nhanh và ốp lưng, giá vẫn giữ nguyên 29.990.000 ạ. Nếu bạn mua ngay hôm nay, mình sẽ tặng thêm tai nghe không dây trị giá 1.990.000 nữa!"},{"speaker":"client","text":"Ok, mình mua luôn! Bao lâu thì giao hàng được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu bạn ở Hà Nội, mình sẽ gửi link thanh toán để bạn xác nhận ạ!"}]','successs',310),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, nhưng giá trên web hơi cao so với mình nghĩ. Bạn có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại Oral-B Pro 3000 đang có chương trình khuyến mại 10% cho đơn hàng đầu tiên ạ. Bạn có muốn mình hỗ trợ đặt hàng luôn không?"},{"speaker":"client","text":"10% thôi à? Mình thấy nơi khác giảm tới 20% đấy. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ thật tiếc là mức giá này đã là ưu đãi tốt nhất từ hãng rồi ạ. Nếu bạn mua kèm dung dịch vệ sinh răng miệng, mình có thể tặng bạn 1 lọ miễn phí ạ."},{"speaker":"client","text":"Thế à, tiếc quá. Mình nghĩ sẽ tìm nơi khác rẻ hơn. Cảm ơn bạn nhé!"}]','fail',311),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc váy len màu xám kia, size M có không nhỉ?"},{"speaker":"salebot","text":"Dạ có ạ! Size M còn 3 chiếc. Mình gửi ảnh chụp chi tiết sản phẩm qua nhé?"},{"speaker":"client","text":"Ok, mình thấy chất liệu khá mềm mại. Giá niêm yết 899k đúng không? Có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Hiện tại shop đang khuyến mại 15% cho đơn hàng đầu tiên, còn 764.150đ thôi."},{"speaker":"client","text":"Tuyệt quá! Mình lấy luôn. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng để lại số điện thoại và địa chỉ nhận hàng nhé."}]','successs',312),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo sơ mi nam kia. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Chiếc áo sơ mi cotton này đang có giá 499.000đ, ạ."},{"speaker":"client","text":"Ôi, đắt quá! Bạn giảm cho mình được không? 400k thôi nhé?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, giá này đã là giá tốt nhất rồi ạ. Nếu bạn mua 2 cái thì mình giảm 5% cho ạ."},{"speaker":"client","text":"Thế à... mình chỉ mua 1 thôi. Thôi thôi, mình không mua nữa đâu. Cảm ơn nhé!"}]','fail',313),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái loa Bluetooth JBL Charge 5 này có khuyến mại gì không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại đang giảm 20% cho sản phẩm này, chỉ còn 2.400.000đ thôi ạ!"},{"speaker":"client","text":"Ồ, giá vậy hơi đắt so với mình nghĩ. Bạn giảm thêm được không? Chẳng hạn 2.200.000đ?"},{"speaker":"salebot","text":"Dạ thật lòng xin lỗi ạ, mức này đã là giá tốt nhất rồi ạ. Nhưng nếu bạn mua kèm sạc dự phòng JBL chính hãng, mình sẽ tặng luôn dây sạc nhanh 100K ạ!"},{"speaker":"client","text":"Thế à, vậy mình lấy luôn cái combo ấy đi. Ship nhanh trong 2h được không?"},{"speaker":"salebot","text":"Dạ được ạ! Vui lòng cung cấp địa chỉ để mình xác nhận đơn hàng ạ."}]','successs',314),
