('[{"speaker":"client","text":"Chào bot, mình đang tìm mua bộ quần áo thể thao cho con gái 12 tuổi. Có size từ 14-16 không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Bộ Adidas có size 14-16, màu xanh dương và hồng đang hot. Giao trong 2 ngày."},{"speaker":"client","text":"Giá bao nhiêu thế? Mình thấy trên web ghi 890k."},{"speaker":"salebot","text":"Dạ đúng ạ, nhưng hôm nay có khuyến mãi 10% nếu bạn đặt ngay. Còn 801k thôi!"},{"speaker":"client","text":"Ok, mình chọn size 15, màu xanh dương. Địa chỉ giao: 123 Lê Lợi, Q.1. Bao giờ nhận được?"},{"speaker":"salebot","text":"Cảm ơn bạn! Đơn sẽ giao vào 15h chiều mai. Thanh toán COD hay chuyển khoản ạ?"},{"speaker":"client","text":"COD nhé. Cảm ơn bot nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn một ngày vui vẻ!"}]','successs',316),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu trắng đang khuyến mại 20% cho đơn hàng hôm nay, giao trong 2 giờ nếu bạn ở TPHCM."},{"speaker":"client","text":"Mình thấy giá niêm yết 2.500.000, vậy giá khuyến mại bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chỉ còn 1.990.000 ạ, giảm sâu lắm luôn!"},{"speaker":"client","text":"Ok, mình lấy luôn. Bao ship phí thế?"},{"speaker":"salebot","text":"Miễn phí ship cho đơn từ 1 triệu ạ, bạn chỉ cần thanh toán 1.990.000 thôi!"},{"speaker":"client","text":"Tuyệt, mình chuyển khoản sau nhé. Cảm ơn bạn nhiều!"}]','successs',317),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn ghế gỗ óc chó này đẹp quá, nhưng 5 triệu rẻ quá nhỉ?"},{"speaker":"salebot","text":"Dạ, sản phẩm 100% gỗ óc chó nhập khẩu, giá niêm yết 5,9 triệu nhưng hôm nay sale ưu đãi chỉ 4,9 triệu thôi ạ!"},{"speaker":"client","text":"Thế giao hàng có nhanh không? Mình cần trong tuần."},{"speaker":"salebot","text":"Dạ có ạ, giao tận nơi trong 2-3 ngày làm việc, phí ship 20k thôi ạ."},{"speaker":"client","text":"Úi, 20k cũng hơi đắt, mình thấy chỗ khác ship miễn phí mà."},{"speaker":"salebot","text":"Dạ, ship miễn phí trên 5 triệu ạ, nhưng bàn ghế này đã giảm rồi nên phí ship vẫn thế ạ. Hay mình gửi link sản phẩm khác ưu đãi hơn cho bạn nhé?"},{"speaker":"client","text":"Thôi vậy, thôi vậy. Cảm ơn bot nhé!"}]','fail',318),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc đồng hồ thể thao cho bé trai 10 tuổi. Có loại nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em giới thiệu đồng hồ thể thao Casio G-Shock trẻ em model GA-100-1A1R, chống va đập tốt, giá chỉ 1.290.000đ thôi ạ!"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình mua 2 cái thì sao?"},{"speaker":"salebot","text":"Dạ anh/chị mua 2 cái thì em giảm còn 1.150.000đ/cái nhé! Kèm quà tặng là dây đeo dự phòng ạ."},{"speaker":"client","text":"Ok, mình lấy 2 cái luôn. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em gửi link thanh toán qua Zalo cho anh/chị nhé. Cảm ơn anh/chị đã mua sắm cùng em!"}]','successs',319),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn phím cơ Logitech MX Keys Mini, có sẵn không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu trắng và đen đều còn hàng. Bạn muốn đặt trước hay giao tận nơi ạ?"},{"speaker":"client","text":"Giao tận nơi được không? Mình ở quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ được ạ! Phí ship 30k, tổng cộng 2.290.000đ. Bạn nhận tiền mặt hay chuyển khoản?"},{"speaker":"client","text":"Chuyển khoản được. Mình gửi link chuyển khoản qua đây nhé."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Sau khi nhận tiền, mình sẽ giao trong 2-3 tiếng ạ. Bạn có nhu cầu gì thêm không?"},{"speaker":"client","text":"Không cần nữa, cảm ơn bạn nhiều!"}]','successs',320),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm một chiếc điện thoại thông minh tầm 10 triệu thôi. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em giới thiệu em Samsung Galaxy A34 128GB, giá 9.990.000đ, cấu hình ổn định cho nhu cầu thường ngày ạ."},{"speaker":"client","text":"Ui, đắt nhỉ! Có giảm giá không? Mình thấy trên shopee giá rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ em có thể hỗ trợ anh/chị thêm 500.000đ nếu anh/chị chọn gói bảo hành 2 năm thay vì 1 năm ạ. Còn 9.490.000đ thôi ạ."},{"speaker":"client","text":"Vậy thôi, mình lấy luôn. Ship nhanh không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ cam kết giao trong 2 giờ nếu anh/chị ở nội thành Hà Nội ạ. Em gửi link thanh toán qua zalo ạ!"}]','successs',321),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Màu xanh dương có size L không nhỉ?"},{"speaker":"salebot","text":"Dạ có ạ! Size L vẫn còn 2 chiếc, bạn muốn xem ảnh chi tiết hay đặt luôn ạ?"},{"speaker":"client","text":"Mình thích rồi nhưng giá 1.499.000 có hơi đắt không? Có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ hiện tại đang có giảm 10% cho đơn từ 1.200.000, chỉ còn 1.349.000 thôi ạ! Giao hàng miễn phí nữa."},{"speaker":"client","text":"Ok, vậy mình lấy luôn nhé. Địa chỉ giao là 123 Lê Lợi, Phường 1, Quận 1, TP.HCM."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Thanh toán bằng tiền mặt hay chuyển khoản ạ? Chúng tôi sẽ giao trong 2 giờ tới ạ."}]','successs',322),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác thể thao của Nike, size M. Bạn còn hàng không?"},{"speaker":"salebot","text":"Dạ còn ạ! Màu xanh dương và đen size M, giá niêm yết 1.290.000đ. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Nếu không thì thôi nhé."},{"speaker":"salebot","text":"Dạ bây giờ ưu đãi 10% cho khách hàng mới, còn 1.161.000đ thôi ạ. Nhập mã KHAMPHA10 khi thanh toán."},{"speaker":"client","text":"À mình không quan tâm mã giảm, cứ giá niêm yết đi. Thôi thôi, mình không mua nữa đâu."}]','fail',323),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác nữ này. Size S và M có không ạ? Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ có đủ size ạ! Size S là 799k, size M là 849k. Bạn thích màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương. Có thể giảm giá không? 700k thôi nhé?"},{"speaker":"salebot","text":"Dạ 700k hơi khó ạ, chúng mình giảm còn 750k được không? Giao hàng miễn phí luôn nè."},{"speaker":"client","text":"Ok, mình lấy size S vậy. Bao lâu nhận được hàng?"},{"speaker":"salebot","text":"Dạ giao trong 2 ngày ạ! Bạn để lại địa chỉ và số điện thoại để mình gửi thông tin nhé."}]','successs',324),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ Casio Edifice EFR-S567D-1A2V, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào anh! Đồng hồ Casio Edifice EFR-S567D-1A2V hiện đang có giá 2.490.000đ, ạ!"},{"speaker":"client","text":"Ủa đắt quá, mình thấy bên kia bán 2.2 triệu thôi!"},{"speaker":"salebot","text":"Dạ anh ơi, giá này đã là ưu đãi nhất rồi ạ! Chúng mình tặng kèm dây da chính hãng và bảo hành 2 năm, bên kia có thể không uy tín đâu ạ."},{"speaker":"client","text":"Thế à, vậy mình order luôn nhé. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu anh ở Hà Nội, hoặc 1 ngày với toàn quốc ạ. Anh có muốn thêm phụ kiện không ạ?"}]','successs',325),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Genius 9000, có màu trắng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu trắng vẫn còn hàng, nhưng chỉ còn 1 chiếc thôi. Bạn cần giao trong ngày hôm nay hay mai ạ?"},{"speaker":"client","text":"Mình thấy giá trên web là 2.990.000, nhưng mình thấy nơi khác bán 2.750.000, bạn có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ, vì đây là sản phẩm mới về nên giá đã ưu đãi nhất rồi ạ. Nhưng nếu bạn mua kèm viên tẩy mảng bám (50k) thì mình giảm còn 2.940.000 cho bạn nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn đi. Địa chỉ giao là 123 Lê Lợi, Phường 1, Quận 1, TP.HCM. Cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Đơn hàng #789567 của bạn sẽ giao trong 2 giờ nữa. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',326),
('[{"speaker":"client","text":"Chào bot, mình thích đôi giày Nike Air Force 1 trắng, nhưng giá 2 triệu hơi đắt quá. Có ưu đãi gì không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá niêm yết là 2 triệu nhưng hôm nay có deal đặc biệt giảm 15% cho khách hàng mới. Còn 1.700.000đ thôi ạ!"},{"speaker":"client","text":"Thế giao hàng trong bao lâu vậy? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Dạ giao trong 2-3 giờ nếu bạn ở nội thành, phí ship 20k (miễn phí trên 1 triệu). Bạn muốn đặt luôn không ạ?"},{"speaker":"client","text":"Ok, mình chọn size 40, màu trắng. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ em đã ghi nhận đơn hàng ạ! Cảm ơn bạn đã mua sắm cùng shop. Chúc bạn vui vẻ!"}]','successs',327),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc bàn phím cơ này nhưng thấy giá hơi cao quá nhỉ? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, sản phẩm này đang có khuyến mại 10% cho đơn hàng đầu tiên ạ! Bạn nhập mã ''KEYBOARD10'' nhé."},{"speaker":"client","text":"Mình thử rồi nhưng không được, chắc hết hạn rồi. Thôi vậy, để mình suy nghĩ thêm."},{"speaker":"salebot","text":"Dạ không sao ạ! Nếu cần tư vấn thêm, hãy quay lại sau nhé. Cảm ơn bạn đã quan tâm!"}]','fail',328),
('[{"speaker":"client","text":"Chào bot! Mình đang quan tâm cái bàn học này, giá 2 triệu 5 trông hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ em hiểu ạ! Bàn này chất liệu gỗ óc chó nguyên khối, chống cong vênh tốt lắm. Có giảm giá 5% cho đơn trên 3 triệu, bạn lấy luôn không ạ?"},{"speaker":"client","text":"5% à? Vậy mình lấy luôn đi, giao trong 2 ngày được chứ? Mình cần gấp."},{"speaker":"salebot","text":"Dạ được ạ! Giao tận nơi trong 2 ngày, phí ship 20k (miễn phí nếu trên 500k). Bạn để lại số điện thoại và địa chỉ nha!"}]','successs',329),
('[{"speaker":"client","text":"Chào salebot, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Bàn chải Oral-B Pro 3000 đang có giá 1.290.000đ, giảm 20% trong tuần này đó ạ."},{"speaker":"client","text":"Mà mình thấy bên mình có tặng kèm hộp đựng không? Mình không thích mua đồ không có hộp."},{"speaker":"salebot","text":"Dạ có ạ! Gói combo gồm bàn chải + 2 đầu thay thế + hộp đựng xịn xò luôn ạ. Nếu bạn mua ngay thì mình free ship trong 2h cho."},{"speaker":"client","text":"Thế không biết mình có thể trả góp 0% không? Mình không thích trả hết 1 lần."},{"speaker":"salebot","text":"Dạ được ạ! Bạn có thể trả góp 3 tháng 0% nếu dùng thẻ tín dụng ngân hàng BIDV, Techcombank hoặc VPBank ạ."},{"speaker":"client","text":"Ok, vậy mình chọn trả góp 3 tháng đi. Bao lâu thì nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 giờ nếu bạn ở Hà Nội, 1 ngày với các tỉnh ạ. Mình sẽ gửi mã tracking qua zalo ngay khi xuất hàng ạ!"}]','successs',330),
('[{"speaker":"client","text":"Chào! Mình thấy cái máy xay sinh tố Philips HR2118/00 trên web có giá 1.200.000đ, bây giờ có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại sản phẩm đang có khuyến mại 10% cho đơn hàng đầu tiên trong hôm nay, chị có thể nhập mã ''SINH10'' để được giảm."},{"speaker":"client","text":"Thế có miễn phí ship không? Mình ở xa lắm, gần 50km ấy."},{"speaker":"salebot","text":"Dạ không ạ, phí ship 30.000đ cho đơn hàng dưới 1.500.000đ. Nếu chị mua thêm sản phẩm khác, mình sẽ hỗ trợ miễn phí ship nhé!"},{"speaker":"client","text":"Thế thôi, mình bỏ qua vậy. Cảm ơn nhé!"}]','fail',331),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn ủi hơi nước Philips GC7830, có hàng không ạ? Mình thấy giá hơi cao so với quảng cáo trên web."},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi đang có chương trình khuyến mại nên giá hiện là 1.990.000đ, rẻ hơn 300k so với quảng cáo. Bạn có muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy vẫn hơi đắt, có thể giảm thêm không? 1.850.000đ được không?"},{"speaker":"salebot","text":"Dạ, vì đây là sản phẩm khuyến mại nên không thể giảm thêm nữa ạ. Nhưng nếu bạn mua kèm 1 hộp bột ủi trị giá 200k, chúng tôi tặng luôn 1 miếng lót bàn ủi nhé?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn kèm theo. Giao trong hôm nay được chứ?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng cung cấp địa chỉ và số điện thoại để chúng tôi xác nhận đơn hàng nhé. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',332),
('[{"speaker":"client","text":"Chào em, mình thấy chiếc bàn chải điện Oral-B Pro 3000 trên web có khuyến mãi gì không vậy?"},{"speaker":"salebot","text":"Chào chị! Hiện sản phẩm đang giảm 15% cho đơn hàng đầu tiên, chị có muốn mình gửi link trực tiếp không ạ?"},{"speaker":"client","text":"À mình thấy giá hơi cao, có thể giảm thêm không? Mình thấy bên khác bán 1.800.000đ thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, Oral-B Pro 3000 là dòng sản phẩm cao cấp với công nghệ chải thông minh, chị có thể dùng thử 7 ngày miễn phí rồi quyết định ạ!"},{"speaker":"client","text":"Thế à? Được vậy thì mình đặt luôn 1 cái đi, giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được chị! Mình sẽ gửi mã giảm thêm 5% cho chị, tổng tiền chỉ còn 1.990.000đ thôi ạ. Địa chỉ giao hàng thế nào ạ?"}]','successs',333),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua cái bàn học cho bé nhà mình, có size nhỏ không? Bé mới 5 tuổi thôi."},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập loại bàn gỗ thông nhỏ xinh, kích thước 80x50cm, rất phù hợp với bé 5 tuổi."},{"speaker":"client","text":"Giá bao nhiêu vậy? Mình thấy trên web ghi 2 triệu rưỡi, có giảm được không?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 2.500.000đ, nhưng hôm nay mình có chương trình khuyến mại 10% cho đơn hàng đầu tiên, còn 2.250.000đ thôi ạ."},{"speaker":"client","text":"Hơi đắt quá, mình thấy bên kia bán 1.9 triệu. Bạn có thể giảm xuống 1.8 triệu không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, mức giá đó mình không thể giảm được vì đây là sản phẩm nhập khẩu chính hãng. Nhưng nếu bạn mua kèm ghế nhỏ thì mình giảm thêm 50k nữa nhé!"},{"speaker":"client","text":"Thôi vậy, mình không mua nữa đâu. Cảm ơn bạn nhé!"}]','fail',334),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S23 FE 5G trên trang có khuyến mại gì không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại sản phẩm đang giảm 10% cho khách hàng lần đầu mua, kèm theo quà tặng là tai nghe không dây trị giá 1 triệu đồng!"},{"speaker":"client","text":"Ồ, vậy giá sau giảm là bao nhiêu vậy? Mình thấy giá niêm yết hơi cao."},{"speaker":"salebot","text":"Dạ giá sau giảm là 19 triệu 900 ngàn ạ! Nếu anh/chị thanh toán bằng thẻ tín dụng ngân hàng partner, mình còn tặng thêm 1 triệu tiền mặt vào thẻ."},{"speaker":"client","text":"Thế giao hàng trong bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu anh/chị ở nội thành, miễn phí ship cho đơn trên 20 triệu ạ! Anh/chị chọn màu nào ạ?"},{"speaker":"client","text":"Mình chọn màu xanh ngọc, vậy mình đặt luôn nhé!"},{"speaker":"salebot","text":"Dạ anh/chị vui lòng cung cấp địa chỉ và số điện thoại để mình xác nhận đơn hàng ạ! Cảm ơn anh/chị đã mua sắm cùng chúng tôi."}]','successs',335),
('[{"speaker":"client","text":"Chào shop ạ, mình đang tìm mua chiếc máy xay sinh tố này. Có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Máy xay sinh tố Philips HR2118 hiện đang có khuyến mại 20% cho đơn hàng từ 2 triệu, giao hàng miễn phí trong 2h."},{"speaker":"client","text":"Ồ, vậy giá cuối cùng là bao nhiêu vậy? Mình thấy trên web ghi 1.200.000, vậy phải trả 960k thôi nhỉ?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Nhưng nếu bạn thanh toán bằng ví MoMo hoặc chuyển khoản ngay hôm nay, mình sẽ tặng kèm 1 cốc thủy tinh cao cấp nữa nè."},{"speaker":"client","text":"Thế à? Hay quá! Vậy mình đặt luôn nhé. Bao lâu thì nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ đơn hàng của bạn sẽ được giao trong vòng 1-2h ạ! Mình gửi link thanh toán qua Zalo cho bạn nhé."}]','successs',336),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc áo sơ mi nam thương hiệu Zara, size M. Bạn còn size này không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu trắng, xanh dương và đen đều còn size M. Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương nhất. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 990.000đ ạ, nhưng hôm nay có khuyến mãi giảm còn 850.000đ nếu bạn mua kèm quần tây Zara nha!"},{"speaker":"client","text":"Thế nếu mình mua riêng áo thì sao? Có giảm không?"},{"speaker":"salebot","text":"Dạ ạ, nếu mua riêng áo thì mình có thể giảm xuống 890.000đ thôi ạ. Hoặc nếu bạn đăng ký email nhận khuyến mãi, mình sẽ gửi mã giảm 5% nốt!"},{"speaker":"client","text":"Ok, mình chọn màu xanh dương đi. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 tiếng ạ, phí ship nội thành 20k, miễn phí ship trên 1 triệu nha! Bạn có muốn mình add vào giỏ chưa ạ?"},{"speaker":"client","text":"Ok, add vào giỏ đi. Mình thanh toán online nha!"},{"speaker":"salebot","text":"Dạ ạ! Cảm ơn bạn đã mua sắm ạ. Chúc bạn một ngày vui vẻ nha!"}]','successs',337),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại thông minh tầm trung. Có gì giới thiệu không?"},{"speaker":"salebot","text":"Dạ, em giới thiệu chiếc Samsung Galaxy A54 5G ạ! Giá niêm yết 11 triệu, nhưng hôm nay có ưu đãi giảm còn 9,5 triệu thôi ạ."},{"speaker":"client","text":"9,5 triệu à? Đắt thế, có giảm nữa không? Mình thấy trên Shopee còn rẻ hơn."},{"speaker":"salebot","text":"Dạ, em có thể giảm thêm 200k nữa nếu bạn lấy kèm ốp lưng miễn phí ạ! Tổng còn 9,3 triệu thôi."},{"speaker":"client","text":"Ồ, vậy mình lấy luôn đi. Ship nhanh không? Mình cần gấp."},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu bạn ở Hà Nội ạ! Em sẽ gửi mã tracking ngay sau khi thanh toán xong."}]','successs',338),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ thông minh Xiaomi Watch 2 Pro, nhưng thấy giá hơi cao so với dự kiến. Bạn có thể giảm giá cho mình không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Đồng hồ Xiaomi Watch 2 Pro hiện đang có chương trình khuyến mại 5% cho khách hàng mới, còn 2.990.000đ thôi ạ!"},{"speaker":"client","text":"5% thôi à? Mà mình thấy trang khác bán 2.850.000đ luôn đó, có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ em kiểm tra lại ạ, nếu anh/chị mua kèm ốp lưng chính hãng thì em có thể giảm thêm 100.000đ nữa, thành 2.890.000đ ạ!"},{"speaker":"client","text":"Ok, mình chọn màu đen kèm ốp lưng nhé! Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị để lại số điện thoại để em xác nhận đơn hàng và gửi thông tin thanh toán nhé!"}]','successs',339),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy S24 Ultra. Mình thấy giá trên web hơi cao, có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại shop đang có chương trình khuyến mãi giảm 3 triệu cho đơn hàng trong hôm nay. Bạn có thể chọn trả góp 0% nếu muốn nữa."},{"speaker":"client","text":"Vậy giao hàng trong bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu bạn ở nội thành, hoặc 1 ngày nếu ở tỉnh. Mình gửi link thanh toán luôn nhé?"},{"speaker":"client","text":"Ok, mình chọn màu đen nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1. Cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn một ngày tốt lành. Hẹn gặp bạn sớm!"}]','successs',340),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến bộ quần áo thể thao Adidas cho bé gái 8 tuổi. Còn size 128 không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Size 128 vẫn còn hàng, nhưng chỉ còn màu xanh dương thôi. Bạn có muốn đặt không?"},{"speaker":"client","text":"Màu xanh dương cũng được. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá gốc 990k, nhưng hôm nay giảm còn 790k thôi ạ!"},{"speaker":"client","text":"Ủa, 790k à? Mình thấy trên shopee có giá 650k nè..."},{"speaker":"salebot","text":"Dạ shopee có nhiều shop lắm ạ, giá mình đã chiết khấu tối đa rồi. Nếu bạn mua kèm 1 đôi tất thể thao nữa thì mình giảm thêm 20k nha!"},{"speaker":"client","text":"Thôi khỏi, mình mua ở shopee cho rẻ. Cảm ơn nha!"}]','fail',341),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn ghế gỗ óc chó này đẹp quá. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Bàn ghế gỗ óc chó này chị ơi, giá niêm yết 12 triệu, nhưng hôm nay sale 10% nên còn 10.8 triệu thôi ạ."},{"speaker":"client","text":"Ui, 10.8 triệu hơi mắc nhỉ. Bán 9 triệu được không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá gốc đã thấp rồi ạ. Nếu chị mua kèm ghế sofa kia thì em giảm thêm 500k nữa ạ."},{"speaker":"client","text":"Thế à... vậy thôi, mình không mua nữa đâu. Cảm ơn bạn nhé!"}]','fail',342),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé gái 10 tuổi, có size từ 130-140 không ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ, bộ đồ thể thao cho bé gái size 130-140 của thương hiệu ABC còn 3 mẫu nè: hồng, xanh dương và xanh lá. Chị thích mẫu nào trước?"},{"speaker":"client","text":"Mình thích mẫu hồng, nhưng giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ mẫu hồng ni 499k chị ạ, giao hàng tận nơi miễn phí nếu đơn trên 500k nè."},{"speaker":"client","text":"Hơi đắt, có giảm giá không? Mình thấy bên shop khác bán 450k thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, sản phẩm nhập khẩu chất lượng nên giá vậy ạ. Nhưng nếu chị mua 2 bộ trở lên thì mình giảm còn 470k/ bộ nè!"},{"speaker":"client","text":"Ok, vậy mình lấy 2 bộ luôn. Bao ship sớm không?"},{"speaker":"salebot","text":"Dạ ship nội thành hôm nay trước 18h chị nhé, chị check mail để lấy mã giảm giá 5% nha! Cảm ơn chị đã ủng hộ."}]','successs',343),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm bộ quần áo thể thao cho bé gái 8 tuổi. Có size 120 không ạ?"},{"speaker":"salebot","text":"Chào chị, size 120 ạ! Bộ đồ thể thao này đang còn 2 màu: hồng và xanh dương. Chị muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu hồng nhưng giá hơi cao, có giảm giá không?"},{"speaker":"salebot","text":"Dạ, hôm nay có chương trình giảm 10% cho đơn hàng đầu tiên chị ạ! Nếu chị đặt luôn thì giá còn 450k thôi."},{"speaker":"client","text":"450k hơi đắt, mình thấy bên kia bán 400k không giảm giá. Thôi mình nghĩ lại đã."},{"speaker":"salebot","text":"Dạ, chị thông cảm ạ! Nếu cần tư vấn thêm thì chị cứ nhắn tin lại nhé."}]','fail',344),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ thông minh Galaxy Watch 5. Màu nào còn hàng vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Galaxy Watch 5 màu đen và bạc đều còn ạ. Màu bạc đang có chương trình giảm 5% cho đơn đầu tiên đó ạ!"},{"speaker":"client","text":"Mình thích màu đen nhưng hơi lo giá. Bao nhiêu tiền vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 4.990.000đ, nhưng do bạn là khách mới nên mình giảm còn 4.790.000đ thôi ạ! Ship miễn phí trong 24h luôn."},{"speaker":"client","text":"Được đấy, mình lấy luôn. Bao giờ nhận được hàng?"},{"speaker":"salebot","text":"Dạ 1 tiếng nữa là giao tới tận nơi ạ! Bạn để lại địa chỉ và số điện thoại để mình xác nhận nhé."}]','successs',345),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại xịn xò cho đứa em chơi game. Giới thiệu mình vài model tầm 15-20 triệu đi!"},{"speaker":"salebot","text":"Dạ, em giới thiệu em ơi! Redmi Note 13 Pro 5G 8GB/256GB giá 16 triệu, chip Snapdragon 7s Gen 2 mạnh mẽ lắm ạ. Còn Realme GT Neo 5 8GB/256GB tầm 18 triệu, màn hình 120Hz siêu mượt."},{"speaker":"client","text":"Ui trời, giá hơi cao so với dự định của mình. Bạn có thể giảm giá không? Mua kèm ốp lưng hoặc tai nghe không?"},{"speaker":"salebot","text":"Dạ, em check khuyến mại cho anh nhé! Nếu mua kèm ốp lưng kháng sốc 199k + tai nghe không dây 399k thì em giảm 500k luôn ạ. Chốt 15.5 triệu thôi!"},{"speaker":"client","text":"Ok ok, vậy mình lấy Redmi Note 13 Pro đi. Ship nội thành nhanh không? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Dạ, giao trong 2 tiếng ạ! Anh để lại số điện thoại và địa chỉ, em sẽ gửi mã tracking ngay cho anh nha."}]','successs',346),
('[{"speaker":"client","text":"Chào shop, mình muốn mua đôi giày thể thao Nike Air Max 90, size 42 có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size 42 vẫn còn hàng, màu đen và trắng đều có, bạn muốn màu nào?"},{"speaker":"client","text":"Mình thích màu đen thôi. Giá bao nhiêu vậy? Có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 2.590.000đ, nhưng hôm nay có chương trình khuyến mại giảm 10% cho khách hàng mới, còn 2.331.000đ thôi ạ!"},{"speaker":"client","text":"Ồ, tốt quá! Mình lấy vậy. Giao hàng tận nơi có mất phí không?"},{"speaker":"salebot","text":"Dạ giao nội thành miễn phí ạ, chỉ cần thanh toán trước là được. Bạn có muốn mình hỗ trợ đặt hàng luôn không?"},{"speaker":"client","text":"Có chứ, mình gửi thông tin luôn đây. Cảm ơn bạn nha!"}]','successs',347),
