('[{"speaker":"client","text":"Chào shop, mình đang tìm mua chiếc bàn chải điện Oral-B Genius 9000. Bạn có hàng không thế?"},{"speaker":"salebot","text":"Dạ có ạ! Màu đen và trắng đều sẵn. Bạn muốn giao trong ngày hay nhận ở cửa hàng?"},{"speaker":"client","text":"Giao trong ngày được thì tốt, nhưng mình nghe giá hơi cao so với quảng cáo. Bán rẻ hơn không?"},{"speaker":"salebot","text":"Dạ em có thể giảm 5% nếu bạn mua kèm 1 hộp tăm điện ạ. Hoặc nếu bạn lấy luôn bộ 3 sản phẩm (bàn chải + 2 hộp tăm) thì giảm 10% luôn ạ!"},{"speaker":"client","text":"Thế à? Mình lấy bộ 3 luôn đi. Địa chỉ giao là 123 Lê Lợi, phường Bến Thành, Quận 1 nhé."},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Tổng tiền sau giảm là 3.150.000đ, giao trong 2 giờ. Cảm ơn bạn đã mua sắm ạ!"}]','successs',349),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng giảm giá không? Mình thấy trên mạng thấy có chỗ bán rẻ hơn 100k đó."},{"speaker":"salebot","text":"Dạ, áo khoác này đang khuyến mại 20% còn 800k thôi ạ! Bao gồm phí ship nội thành luôn."},{"speaker":"client","text":"800k à? Mình thấy chỗ khác bán 700k kèm phí ship 50k, thế có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, mức giá này đã là ưu đãi nhất rồi. Nếu không ưng có thể tham khảo sản phẩm tương tự khác nhé!"},{"speaker":"client","text":"Thôi được, thôi được. Mình đặt tạm vậy. Bao lâu nhận hàng?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, cảm ơn bạn đã ủng hộ!"}]','fail',350),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua đôi giày thể thao Nike Air Max 90, size 42 có không?"},{"speaker":"salebot","text":"Dạ chào chị! Size 42 vẫn còn ạ, nhưng chỉ có màu trắng thôi chị nhé."},{"speaker":"client","text":"À, mình thích màu đen hơn. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ màu đen hết hàng rồi chị ạ, chị thông cảm nha. Màu trắng 2.890.000đ thôi."},{"speaker":"client","text":"Hơi đắt nhỉ, có giảm giá không?"},{"speaker":"salebot","text":"Dạ thôi chị ơi, giá niêm yết rồi chị. Nhưng nếu chị mua 2 đôi thì tặng 1 đôi vớ thể thao nha."},{"speaker":"client","text":"Thôi vậy, mình chỉ mua 1 đôi thôi. Ship bao lâu vậy?"},{"speaker":"salebot","text":"Dạ giao trong 3-5 ngày chị nhé. Chị để lại số điện thoại để mình xác nhận đơn nha."},{"speaker":"client","text":"Mình không muốn để số đâu. Thôi thôi, mình nghĩ lại vậy. Cảm ơn nhé."}]','fail',351),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc váy đen size L của shop. Còn size không vậy?"},{"speaker":"salebot","text":"Dạ chào chị, váy size L vẫn còn ạ! Giá niêm yết 890k, chị muốn mình tư vấn thêm style không?"},{"speaker":"client","text":"Cảm ơn, nhưng giá hơi cao. Có giảm giá sale không? Mình thấy bên kia bán 750k thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, shop vừa nhập đợt đầu nên giá chưa thể giảm nhiều ạ. Nhưng nếu chị mua kèm giày ở shop thì tặng 50k tiền ship nha!"},{"speaker":"client","text":"Thế à, nhưng mình chỉ mua váy thôi. Thôi thôi, để mình suy nghĩ lại vậy. Cảm ơn nha!"}]','fail',352),
('[{"speaker":"client","text":"Chào bot, mình đang cần mua bàn chải điện Philips Sonicare DiamondClean 9000, nhưng giá trên web em thấy hơi cao quá, có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Giá niêm yết là 4.990.000đ, nhưng hôm nay có khuyến mại giảm 10% nếu chị đăng ký nhận mail ạ!"},{"speaker":"client","text":"10% thôi à? Mà mình thấy bên trên shopee giảm nhiều hơn kìa, có bằng giá không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, mình không thể bằng shopee được. Nhưng nếu chị mua kèm bàn chải thay thế (1 triệu) thì mình giảm thêm 200k nữa nhé!"},{"speaker":"client","text":"Thế à... vậy thôi, mình không cần nữa đâu. Cảm ơn nhé!"}]','fail',353),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Genius X, nhưng thấy giá hơi cao quá. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ, hiện tại sản phẩm này đang có chương trình khuyến mại 15% cho đơn hàng đầu tiên trong hôm nay đó ạ!"},{"speaker":"client","text":"15% à? Mà mình thấy bên Shopee còn rẻ hơn 50k nữa kìa. Bao nhiêu tiền thế?"},{"speaker":"salebot","text":"Dạ em xin lỗi, giá niêm yết tại đây đã cố định rồi ạ. Chị có thể chọn trả góp 0% để tiện lợi hơn không?"},{"speaker":"client","text":"Thôi được, mình không có nhu cầu trả góp đâu. Cảm ơn nhé!"}]','fail',354),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ Casio G-Shock GA-2100, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Còn hàng ạ, màu đen và xanh dương đều có sẵn. Anh/chị muốn giao trong ngày không ạ?"},{"speaker":"client","text":"Mình thấy giá hơi cao so với những chỗ khác, có thể giảm giá không bạn?"},{"speaker":"salebot","text":"Dạ em xin lỗi vì điều này ạ! Nếu anh/chị mua kèm theo dây da thì em có thể giảm 5% ạ. Ngoài ra, nếu thanh toán bằng ví MoMo sẽ được tặng thêm 1 cặp pin dự phòng ạ."},{"speaker":"client","text":"Ok, vậy mình chọn màu đen kèm dây da nhé. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ ạ, giao trong 2 giờ nếu anh/chị ở nội thành. Em sẽ gửi mã tracking qua Zalo cho anh/chị ngay sau khi xác nhận đơn ạ. Cảm ơn anh/chị đã mua sắm cùng shop!"}]','successs',355),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, bạn có thể tư vấn không?"},{"speaker":"salebot","text":"Dạ có ạ! Chiếc bàn chải này hiện đang giảm 20% giá gốc 2.590.000₫ còn 2.072.000₫. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Ồ, giá khá hời đấy! Nhưng mình nghe nói bàn chải này hay hỏng sớm lắm, có bảo hành lâu không?"},{"speaker":"salebot","text":"Dạ bảo hành 24 tháng ạ, lỗi do nhà sản xuất sẽ đổi mới hoàn toàn. Còn lỗi do người dùng thì hỗ trợ sửa chữa."},{"speaker":"client","text":"Vậy mình cân nhắc thêm chút, có thể giảm giá thêm không? Mình thấy bên khác bán 1.950.000₫ kèm quà tặng."},{"speaker":"salebot","text":"Dạ em xin phép check lại ạ... 1.990.000₫ là giá tốt nhất rồi ạ, nếu bạn mua kèm kem đánh răng Oral-B 3D White thì tặng kèm 1 tuýp."},{"speaker":"client","text":"Thế à, vậy mình không mua nữa, cảm ơn bạn nhé!"}]','fail',356),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc đồng hồ thể thao cho con trai. Nó mới 15 tuổi thôi, nên giá tầm 2-3 triệu là ổn."},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em thấy Casio G-Shock GA-2100 hay lắm ạ, giá 2.5 triệu, chống nước, chống sốc, rất phù hợp cho tuổi teen ạ."},{"speaker":"client","text":"Mấy nay mình đang tiết kiệm nên hơi eo hẹp. Có thể giảm giá cho mình không? 2 triệu thôi được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi anh/chị, giá này đã là ưu đãi nhất rồi ạ. Nếu anh/chị lấy 2 chiếc trở lên thì em có thể giảm thêm 50k/1 chiếc ạ."},{"speaker":"client","text":"Thế à, vậy thôi. Mà mình ở xa quá, giao hàng mất bao lâu vậy?"},{"speaker":"salebot","text":"Dạ giao trong 3-5 ngày ạ, phí ship 30k nếu anh/chị không lấy đủ 500k ạ. Em có thể gửi link đặt hàng qua zalo không ạ?"},{"speaker":"client","text":"Thôi mình bỏ qua vậy. Chúc shop may mắn nhé!"}]','fail',357),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái điện thoại Samsung Galaxy S24 Ultra trên web có khuyến mại không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang giảm 5 triệu khi mua kèm ốp lưng chính hãng."},{"speaker":"client","text":"Ốp lưng bao nhiêu tiền vậy? Mình chỉ cần điện thoại thôi."},{"speaker":"salebot","text":"Dạ ốp lưng 500k ạ, nhưng nếu mua kèm thì được giảm 5 triệu luôn. Tiết kiệm hơn nhiều!"},{"speaker":"client","text":"Thế nếu mình không lấy ốp lưng thì sao? Giá điện thoại có giảm không?"},{"speaker":"salebot","text":"Dạ không ạ, giá điện thoại vẫn như cũ. Nếu bạn muốn tiết kiệm, mình khuyên nên mua kèm ốp lưng nhé!"},{"speaker":"client","text":"Thế à... thôi mình không mua nữa, cảm ơn bạn nhé!"}]','fail',358),
('[{"speaker":"client","text":"Chào em, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Sản phẩm này đang trong tình trạng sắp hết hàng rồi ạ, chỉ còn 2 cái cuối thôi."},{"speaker":"client","text":"À vậy à, giá bao nhiêu vậy em?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 2.490.000đ, nhưng do sắp hết hàng nên mình có giảm còn 2.290.000đ thôi ạ."},{"speaker":"client","text":"Hơi đắt quá, mình thấy trên shopee có giá 2 triệu rưỡi kìa."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá trên shopee có thể là giá cũ hoặc khuyến mại thôi ạ. Đây là giá cuối cùng rồi ạ, nếu anh/chị muốn đặt trước thì em sẽ giữ hàng cho."},{"speaker":"client","text":"Thôi vậy, mình để đó đã. Cảm ơn em nhé!"}]','fail',359),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và hồng đều có sẵn. Bạn muốn giao tận nơi hay nhận tại cửa hàng?"},{"speaker":"client","text":"Giao tận nơi luôn nhé. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ 1.999.000đ thôi ạ, đã bao gồm quà tặng là 2 đầu bàn chải thay thế. Bạn có muốn thanh toán online không?"},{"speaker":"client","text":"Ok, mình thanh toán bằng momo nhé. Cảm ơn bạn!"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua hàng! Chúc bạn sức khỏe và hẹn gặp lại."}]','successs',360),
('[{"speaker":"client","text":"Chào bot! Mình thấy cái nồi chống dính 30cm của nhà bếp Sunhouse giá 599k, bây giờ có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Hiện tại nồi Sunhouse 30cm đang giảm còn 499k thôi ạ, chỉ trong hôm nay thôi chị nhé!"},{"speaker":"client","text":"Wow, giảm nhiều thế! Thế có giao hàng tận nhà không? Mình ở quận 7 đấy."},{"speaker":"salebot","text":"Dạ có chị ơi! Giao miễn phí trong 24h nếu chị đặt trước 18h hôm nay. Chị có muốn mình hỗ trợ thêm gì không ạ?"},{"speaker":"client","text":"Ok, mình lấy luôn 1 cái nồi vậy. Bao giờ nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ chị sẽ nhận hàng vào chiều mai ạ. Em gửi mã đơn hàng qua Zalo cho chị nhé! Cảm ơn chị đã mua sắm cùng shop."}]','successs',361),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác Nike thể thao này. Size L có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size L còn 2 cái, màu xanh dương và đen. Bạn muốn đặt màu nào?"},{"speaker":"client","text":"Mình thích màu xanh nhưng giá hơi cao so với mình. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ không ạ, giá niêm yết rồi. Nhưng bạn có thể nhập mã giảm giá ''SALE20'' để được 10% nhé!"},{"speaker":"client","text":"10% vẫn hơi cao, mình chỉ định mua nếu giá dưới 1,5 triệu thôi."},{"speaker":"salebot","text":"Dạ tiếc quá, giá gốc là 1,8 triệu rồi, chúng tôi không thể giảm thêm ạ."},{"speaker":"client","text":"Thôi vậy, cảm ơn bạn nhé! Tạm biệt."}]','fail',362),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này. Size S còn không thế?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Size S vẫn còn 2 cái, màu xanh dương và đen. Anh/chị muốn màu nào ạ?"},{"speaker":"client","text":"Màu đen đi. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ 999k ạ, đang có khuyến mại 10% nên chỉ còn 899k thôi ạ."},{"speaker":"client","text":"Hơi đắt nhỉ, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ anh/chị đặt luôn thì mình giảm thêm 5% nữa nhé, còn 854k ạ. Giao trong 2h nếu anh/chị ở TPHCM."},{"speaker":"client","text":"Ok, mình lấy. Địa chỉ giao là 123 Lê Lợi, Q1. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Anh/chị vui lòng thanh toán trước 50% để xác nhận đơn hàng nha. Cảm ơn anh/chị đã mua sắm cùng shop!"}]','successs',363),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc điện thoại thông minh tầm 10 triệu thôi. Bạn có gợi ý không?"},{"speaker":"salebot","text":"Dạ có ạ! Điện thoại Samsung Galaxy A14 128GB giá 9,99 triệu, còn khuyến mãi 500k nếu bạn mua hôm nay. Bạn thấy sao?"},{"speaker":"client","text":"Mình thích nhưng hơi đắt. Có thể giảm giá thêm không?"},{"speaker":"salebot","text":"Dạ, nếu bạn mua kèm ốp lưng chính hãng tặng kèm, mình có thể giảm xuống 9,5 triệu ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Bạn hỗ trợ giao hàng tận nơi không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn vui lòng cung cấp địa chỉ và số điện thoại để mình xử lý đơn hàng nhé. Cảm ơn bạn đã mua sắm!"}]','successs',364),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G, nhưng giá trên web hơi cao quá, có deal gì không ạ?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Hiện tại chúng mình đang có chương trình khuyến mại giảm 5% cho sản phẩm này nếu anh/chị thanh toán bằng thẻ ngân hàng nội địa ạ."},{"speaker":"client","text":"Giảm 5% thôi à? Có thể giảm thêm không, mình thấy bên đối thủ có giá thấp hơn 1 triệu nữa đó."},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, mức giảm 5% là ưu đãi tối đa cho sản phẩm mới ra mắt này rồi ạ. Nhưng nếu anh/ch chị đăng ký nhận tin tức khuyến mại, mình sẽ gửi mã giảm 10% cho lần mua sau ạ!"},{"speaker":"client","text":"Ok, vậy mình chọn màu đen, giao trong ngày được không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị vui lòng cung cấp địa chỉ cụ thể để mình báo giá vận chuyển nhé. Tổng tiền sau giảm giá là 24.750.000đ, phí ship nội thành 22.000đ ạ."}]','successs',365),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua chiếc điện thoại Samsung Galaxy S24 Ultra, nhưng giá trên web cao quá. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại Galaxy S24 Ultra đang khuyến mại 10% nếu thanh toán bằng thẻ ngân hàng nội địa. Còn 5 phút nữa là hết ưu đãi này nè."},{"speaker":"client","text":"10% à? Mình thấy trên Shopee còn rẻ hơn 500k nữa. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ thật lòng anh/chị ơi, giá trên web đã là giá tốt nhất rồi ạ. Nếu anh/chị mua kèm ốp lưng chính hãng tặng 50k nữa thì được không ạ?"},{"speaker":"client","text":"Thế thôi, mình không mua thêm gì đâu. Cảm ơn nhé!"}]','fail',366),
('[{"speaker":"client","text":"Chào anh, mình đang tìm mua một chiếc điện thoại tầm trung để thay thế chiếc cũ. Có sản phẩm nào mới và đáng tiền không?"},{"speaker":"salebot","text":"Dạ chào chị! Em gợi ý chị chiếc Xiaomi Redmi Note 13 Pro 5G vừa ra mắt ạ. Màn hình AMOLED 120Hz, camera 200MP, giá 7.990.000đ thôi ạ!"},{"speaker":"client","text":"Ồ, nghe cũng ổn. Nhưng mình thấy trên shopee giá rẻ hơn 1 triệu, có giảm giá không?"},{"speaker":"salebot","text":"Dạ giá trên web đã là giá sốc rồi ạ! Nhưng nếu chị đặt ngay hôm nay, em có thể giảm thêm 200k cho chị nhé. Tổng còn 7.790.000đ ạ."},{"speaker":"client","text":"Được rồi, mình chọn luôn. Mình ở quận 1, giao hàng nhanh không?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ ạ! Em sẽ gửi link thanh toán qua Zalo ngay bây giờ ạ. Cảm ơn chị đã ủng hộ!"}]','successs',367),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bàn chải điện Philips Sonicare DiamondClean 9000. Có màu xanh dương không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương vẫn còn hàng, mình gửi link sản phẩm kèm giá ưu đãi 15% cho bạn nè."},{"speaker":"client","text":"Giá niêm yết 4.990.000, vậy mình được giảm còn bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giảm còn 4.241.500 ạ, kèm quà tặng là 2 đầu bàn chải thay thế. Bạn nhận luôn hôm nay không?"},{"speaker":"client","text":"Ok, mình chọn giao vào chiều mai nhé. Địa chỉ: 123 Lê Lợi, phường Bến Nghé, quận 1."},{"speaker":"salebot","text":"Dạ đã ghi nhận đơn hàng ạ! Cảm ơn bạn đã mua sắm cùng shop, chúc bạn ngày mới vui vẻ!"}]','successs',368),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác denim nữ hiệu Levi''s, size M. Bạn có size này không vậy?"},{"speaker":"salebot","text":"Chào bạn ạ! Dạ shop có size M của Levi''s 511, màu xanh nhạt và đen. Bạn muốn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh nhạt hơn. Giá bao nhiêu vậy bạn?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.299.000đ, nhưng hôm nay có khuyến mại 10% nên chỉ còn 1.169.000đ thôi ạ!"},{"speaker":"client","text":"Hơi đắt so với mình, 1.100.000đ được không bạn? Mua 1 cái thôi nha."},{"speaker":"salebot","text":"Dạ không dám ạ, shop giảm tối đa 10% thôi. Nhưng nếu bạn mua kèm khăn len, shop giảm thêm 50k nữa nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy áo + khăn len. Địa chỉ giao là 123 Lê Lợi, Phường Bến Thành, Quận 1."},{"speaker":"salebot","text":"Dạ 100% rồi ạ! Tổng tiền 1.269.000đ, shop sẽ giao trong 2h. Cảm ơn bạn đã mua sắm cùng shop!"}]','successs',369),
('[{"speaker":"client","text":"Chào, mình muốn mua chiếc bàn chải điện Oral-B Genius X 10000 của hãng. Có giảm giá gì không thế?"},{"speaker":"salebot","text":"Dạ có ạ! Đang khuyến mại 20% cho sản phẩm này, chỉ còn 1.599.000đ thay vì 1.999.000đ."},{"speaker":"client","text":"1.599k hơi đắt, mình thấy nơi khác bán 1.350k thôi. Có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ không ạ, mức giá này đã là ưu đãi nhất rồi. Bạn có thể chọn trả góp 0% nếu muốn ạ."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',370),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc váy này nhưng nhìn thấy giá hơi cao so với dự định. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc váy này đang sale 20% cho đơn hàng đầu tiên đấy chị. Giá gốc 1.200.000đ, giờ còn 960.000đ thôi!"},{"speaker":"client","text":"Thế có miễn phí ship không? Mình ở xa một chút."},{"speaker":"salebot","text":"Dạ chị ơi, ship nội thành miễn phí luôn ạ. Còn ngoại thành thì 30.000đ thôi nè. Chị có muốn mình kiểm tra mã giảm giá khác không?"},{"speaker":"client","text":"Ok, mình lấy luôn nhé. Thanh toán online được chứ?"},{"speaker":"salebot","text":"Dạ vâng chị! Chị có thể thanh toán qua momo, vnpay hoặc chuyển khoản đều được ạ. Mình sẽ gửi link cho chị ngay!"}]','successs',371),
('[{"speaker":"client","text":"Chào shop, mình muốn mua điện thoại Samsung Galaxy A54 5G. Bạn có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Còn 2 màu: xanh lam và đen. Bạn muốn đặt luôn không ạ?"},{"speaker":"client","text":"Mình thấy giá 12 triệu hơi cao nhỉ, có giảm được không?"},{"speaker":"salebot","text":"Dạ shop mình đã giảm xuống 11 triệu 5 rồi ạ, đây là giá tốt nhất rồi ạ!"},{"speaker":"client","text":"Thế à, 11 triệu 5 thì mình cân nhắc đã. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Nếu cần hỗ trợ thêm thì cứ inbox shop nhé!"}]','fail',372),
('[{"speaker":"client","text":"Chào bot, mình thấy bộ quần áo thể thao này đẹp quá, nhưng giá 1 triệu 5 hơi đắt. Có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ, hôm nay có chương trình khuyến mại 10% cho khách hàng mới, còn 1 triệu 350k thôi ạ!"},{"speaker":"client","text":"Thế giao hàng tận nhà miễn phí chứ? Mình không có xe ra lấy."},{"speaker":"salebot","text":"Dạ có ạ! Miễn phí giao hàng nội thành, chỉ 2 giờ nữa là tới nơi luôn."},{"speaker":"client","text":"Ok, mình chọn size M nhé. Thanh toán online được không?"},{"speaker":"salebot","text":"Dạ được ạ! Chúng mình hỗ trợ tất cả phương thức thanh toán: tiền mặt, chuyển khoản, ví điện tử. Bạn chọn nhé."}]','successs',373),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua một chiếc điện thoại thông minh tầm 10 triệu thôi. Có mẫu nào mới không?"},{"speaker":"salebot","text":"Dạ có ạ! Samsung Galaxy A35 5G vừa ra mắt, giá 9.990.000đ, pin 5000mAh, màn hình AMOLED 120Hz. Bạn thích màu nào?"},{"speaker":"client","text":"Màu xanh dương được không? Còn giảm giá nữa không?"},{"speaker":"salebot","text":"Dạ có ạ! Giảm còn 8.990.000đ nếu bạn mua trong hôm nay, kèm quà tặng là ốp lưng cao cấp. Bạn nhận hàng ở đâu?"},{"speaker":"client","text":"Mình ở quận 1, giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Đơn hàng sẽ giao trong 2-4 tiếng, bạn thanh toán COD hay chuyển khoản?"},{"speaker":"client","text":"COD nhé, cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn một ngày vui vẻ, hẹn gặp lại!"}]','successs',374),
('[{"speaker":"client","text":"Chào shop, mình thấy chiếc bàn chải điện Philips Sonicare DiamondClean 9000 có khuyến mại gì không?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang giảm 20% cho sản phẩm này, chỉ còn 3.200.000đ thay vì 4.000.000đ. Bạn muốn mua không?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có thể giảm thêm không? Mình thấy bên kia bán 2.900.000đ đấy."},{"speaker":"salebot","text":"Dạ, mình sẽ cố gắng hỗ trợ cho bạn ạ! Nếu mua kèm theo đầu bàn chải dự phòng (giá 500.000đ) thì mình có thể giảm xuống 3.000.000đ trọn bộ. Bạn thấy thế nào?"},{"speaker":"client","text":"Ok, mình đồng ý. Bao lâu nhận được hàng?"},{"speaker":"salebot","text":"Dạ, giao trong 1-2 ngày làm việc ạ. Bạn để lại số điện thoại để mình xác nhận đơn hàng nhé!"}]','successs',375),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao của Adidas, size L có không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Bộ có đủ màu đen, xanh dương và xám. Bạn muốn size L thì có 2 size: L và XL, bạn chọn size nào?"},{"speaker":"client","text":"Mình chọn L thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ bộ đó giá 1.290.000đ ạ! Nếu bạn mua 2 bộ thì giảm còn 1.150.000đ/1 bộ luôn nè."},{"speaker":"client","text":"Ôi, hơi đắt quá. Mình thấy bên kia bán có 1.050.000đ thôi, shop có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ shop mình không có chính sách giảm nhiều hơn ạ, nhưng nếu bạn nhận hàng nhanh trong 2h thì mình tặng luôn mũ thể thao 50k nha!"},{"speaker":"client","text":"Thôi được, mình nghĩ lại rồi. Cảm ơn nha!"}]','fail',376),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng thấy giá hơi cao quá. Có giảm giá cho mình không?"},{"speaker":"salebot","text":"Dạ chào chị! Chị đang xem mẫu áo khoác mùa đông này đúng không ạ? Hiện tại shop đang có chương trình giảm 10% nếu chị mua trong hôm nay. Chị có muốn mình check size sẵn sàng không?"},{"speaker":"client","text":"Mấy size có sẵn cho mình? Mình mặc size M."},{"speaker":"salebot","text":"Dạ size M chị ơi, còn 3 cái. Giá gốc 1.290.000đ, sau khi giảm còn 1.161.000đ thôi chị. Chị lấy luôn không ạ?"},{"speaker":"client","text":"Ok, mình lấy rồi. Địa chỉ giao là 123 Lê Lợi, phường Bến Thành, quận 1 nhé."},{"speaker":"salebot","text":"Dạ chị vui lòng chuyển khoản 1.161.000đ vào số tài khoản 0123456789 (Techcombank) nhé. Đơn hàng sẽ giao trong 2 giờ tới ạ. Cảm ơn chị đã mua sắm!"}]','successs',377),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn ghế gỗ óc chó này đẹp quá. Mình muốn mua 1 bộ, nhưng giá có hơi cao so với dự định. Bao nhiêu tiền vậy?"},{"speaker":"salebot","text":"Dạ bộ bàn ghế gỗ óc chó này giá 12 triệu 500 ngàn ạ. Đồ nội thất cao cấp nên giá hơi cao 1 chút, nhưng chất lượng gỗ óc chó nguyên khối, bền lắm ạ!"},{"speaker":"client","text":"Ừ, mình cũng thích chất lượng rồi. Nhưng 12 triệu rưỡi thì hơi đắt quá. Bán cho mình 10 triệu 500 ngàn được không?"},{"speaker":"salebot","text":"Dạ không ạ, giá đó chúng em không thể giảm được vì chi phí gỗ óc chó nguyên liệu đang tăng cao lắm. Chúng em có thể giảm 500 ngàn cho bạn, thành 12 triệu là giá cuối cùng rồi ạ."},{"speaker":"client","text":"Thế à... 12 triệu thì mình chưa mua được ngay. Để mình suy nghĩ lại rồi liên hệ sau nhé. Cảm ơn bạn!"}]','fail',378),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm chiếc bàn chải đánh răng điện Philips Sonicare DiamondClean, có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại bàn chải đang giảm 20% còn 1.999.000đ, kèm quà tặng là 2 đầu bàn chải thay thế. Bạn muốn đặt luôn không ạ?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có thể giảm thêm không? Mình thấy bên kia bán giá 1.850.000đ kìa."},{"speaker":"salebot","text":"Dạ, vì sản phẩm này đang khuyến mại nên không thể giảm thêm nữa ạ. Nhưng nếu bạn mua kèm 1 lọ nước súc miệng Philips, mình sẽ tặng 1 đầu bàn chải nữa ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn bộ đó vậy. Giao hàng miễn phí chứ?"},{"speaker":"salebot","text":"Dạ có ạ! Đơn hàng sẽ giao trong 2-3 ngày. Cảm ơn bạn đã mua sắm cùng shop!"}]','successs',379),
('[{"speaker":"client","text":"Chào shop, mình muốn mua đôi giày thể thao Nike Air Max 90, size 42 có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen đều có size 42. Bạn muốn mua màu nào?"},{"speaker":"client","text":"Mình thích màu xanh dương nhưng giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 2.500.000đ, nhưng hôm nay sale 10% nên còn 2.250.000đ thôi ạ!"},{"speaker":"client","text":"Hơi đắt quá, mình thấy bên kia bán 2.100.000đ không ship phí."},{"speaker":"salebot","text":"Dạ không ạ, giá này đã là ưu đãi rồi. Nếu bạn mua kèm vớ thể thao thì giảm thêm 5% nữa."},{"speaker":"client","text":"Thôi vậy, chắc mình không mua nữa. Cảm ơn nhé!"}]','fail',380),
('[{"speaker":"client","text":"Chào bạn, mình cần mua một chiếc đồng hồ thể thao cho anh trai. Anh ấy thích màu xanh dương, có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em thấy anh trai chị phù hợp với mẫu Casio G-Shock GMW-B5000DC-1, màu xanh dương kim loại, chống nước 200m, giá 4.990.000đ ạ."},{"speaker":"client","text":"Ồ, đẹp quá! Nhưng giá hơi cao so với dự định của mình, có thể giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ em kiểm tra thấy hôm nay có chương trình khuyến mại 5% cho sản phẩm này, nên còn 4.740.500đ thôi ạ. Nếu anh/chị mua kèm dây da thì tặng luôn 1 cái ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn vậy! Ship trong ngày được không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ gửi đơn hàng ngay bây giờ. Anh/chị vui lòng cho địa chỉ chi tiết và số điện thoại nhận hàng ạ."}]','successs',381),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái bàn phím cơ Keychron K8 giá 2 triệu rưỡi, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Chúng mình đang có chương trình khuyến mại 10% cho đơn từ 2 triệu, nên bàn phím này bạn chỉ cần trả 2 triệu 250k thôi ạ!"},{"speaker":"client","text":"Ui, vậy có miễn phí ship không? Mình ở xa lắm."},{"speaker":"salebot","text":"Dạ tiếc quá ạ, ship nội thành mới miễn phí. Bạn có thể chọn ship tiết kiệm 30k hoặc giao nhanh 50k ạ."},{"speaker":"client","text":"Thế à, vậy mình cân nhắc lại vậy. Cảm ơn nhé!"}]','fail',382),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại thông minh tầm 10 triệu. Bạn có gợi ý gì không?"},{"speaker":"salebot","text":"Dạ, mình giới thiệu anh/chị chiếc Xiaomi Redmi Note 12 Pro 5G giá 9,99 triệu ạ! Cấu hình khỏe, màn hình AMOLED 120Hz, pin 5000mAh, rất đáng tiền."},{"speaker":"client","text":"Mình thấy trên mạng giá rẻ hơn 1 triệu, sao giá của bạn cao thế?"},{"speaker":"salebot","text":"Dạ, giá niêm yết là 9,99 triệu ạ, nhưng nếu anh/chị đặt mua hôm nay mình có voucher giảm 200k, còn 9,79 triệu thôi ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn chiếc này. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu anh/chị ở nội thành, hoặc trong ngày mai nếu ở tỉnh thành khác ạ. Anh/chị có muốn chọn màu xanh dương hay đen không?"},{"speaker":"client","text":"Mình chọn màu đen. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Cảm ơn anh/chị đã mua hàng, chúc anh/chị một ngày tốt lành!"}]','successs',383),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị, chiếc áo khoác này hiện có giá 1.200.000đ, chị có size nào ưu thích không ạ?"},{"speaker":"client","text":"Mình mặc size M thôi. Có giảm giá gì không? Đồ online thấy nhiều nơi rẻ hơn..."},{"speaker":"salebot","text":"Dạ chị thông cảm, đây là giá tốt nhất rồi ạ! Nhưng nếu chị mua 2 sản phẩm trở lên sẽ giảm 5% cho chị nhé."},{"speaker":"client","text":"Thế à... mình chỉ mua mỗi cái này thôi. Bao giờ giao được vậy?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày làm việc chị nhé. Nếu không ưng ý chị có thể trả hàng miễn phí trong 7 ngày."},{"speaker":"client","text":"Ok, thôi mình không mua nữa. Cảm ơn nhé!"}]','fail',384),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra 5G 256GB trên web có khuyến mãi không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại đang giảm 3 triệu, còn 20.990.000đ thôi. Mà bạn ở đâu để mình check phí ship nhé!"},{"speaker":"client","text":"Mình ở Đà Nẵng, phí ship có đắt lắm không? Mà mình thấy giá hơi cao, giảm thêm được không?"},{"speaker":"salebot","text":"Dạ phí ship tận nhà khoảng 30k-50k tùy cân nặng ạ. Nếu bạn mua trong hôm nay, mình giảm thêm 500k nữa nhé!"},{"speaker":"client","text":"Ok, mình lấy luôn vậy. Bao lâu giao tới được?"},{"speaker":"salebot","text":"Dạ giao nhanh trong 2 ngày ạ! Bạn để lại số điện thoại và địa chỉ chi tiết nhé, mình gửi mã giảm giá qua tin nhắn luôn."}]','successs',385),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình đang có khuyến mãi 20% cho sản phẩm này trong tuần này nè."},{"speaker":"client","text":"À, thế giá gốc là bao nhiêu vậy? Mình thấy trên mạng cũng có nhưng không rõ chất lượng."},{"speaker":"salebot","text":"Dạ giá gốc là 2.500.000đ, nay chỉ còn 2.000.000đ thôi ạ. Bao gồm sạc và 2 đầu bàn chải tặng kèm."},{"speaker":"client","text":"Hơi đắt so với mình nghĩ, có giảm nữa không? Mình thấy bên kia bán 1.800.000đ luôn."},{"speaker":"salebot","text":"Dạ em xin phép check lại ạ... À, nếu bạn mua trong hôm nay thì em có thể giảm thêm 100k nữa, thành 1.900.000đ nhé!"},{"speaker":"client","text":"Thế giao hàng mất bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, nhưng nếu bạn chọn ship nhanh thì 1 ngày có ngay. phí ship 30k nha."},{"speaker":"client","text":"Thôi vậy, cảm ơn nhé. Mình cân nhắc lại đã."}]','fail',386),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua một chiếc điện thoại tầm trung, ngân sách khoảng 5-6 triệu thôi. Bạn có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ có ạ! Em giới thiệu chiếc Xiaomi Redmi Note 12 4GB/128GB giá 5,99 triệu, cấu hình ổn định cho nhu cầu cơ bản. Bạn có quan tâm không?"},{"speaker":"client","text":"Mình thấy giá hơi cao so với kỳ vọng. Có giảm được không? Mình thấy bên kia bán 5,5 triệu cơ."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá niêm yết của hãng không giảm được nữa. Nhưng nếu bạn mua kèm ốp lưng và màn hình dán khuyến mại, em có thể tặng thêm 100k ạ."},{"speaker":"client","text":"Thế ốp lưng và màn hình dán loại nào? Chất lượng thế nào?"},{"speaker":"salebot","text":"Dạ ốp lưng silicon chống sốc, màn hình dán cường lực 9H chống xước ạ. Đi kèm sản phẩm chính hãng từ Xiaomi. Bạn có muốn đặt không?"},{"speaker":"client","text":"Thôi được, mình mua vậy. Bao lâu giao hàng được?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, phí ship 20k nếu bạn ở TPHCM. Bạn có muốn thanh toán trước 30% không?"},{"speaker":"client","text":"Không, mình thanh toán khi nhận hàng thôi. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ em cảm ơn ạ! Chúc bạn một ngày tốt lành."}]','fail',387),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S24 Ultra. Giá trên web là 32 triệu, có giảm được không?"},{"speaker":"salebot","text":"Dạ chào chị! Chị ở đâu ạ? Em check xem có thể hỗ trợ giảm giá không. Ngoài ra, chị có muốn mua kèm ốp lưng không ạ? Giảm 200k cho combo."},{"speaker":"client","text":"Mình ở Hà Nội. Ốp lưng thì mình chưa quyết định, nhưng nếu giảm giá điện thoại xuống 30 triệu thì mình lấy luôn."},{"speaker":"salebot","text":"Dạ chị thông cảm, giá sàn của sản phẩm là 31 triệu ạ. Nhưng em có thể hỗ trợ chị 1 triệu giảm giá + tặng ốp lưng silicon xịn. Được không ạ?"},{"speaker":"client","text":"Thế thì ok, mình lấy luôn. Ship nhanh trong ngày được không?"},{"speaker":"salebot","text":"Dạ vâng chị! Em sẽ xử lý đơn hàng ngay, giao trong 2-3 tiếng tới ạ. Chị check thông tin sau nha: [Tên + SĐT + Địa chỉ]. Có gì thắc mắc cứ nhắn em nha!"}]','successs',388),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Đang giảm 30% giá gốc, chỉ còn 1.990.000đ thôi."},{"speaker":"client","text":"Ôi, giá hơi cao so với mình mong đợi, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ anh chị ơi, đây là giá sốc nhất rồi ạ. Nếu mua kèm kem đánh răng Oral-B 3D White thì được tặng 1 tuýp nha."},{"speaker":"client","text":"Thế à, nhưng mình chỉ cần bàn chải thôi. Thôi thì thôi, mình bỏ qua vậy."}]','fail',389),
('[{"speaker":"client","text":"Chào em, mình đang tìm mua chiếc áo khoác mùa đông này. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị, áo khoác này có giá 1.299.000đ chị nhé. Loại vải chống gió siêu ấm, giao hàng tận nơi luôn ạ."},{"speaker":"client","text":"Ồ, đắt quá! Em có thể giảm giá cho mình không? Mình thấy trên trang khác có bán rẻ hơn 200k đó."},{"speaker":"salebot","text":"Dạ chị thông cảm, đây là sản phẩm chính hãng nên giá đã ổn định rồi ạ. Nhưng nếu chị đặt ngay hôm nay, mình có thể tặng kèm khăn len trị giá 99k, chị thấy thế nào?"},{"speaker":"client","text":"Thế à? Nhưng mình vẫn thấy hơi mắc. Thôi được, mình nghĩ thêm đã rồi quay lại sau vậy."}]','fail',390),
('[{"speaker":"client","text":"Chào shop, mình đang tìm mua chiếc điện thoại Samsung Galaxy S23 Ultra. Bạn có còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ vẫn còn ạ! Màu đen và xanh lá đều có sẵn. Bạn muốn đặt trước hay giao hàng tận nơi ạ?"},{"speaker":"client","text":"Mình thích màu đen. Giá bao nhiêu vậy? Có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 28 triệu, nhưng hôm nay có chương trình khuyến mại giảm 2 triệu nếu mua trong hôm nay. Bạn lấy luôn không ạ?"},{"speaker":"client","text":"Ok, mình lấy luôn. Giao trong ngày được không? Tiền mặt hay chuyển khoản?"},{"speaker":"salebot","text":"Dạ giao trong ngày tận nơi miễn phí nếu bạn ở nội thành. Chuyển khoản ưu đãi hơn 5% nha! Bạn chọn phương thức nào ạ?"}]','successs',391),
('[{"speaker":"client","text":"Chào! Cho mình hỏi chiếc áo khoác da này còn size L không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size L vẫn còn hàng, nhưng chỉ có màu đen thôi nha."},{"speaker":"client","text":"Màu đen cũng được. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 1.599.000đ ạ, đang giảm giá 20% nên khá hời luôn nè!"},{"speaker":"client","text":"Đắt quá, mình thấy nơi khác chỉ 1.3tr thôi..."},{"speaker":"salebot","text":"Dạ đây là giá niêm yết ạ, nhưng nếu bạn lấy 2 cái trở lên thì mình giảm thêm 5% nha!"},{"speaker":"client","text":"Thế à... Mình chỉ cần 1 thôi. Không giảm nữa à?"},{"speaker":"salebot","text":"Dạ thôi lỗ quá ạ, mình cố gắng giảm còn 1.5tr vậy nha!"},{"speaker":"client","text":"Ừm... Thôi vậy, mình lấy 1 cái. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ không ạ, hôm nay hết hàng rồi, giao vào ngày mai nha!"},{"speaker":"client","text":"Vậy thôi, mai mình quay lại lấy. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn bạn đã quan tâm ạ! Chúc bạn ngày tốt lành!"}]','fail',392),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc đồng hồ Casio G-Shock GA-2100-1A3 trên web khá ưng, nhưng giá 2 triệu rưỡi có hơi đắt không nhỉ?"},{"speaker":"salebot","text":"Dạ, đây là phiên bản mới nhất với thiết kế siêu bền và chống sốc, ạ! Chúng tôi có giảm giá 5% nếu bạn chọn thanh toán qua ngân hàng nội địa."},{"speaker":"client","text":"5% thì vẫn còn 2 triệu 375k, mình thấy chỗ khác bán 2 triệu 150k thôi..."},{"speaker":"salebot","text":"Dạ, chúng tôi cam kết sản phẩm chính hãng 100% từ Casio, còn chỗ kia có thể là hàng nhái ạ. Nếu không ưng, mình có thể gửi link so sánh chất lượng cho bạn xem ạ!"},{"speaker":"client","text":"Thế à... thôi mình nghĩ mình sẽ suy nghĩ thêm rồi quay lại sau vậy. Cảm ơn nhé!"}]','fail',393),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác da này nhưng giá 3 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ, đây là sản phẩm da thật nhập khẩu nên giá hơi cao ạ. Nhưng em có mã giảm 5% cho khách hàng đầu tiên nè, chỉ còn 2.85 triệu thôi!"},{"speaker":"client","text":"Mình thấy trên mạng thấy giá rẻ hơn nhiều, chắc không mua nữa đâu."},{"speaker":"salebot","text":"Dạ em xin lỗi vì không thể đáp ứng được ạ. Chúc bạn ngày tốt lành!"}]','fail',394),
('[{"speaker":"client","text":"Chào mình là Linh, mình đang tìm mua một chiếc điện thoại mới. Bên mình có iPhone 15 Pro Max màu tím không vậy?"},{"speaker":"salebot","text":"Dạ chào Linh ạ! Chúng mình có iPhone 15 Pro Max tím chuẩn 100%, còn 5 chiếc. Bạn muốn mua không ạ?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm giá không? Mình thấy nơi khác bán 27 triệu rưỡi."},{"speaker":"salebot","text":"Dạ giá niêm yết là 29 triệu, nhưng Linh là khách mới nên giảm còn 28 triệu 500k thôi ạ. Có bảo hành chính hãng 12 tháng luôn."},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Bạn có giao hàng tận nơi không? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ có ạ! Giao miễn phí trong 2 giờ nếu bạn đặt trong hôm nay. Bạn gửi địa chỉ cụ thể để mình báo phí ship ạ."},{"speaker":"client","text":"Cảm ơn, mình gửi địa chỉ qua đây nha: 123 Đường Nguyễn Văn Linh, Phường Tân Phong, Quận 7."},{"speaker":"salebot","text":"Dạ cảm ơn Linh ạ! Đơn hàng của bạn đã được xác nhận. Chúc bạn ngày mới vui vẻ!"}]','successs',395),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đã giảm còn 1.299.000đ từ 1.799.000đ, giao trong 3 ngày."},{"speaker":"client","text":"Mà mình thấy ship phí 50k, có miễn phí không?"},{"speaker":"salebot","text":"Dạ không ạ, nhưng nếu bạn mua kèm dung dịch vệ sinh 50ml giá 99k thì miễn phí ship nha!"},{"speaker":"client","text":"Ồ, vậy mình không lấy nữa. Thanks!"}]','fail',396),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy A54 5G. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Chào chị ạ! Dạ Galaxy A54 5G của mình đang có giá 8.990.000đ, màu đen và xanh dương đều có ạ. Chị muốn mua không ạ?"},{"speaker":"client","text":"Mình thấy hơi đắt, có chương trình giảm giá gì không?"},{"speaker":"salebot","text":"Dạ chị ơi, mình đang có chương trình tặng ốp lưng miễn phí và giảm 500k khi thanh toán qua ví Momo. Nếu chị mua combo luôn thì giá chỉ còn 8.490.000đ thôi ạ!"},{"speaker":"client","text":"Ok, mình chọn màu đen đi. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ chị yên tâm, giao trong 2 giờ nếu chị ở Hà Nội ạ. Địa chỉ nhận hàng là thế nào ạ?"},{"speaker":"client","text":"Mình ở 123 Lê Thánh Tông, quận Hoàn Kiếm. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc chị một ngày tốt lành. Đơn hàng của chị đã được xác nhận, cám ơn chị đã mua sắm cùng shop!"}]','successs',397),
('[{"speaker":"client","text":"Chào shop, mình thấy đôi giày thể thao Nike Air Max 90 đang giảm giá 30% thế à? Mình muốn mua size 42 nhưng không biết còn hàng không?"},{"speaker":"salebot","text":"Dạ vâng ạ, size 42 vẫn còn ạ! Giá gốc 3.500.000đ giờ chỉ còn 2.450.000đ thôi ạ. Bạn muốn mình check kho phụ không?"},{"speaker":"client","text":"Hơi đắt quá, mình thấy bên kia bán 2.200.000đ mà. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ không ạ, giá đã là ưu đãi nhất rồi ạ. Nhưng nếu bạn mua kèm vớ thể thao, mình có thể tặng bạn 1 đôi vớ cotton miễn phí ạ!"},{"speaker":"client","text":"Thôi mình không mua nữa, cảm ơn nhé!"}]','fail',398),
('[{"speaker":"client","text":"Chào em, mình muốn mua bộ quần áo thể thao cho bé 10 tuổi. Bên em có size 140 không ạ?"},{"speaker":"salebot","text":"Dạ có ạ, bộ quần áo thể thao cho bé size 140 vẫn còn 3 mã màu. Màu xanh dương, hồng và đen. Bạn thích màu nào?"},{"speaker":"client","text":"Màu xanh dương đi. Giá bao nhiêu thế? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 499k, nhưng hôm nay em có khuyến mại 10% nếu bạn mua kèm giày thể thao ạ. Giá sau giảm còn 449k thôi."},{"speaker":"client","text":"À mình chỉ mua quần áo thôi. Thôi vậy 449k cũng được, nhưng giao hàng tận nơi miễn phí chứ?"},{"speaker":"salebot","text":"Dạ giao tận nơi miễn phí trong nội thành ạ, nhưng phí ship ngoại thành 30k. Bạn chọn địa chỉ nào ạ?"},{"speaker":"client","text":"Mình ở quận 7, giao trong ngày được không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ ạ, giao trong ngày trong giờ hành chính ạ. Bạn vui lòng cung cấp số điện thoại để shop xác nhận đơn hàng nhé."},{"speaker":"client","text":"À mình không có nhu cầu nữa đâu, cảm ơn nhé!"}]','fail',399),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc bàn làm việc này. Giá niêm yết 2.500.000đ có được giảm không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chị là khách hàng mới hay đã từng mua hàng ở shop rồi ạ? Nếu chị mua ngay hôm nay, shop có voucher 5% cho chị nè!"},{"speaker":"client","text":"Mình là khách mới. Vậy có miễn phí vận chuyển không? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ miễn phí vận chuyển nội thành chị ạ! Bàn có bảo hành 2 năm đầy đủ. Chị muốn thanh toán bằng tiền mặt hay chuyển khoản?"},{"speaker":"client","text":"Ok, mình chọn chuyển khoản. Gửi link cho mình nhé!"},{"speaker":"salebot","text":"Dạ vui lòng chuyển khoản vào số tài khoản sau: 123456789 (TechShop). Nội dung ghi: Tên + SĐT + ''Bàn làm việc''. Shop sẽ xác nhận và giao hàng trong 2h chị nhé!"}]','successs',400),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng giá hơi cao so với mình mong muốn. Có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Hiện sản phẩm này đang có chương trình khuyến mãi 10% khi thanh toán bằng thẻ ngân hàng. Anh/chị có muốn áp dụng không?"},{"speaker":"client","text":"Nếu vậy thì mình chọn thẻ ngân hàng luôn. Còn phí vận chuyển thế nào vậy?"},{"speaker":"salebot","text":"Dạ phí vận chuyển trong nội thành là 20k, ngoài ra miễn phí trên 500k. Anh/chị có muốn chọn giao vào ngày mai không?"},{"speaker":"client","text":"Được, vậy mình đặt luôn. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Cảm ơn anh/ch chị đã mua hàng. Chúc anh/chị ngày mới vui vẻ!"}]','successs',401),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc đồng hồ Casio G-Shock GA-2100, bạn có size phù hợp không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size 20.5cm đang còn hàng, màu đen và xanh dương. Bạn muốn chọn màu nào?"},{"speaker":"client","text":"Mình thích màu xanh dương nhưng giá hơi cao so với dự định. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ shop có voucher giảm 10% cho đơn trên 1 triệu, bạn có thể dùng mã SALE10. Hoặc mình tư vấn thêm sản phẩm khác nhé?"},{"speaker":"client","text":"Ừ, vậy mình sẽ suy nghĩ thêm. Cảm ơn nhé!"}]','fail',402),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc váy len đen size M, còn không?"},{"speaker":"salebot","text":"Dạ chào chị, váy len size M còn 5 chiếc ạ! Giá niêm yết 1.200k, chị có muốn đặt trước không?"},{"speaker":"client","text":"Mấy trăm vậy? Đắt quá, em giảm cho chị 1.000k thôi nhé?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá vốn đã thấp nhất rồi. Chị lấy 2 chiếc đi, tặng kèm khăn len nhé?"},{"speaker":"client","text":"Thôi vậy, gửi em 1 cái size M thôi. Địa chỉ: 123 Lê Lợi, quận 1."},{"speaker":"salebot","text":"Dạ chị vui lòng chuyển khoản 1.000k vào số này ạ: 0123456789 (MBBank). Cảm ơn chị!"}]','fail',403),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao cho bé nhà mình. Bé mới 5 tuổi thôi, có size nào không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Chúng mình có size 5-6 tuổi nè, cả nam lẫn nữ. Màu sắc thì có xanh dương, hồng và trắng. Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ bộ này giá 350k ạ, mình có giảm giá 10% nếu bạn mua kèm mũ thể thao nè!"},{"speaker":"client","text":"Hơi đắt quá, mình thấy bên kia bán 300k thôi. Bạn có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá này là ổn nhất rồi ạ. Nhưng nếu bạn mua 2 bộ trở lên thì giá 320k/ bộ nè!"},{"speaker":"client","text":"Thôi không mua nữa, cảm ơn bạn nhé!"}]','fail',404),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc bàn phím cơ Keychron K8, mình thấy nó khá đắt so với giá mình nghĩ. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Bàn phím Keychron K8 hiện đang có chương trình khuyến mại giảm 10% cho đơn hàng trong hôm nay, giá chỉ còn 1.990.000đ thôi ạ!"},{"speaker":"client","text":"Ồ, vậy thì tốt quá! Mình mua luôn. Bao lâu thì giao được vậy?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày làm việc ạ, mình sẽ gửi mã tracking sau khi thanh toán thành công. Bạn chọn màu nào ạ?"},{"speaker":"client","text":"Mình chọn màu trắng nhé. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ, hẹn gặp lại!"}]','successs',405),
('[{"speaker":"client","text":"Chào! Mình thấy cái bàn làm việc kiểu công thái học của bạn có mẫu GamerPro 2000, bao nhiêu tiền vậy?"},{"speaker":"salebot","text":"Dạ mẫu GamerPro 2000 hiện đang giảm giá còn 2.990.000đ thôi ạ! Chất liệu chống trơn trượt, nâng đỡ lưng tốt lắm."},{"speaker":"client","text":"Ồ, vậy có bảo hành không? Mình thấy chỗ khác bán rẻ hơn 200k cơ."},{"speaker":"salebot","text":"Dạ bảo hành chính hãng 2 năm ạ! Còn 200k kia chắc là hàng trôi nổi, không rõ nguồn gốc. Nếu mua của mình, mình tặng luôn gối cổ miễn phí ạ!"},{"speaker":"client","text":"Thôi được, mình cân nhắc đã. Cảm ơn nhé!"}]','fail',406),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc bàn chải điện cho gia đình. Bạn có loại nào tốt và giá cả phải chăng không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng tôi có bàn chải điện Philips Sonicare ProtectiveClean 6100, giá 2.490.000đ, dùng công nghệ rung siêu âm, bảo hành 2 năm."},{"speaker":"client","text":"Mình thấy hơi đắt so với ngân sách 2 triệu. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, đây là sản phẩm cao cấp nên giá đã ưu đãi. Nhưng nếu chị mua kèm kem đánh răng tặng 3 tháng, mình giảm còn 2.350.000đ nha!"},{"speaker":"client","text":"Ừ, vậy mình lấy luôn. Bao lâu giao được ạ?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu chị ở TP.HCM, chị vui lòng để lại địa chỉ và số điện thoại ạ!"}]','successs',407),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc váy này nhưng nhìn hơi ngắn, có size dài hơn không?"},{"speaker":"salebot","text":"Dạ xin lỗi ạ, size S và M chỉ có mẫu ngắn thôi. Size L thì may dài hơn 5cm nhưng giá sẽ cao hơn 150k."},{"speaker":"client","text":"Hơi đắt nhỉ, mình thấy trên Shopee cùng mẫu rẻ hơn 300k."},{"speaker":"salebot","text":"Dạ shop mình miễn phí ship nội thành, Shopee thì phí 30k. Còn kém 150k thôi ạ!"},{"speaker":"client","text":"Thế à, nhưng mình vẫn thấy chênh lệch quá. Thôi cảm ơn nhé, bye!"}]','fail',408),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác mùa đông này nhưng giá hơi cao so với mình. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại sản phẩm đang giảm 15% cho đợt khuyến mại cuối tháng, chị có thể thanh toán qua ví MoMo hoặc chuyển khoản để được nhận thêm 5% nữa."},{"speaker":"client","text":"Thế giá cuối cùng là bao nhiêu thế? Mình thấy trên web ghi 2.500.000đ nhưng mình chỉ có 2.300.000đ thôi."},{"speaker":"salebot","text":"Dạ chị ơi, giá cuối cùng sau khi giảm 15% + 5% ưu đãi thanh toán là 2.125.000đ thôi ạ. Nếu chị nhận hàng tại shop, mình có thể giảm thêm 50k nữa cho chị nhé!"},{"speaker":"client","text":"Ok, mình chọn màu đen size M vậy. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ chị ở đâu ạ? Nếu nội thành HN thì giao trong 2h, ngoại thành thì 1-2 ngày ạ. Mình sẽ gửi mã tracking ngay sau khi thanh toán ạ!"}]','successs',409),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ có ạ! Máy Galaxy S23 Ultra màu đen 128GB đang có giá 25 triệu, giao trong 2h nếu bạn ở TP.HCM."},{"speaker":"client","text":"25 triệu à? Mà mình thấy trên shopee giá có 23 triệu kèm khuyến mại. Bạn giảm được không?"},{"speaker":"salebot","text":"Dạ giá niêm yết ạ, nhưng nếu bạn lấy combo sạc + ốp lưng thì mình có thể giảm 500k ạ."},{"speaker":"client","text":"Thế combo ấy bao nhiêu vậy? Mình chỉ cần máy thôi."},{"speaker":"salebot","text":"Dạ vậy thì thôi ạ, mình xin lỗi vì không thể giảm giá hơn được. Cảm ơn bạn đã quan tâm!"}]','fail',410),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn phím cơ Keychron K8, nhưng thấy giá hơi cao thế ạ?"},{"speaker":"salebot","text":"Dạ, giá niêm yết là 2.990.000đ, nhưng hôm nay có khuyến mãi 5% nếu bạn đặt ngay!"},{"speaker":"client","text":"5% thì vẫn còn hơn 2.8 triệu, mình thấy bên shop khác bán 2.6 triệu thôi..."},{"speaker":"salebot","text":"Dạ, mình có thể giảm thêm 100k nếu bạn lấy kèm bộ dây USB-C nữa ạ. Tổng cộng 2.790.000đ, giao tận nơi miễn phí!"},{"speaker":"client","text":"Thế à... cuối tuần mình suy nghĩ lại rồi quyết định sau vậy. Cảm ơn bạn nhé!"}]','fail',411),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác da nam này nhưng giá hơi cao so với mình. Có giảm giá không?"},{"speaker":"salebot","text":"Chào bạn! Hiện tại shop đang có chương trình giảm 10% cho đơn hàng từ 2 triệu trở lên đó ạ."},{"speaker":"client","text":"Mình thấy giá gốc đã 2,5 triệu rồi, giảm 10% vẫn còn 2,25 triệu. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ, mình sẽ hỗ trợ bạn giảm xuống 2 triệu nếu mua kèm đôi giày thể thao bên shop ạ. Bên mình có combo giá ưu đãi!"},{"speaker":"client","text":"Ồ, thế à? Mình chỉ mua áo thôi. Thôi để lần sau vậy, cảm ơn nhé!"}]','fail',412),
('[{"speaker":"client","text":"Chào, mình đang tìm đồ chơi cho bé nhà mình. Có sản phẩm nào an toàn cho trẻ 3 tuổi không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi có bộ đồ chơi xếp hình bằng gỗ không sơn, đạt tiêu chuẩn an toàn châu Âu, giá 499k ạ."},{"speaker":"client","text":"Đắt quá nhỉ, mình thấy bên khác bán rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ sản phẩm này nhập khẩu nguyên chiếc từ Đức, chất liệu gỗ cứng cáp, bé chơi không mẻ ạ. Nếu anh/chị lấy 2 bộ thì giảm còn 450k/ bộ ạ."},{"speaker":"client","text":"Thế à, mình cân nhắc rồi quay lại sau nhé."}]','fail',413),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn phím cơ Keychron K8 trên web có giá 2.499.000đ, có khuyến mãi gì không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại sản phẩm đang giảm còn 2.299.000đ thôi ạ, kèm theo quà tặng là bàn chải vệ sinh bàn phím miễn phí!"},{"speaker":"client","text":"À vậy à, thế giao hàng có mất phí không? Mình ở Đà Nẵng nè."},{"speaker":"salebot","text":"Dạ giao tận nơi ở Đà Nẵng chỉ mất 35.000đ thôi ạ, hoặc anh/chị chọn giao nhanh trong 2h thì 50.000đ ạ!"},{"speaker":"client","text":"Ok, mình chọn giao nhanh trong 2h đi. Vậy tổng tiền hết bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ tổng cộng 2.349.000đ ạ (sản phẩm 2.299.000đ + phí ship 50.000đ). Anh/chị có muốn thêm mouse pad không ạ? Có ưu đãi 50% nè!"},{"speaker":"client","text":"Thôi khỏi, mình chỉ cần bàn phím thôi. Vậy mình đặt luôn đây, cám ơn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn anh/chị đã mua hàng! Đơn hàng sẽ được giao trong 2h ạ. Chúc anh/chị một ngày tốt lành!"}]','successs',414),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy A54 5G. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Samsung Galaxy A54 5G của mình đang có giá 8.990.000đ, màu xanh lam và đen đều sẵn. Bạn muốn mua không ạ?"},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm giá không? Mình thấy nơi khác bán 8.500.000đ thôi."},{"speaker":"salebot","text":"Dạ thôi thì mình giảm xuống 8.700.000đ cho bạn, được không ạ? Đi kèm là quà tặng sạc không dây trị giá 300.000đ luôn nè!"},{"speaker":"client","text":"Ok, mình lấy vậy. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ mình cam kết giao trong 2 tiếng nếu bạn ở TP.HCM, phí ship 20.000đ. Bạn đồng ý chứ ạ?"},{"speaker":"client","text":"Được, mình đồng ý. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Cảm ơn bạn đã mua sắm cùng shop. Chúc bạn một ngày vui vẻ!"}]','successs',415),
('[{"speaker":"client","text":"Chào em, mình thấy cái bàn chải điện Oral-B Pro 3000 trên web có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại sản phẩm đang giảm 20% còn 1.200.000đ thôi ạ. Còn 5 cái cuối cùng trong kho."},{"speaker":"client","text":"Ồ, vậy có kèm quà tặng gì không? Mình nghe nói có kèm đầu bàn chải dự phòng."},{"speaker":"salebot","text":"Dạ có ạ! Mỗi bộ tặng kèm 2 đầu bàn chải dự phòng miễn phí ạ. Anh/chị muốn đặt luôn không ạ?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có thể giảm thêm không? Bán 1.000.000đ mình lấy luôn."},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, mức giá đã là ưu đãi nhất rồi ạ. Nếu anh/chị lấy 2 bộ thì mình có thể giảm 50.000đ mỗi bộ ạ."},{"speaker":"client","text":"Thôi vậy, mình lấy 1 bộ thôi. Địa chỉ giao là 123 Lê Lợi, Quận 1 nhé."},{"speaker":"salebot","text":"Dạ vâng ạ! Anh/chị vui lòng chuyển khoản 1.200.000đ vào số tài khoản 123456789 ngân hàng Techcombank ạ. Cảm ơn anh/chị đã tin tưởng mua sắm!"}]','fail',416),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc váy xanh dương này nhưng không biết size có vừa không?"},{"speaker":"salebot","text":"Dạ chào chị! Size M hay L thường vừa ạ, chị có thể đo vòng eo và xem hướng dẫn size trên web nhé!"},{"speaker":"client","text":"Mình đo rồi, eo 70cm thì size nào hợp lý?"},{"speaker":"salebot","text":"Eo 70cm thì size S sẽ vừa ạ, nhưng chị có thể chọn size M nếu thích rộng rãi hơn! Giá hiện tại 1.299k, chị có muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Nếu giảm còn 999k thì mua ngay!"},{"speaker":"salebot","text":"Dạ chị thông cảm, giá đã chiết khấu 20% rồi ạ! Nhưng nếu chị đặt trong 2 giờ nữa, mình gửi mã code giảm thêm 5% nha!"},{"speaker":"client","text":"Thế à? Ok, mình chọn size S và lấy luôn, mình gửi địa chỉ sau nhé!"},{"speaker":"salebot","text":"Dạ chị vui lòng gửi địa chỉ và số điện thoại để mình xác nhận đơn hàng ạ! Cảm ơn chị đã mua sắm cùng shop!"}]','successs',417),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn làm việc gỗ óc chó trên web có giá 3 triệu 5 trăm. Mà bây giờ sale giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào anh! Hiện tại bàn gỗ óc chó chỉ còn 2 triệu 8, giảm 20% thôi ạ. Anh có muốn đặt không?"},{"speaker":"client","text":"2 triệu 8 à? Đắt quá, mình thấy chỗ khác có 2 triệu 5 thôi. Bớt cho mình 2 triệu 2 đi được không?"},{"speaker":"salebot","text":"Dạ anh ơi, 2 triệu 5 là giá sỉ rồi, mình không giảm thêm được ạ. Nếu anh mua kèm ghế văn phòng giảm 5% nữa nha!"},{"speaker":"client","text":"Thôi được, nhưng giao hàng tận nơi miễn phí nhé. Không thì thôi!"},{"speaker":"salebot","text":"Dạ ạ! Anh cứ yên tâm, giao miễn phí trong 24h. Anh để lại số điện thoại và địa chỉ nhé!"},{"speaker":"client","text":"À không, mình đổi ý rồi. Thôi để dịp khác vậy. Cảm ơn!"}]','fail',418),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc túi xách da thật cho vợ. Có loại nào vừa túi tiền vừa chất lượng không?"},{"speaker":"salebot","text":"Dạ có ạ! Em giới thiệu mẫu túi da bò cao cấp của thương hiệu ABC, giá 1.200.000đ, vừa sang trọng lại bền. Bạn có muốn xem ảnh sản phẩm không?"},{"speaker":"client","text":"1.200.000đ hơi đắt nhỉ, có giảm giá không? Hay trả góp được không?"},{"speaker":"salebot","text":"Dạ bọn em có chương trình giảm 5% nếu thanh toán bằng ví MoMo, còn trả góp 0% lãi suất trong 3 tháng. Nếu bạn thích thì em gửi link sản phẩm qua Zalo nhé?"},{"speaker":"client","text":"Ok, mình mua luôn. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP HCM. Ship nhanh không?"},{"speaker":"salebot","text":"Dạ vâng ạ! Đơn hàng sẽ giao trong 2 tiếng. Cảm ơn bạn đã mua sắm cùng shop!"}]','successs',419),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ Casio G-Shock GA-2100, có màu xanh dương không?"},{"speaker":"salebot","text":"Dạ, hiện tại màu xanh dương đã hết hàng rồi chị ạ. Chị có thể tham khảo màu đen hoặc xanh lá không?"},{"speaker":"client","text":"Hết rồi à? Chán quá, mình thích màu xanh dương lắm. Có cách nào để đặt trước không?"},{"speaker":"salebot","text":"Dạ, chị có thể để lại thông tin để mình báo khi có hàng lại nhé! Hoặc chị xem thêm mẫu GA-1100 giá 1.2 triệu, cũng hợp thời trang."},{"speaker":"client","text":"1.2 triệu à? Đắt quá, mình thấy ngoài kia bán 900k thôi. Bao giờ giảm giá?"},{"speaker":"salebot","text":"Dạ, giá niêm yết của hãng là 1.2 triệu, nhưng nếu chị mua kèm dây da tặng 50k hoặc thanh toán qua ngân hàng ưu đãi 5% nha chị."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',420),
('[{"speaker":"client","text":"Chào shop! Mình thấy sản phẩm áo khoác chống thấm này khá đẹp, nhưng mình là dân văn phòng, không hay đi ra ngoài trời mưa nên có cần thiết không nhỉ?"},{"speaker":"salebot","text":"Dạ, áo này có lớp chống thấm tốt lắm ạ! Nếu bạn đi xe máy hay ra ngoài buổi tối thì vẫn hữu ích đó. Chỉ 599k thôi, rẻ hơn nhiều so với ngoài cửa hàng."},{"speaker":"client","text":"Thế à? Nhưng mình thấy giá hơi cao, có giảm được không? 500k thì sao?"},{"speaker":"salebot","text":"Dạ, 599k là giá niêm yết rồi ạ. Nếu bạn mua 2 cái hoặc giới thiệu bạn bè thì mình giảm còn 550k cho 1 cái thôi!"},{"speaker":"client","text":"Ý mình là 500k thôi, nếu không thì thôi. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ, không có giảm được ạ. Chúc bạn ngày tốt lành!"}]','fail',421),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc bàn làm việc gỗ óc chó cho phòng khách. Có loại nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Bên mình có bàn gỗ óc chó nguyên khối, kích thước 120x60cm giá 5.5 triệu đồng. Có mẫu cổ điển và hiện đại, anh/chị muốn xem ảnh không?"},{"speaker":"client","text":"Mẫu cổ điển thì sao? Mình thích phong cách vintage ấy."},{"speaker":"salebot","text":"Dạ mẫu cổ điển có chân xoắn, mặt bóng gỗ óc chó tự nhiên ạ. Giá niêm yết 5.5 triệu, nhưng hôm nay có ưu đãi giảm còn 4.8 triệu nếu anh/chị thanh toán online."},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm nữa không? 4 triệu được không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm, giá đã ưu đãi lắm rồi ạ. Mà nếu anh/chị mua kèm ghế gỗ nữa thì mình giảm thêm 200k, thành 4.6 triệu thôi!"},{"speaker":"client","text":"Thôi được, mình không cần ghế nữa. Cảm ơn nhé, để mình suy nghĩ lại đã."}]','fail',422),
('[{"speaker":"client","text":"Chào shop, mình muốn mua đôi giày thể thao Nike Air Max 90, nhưng giá trên web thấy hơi cao so với shop khác."},{"speaker":"salebot","text":"Dạ em hiểu ạ, nhưng sản phẩm này đang khuyến mại 10% cho đơn hàng đầu tiên trong hôm nay. Nếu bạn nhận hàng trong 2 giờ nữa, còn free ship nữa nè."},{"speaker":"client","text":"Thế giá cuối cùng là bao nhiêu vậy? Mình thấy shop khác bán 1.800.000đ thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá gốc 2.200.000đ nhưng ưu đãi hôm nay chỉ còn 1.990.000đ thôi ạ. Nếu bạn mua thêm 1 đôi phụ kiện, em giảm thêm 50k nha."},{"speaker":"client","text":"Thế không được nữa à? Mình thấy trên shopee có 1.750.000đ kèm quà tặng luôn."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá mình đã chào tốt nhất rồi. Nếu bạn không hài lòng, em xin phép kết thúc cuộc trò chuyện ạ. Cảm ơn bạn đã quan tâm!"}]','fail',423),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác denim nữ hiệu Levi''s size M, giá bao nhiêu nhỉ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Áo Levi''s size M hiện đang có giá 1.299.000đ, chị muốn chọn màu nào ạ? Màu xanh navy hay màu đen?"},{"speaker":"client","text":"Mình thích màu xanh navy nhưng hơi lo là giá hơi cao, có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chị yên tâm ạ! Nếu chị mua trong hôm nay thì shop giảm ngay 10% cho chị, còn 1.169.100đ thôi ạ. Chị có muốn đặt luôn không?"},{"speaker":"client","text":"Okie, mình lấy luôn nhé! Ship trong ngày được không shop?"},{"speaker":"salebot","text":"Dạ được ạ! Chị cung cấp địa chỉ và số điện thoại để shop xác nhận đơn hàng nha chị."}]','successs',424),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn làm việc gỗ óc chó này đẹp quá. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ, bàn gỗ óc chó 4 chân giá 5.500.000đ ạ, giao tận nhà miễn phí trong nội thành."},{"speaker":"client","text":"Ồ, hơi đắt nhỉ. Bạn có thể giảm còn 4.800.000đ không? Mình thấy trên shopee cũng có giá tương tự."},{"speaker":"salebot","text":"Dạ, 5.200.000đ được không ạ? Đây là giá tốt nhất vì gỗ óc chó nhập khẩu 100%."},{"speaker":"client","text":"Thế à... thôi mình bỏ qua vậy. Cảm ơn nhé!"}]','fail',425),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo sơ mi trắng của thương hiệu Zara, size M có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Áo sơ mi trắng size M còn 3 chiếc, giao hàng miễn phí nếu bạn đặt trong hôm nay."},{"speaker":"client","text":"Giá bao nhiêu thế? Mình thấy trên web ghi 890k nhưng có giảm giá không?"},{"speaker":"salebot","text":"Dạ, hôm nay ưu đãi 10% cho sản phẩm này, chỉ còn 799k thôi ạ! Kèm theo quà tặng là móc khóa Zara nho nhỏ."},{"speaker":"client","text":"Ok, mình chọn size M. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Nếu bạn ở Hà Nội, giao trong 2 giờ ạ! Nếu nơi khác, 1-2 ngày thôi. Bạn có muốn thanh toán online hay COD?"},{"speaker":"client","text":"Mình thanh toán online nhé. Gửi link cho mình!"},{"speaker":"salebot","text":"Dạ đây ạ: [link thanh toán]. Sau khi thanh toán xong, mình sẽ gửi mã vận đơn cho bạn ngay!"}]','successs',426),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, nhưng giá trên web hơi cao so với nơi khác. Bạn có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Bàn chải Oral-B Pro 3000 hiện đang khuyến mại 10% cho đơn hàng đầu tiên, chỉ còn 1.890.000đ thôi ạ. Có kèm quà tặng là 3 đầu bàn chải thay thế nữa!"},{"speaker":"client","text":"Ồ, vậy thì được. Mình chọn màu trắng nhé. Bạn giao trong hôm nay được không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị để lại số điện thoại và địa chỉ chi tiết, mình sẽ xử lý đơn hàng ngay. Cảm ơn anh/chị đã mua sắm cùng shop!"}]','successs',427),
('[{"speaker":"client","text":"Chào, mình đang tìm bộ quần áo thể thao cho bé gái 5 tuổi. Bên mình có size 5-6 tuổi không?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu mới nhất vừa về, màu hồng và xanh dương. Bạn muốn xem ảnh không?"},{"speaker":"client","text":"Mình thấy ảnh rồi, nhưng giá 590k hơi cao nhỉ? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, giá niêm yết vậy ạ. Nhưng nếu bạn mua 2 cái trở lên sẽ giảm 10% cho mỗi sản phẩm."},{"speaker":"client","text":"Thế à... 2 cái thì tốn 1.062k, vẫn hơi đắt. Mình chỉ cần 1 cái thôi."},{"speaker":"salebot","text":"Dạ, 590k là giá tốt nhất rồi ạ. Nếu không ưng, mình có thể gửi link sản phẩm khác giá rẻ hơn cho bạn tham khảo ạ."},{"speaker":"client","text":"Thôi vậy, cảm ơn nhé. Mình để đó suy nghĩ thêm."}]','fail',428),
