('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và hồng đều còn. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy giá 2.500.000đ hơi đắt, có giảm giá không?"},{"speaker":"salebot","text":"Dạ giá niêm yết là vậy ạ, nhưng nếu bạn mua kèm kem đánh răng Oral-B 30ml thì giảm 10% ạ."},{"speaker":"client","text":"Thế thôi, mình bỏ qua vậy. Cảm ơn nhé!"}]','fail',430),
('[{"speaker":"client","text":"Chào shop, mình nhìn thấy bộ quần áo thể thao của Adidas trên web, có size S không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size S vẫn còn 5 chiếc, nhưng màu xanh lá đã hết rồi ạ."},{"speaker":"client","text":"Thế màu đen và xám thì sao? Mình thích màu tối hơn."},{"speaker":"salebot","text":"Dạ 2 màu đó vẫn đủ size S ạ. Giá gốc 1.290.000đ, giờ sale còn 990.000đ thôi ạ."},{"speaker":"client","text":"Mà mình thấy shop hay giảm nữa không? Giảm xuống 850.000đ được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, mức giảm này là mức thấp nhất rồi ạ. Nếu bạn mua 2 sản phẩm trở lên thì giảm thêm 5% nữa ạ."},{"speaker":"client","text":"Thế à, tiếc quá. Mình chỉ cần 1 cái thôi. Thôi để lúc khác vậy nhé!"}]','fail',431),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm bàn chải điện cho gia đình 4 người. Có loại nào tốt và tiết kiệm không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Chúng tôi có bàn chải điện Oral-B Genius X 10000, giá 2.590.000đ, tích hợp cảm biến thông minh. Nếu anh/chị mua combo 2 chiếc thì giảm còn 4.500.000đ ạ!"},{"speaker":"client","text":"Ui trời ơi, giá hơi cao so với túi tiền mình. Có loại nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ em có Oral-B Vital 100 giá 1.290.000đ, nhưng không có màn hình thông minh ạ. Anh/chị có nhu cầu không?"},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',432),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác này nhưng giá 2 triệu hơi đắt quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, hiện tại shop đang có chương trình giảm 10% cho đơn hàng đầu tiên, vậy 1.8 triệu nhé!"},{"speaker":"client","text":"1.8 triệu vẫn hơi cao, mình thấy bên kia bán giá 1.5 triệu thôi. Không thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ, giá gốc đã thấp nhất rồi ạ, mình có thể tặng kèm khăn lau miễn phí nếu bạn mua trong hôm nay?"},{"speaker":"client","text":"Thôi, mình nghĩ để cân nhắc thêm. Cảm ơn bot nhé!"}]','fail',433),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng thấy giá hơi cao so với mình. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ, hôm nay là ngày siêu sale 11.11! Áo khoác này chỉ còn 899k thôi ạ (giá gốc 1.299k). Bạn muốn chọn size nào không?"},{"speaker":"client","text":"Mình thích size M nhưng hơi lo lắng về chất liệu. Nó có thoáng khí không nhỉ?"},{"speaker":"salebot","text":"Dạ chất liệu 100% polyester chống thấm nhẹ, thoáng khí tốt ạ. Mình gửi kèm video review về sản phẩm trong link đây nè!"},{"speaker":"client","text":"Ok, mình sẽ mua size M. Bạn có giao hàng tận nơi không? Phí ship bao nhiêu?"},{"speaker":"salebot","text":"Dạ giao tận nơi miễn phí nếu đơn trên 500k ạ! Đơn của bạn đã đủ điều kiện rồi. Mình sẽ gửi mã giảm giá 50k cho lần mua sau nhé!"}]','successs',434),
('[{"speaker":"client","text":"Chào bot! Mình muốn mua chiếc áo khoác thể thao này của Nike. Size M có không vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Size M vẫn còn ạ, màu xanh dương và đen đều sẵn. Chị muốn giao trong ngày không?"},{"speaker":"client","text":"Ừ, giao trong ngày được thì tốt. Mà giá bao nhiêu vậy? Có khuyến mại gì không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.990.000đ, hôm nay sale 15% nên còn 1.691.500đ chị nhé! Nếu chị thanh toán qua ví Momo thì giảm thêm 5% nữa."},{"speaker":"client","text":"Thế 1.691.500đ thôi à? Mà nếu mình lấy 2 cái thì có giảm nữa không?"},{"speaker":"salebot","text":"Dạ nếu chị lấy 2 cái cùng màu thì mình giảm thêm 10% cho mỗi cái, tức là 1.522.350đ/cái ạ! Tổng 3.044.700đ chị nhé."},{"speaker":"client","text":"Ok, vậy mình lấy 2 cái luôn. Địa chỉ giao là 123 Lê Lợi, phường Bến Nghé, quận 1 nhé."},{"speaker":"salebot","text":"Dạ chị vui lòng chuyển khoản 3.044.700đ vào số tài khoản 123456789 (Techcombank) nhé! Shop sẽ giao trong 2 giờ."}]','successs',435),
('[{"speaker":"client","text":"Chào em, mình thấy chiếc điện thoại Samsung Galaxy A54 128GB trên web có khuyến mãi không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện sản phẩm đang có chương trình giảm 1 triệu cho đơn hàng đầu tiên trong hôm nay ạ!"},{"speaker":"client","text":"Ồ, vậy giá cuối cùng là bao nhiêu thế? Mình nghe bảo giá gốc có 9 triệu rưỡi ấy."},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Sau khuyến mãi còn 8 triệu 5 trăm ngàn ạ, giao tận nhà miễn phí luôn ạ!"},{"speaker":"client","text":"Hơi đắt nhỉ, mình thấy bên kia bán 8 triệu thôi mà. Thôi để mình suy nghĩ lại vậy."},{"speaker":"salebot","text":"Dạ không sao ạ! Anh/chị có thể quay lại sau hoặc để lại số điện thoại, em sẽ nhắn tin nhắc nhở ạ!"}]','fail',436),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào chị! Oral-B Pro 3000 hiện đang có ưu đãi giảm 15% cho đơn hàng đầu tiên chị ạ. Chị muốn chọn màu nào? Trắng hay xanh dương?"},{"speaker":"client","text":"Mình thích màu trắng. Vậy giá sau giảm là bao nhiêu vậy bạn?"},{"speaker":"salebot","text":"Giá gốc 2.990.000đ, sau giảm còn 2.541.500đ chị nhé. Giao tận nhà trong 2 ngày, chị có muốn đặt luôn không?"},{"speaker":"client","text":"Ok, mình chọn màu trắng luôn nhé. Có quà tặng kèm không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Kèm theo 1 tuýp kem đánh răng Oral-B Pro-Health trị giá 200.000đ. Chị có thể thanh toán COD hoặc chuyển khoản đều được."},{"speaker":"client","text":"Cảm ơn bạn, mình chọn COD nhé. Địa chỉ là 123 đường Lê Lợi, phường Bến Nghé, quận 1."},{"speaker":"salebot","text":"Dạ, đơn hàng của chị đã được ghi nhận! Chúng tôi sẽ giao trong vòng 48h và liên hệ trước khi giao. Chúc chị sức khỏe!"}]','successs',437),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác thể thao này. Size M còn không?"},{"speaker":"salebot","text":"Dạ còn ạ! Màu đen và xanh dương đều có size M. Bạn muốn chọn màu nào?"},{"speaker":"client","text":"Mình thích màu xanh dương nhưng giá hơi cao, có giảm giá không?"},{"speaker":"salebot","text":"Dạ shop đang có khuyến mại 10% cho sản phẩm này trong hôm nay, bạn có thể nhập mã SALE10 khi thanh toán."},{"speaker":"client","text":"Ok, mình lấy màu xanh dương vậy. Nhưng mình ở xa, giao hàng mất bao lâu?"},{"speaker":"salebot","text":"Dạ trong vòng 3-5 ngày là tới ạ, phí ship 20k nếu bạn ở tỉnh xa. Bạn có muốn mình hỗ trợ đặt hàng luôn không?"},{"speaker":"client","text":"Thôi mình nghĩ vậy, mình sẽ suy nghĩ thêm rồi liên hệ sau. Cảm ơn nhé!"}]','fail',438),
('[{"speaker":"client","text":"Chào em, mình muốn mua chiếc áo khoác mùa đông này. Màu xanh dương size L có không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Chúng em vừa kiểm tra thì size L màu xanh dương đã hết hàng rồi ạ. Anh/chị xem màu xám hoặc size M có được không ạ?"},{"speaker":"client","text":"À thế à. Màu xám thì mình không thích lắm. Size M thì mình mặc hơi chật. Có cách nào khác không?"},{"speaker":"salebot","text":"Dạ thôi em xin lỗi anh/chị ạ. Hiện tại thì sản phẩm này hết size L màu xanh dương rồi nên không thể hỗ trợ được ạ. Em mong anh/chị thông cảm!"}]','fail',439),
('[{"speaker":"client","text":"Chào, mình thấy nồi chiên không dầu Philips HD6220 có khuyến mại gì không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Giảm 20% trong tuần này, chỉ còn 1.990.000đ thay vì 2.490.000đ. Bao gồm cả quà tặng là sách nấu ăn miễn phí!"},{"speaker":"client","text":"Thế giao hàng mất bao lâu vậy? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Nếu bạn ở Hà Nội thì giao trong 2 giờ, ngoài ra là 1 ngày. Còn nếu chọn nhận tại cửa hàng thì miễn phí ship luôn ạ!"},{"speaker":"client","text":"Ok, mình đặt 1 cái. Có thể thanh toán bằng ví MoMo không?"},{"speaker":"salebot","text":"Dạ được ạ! Sau khi chọn sản phẩm, hệ thống sẽ gửi link thanh toán MoMo đến số điện thoại của bạn. Cảm ơn mua hàng!"}]','successs',440),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000. Giá trên web là 1.500.000đ, có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Hiện tại Oral-B Pro 3000 đang khuyến mại 20% còn 1.200.000đ thôi ạ. Anh/chị muốn đặt luôn không ạ?"},{"speaker":"client","text":"À, mình thấy trên Shopee giá rẻ hơn 100k nữa, sao web mình lại không thấy?"},{"speaker":"salebot","text":"Dạ web em có chính sách giá ổn định nhất ạ, Shopee hay có chương trình flash sale không báo trước. Anh/chị cứ yên tâm, em cam kết sản phẩm chính hãng 100% ạ."},{"speaker":"client","text":"Thế mình đặt 1 cái nhé, ship nhanh trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ xử lý đơn hàng ngay bây giờ, giao trong 2-3 tiếng nếu anh/chị ở TP.HCM. Anh/chị để lại số điện thoại để em xác nhận đơn nhé!"}]','successs',441),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng thấy giá hơi cao so với dự định. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện sản phẩm đang có chương trình khuyến mại 15% cho đơn hàng đầu tiên trong hôm nay đó ạ!"},{"speaker":"client","text":"Thế giao hàng trong bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao tận nhà trong 2-3 ngày làm việc nếu anh/chị đặt hôm nay ạ. Nếu chọn giao nhanh thì chỉ 1 ngày thôi ạ!"},{"speaker":"client","text":"Ok, mình lấy size M, màu xanh navy. Bao gồm phí ship không vậy?"},{"speaker":"salebot","text":"Dạ phí ship miễn phí cho đơn từ 500k trở lên ạ. Sản phẩm anh/chị chọn là 699k nên được miễn phí ship luôn ạ!"},{"speaker":"client","text":"Tuyệt vời, mình đặt luôn đây. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn anh/chị đã ủng hộ! Đơn hàng của anh/chị sẽ được xử lý trong 15 phút nữa ạ. Chúc anh/chị một ngày tốt lành!"}]','successs',442),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc đồng hồ Casio để đi bơi, loại chống nước tốt nhất là model nào vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị, Casio A168W-1 có khả năng chống nước 5ATM, phù hợp bơi lội ạ. Giá niêm yết 1,2 triệu, hôm nay có khuyến mại 10% cho đơn hàng đầu tiên."},{"speaker":"client","text":"Ồ, 1,2 triệu hơi đắt. Có model nào rẻ hơn không? Mình chỉ cần chống nước thôi."},{"speaker":"salebot","text":"Dạ, Casio F-91W chống nước 3ATM, giá 250k thôi ạ. Chỉ cần tránh ngâm lâu là được."},{"speaker":"client","text":"250k thì được, nhưng mình thấy nó hơi đơn giản. Có model nào chống nước tốt hơn chút không?"},{"speaker":"salebot","text":"Dạ, Casio G-Shock GW-B5600 giá 1,8 triệu có chống nước 20ATM, chống sốc cực tốt ạ. Nếu anh/chị muốn tiết kiệm, mình có thể giảm xuống 1,6 triệu."},{"speaker":"client","text":"1,6 triệu vẫn cao. Mình chỉ mua dùng tạm thôi, 1 triệu là tối đa rồi."},{"speaker":"salebot","text":"Dạ, mình xin lỗi ạ, giá sàn của G-Shock là 1,5 triệu, không thể giảm thêm nữa. Anh/chị có thể cân nhắc F-91W hoặc A168W ạ."}]','fail',443),
('[{"speaker":"client","text":"Chào anh, mình thấy chiếc bàn phím cơ Keychron K8 trên web. Mình muốn mua nhưng không biết chất lượng thế nào?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Bàn phím này rất được ưa chuộng, hàng chính hãng, chất lượng gõ êm, độ bền cao. Chị muốn mua màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xám bạc. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 2.290.000đ, nhưng hôm nay có chương trình khuyến mại giảm còn 2.150.000đ nếu chị đặt ngay."},{"speaker":"client","text":"Ồ, giảm nhiều thế! Nhưng mình thấy giá trên shopee rẻ hơn 200k, sao web bên mình lại đắt vậy?"},{"speaker":"salebot","text":"Dạ chị ơi, giá trên web đã bao gồm phí ship nội thành, còn shopee có thể phí ship cao hoặc hàng không chính hãng. Chị có thể check review sản phẩm trên web mình nhé!"},{"speaker":"client","text":"Thôi được, mình cân nhắc đã. Cảm ơn nhé!"}]','fail',444),
('[{"speaker":"client","text":"Chào bot, mình thấy chiếc bàn chải điện Philips Sonicare DiamondClean 9000 trên web. Cho mình hỏi giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Giá niêm yết là 4.990.000đ, nhưng hôm nay có khuyến mại 10% nếu chị mua trả góp 0%."},{"speaker":"client","text":"Ồ, vậy 4.491.000đ thôi nhỉ? Mà mình chỉ mua trả tiền 1 lần thôi, không trả góp."},{"speaker":"salebot","text":"Dạ thưa chị, nếu trả tiền 1 lần thì khuyến mại chỉ còn 5% ạ, giá sẽ là 4.740.500đ. Nếu chị thích trả góp 0% thì vẫn 4.491.000đ."},{"speaker":"client","text":"Hmm, vậy thôi, mình không quan tâm trả góp. Để mình nghĩ đã, cảm ơn bạn nhé."},{"speaker":"salebot","text":"Dạ vâng chị ạ! Nếu cần tư vấn thêm hay có quyết định thì chị cứ phản hồi nhé ạ. Chúc chị một ngày tốt lành!"}]','fail',445),
