('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc túi xách da Kate Spade này đẹp quá. Mình muốn mua nhưng sợ giá cao quá!"},{"speaker":"salebot","text":"Dạ chào chị ạ! Túi này đang giảm giá 20% chị nhé, từ 3.500.000đ còn 2.800.000đ thôi ạ."},{"speaker":"client","text":"Hơi đắt nhưng mình thích màu này lắm. Có thể ship tận nhà không? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ có chị ạ! Ship nội thành chỉ 30.000đ, giao trong 2 tiếng nếu chị đặt trước 12h trưa. Chị muốn nhận lúc mấy giờ ạ?"},{"speaker":"client","text":"Ok, mình chọn giao lúc 3h chiều nhé. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc chị một ngày vui vẻ, hẹn gặp chị ạ 😊"}]','successs',451),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm một chiếc bàn phím cơ có giá tầm 2 triệu thôi. Có loại nào tốt không?"},{"speaker":"salebot","text":"Dạ có ạ! Bàn phím cơ Keychron K3 có giá 1.990.000đ, chất lượng tốt lắm ạ. Bạn muốn màu nào?"},{"speaker":"client","text":"Màu xám bạc được không? Mình thích kiểu gõ êm ái."},{"speaker":"salebot","text":"Dạ được ạ! Kèm theo phím PBT bền màu, giao trong 2 giờ nếu bạn ở HCM. Đặt luôn không ạ?"},{"speaker":"client","text":"Có giảm giá không? Mình thấy bên khác bán 1.850.000đ thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, nhưng giá này đã ưu đãi rồi ạ. Nếu bạn mua kèm chuột không dây Keychron M1 thì giảm thêm 50k ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy cả bàn phím lẫn chuột. Ship nhanh nhé!"},{"speaker":"salebot","text":"Dạ cam kết ạ! Cảm ơn bạn đã mua hàng, chúc bạn một ngày vui vẻ!"}]','successs',452),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại thông minh tầm 10 triệu thôi. Có gợi ý không?"},{"speaker":"salebot","text":"Dạ, mình giới thiệu bạn chiếc Xiaomi Redmi Note 12 4G giá 9,99 triệu vừa ra mắt, cấu hình tốt lắm ạ!"},{"speaker":"client","text":"Mình thấy nó hơi đắt, có giảm giá không? Mà mình nghe nói có đợt khuyến mại không?"},{"speaker":"salebot","text":"Dạ, hiện tại shop đang có ưu đãi 500k nếu bạn thanh toán qua ví MoMo, còn 9,49 triệu thôi ạ!"},{"speaker":"client","text":"Thế mình đặt luôn đi, nhưng giao hàng chậm quá mình không chịu nổi đâu. Có cam kết không?"},{"speaker":"salebot","text":"Dạ, mình cam kết giao trong 24h nếu bạn ở TP.HCM, nếu trễ mình xin lỗi ạ. Bạn có muốn chọn màu không?"},{"speaker":"client","text":"Mình không quan tâm màu, nhưng nếu giao chậm mình sẽ hủy đơn. Thôi mình nghĩ lại đã."}]','fail',453),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu trắng và đen đều có sẵn. Bạn muốn mua kèm pin dự phòng không ạ? Giảm 10% nếu mua kèm."},{"speaker":"client","text":"Ừ, mình lấy luôn. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Bàn chải 1.299.000đ, pin dự phòng 299.000đ. Tổng 1.598.000đ. Bạn có muốn nhận hàng ở cửa hàng gần nhất không ạ?"},{"speaker":"client","text":"Được, mình chọn cửa hàng 123 Nguyễn Trãi. Cảm ơn nhé!"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua sắm! Hàng sẽ giao trong 2 giờ tới. Chúc bạn một ngày tốt lành!"}]','successs',454),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm một chiếc điện thoại tầm trung dưới 10 triệu, có mẫu nào mới không?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Em giới thiệu Samsung Galaxy A54 5G vừa ra mắt tháng trước, giá 8.990.000đ, cấu hình mạnh mẽ lắm ạ!"},{"speaker":"client","text":"Ừm, mình thấy nó hơi đắt so với dự định. Có chương trình giảm giá nào không?"},{"speaker":"salebot","text":"Anh/chị ơi, em có thể giảm xuống 8.490.000đ nếu thanh toán bằng ví MoMo hoặc nhận hàng tại siêu thị ạ. Cả 2 đều miễn phí ship nữa!"},{"speaker":"client","text":"Ok, vậy mình chọn màu đen nhé. Giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em xác nhận đơn hàng ngay bây giờ, anh/chị check thông tin nhận hàng giúp em với nhé?"}]','successs',455),
('[{"speaker":"client","text":"Chào! Mình thấy bộ quần áo thể thao này đẹp quá, nhưng giá 1.200.000đ hơi đắt nhỉ? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, hôm nay có chương trình giảm 10% cho sản phẩm mới ạ! Còn 1.080.000đ thôi ạ."},{"speaker":"client","text":"1.080.000đ vẫn hơi cao, mình thấy bên kia bán có 950.000đ thôi. Bao nhiêu thì được?"},{"speaker":"salebot","text":"Dạ, vì đây là sản phẩm mới nên không thể giảm thêm ạ. Nhưng nếu bạn mua 2 sản phẩm, mình giảm thêm 5% nữa nhé!"},{"speaker":"client","text":"Thôi, mình không mua nữa đâu. Cảm ơn nhé!"}]','fail',456),
('[{"speaker":"client","text":"Chào! Mình thấy chiếc váy xanh dương trên web, có size S không nhỉ? Mình khá gầy nên muốn thử."},{"speaker":"salebot","text":"Dạ có ạ! Size S vẫn còn 2 chiếc. Bạn mặc size nào thường xuyên vậy?"},{"speaker":"client","text":"Mình hay mặc size S thôi. Nhưng giá 1.290.000đ hơi đắt quá, có giảm giá không?"},{"speaker":"salebot","text":"Dạ, hôm nay có chương trình khuyến mại 10% cho sản phẩm mới, còn 1.161.000đ thôi ạ!"},{"speaker":"client","text":"10% thôi à? Mình thấy chỗ khác bán rẻ hơn 200k cơ."},{"speaker":"salebot","text":"Dạ, chúng mình cam kết sản phẩm chính hãng 100%, chỗ kia có thể là hàng replica. Hay bạn để mình check kho lần nữa?"},{"speaker":"client","text":"Thôi vậy... Cảm ơn nha, mình nghĩ rồi nhé."}]','fail',457),
