('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc áo khoác nữ hiệu Zara này. Size S và M còn không?"},{"speaker":"salebot","text":"Dạ có ạ! Size S còn 2 chiếc, M còn 5 chiếc. Mẫu này đang giảm 30% nè, hợp với chị lắm đó!"},{"speaker":"client","text":"Ui, giá gốc 1 triệu 2, giờ còn 840k à? Đắt quá chị ơi, giảm nữa được không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, đây đã là giá tốt nhất rồi ạ. Nếu chị mua kèm khăn quàng (150k) thì mình free ship luôn nha!"},{"speaker":"client","text":"Thôi được, mình lấy luôn. Size S thôi nhé, mình gửi địa chỉ dưới đây..."},{"speaker":"salebot","text":"Dạ chị vui lòng gửi số điện thoại để mình xác nhận đơn hàng nha! Cảm ơn chị đã ủng hộ ạ 😊"}]','successs',459),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm một chai rượu vang Pháp ngon, tầm dưới 1 triệu thôi. Có gì giới thiệu không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chị có thể tham khảo dòng Bordeaux Chateau Margaux 2018, giá 950k/chai, khuyến mại 5% nếu mua 2 chai."},{"speaker":"client","text":"Ồ, hơi đắt nhỉ. Có loại nào ngon mà rẻ hơn không?"},{"speaker":"salebot","text":"Dạ chị ơi, em có dòng Bourgogne Pinot Noir 2020 giá 790k/chai, vị trái cây đỏ nhẹ nhàng, phù hợp với chị lắm ạ!"},{"speaker":"client","text":"Nghe cũng ổn. Thế giao hàng trong bao lâu vậy?"},{"speaker":"salebot","text":"Dạ giao trong 24h trong nội thành, chị cứ thoải mái nhé! Em đặt hàng luôn cho chị nhé?"},{"speaker":"client","text":"Ok, mình chọn chai Bourgogne nhé. Cảm ơn bạn!"}]','successs',460),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua một chiếc điện thoại thông minh tầm trung khoảng 5-6 triệu thôi. Có mẫu nào mới không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em có mẫu Xiaomi Redmi Note 12 4GB/128GB giá 5,2 triệu, vừa ra mắt tháng trước, pin 5000mAh, màn hình AMOLED 120Hz. Anh/chị quan tâm không ạ?"},{"speaker":"client","text":"Ui, màn hình 120Hz thì hay nhỉ! Nhưng 5,2 triệu hơi cao so với dự tính. Có giảm giá không bạn?"},{"speaker":"salebot","text":"Dạ em có coupon ưu đãi 200k cho khách hàng mới lần đầu mua ạ! Giá sẽ còn 5 triệu thôi. Anh/chị nhận luôn không ạ?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 tiếng ạ! Anh/chị thanh toán online hay COD ạ?"},{"speaker":"client","text":"COD nhé. Cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc anh/chị một ngày tốt lành. Hẹn gặp lại!"}]','successs',461),
('[{"speaker":"client","text":"Chào em, mình muốn mua đôi giày thể thao Nike Air Max 270, size 40 có không?"},{"speaker":"salebot","text":"Dạ có ạ! Size 40 vẫn còn 2 đôi, màu trắng và đen. Bạn chọn màu nào?"},{"speaker":"client","text":"Màu trắng đi. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ 2.990.000đ thôi ạ, đang khuyến mại 10%. Bạn muốn thanh toán online hay nhận hàng rồi trả tiền?"},{"speaker":"client","text":"Hơi đắt quá, giảm còn 2.700.000 được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi, giá đã được niêm yết rồi ạ. Nếu bạn mua kèm tất thể thao, em có thể giảm thêm 50k."},{"speaker":"client","text":"Thế à, tiếc quá. Thôi mình nghĩ lại vậy. Cảm ơn nhé!"}]','fail',462),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao cho bé gái 10 tuổi. Size 130-140 thôi nhé, có không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập lô mới, đủ màu xanh đỏ tím vàng. Bé nhà bạn thích màu nào nhất?"},{"speaker":"client","text":"Màu hồng nhạt thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Bộ giá 499k ạ, đang khuyến mãi 10% nếu mua 2 bộ trở lên."},{"speaker":"client","text":"Hơi đắt quá, mình thấy shop khác bán 450k thôi."},{"speaker":"salebot","text":"Dạ thưa chị, sản phẩm mình nhập từ Hàn, chất liệu cotton 100% thoáng khí, an toàn cho da bé. Nếu chị mua 2 bộ thì mình giảm còn 470k ạ."},{"speaker":"client","text":"Thôi vậy, mình lấy 2 bộ đi. Giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ rất tiếc ạ, do hôm nay trời mưa nên giao hàng muộn hơn 1-2 tiếng thôi. Chị có thể đợi không ạ?"},{"speaker":"client","text":"Không được đâu, mình cần gấp lắm. Thôi thôi, thôi vậy, lần sau nhé."}]','fail',463),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái máy xay sinh tố này trông hay đấy. Mấy tiền vậy?"},{"speaker":"salebot","text":"Dạ chào chị, máy xay sinh tố Philips HR2115 có giá 1.290.000đ thưa chị. Hiện đang khuyến mại 10% nếu chị mua trong hôm nay."},{"speaker":"client","text":"Ủa vậy có bảo hành không? Mấy năm vậy?"},{"speaker":"salebot","text":"Dạ có bảo hành chính hãng 2 năm chị ạ. Mà chị có thể đăng ký bảo hành online luôn trên web sau khi mua."},{"speaker":"client","text":"Thế à... Nhưng mình thấy trên shopee rẻ hơn 200k kìa. Sao bên mình không giảm bớt đi?"},{"speaker":"salebot","text":"Dạ thưa chị, giá mình niêm yết đã cạnh tranh rồi ạ. Nếu chị lấy 2 sản phẩm trở lên thì mình giảm thêm 5% được không ạ?"},{"speaker":"client","text":"Thôi được, nhưng nếu giao chậm quá mình không lấy đâu. Mấy giờ giao được?"},{"speaker":"salebot","text":"Dạ chị yên tâm, giao trong 2-3 tiếng thôi ạ. Chị cứ để lại số điện thoại để mình xác nhận đơn nha!"}]','fail',464),
('[{"speaker":"client","text":"Chào em, mình thấy chiếc túi xách da này đẹp quá, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị, chiếc túi da này giá 2.990.000đ ạ. Hiện đang có ưu đãi 10% cho đơn hàng đầu tiên."},{"speaker":"client","text":"Ôi, đắt quá nhỉ. Mà mình thấy trên shopee cùng loại rẻ hơn 200k, em có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá niêm yết của hãng là vậy, nhưng nếu chị mua kèm phụ kiện thì em có thể giảm 5% thôi ạ."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa, tạm biệt nhé!"}]','fail',465),
('[{"speaker":"client","text":"Chào anh, mình thấy cái máy xay sinh tố Philips HR3655 trên trang web, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ sản phẩm này hiện đang khuyến mại 2.490.000đ, giảm từ 2.990.000đ ạ!"},{"speaker":"client","text":"Ôi, hơi mắc nhỉ. Có thể giảm thêm 100k không? Mình mua luôn đó."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, mức giá đã là ưu đãi nhất rồi ạ. Nếu bạn mua kèm phụ kiện thì sẽ có thêm quà tặng nè!"},{"speaker":"client","text":"Thôi được, vậy gửi mình địa chỉ sau nhé. Cảm ơn nha!"},{"speaker":"salebot","text":"Dạ cảm ơn quý khách đã ủng hộ ạ! Chúc bạn một ngày tốt lành."}]','fail',466),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Nó có size L không nhỉ?"},{"speaker":"salebot","text":"Dạ có ạ! Size L vẫn còn 3 chiếc, bạn muốn mình giữ lại không ạ?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có thể giảm giá được không? Mình thấy trên shopee nó rẻ hơn 200k"},{"speaker":"salebot","text":"Dạ giá của shop đã ưu đãi nhất rồi ạ, mình có thể tặng bạn 1 chiếc khăn len miễn phí nếu mua trong hôm nay nhé?"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Nhưng giao trong 2 ngày thôi nhé, mình cần gấp."},{"speaker":"salebot","text":"Dạ không ạ, hôm nay giao muộn quá rồi, mình xin lỗi. Ngày mai sớm nhất là 10h sáng ạ."},{"speaker":"client","text":"Vậy thôi, mai mình đợi vậy. Cảm ơn nhé!"}]','fail',467),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại Samsung Galaxy S23 Ultra. Có khuyến mại gì không vậy?"},{"speaker":"salebot","text":"Dạ vâng, hôm nay có chương trình giảm giá 10% nếu mua kèm ốp lưng chính hãng ạ. Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu tím ấy. Vậy giá sau giảm là bao nhiêu?"},{"speaker":"salebot","text":"Dạ sau giảm giá là 26.990.000 VND ạ. Bao gồm cả ốp lưng. Bạn có nhu cầu giao hàng không ạ?"},{"speaker":"client","text":"Được, mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP. HCM. Bao lâu thì nhận được?"},{"speaker":"salebot","text":"Dạ trong 2 giờ ạ! Bạn check điện thoại nhé, chúc bạn vui vẻ!"}]','successs',468),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy A54 5G. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào bạn! Galaxy A54 5G đang có sẵn với 3 màu: đen, trắng, tím. Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu tím, nhưng giá trên web hơi cao. Bán cho mình giá 8 triệu được không?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 9.5 triệu ạ, nhưng do bạn mua lần đầu nên mình giảm còn 8.8 triệu nhé! Có kèm quà tặng là ốp lưng."},{"speaker":"client","text":"8.8 triệu vẫn hơi cao, mình chỉ có 8.5 triệu thôi. Lấy luôn đi, mình cần gấp."},{"speaker":"salebot","text":"Dạ vậy thì mình giảm thêm 50k nữa, 8.5 triệu nhé! Bạn chọn giao hàng tận nơi hay nhận tại cửa hàng ạ?"},{"speaker":"client","text":"Giao tận nơi đi, mình ở quận 1. Cảm ơn bạn nhiều!"}]','successs',469),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này nhưng giá hơi cao so với túi tiền của mình. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ, sản phẩm hiện đang giảm 10% cho khách hàng mới. Nếu bạn đặt ngay hôm nay, mình có thể cộng thêm 5% nữa cho bạn nhé!"},{"speaker":"client","text":"Thế giá cuối cùng là bao nhiêu? Mình chỉ có 1 triệu thôi."},{"speaker":"salebot","text":"Dạ, giá gốc 1.200.000, sau khi giảm 15% thì còn 1.020.000. Bạn có thể thanh toán trả góp 0% không nhỉ?"},{"speaker":"client","text":"1.020.000 vẫn hơi quá, mình chỉ có 900k thôi. Bạn có thể làm giá thấp hơn không?"},{"speaker":"salebot","text":"Dạ, tiếc quá ạ. Giá đã được chiết khấu tối đa rồi. Nếu bạn quan tâm sản phẩm khác, mình có thể giới thiệu mẫu khác nhé!"}]','fail',470),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra nhưng giá hơi đắt quá, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào anh chị ạ! Hiện tại em có chương trình khuyến mại nhân dịp lễ 30/4 - 1/5, anh chị có thể giảm 2 triệu nếu mua kèm ốp lưng chính hãng ạ!"},{"speaker":"client","text":"Ồ, vậy là còn 25 triệu thôi nhỉ? Đi kèm ốp lưng có quà gì không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Mua kèm ốp lưng sẽ tặng ngay tai nghe Bluetooth trị giá 1 triệu, anh chị có muốn đặt ngay không ạ?"},{"speaker":"client","text":"Tuyệt quá, vậy mình đặt luôn đi! Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh chị vui lòng để lại số điện thoại và địa chỉ, em sẽ xử lý đơn hàng ngay sau khi thanh toán thành công ạ!"}]','successs',471),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc bàn chải điện Oral-B Pro 3000. Mình thấy nó khá đắt, có giảm giá không thế?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Bàn chải Oral-B Pro 3000 hiện đang có chương trình khuyến mại 20% cho đơn hàng đầu tiên trong hôm nay ạ."},{"speaker":"client","text":"20% à? Thế giá cuối cùng là bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá gốc 2.990.000đ, sau giảm giá còn 2.392.000đ thôi ạ. Kèm theo quà tặng là đầu bàn chải dự phòng nữa!"},{"speaker":"client","text":"Ok, mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Phường Bến Thành, Quận 1, TP.HCM. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ ạ! Anh/chị có thể thanh toán online hoặc COD đều được ạ."}]','successs',472),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc nồi cơm điện Philips HD3128, giá trên web là 1.890.000đ phải không?"},{"speaker":"salebot","text":"Dạ vâng ạ! Đúng rồi ạ, sản phẩm đang có sẵn ạ. Bạn muốn mua không ạ?"},{"speaker":"client","text":"Mình thấy hơi đắt so với tầm giá 1 triệu rưỡi mà mình định mua. Bạn có thể giảm giá được không?"},{"speaker":"salebot","text":"Dạ em có thể hỗ trợ bạn giảm 100.000đ ạ, còn 1.790.000đ thôi. Bao gồm quà tặng là chiếc thìa gỗ nữa ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn nhé. Bao lâu thì giao được vậy?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu bạn ở nội thành ạ. Bạn có thể chọn nhận hàng tận nơi hoặc ship COD ạ."}]','successs',473),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000. Có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang khuyến mại 20% cho sản phẩm này, chỉ còn 1.200.000đ thôi ạ."},{"speaker":"client","text":"Ồ, giá hơi cao so với mình mong đợi. Bạn có thể giảm thêm không? 1.000.000đ được không?"},{"speaker":"salebot","text":"Dạ không thể giảm thêm ạ, nhưng nếu bạn mua kèm kem đánh răng Oral-B 3D White, mình sẽ tặng kèm 1 tuýp ạ!"},{"speaker":"client","text":"Thế thì được rồi, mình chọn màu trắng nhé. Bao lâu thì giao hàng?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, phí ship 25.000đ nếu bạn không ở nội thành. Bạn nhập địa chỉ để mình xác nhận!"}]','successs',474),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc túi xách da thật cho công sở, có size vừa phải không? Nghe nói túi da thật bền lắm nhỉ?"},{"speaker":"salebot","text":"Dạ có ạ! Túi da thật thương hiệu Việt Nam, size M vừa vặn, bảo hành 1 năm. Giá niêm yết 1.200.000đ nhưng hôm nay sale 20% còn 960.000đ thôi ạ."},{"speaker":"client","text":"960k hơi đắt so với mình nghĩ. Có giảm thêm được không? Mình thấy trên Shopee cùng loại 850k thôi."},{"speaker":"salebot","text":"Dạ Shopee có thể rẻ nhưng túi bên em là da thật 100%, còn Shopee toàn da giả da thôi ạ. Em giảm thêm 50k nữa nhé, 910k thôi!"},{"speaker":"client","text":"Thôi được, mình lấy luôn. Ship trong ngày được không ạ? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Em giao trong 2 giờ, thanh toán khi nhận hàng nhé. Cảm ơn chị đã mua sắm ạ!"}]','successs',475),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại thông minh tầm 10 triệu thôi. Có gì giới thiệu không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện bên mình có Xiaomi Redmi Note 12 4GB/128GB giá 9.990.000đ, cấu hình khỏe, camera 50MP. Bạn muốn xem chi tiết không?"},{"speaker":"client","text":"Ui, mình thích rồi! Nhưng 9 triệu rưỡi thì hơi cao, có giảm giá được không? Mình thấy bên khác bán 9 triệu thôi ấy."},{"speaker":"salebot","text":"Dạ thưa bạn, đây là giá niêm yết nhưng nếu bạn mua ngay hôm nay, mình có thể giảm xuống 9.500.000đ cho bạn nhé! Kèm quà tặng là ốp lưng và dán màn hình."},{"speaker":"client","text":"Thế à? Ok, mình nhận 9.5 triệu đi. Đóng gói cẩn thận nhé, mình nhận hàng tận nơi."},{"speaker":"salebot","text":"Dạ vâng ạ! Bạn để lại địa chỉ và số điện thoại để mình xác nhận đơn hàng nha. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',476),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại thông minh tầm 10 triệu thôi. Có sản phẩm nào tốt không?"},{"speaker":"salebot","text":"Dạ chào bạn! Em gợi ý luôn cho bạn chiếc Xiaomi Redmi Note 12 5G giá 9.990.000đ, chip Snapdragon 685, pin 5000mAh, 4G/5G đầy đủ ạ."},{"speaker":"client","text":"Ui, nghe cũng ổn đấy. Nhưng mình thấy trên web có giảm giá nữa không? Hay chỉ giá niêm yết vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hôm nay là ngày khuyến mại, bạn được giảm 500k nếu mua kèm ốp lưng trong hôm nay. Giá cuối sẽ còn 9.490.000đ thôi!"},{"speaker":"client","text":"Thế giao hàng trong bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao nhanh trong 2 giờ nếu bạn ở TP. Hồ Chí Minh, toàn quốc 24-48 giờ ạ. Bạn có muốn mình check kho gần nhất không?"},{"speaker":"client","text":"Ok, mình chọn màu xanh dương nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP. HCM. Bao nhiêu tiền ship?"},{"speaker":"salebot","text":"Dạ ship nội thành miễn phí ạ, bạn chỉ cần thanh toán 9.490.000đ thôi! Em sẽ gửi mã đơn hàng qua Zalo ngay cho bạn."}]','successs',477),
('[{"speaker":"client","text":"Chào shop! Mình thấy sản phẩm bàn chải điện Oral-B Pro 3000 có khuyến mãi gì không vậy? Giá gốc 1.800.000, mình thấy hơi cao."},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại Oral-B Pro 3000 đang giảm còn 1.490.000 ạ, kèm theo quà tặng là 2 đầu bàn chải thay thế. Bạn có muốn đặt không?"},{"speaker":"client","text":"1.490.000 cũng tạm ổn, nhưng mình thấy đối thủ có giá 1.350.000. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ thật tiếc là mức giá này đã là ưu đãi nhất rồi ạ. Nhưng nếu bạn đặt trong 2 giờ nữa, mình sẽ tặng thêm 1 túi vệ sinh răng miệng trị giá 50.000 ạ!"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Ship có nhanh không? Mình cần gấp."},{"speaker":"salebot","text":"Dạ cam kết giao trong 24h ạ! Bạn vui lòng cung cấp địa chỉ và số điện thoại để shop xử lý đơn hàng nhé."}]','successs',478),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Có màu gì thế?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Áo khoác mùa đông này có 5 màu: đen, xám, nâu, xanh navy và đỏ. Chị thích màu nào nhất?"},{"speaker":"client","text":"Mình thích màu đen nhưng giá hơi cao so với dự định. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chị ơi, hôm nay là siêu sale cuối tuần nên em có thể giảm 10% cho chị. Chỉ còn 1.350.000đ thôi ạ!"},{"speaker":"client","text":"Ok, mình lấy 1 chiếc màu đen nhé. Ship nhanh không?"},{"speaker":"salebot","text":"Dạ ship nội thành trong 2 giờ ạ, chị cứ yên tâm! Em sẽ gửi mã giảm giá qua tin nhắn luôn."}]','successs',479),
('[{"speaker":"client","text":"Chào! Mình thấy cái bàn làm việc này đẹp quá, nhưng giá 5 triệu hơi đắt nhỉ? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Bàn này đang khuyến mại 10% cho khách hàng mới, còn 4.5 triệu thôi ạ. Giao tận nhà miễn phí trong 3 ngày."},{"speaker":"client","text":"Hơi mắc quá, có thể giảm thêm không? Mình thấy trên Shopee có giá 4 triệu rưỡi luôn ấy."},{"speaker":"salebot","text":"Dạ thiệt tình chị ơi, 4.5 triệu là giá tốt nhất rồi ạ. Bàn này chất liệu gỗ công nghiệp cao cấp, chịu lực tốt lắm chị!"},{"speaker":"client","text":"Thế à... thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',480),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác gió thể thao này. Size L có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen đều còn. Bạn muốn size L nhé?"},{"speaker":"client","text":"Ừ, mình thích màu xanh dương. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ 899k ạ! Hiện tại đang giảm 20% nên còn 719k thôi. Nếu bạn mua kèm giày thể thao cùng hãng sẽ giảm thêm 50k nữa."},{"speaker":"client","text":"Thế không mua giày thì có giảm không?"},{"speaker":"salebot","text":"Dạ không ạ, nhưng mình có thể tặng bạn 1 chiếc tất thể thao miễn phí nếu thanh toán bằng ví MoMo."},{"speaker":"client","text":"Ok, vậy mình lấy luôn chiếc áo thôi. Bao ship thế?"},{"speaker":"salebot","text":"Miễn phí ship cho đơn từ 500k ạ! Còn bây giờ là 30k thôi. Bạn có muốn mình check mã giảm giá không?"},{"speaker":"client","text":"Thôi khỏi, mình chọn thanh toán tiền mặt khi nhận hàng vậy. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn một ngày tốt lành. Hẹn gặp bạn sớm!"}]','successs',481),
('[{"speaker":"client","text":"Chào em, mình muốn mua bộ quần áo thể thao cho con gái 12 tuổi. Size 150 có không?"},{"speaker":"salebot","text":"Dạ chào chị! Size 150 có ạ, nhưng chỉ còn 2 mẫu thôi chị nhé. Màu hồng chibi và xanh navy."},{"speaker":"client","text":"Màu hồng chibi đi chị. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ 599k chị, nhưng hôm nay có khuyến mãi 10% nếu chị đặt ngay."},{"speaker":"client","text":"599k hơi đắt nhỉ, mình thấy bên kia bán 520k thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, mẫu này chất lượng vải tốt lắm ạ, chị có thể check review trên web. Còn 1 mẫu nữa là xanh navy 499k, chị xem có thích không?"},{"speaker":"client","text":"Thôi tiếc quá, mình không mua nữa. Cảm ơn em nha!"}]','fail',482),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác nữ hiệu The North Face, size M có không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Size M của áo The North Face WindWall 2 thì vừa hết hàng chị nhé, chỉ còn size S và L thôi."},{"speaker":"client","text":"Thế à? Mình thích màu đen ấy, tiếc quá. Còn size L thì sao?"},{"speaker":"salebot","text":"Size L màu đen thì chị có thể đặt trước ạ, giao trong 3-5 ngày. Giá gốc 3.290.000đ, chị có thể nhận ưu đãi 10% nếu đặt ngay hôm nay."},{"speaker":"client","text":"Ủa 3 triệu rưỡi mà giảm có 300k thôi à? Mình thấy bên kia bán giá 2.8tr luôn ấy."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá gốc của The North Face là thế, nhưng nếu chị mua kèm găng tay cùng hãng thì mình giảm thêm 50k nữa cho chị nhé?"},{"speaker":"client","text":"Thôi được, mình không mua thêm gì đâu. Nhắn zalo mình sau khi có hàng nhé, cảm ơn."}]','fail',483),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua một chiếc điện thoại thông minh tầm 10 triệu thôi. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện bên mình có Xiaomi Redmi Note 12 4GB/128GB giá 9,99 triệu, cấu hình tốt lắm ạ!"},{"speaker":"client","text":"Mình thấy nó hơi đắt, có giảm giá không? Mình thấy bên khác bán 9,5 triệu thôi."},{"speaker":"salebot","text":"Dạ, mình có thể giảm xuống 9,7 triệu cho bạn nếu mua kèm ốp lưng và dán màn hình ạ! Còn 2 triệu thôi."},{"speaker":"client","text":"Ồ, vậy thì được. Mình chọn màu xanh dương nhé!"},{"speaker":"salebot","text":"Dạ vui lòng để lại số điện thoại và địa chỉ giao hàng, mình sẽ gửi mã giảm giá và xác nhận đơn hàng ngay ạ!"}]','successs',484),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác thể thao của Nike, size L có không ạ? Mình thấy nó hơi đắt, có giảm giá không thế?"},{"speaker":"salebot","text":"Dạ chào chị! Áo khoác Nike size L vẫn còn ạ, hôm nay có chương trình giảm giá 15% cho đơn hàng đầu tiên chị nhé!"},{"speaker":"client","text":"Ồ, vậy giá sau giảm là bao nhiêu vậy? Mình thích màu xanh dương ấy."},{"speaker":"salebot","text":"Dạ giá gốc 1.299.000đ, sau giảm còn 1.099.000đ chị nhé! Màu xanh dương size L vẫn còn 3 chiếc đó."},{"speaker":"client","text":"Thế giao hàng trong bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ nếu chị ở Hà Nội, giao trong 2-3 tiếng ạ! Chị chọn màu xanh dương nhé, mình gửi link thanh toán luôn."},{"speaker":"client","text":"Ok, mình mua luôn. Cảm ơn bạn nha!"}]','successs',485),
('[{"speaker":"client","text":"Chào shop! Mình thấy chiếc bàn chải điện Oral-B Pro 3000 đang giảm giá 30% thế à? Có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Đang trong chương trình khuyến mại tháng 5. Bạn muốn mình gửi kèm pin sạc dự phòng không? Giá chỉ 150k thôi."},{"speaker":"client","text":"Ồ, vậy giá sau khi giảm là bao nhiêu vậy? Mình thấy bên kia bán 2 triệu rưỡi."},{"speaker":"salebot","text":"Dạ giá gốc 3 triệu, giờ chỉ còn 1 triệu 950k ạ. Đi kèm pin sạc là 2 triệu 100k, rẻ hơn hẳn rồi!"},{"speaker":"client","text":"Ok ok, vậy mình lấy luôn bộ đó kèm pin sạc. Địa chỉ giao là 123 Lê Lợi, Quận 1 nha."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng sẽ được giao trong 2 giờ tới ạ. Chúc bạn ngon miệng!"}]','successs',486),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bàn chải điện Philips Sonicare DiamondClean. Mấy hôm nay thấy khuyến mãi giảm 30% không?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại bàn chải này đang giảm từ 4.500.000đ xuống 3.150.000đ, kèm quà tặng là 2 đầu bàn chải thay thế."},{"speaker":"client","text":"Ồ, được vậy thì mình lấy luôn. Nhưng mình ở xa, phí ship có đắt không?"},{"speaker":"salebot","text":"Dạ phí ship chỉ 30.000đ thôi ạ, nếu mua trên 3 triệu giao miễn phí. Bạn có muốn thanh toán bằng chuyển khoản hay COD?"},{"speaker":"client","text":"Chuyển khoản đi, mình gửi địa chỉ sau nhé. Cảm ơn nha!"}]','successs',487),
('[{"speaker":"client","text":"Chào shop, cho mình hỏi chiếc áo khoác blazer này còn size S không vậy? Mình thấy nó khá đẹp nhưng hơi chật."},{"speaker":"salebot","text":"Dạ chào bạn! Size S hiện tại vẫn còn 1 chiếc thôi ạ, nhưng bạn có thể thử size M nếu muốn rộng hơn nhé."},{"speaker":"client","text":"Size M thì hơi rộng quá, thế giá có thể giảm chút không? Mình thấy trên web ghi 1 triệu 2."},{"speaker":"salebot","text":"Dạ giá gốc là 1 triệu 2, nhưng nếu bạn lấy luôn hôm nay, mình có thể giảm còn 1 triệu 1 cho bạn nhé!"},{"speaker":"client","text":"1 triệu 1 thì mình nghĩ vẫn hơi cao, mình thấy shop khác bán giá 950k thôi."},{"speaker":"salebot","text":"Dạ shop mình không có khuyến mại thấp hơn được nữa ạ, nhưng nếu bạn lấy kèm phụ kiện thì mình giảm thêm 50k nhé!"},{"speaker":"client","text":"Thôi mình không mua nữa, cảm ơn nhé."}]','fail',488),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại thông minh tầm 10-12 triệu. Bạn có sản phẩm nào gợi ý không?"},{"speaker":"salebot","text":"Dạ có ạ! Samsung Galaxy A54 5G đang khuyến mại chỉ 11,9 triệu, cấu hình ổn định, camera 50MP, pin trâu nữa ạ."},{"speaker":"client","text":"Mình thấy giá hơi cao so với mong đợi, có thể giảm xuống 10 triệu không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã là ưu đãi rồi ạ. Nhưng nếu bạn mua kèm ốp lưng chính hãng giảm 200k nữa thì 11,7 triệu thôi ạ!"},{"speaker":"client","text":"Ok, mình chọn màu đen nhé. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao tận nhà trong 2 giờ ạ! Bạn vui lòng cung cấp địa chỉ để em xác nhận ạ."}]','successs',489),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn ghế gỗ óc chó 4 chỗ ngồi trên web có vẻ đẹp, nhưng giá 15 triệu hơi đắt quá nhỉ? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, sản phẩm này đang khuyến mãi còn 13,5 triệu thôi ạ! Đi kèm quà tặng là bộ ghế da bọc nệm nữa."},{"speaker":"client","text":"13,5 triệu vẫn hơi cao, mình chỉ có 12 triệu thôi. Bao nhiêu thì giao hàng tận nơi được?"},{"speaker":"salebot","text":"Dạ, giá sàn của shop là 12,8 triệu ạ, nếu bạn chịu bỏ thêm 800k nữa thì mình giao luôn hôm nay được."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',490),
('[{"speaker":"client","text":"Chào bạn! Mình muốn mua chiếc máy ảnh Canon EOS R50, nhưng giá hơi cao so với dự định. Có ưu đãi gì không?"},{"speaker":"salebot","text":"Dạ, hôm nay shop có chương trình giảm 5% cho đơn từ 20 triệu trở lên ạ! Máy ảnh Canon EOS R50 đang có giá 24.990.000đ, sau giảm còn 23.740.500đ thôi ạ."},{"speaker":"client","text":"Thế giao hàng miễn phí không? Mình ở quận 7, TPHCM."},{"speaker":"salebot","text":"Dạ có ạ! Đơn từ 15 triệu trở lên giao nội thành TPHCM miễn phí ạ. Bạn đặt luôn không? Chúng mình cam kết hàng chính hãng 100%."},{"speaker":"client","text":"Ok, mình đặt luôn! Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ giao nhanh trong 2-4 tiếng ạ! Mình gửi link thanh toán ZaloPay/VNPay nhé? Sau khi thanh toán xong, shop sẽ gửi mã vận chuyển ngay ạ."}]','successs',491),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Có size M không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size M vẫn còn 2 cái, màu xám và đen. Bạn thích màu nào?"},{"speaker":"client","text":"Mình thích màu xám nhưng giá 1,2 triệu hơi đắt quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ em check lại cho ạ, ạ có thể nhận 10% giảm giá nếu thanh toán bằng ví điện tử."},{"speaker":"client","text":"10% thì cũng chỉ còn 1,08 triệu thôi, mình vẫn thấy hơi cao. 1 triệu rưỡi được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã niêm yết không thể giảm thêm. Mong ạ thông cảm!"},{"speaker":"client","text":"Thôi vậy, cảm ơn bạn nhé. Để mình suy nghĩ thêm."}]','fail',492),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác da này. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Áo khoác da này hiện có giá 2.990.000đ, chị có muốn mua không ạ?"},{"speaker":"client","text":"Hơi đắt nhỉ, có giảm giá không? Mình thấy bên kia bán 2.500.000đ thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, sản phẩm chất lượng da thật 100% nên giá hơi cao ạ. Nhưng nếu chị mua trong hôm nay, mình có thể giảm còn 2.790.000đ, giao hàng miễn phí luôn chị nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy 1 cái. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nữa chị nhé! Chị để lại số điện thoại để shop xác nhận đơn hàng ạ?"}]','successs',493),
('[{"speaker":"client","text":"Mình thấy chiếc bàn chải điện Oral-B Pro 3000 trên web có khuyến mãi không vậy? Mình đang tìm cho bố già rồi."},{"speaker":"salebot","text":"Dạ chào bác ạ! Hiện sản phẩm đang giảm 20% còn 1.890.000đ, giao hàng miễn phí nếu bác đặt trong hôm nay ạ."},{"speaker":"client","text":"Ồ giá hơi cao nhỉ, có thể giảm thêm được không? Bác thấy trên shopee rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ em xin lỗi bác ạ, đó là giá tốt nhất rồi ạ. Nhưng nếu bác đặt 2 sản phẩm trở lên thì giảm thêm 5% nha bác."},{"speaker":"client","text":"Thế à, nhưng bố già mình chỉ cần 1 cái thôi. Thôi thì để vậy đi, mai mình suy nghĩ đã."},{"speaker":"salebot","text":"Dạ ạ, em chúc bác ngủ ngon ạ! Nếu cần hỗ trợ thêm thì cứ nhắn tin cho em nhé."}]','fail',494),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật cho vợ. Loại nào vừa túi tiền vừa chất lượng ạ?"},{"speaker":"salebot","text":"Dạ chào chị! Em gợi ý mẫu túi da bò cao cấp của thương hiệu VINALeather ạ. Size vừa phải, giá 1.800.000đ, giao hàng tận nơi trong 2 ngày."},{"speaker":"client","text":"Ồ, hơi đắt so với dự kiến của mình. Có mẫu nào rẻ hơn không? Em giảm giá được không?"},{"speaker":"salebot","text":"Dạ em có mẫu túi da tổng hợp giá 1.200.000đ nhưng vẫn đảm bảo độ bền 2 năm ạ. Nếu chị mua kèm dây đeo da phụ tặng, chị chỉ mất 1.350.000đ thôi!"},{"speaker":"client","text":"Thế à? Mình chọn mẫu 1.350.000đ đi. Bao bì có đẹp không? Vì mình tặng vợ nè."},{"speaker":"salebot","text":"Dạ tất nhiên rồi ạ! Em sẽ đóng gói bằng hộp sang trọng kèm thiệp chúc mừng miễn phí. Chị có thể thanh toán online hoặc COD đều được ạ."}]','successs',495),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác thể thao Adidas này. Size L còn không ạ?"},{"speaker":"salebot","text":"Dạ chào bạn, size L vẫn còn ạ! Màu xanh dương và đen đều có sẵn. Bạn muốn mua không ạ?"},{"speaker":"client","text":"À, mình thấy giá hơi cao, có giảm giá không? Mình thấy trên shopee giá rẻ hơn 100k đó."},{"speaker":"salebot","text":"Dạ shop có chương trình khuyến mại 5% cho đơn hàng đầu tiên ạ. Nếu bạn mua ngay hôm nay, mình sẽ tặng kèm dây buộc tóc thể thao luôn!"},{"speaker":"client","text":"Ok, thế thì mình lấy luôn. Bao lâu giao được ạ?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, phí ship nội thành 30k. Bạn để lại địa chỉ và số điện thoại để mình xử lý đơn hàng nhé!"}]','successs',496),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy S23 Ultra. Bạn có giảm giá gì cho mình không? Mình là sinh viên nên ngân sách có hạn."},{"speaker":"salebot","text":"Dạ chào bạn ạ! Galaxy S23 Ultra hiện có chương trình khuyến mại ưu đãi: giảm 2 triệu cho sinh viên (cần xuất trình thẻ sinh viên). Ngoài ra, bạn có thể trả góp 0% trong 12 tháng."},{"speaker":"client","text":"Thế giá cuối cùng là bao nhiêu vậy? Mình nghe bảo còn giảm nữa không?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 25 triệu, sau khi giảm cho sinh viên còn 23 triệu. Nếu bạn mua kèm ốp lưng chính hãng tặng kèm, mình có thể giảm thêm 500k nữa."},{"speaker":"client","text":"Ok, mình quyết định mua luôn. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ ạ! Bạn vui lòng cung cấp địa chỉ và số điện thoại để mình xử lý đơn hàng nhé."}]','successs',497),
('[{"speaker":"client","text":"Chào bot, mình thấy chiếc bàn phím cơ Keychron K8 trên web có giá 2 triệu rưỡi. Bán có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn, hiện tại sản phẩm đang có khuyến mại 5% nếu mua trước 12h hôm nay. Bạn muốn đặt luôn không ạ?"},{"speaker":"client","text":"5% thôi à? Mình thấy nơi khác có giảm tới 10% kia. Không lẽ mình mua ở đây?"},{"speaker":"salebot","text":"Dạ thật tiếc, giá niêm yết của bên mình đã ưu đãi nhất rồi ạ. Nếu bạn mua kèm chuột không dây Keychron M5 thì mình có thể giảm thêm 500k nữa."},{"speaker":"client","text":"Thế à... thôi vậy mình nghĩ lại đã. Cảm ơn bot nhé!"}]','fail',498),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua chiếc váy len cho mùa đông này. Màu xanh dương có không?"},{"speaker":"salebot","text":"Dạ có ạ! Size S đến XL đều có, giá niêm yết 899k. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình thấy bên kia bán 750k thôi."},{"speaker":"salebot","text":"Dạ giá gốc vậy ạ, nhưng mình có thể hỗ trợ bạn 5% nếu mua combo váy + áo khoác len ạ. Còn 854k thôi!"},{"speaker":"client","text":"Ui, combo cũng được. Nhưng mình chỉ cần váy thôi. Thôi để mình suy nghĩ lại rồi quay lại sau vậy."}]','fail',499),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen đều còn, giao trong 2 ngày. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm giá không? Mình thấy bên khác bán 1.200k thôi."},{"speaker":"salebot","text":"Dạ đây là giá niêm yết ạ, nhưng nếu bạn đặt ngay hôm nay có thể giảm 5% cho bạn nha!"},{"speaker":"client","text":"Ừm, mình cân nhắc lại. Thôi thôi, mình không mua nữa, cảm ơn bạn nhé."}]','fail',500),
