('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy A34 5G. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ, điện thoại Samsung Galaxy A34 5G đang có giá 7.990.000 đồng. Bạn muốn mua không ạ?"},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm giá không? Mình thấy bên khác bán 7.500.000 đồng."},{"speaker":"salebot","text":"Dạ, giá niêm yết của hãng là vậy ạ. Nhưng nếu bạn mua kèm ốp lưng hoặc màn hình bảo vệ, mình có thể giảm 200.000 đồng cho bạn."},{"speaker":"client","text":"Thế mình mua kèm 2 phụ kiện đó luôn. Có giao hàng tận nơi không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn vui lòng để lại địa chỉ và số điện thoại, mình sẽ báo giá chi tiết và giao trong 2h."},{"speaker":"client","text":"À, mình đổi ý rồi, cảm ơn bạn nhé!"}]','fail',520),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Còn ạ, sản phẩm đang khuyến mại 20% nè chị. Mình có thể giao tận nơi trong 2 ngày."},{"speaker":"client","text":"Ồ hay quá, mình thấy giá niêm yết 1.800.000, vậy mình mua thì hết bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ sau khuyến mại chị chỉ hết 1.440.000 chị nhé, kèm tặng 1 lọ nước súc miệng mini nữa."},{"speaker":"client","text":"Okay, mình lấy luôn 1 cái. Địa chỉ giao là 123 Lê Lợi, phường Bến Thành, quận 1 nha."},{"speaker":"salebot","text":"Dạ em ghi nhận đơn hàng rồi ạ! Chị kiểm tra email để nhận hóa đơn nha. Cảm ơn chị nhiều!"}]','successs',521),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác thể thao này nhưng nhìn hơi đắt. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, sản phẩm này đang khuyến mại 20% cho đợt cuối tháng ạ. Giá gốc 1.200.000đ giờ chỉ còn 960.000đ thôi!"},{"speaker":"client","text":"960k vẫn hơi cao, mình thấy trên shopee có giá 850k. Bao ship phí không?"},{"speaker":"salebot","text":"Dạ, ship nội thành miễn phí ạ, nhưng giá trên shopee có thể là hàng cũ hoặc kém chất lượng. Sản phẩm của shop mình là hàng chính hãng 100% ạ."},{"speaker":"client","text":"Thế thôi, mình không mua nữa. Cảm ơn nhé!"}]','fail',522),
('[{"speaker":"client","text":"Chào shop, mình muốn mua nồi cơm điện Tefal 1.8L, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Nồi có sẵn, giá niêm yết 1.990.000đ, giao tận nhà trong 2 ngày."},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm được không?"},{"speaker":"salebot","text":"Dạ giá đã ưu đãi rồi ạ, nhưng nếu bạn mua kèm nắp thủy tinh 50k thì giảm 100k nha!"},{"speaker":"client","text":"Thế thôi, mình không cần nắp nữa. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có ưu đãi thêm nữa thì mình xin lỗi ạ. Cảm ơn bạn đã quan tâm!"}]','fail',523),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ sạc dự phòng Xiaomi 20000mAh, có giảm giá gì không thế?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại shop đang khuyến mại 10% cho sản phẩm này, giá gốc 790k giờ còn 711k thôi."},{"speaker":"client","text":"À, mình thấy trên shopee rẻ hơn 50k, shop có thể giảm nữa không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá sàn shopee rồi ạ. Nhưng shop mình giao tận nhà miễn phí, trong khi shopee thu phí ship 25k nếu dưới 300k ạ."},{"speaker":"client","text":"Ok, mình chọn màu đen vậy. Bao lâu nhận được hàng?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 tiếng ạ, mình sẽ gửi mã tracking qua zalo cho bạn ngay khi xuất kho."}]','successs',524),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại thông minh tầm 10 triệu. Có gì giới thiệu không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại em có chiếc Xiaomi Redmi Note 12 Pro 5G giá 9.990.000đ, cấu hình tốt, camera 108MP, pin 5000mAh, anh/chị thấy sao ạ?"},{"speaker":"client","text":"Mình thích nhưng giá hơi cao, có giảm được không?"},{"speaker":"salebot","text":"Dạ em có thể giảm xuống 9.500.000đ cho anh/chị, kèm quà tặng là ốp lưng và dán màn hình miễn phí ạ!"},{"speaker":"client","text":"Ok, mình chọn màu xanh dương nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM."},{"speaker":"salebot","text":"Dạ em xác nhận đơn hàng ạ! Anh/chị sẽ nhận hàng trong 2 giờ tới ạ. Cảm ơn anh/chị đã mua sắm!"}]','successs',525),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn phím cơ này nhưng giá hơi cao so với dự định của mình. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào chị, bàn phím này đang có chương trình khuyến mại 10% nếu chị đặt trong hôm nay ạ. Ngoài ra nếu chị mua kèm chuột không dây thì sẽ được tặng thêm 1 cuốn sổ tay xinh xắn!"},{"speaker":"client","text":"Ôi vậy thì hay quá! Mình lấy luôn bàn phím + chuột với tặng phẩm đi. Ship trong bao lâu vậy?"},{"speaker":"salebot","text":"Dạ giao hàng trong 2-3 ngày làm việc chị nhé! Em sẽ gửi mã tracking qua tin nhắn sau khi đặt hàng xong ạ. Cảm ơn chị đã ủng hộ!"}]','successs',526),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy A54 5G. Bạn có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen đều sẵn. Bạn muốn giao trong ngày hay nhận tại cửa hàng?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm giá gì không? Mình chỉ có 8 triệu thôi."},{"speaker":"salebot","text":"Dạ không ạ, giá niêm yết rồi ạ. Nhưng nếu bạn mua kèm ốp lưng thì mình giảm 100k nhé!"},{"speaker":"client","text":"Thế ốp lưng bao nhiêu vậy? Mình không cần đâu."},{"speaker":"salebot","text":"Dạ ốp lưng 200k thôi ạ. Nhưng nếu không mua thì mình không thể giảm giá được nữa ạ."},{"speaker":"client","text":"Thôi được, mình ghé cửa hàng xem trước đã. Cảm ơn nhé!"}]','fail',527),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc túi xách da đen của hãng này. Bao nhiêu tiền vậy?"},{"speaker":"salebot","text":"Dạ túi da đen hiện đang khuyến mại 1.200.000đ, giá gốc 1.500.000đ ạ."},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm cho mình 200k không?"},{"speaker":"salebot","text":"Dạ chúng tôi đã giảm tối đa rồi ạ. Nếu bạn mua 2 cái thì tặng kèm khăn lau da miễn phí nè."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Tạm biệt!"}]','fail',528),
('[{"speaker":"client","text":"Chào! Mình đang tìm mua chiếc áo khoác da nữ hiệu Zara, size S có không vậy?"},{"speaker":"salebot","text":"Dạ, áo khoác da nữ Zara size S hiện đã hết hàng ạ. Có thể đổi size M hoặc L không ạ?"},{"speaker":"client","text":"Thế size M giá bao nhiêu? Mình chỉ quan tâm size S thôi."},{"speaker":"salebot","text":"Size M giá 2.490.000đ, size L 2.690.000đ ạ. Nếu bạn muốn size S, mình có thể báo khách hàng hủy order cũ để ưu tiên giao trước 12h hôm nay."},{"speaker":"client","text":"Không, thôi vậy. Mình không vội. Cảm ơn nhé!"}]','fail',529),
('[{"speaker":"client","text":"Chào bot, mình đang cần mua một chiếc áo khoác mùa đông. Mà không biết shop có size lớn không nhỉ?"},{"speaker":"salebot","text":"Dạ có ạ! Size từ S đến 3XL đều có sẵn. Bạn muốn màu gì ạ?"},{"speaker":"client","text":"Mình thích màu xám, nhưng giá hơi cao so với dự tính. Có ưu đãi gì không?"},{"speaker":"salebot","text":"Dạ giờ có chương trình giảm 10% cho đơn hàng trên 500k, bạn có thể chọn thêm phụ kiện để đạt nhé!"},{"speaker":"client","text":"Thế áo kia 1 triệu 2, mình lấy thì còn thiếu 300k. Không thể giảm thêm chút nào à?"},{"speaker":"salebot","text":"Dạ không ạ, giá đã chiết khấu rồi. Nếu bạn đặt gấp 2 ngày nữa sẽ có voucher 5% nữa, nhưng chậm ship."},{"speaker":"client","text":"Thôi không mua nữa, cảm ơn."}]','fail',530),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy S23 Ultra. Màu đen còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Chiếc Galaxy S23 Ultra màu đen vẫn còn ạ. Hiện tại mình có chương trình tặng kèm ốp lưng và dán màn hình miễn phí nếu mua trong hôm nay."},{"speaker":"client","text":"À thế ạ? Giá nó bao nhiêu vậy? Mình thấy trên mạng có chỗ bán rẻ hơn 1 triệu so với giá niêm yết."},{"speaker":"salebot","text":"Dạ giá niêm yết là 28.990.000đ, nhưng hôm nay mình có giảm còn 27.500.000đ kèm quà tặng. Nếu anh/chị mua kèm phụ kiện như sạc nhanh hay tai nghe thì mình có thêm 500k discount nữa."},{"speaker":"client","text":"Vậy nếu mình lấy nguyên hộp luôn thì giá thế nào? Mình cần đầy đủ phụ kiện gốc."},{"speaker":"salebot","text":"Dạ nếu anh/chị lấy nguyên hộp kèm đầy đủ phụ kiện gốc, mình sẽ giảm xuống 26.900.000đ thôi ạ. Đi kèm là ốp lưng, dán màn hình, sạc nhanh 45W và tai nghe AKG miễn phí luôn."},{"speaker":"client","text":"Ok, mình lấy vậy. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 giờ nếu anh/chị ở TPHCM, hoặc ngày mai đối với các tỉnh. Anh/chị có muốn mình hỗ trợ thanh toán online hay COD ạ?"},{"speaker":"client","text":"Mình thanh toán online nha. Cảm ơn bạn nhiều!"}]','successs',531),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác da này nhưng không thấy size L có hàng vậy?"},{"speaker":"salebot","text":"Dạ size L vừa hết ạ, nhưng size M và XL vẫn còn. Anh/chị có muốn thử size khác không?"},{"speaker":"client","text":"Thế size M hơi chật rồi, còn cách nào khác không? Giá có giảm được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, size L vừa hết nên không có cách nào khác ạ. Còn size XL thì giá là 1.890.000đ, anh/chị thấy sao?"},{"speaker":"client","text":"1.890.000 à? Đắt quá, mình chỉ định 1.500.000 thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi, giá đã niêm yết rồi ạ. Nhưng nếu anh/chị mua 2 sản phẩm trở lên thì em có thể giảm 5% ạ."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',532),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc túi xách da thật này, nhưng giá 3 triệu hơi đắt quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Túi da này là hàng chất lượng, da bò nguyên miếng 100%. Nếu anh/chị mua ngay hôm nay, em có thể giảm 5% xuống 2.85 triệu thôi ạ!"},{"speaker":"client","text":"5% thôi à? Mà mình thấy trên web ghi giá 2.7 triệu kìa?"},{"speaker":"salebot","text":"Dạ đúng ạ, nhưng đây là sản phẩm mới ra, nên em chỉ giảm 5% thôi ạ. Nếu anh/chị mua kèm sổ tay da thì em giảm thêm 100k nữa nhé!"},{"speaker":"client","text":"Ok, vậy mình chọn túi da thôi. Đóng gói cẩn thận nhé, mình ở quận 1, giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ giao tận nơi trong 2-3 tiếng nữa. Anh/chị có muốn thanh toán COD không ạ?"},{"speaker":"client","text":"Ừ, COD đi. Cảm ơn nhé!"}]','successs',533),
('[{"speaker":"client","text":"Chào! Mình thấy cái bàn ghế gỗ óc chó này đẹp quá, nhưng giá 12 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ anh ơi, sản phẩm làm từ gỗ óc chó nguyên khối 100%, bền theo năm tháng, giá đó là ưu đãi lắm rồi ạ!"},{"speaker":"client","text":"Mà mình thấy trên mạng cùng loại rẻ hơn 3 triệu, có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ anh thông cảm, chúng tôi cam kết chất lượng gỗ 100% nguyên bản, không ép giá được nữa ạ. Nếu anh không hài lòng, có thể trả lại trong 7 ngày."},{"speaker":"client","text":"Thôi vậy, tiếc quá. Cảm ơn nhé!"}]','fail',534),
('[{"speaker":"client","text":"Chào bạn, mình đang muốn mua bộ quần áo thể thao cho bé gái 10 tuổi. Có size 120 không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Size 120 đang còn hàng, màu hồng và xanh dương. Bé nhà mình thích màu gì hơn?"},{"speaker":"client","text":"Mình thích màu hồng nhưng giá hơi cao, có giảm giá không?"},{"speaker":"salebot","text":"Dạ thưa chị, sản phẩm này đang khuyến mại 10% cho đơn từ 500k. Chị có muốn đặt luôn không ạ?"},{"speaker":"client","text":"À, mình chỉ mua 1 bộ thôi, vậy giá thế nào?"},{"speaker":"salebot","text":"Dạ không giảm được nữa ạ, nhưng giao hàng miễn phí trong 2h nếu chị thanh toán online. Chị quyết định chưa?"},{"speaker":"client","text":"Thôi mình xem nơi khác rồi, cảm ơn nhé!"}]','fail',535),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ Casio G-Shock GA-2100, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu đen và xanh dương đều còn sẵn. Bạn muốn giao trong ngày hay nhận tại cửa hàng?"},{"speaker":"client","text":"Mình ở xa nên giao tận nơi thôi. Giá bao nhiêu vậy bạn?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.890.000đ, nhưng hôm nay có khuyến mại giảm còn 1.690.000đ thôi ạ!"},{"speaker":"client","text":"Hơi đắt quá, có giảm nữa không? Mình thấy bên kia bán 1.550.000đ."},{"speaker":"salebot","text":"Dạ để mình check lại ạ... Nếu bạn mua kèm dây da tặng kèm thì mình giảm xuống 1.650.000đ được không ạ?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Bao gồm phí ship không?"},{"speaker":"salebot","text":"Dạ ship miễn phí cho đơn từ 1 triệu ạ! Bạn nhập địa chỉ nhận hàng đi ạ."}]','successs',536),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc bàn chải điện Oral-B Pro 3, nhưng thấy giá hơi cao quá, có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị! Hiện tại Oral-B Pro 3 đang khuyến mại 20% cho đơn hàng đầu tiên chị ạ. Chỉ còn 1.299.000đ thay vì 1.600.000đ!"},{"speaker":"client","text":"Ồ, vậy giao hàng trong bao lâu vậy? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu chị ở Hà Nội, chị ơi! Địa chỉ mình gửi kèm link google maps nha."},{"speaker":"client","text":"Tuyệt! Mình chọn ship trong ngày luôn. Cảm ơn bạn nhiều!"}]','successs',537),
('[{"speaker":"client","text":"Chào! Mình thấy nồi chiên không dầu này có giá 3 triệu, bây giờ có khuyến mại không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang giảm còn 2.5 triệu nếu bạn đặt trong hôm nay. Đi kèm quà tặng là một giỏ hoa quả miễn phí."},{"speaker":"client","text":"Hơi đắt, mình thấy nơi khác bán 2.3 triệu thôi. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ không ạ, nhưng nếu bạn mua kèm lò nướng mini thì được giảm thêm 100k nữa. Tổng cộng 2.4 triệu, có hợp lý không ạ?"},{"speaker":"client","text":"Ok, mình chọn combo vậy. Giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Địa chỉ giao tới là đâu vậy bạn?"}]','successs',538),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác nữ này. Size S còn không vậy?"},{"speaker":"salebot","text":"Dạ còn ạ! Màu xanh dương và đen đều có size S. Bạn muốn mua màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương nhưng hơi lo size S có vừa không. Bao lâu mình có thể đổi size nếu không vừa?"},{"speaker":"salebot","text":"Dạ đổi size trong 7 ngày miễn phí ạ. Bạn yên tâm đặt size S trước, nếu không vừa mình hỗ trợ đổi ngay."},{"speaker":"client","text":"Vậy được rồi. Mình chọn màu xanh dương size S. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 999k ạ, nhưng hôm nay có khuyến mãi giảm còn 899k nếu bạn đặt trong 2 giờ nữa ạ!"},{"speaker":"client","text":"Thế à? Được thôi, mình lấy luôn. Bao lâu giao hàng được?"},{"speaker":"salebot","text":"Dạ giao trong ngày ạ, phí ship 20k nếu bạn ở TP.HCM. Bạn có muốn thanh toán online không?"},{"speaker":"client","text":"Ok, mình thanh toán online luôn. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ. Hẹn gặp lại!"}]','successs',539),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc điện thoại Samsung Galaxy S23 Ultra. Mình thấy giá trên web hơi cao, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại chúng mình đang có chương trình khuyến mại giảm 5 triệu cho sản phẩm này trong tuần này. Anh/chị muốn mình check mã khuyến mại cho không ạ?"},{"speaker":"client","text":"Ok, vậy giá sau giảm là bao nhiêu vậy? Mình muốn chắc chắn trước khi quyết định."},{"speaker":"salebot","text":"Dạ giá sau giảm là 24 triệu 990 cho anh/chị ạ! Anh/chị có muốn mình hỗ trợ đặt hàng luôn không ạ?"},{"speaker":"client","text":"Được rồi, mình lấy luôn chiếc này. Bao lâu mình nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ nếu anh/chị ở nội thành thì giao trong ngày luôn ạ! Anh/chị có nhu cầu giao tận nơi không ạ?"},{"speaker":"client","text":"Vâng, giao tận nơi nhé. Cảm ơn bạn nhiều!"}]','successs',540),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác nữ hiệu The North Face, size S có không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Size S thương hiệu The North Face còn 2 chiếc thôi chị, màu xanh navy và đen. Chị muốn đặt trước không?"},{"speaker":"client","text":"Màu đen thôi, giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ 2.990.000đ chị ạ, đang khuyến mại 10% nè. Nếu chị lấy luôn hôm nay giao trong 2 tiếng."},{"speaker":"client","text":"Đắt quá! Em giảm cho mình 2.700.000 đi, mình lấy luôn bây giờ."},{"speaker":"salebot","text":"Dạ em xin lỗi chị ạ, giá sàn đã niêm yết rồi, không giảm được nữa. Nhưng nếu chị đăng ký thành viên sẽ có 5% tích lũy sau này."},{"speaker":"client","text":"Thôi vậy, mai mình quay lại mua cũng được. Cảm ơn nhé!"}]','fail',541),
('[{"speaker":"client","text":"Chào shop, mình thấy em điện thoại Oppo Reno 11 Pro 5G đang giảm giá 20% trên web. Mình muốn mua, nhưng giá còn cao quá, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ chào bạn, em xin lỗi giá đã ở mức ưu đãi nhất rồi ạ. Nếu bạn mua kèm ốp lưng và dán màn hình khuyến mại 0đ, mình có thể giảm thêm 5% cho bạn nhé!"},{"speaker":"client","text":"Hmm, 5% vẫn hơi ít. Mình thấy bên kia bán cùng sản phẩm rẻ hơn 300k. Bạn có thể match giá không?"},{"speaker":"salebot","text":"Dạ em xin lỗi, mình không thể giảm nữa vì giá vốn đã sát rồi. Nhưng nếu bạn mua trả góp 0%, mình có thể hỗ trợ phí ship toàn quốc miễn phí ạ!"},{"speaker":"client","text":"Thế à... thôi mình nghĩ lại vậy. Cảm ơn bạn nhé!"}]','fail',542),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm bàn chải điện Philips Sonicare DiamondClean. Có mẫu mới nhất không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu DiamondClean 9900 mới nhất vừa về, kèm 5 đầu bàn chải và hộp sạc không dây. Bạn muốn đặt trước không?"},{"speaker":"client","text":"Mình thấy giá hơi cao so với mức bình thường, có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ thưa bạn, hiện tại có chương trình khuyến mại giảm 10% cho đơn hàng từ 3 triệu trở lên. Bạn có thể chọn mua kèm dung dịch vệ sinh miễn phí để đạt ưu đãi."},{"speaker":"client","text":"Ok, mình lấy luôn 1 cái bàn chải + dung dịch vậy. Bạn check giúp giá cuối cùng nhé!"},{"speaker":"salebot","text":"Dạ 3.799.000đ (giảm 10%) + dung dịch miễn phí. Ship tận nơi trong 2 ngày. Bạn có muốn thanh toán online hay COD ạ?"},{"speaker":"client","text":"COD đi bạn, cảm ơn nhé!"}]','successs',543),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm chiếc áo khoác thể thao của Nike, size M có không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen vẫn còn size M, giao trong 2 ngày."},{"speaker":"client","text":"Giá bao nhiêu vậy? Mình thấy trên shopee rẻ hơn 50k."},{"speaker":"salebot","text":"Dạ giá niêm yết là 1.299.000đ, nhưng cho bạn 1.249.000đ thôi ạ!"},{"speaker":"client","text":"1.249k vẫn hơi đắt, mình chỉ lấy 1.150k thôi."},{"speaker":"salebot","text":"Xin lỗi ạ, giá này không thể giảm nữa vì phí vận chuyển cao lắm ạ."},{"speaker":"client","text":"Thôi được, mình bỏ qua vậy. Cảm ơn nhé!"}]','fail',544),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác thể thao Nike vừa xem hôm qua. Còn size L không ạ?"},{"speaker":"salebot","text":"Dạ còn ạ! Size L vẫn còn 3 chiếc, màu đen hoặc xanh dương. Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu đen nhưng giá 1.299k hơi cao, có giảm giá không? Mình thấy trên mạng bán 1.150k đó."},{"speaker":"salebot","text":"Dạ shop có chương trình khuyến mại hôm nay, tặng kèm mũ thể thao nếu bạn mua ngay. Còn 1.250k thôi ạ, bạn lấy không?"},{"speaker":"client","text":"Ok, mình lấy vậy. Bao ship phí thế nào?"},{"speaker":"salebot","text":"Miễn phí ship cho đơn từ 500k ạ, bạn chỉ cần thanh toán 1.250k thôi. Địa chỉ nhận hàng là gì ạ?"},{"speaker":"client","text":"Mình ở quận 1, địa chỉ 123 Nguyễn Huệ, tòa nhà ABC. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Cảm ơn bạn đã mua sắm! Đơn hàng sẽ giao trong 2h tới. Chúc bạn ngày tốt lành!"}]','successs',545),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc điện thoại Samsung Galaxy A54 5G, nhưng giá hơi cao so với mình mong đợi. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại sản phẩm đang được giảm 5% cho đơn hàng đầu tiên, còn 10 triệu 500 nghìn thôi ạ. Bên mình miễn phí ship trong 24h nếu bạn ở Hà Nội."},{"speaker":"client","text":"10 triệu rưỡi à? Mình thấy trên shopee giá còn 9 triệu 800 nữa kìa. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ thật tiếc là mức giảm đó là ưu đãi tối đa rồi ạ. Nhưng nếu bạn mua kèm ốp lưng hoặc dán màn hình, mình sẽ tặng kèm miễn phí ạ!"},{"speaker":"client","text":"Thôi được, mình không cần thêm phụ kiện đâu. Cảm ơn nhé, mình nghĩ rồi quyết định sau."}]','fail',546),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác Nike thể thao màu xanh navy, size M có không?"},{"speaker":"salebot","text":"Dạ có ạ! Áo khoác Nike thể thao màu navy size M còn 2 sản phẩm, bạn muốn đặt ngay không?"},{"speaker":"client","text":"Mình thấy giá hơi đắt, có giảm giá gì không? Mình thấy mấy chỗ khác bán rẻ hơn 50k đấy."},{"speaker":"salebot","text":"Dạ em rất tiếc ạ, đây là sản phẩm chính hãng nên không thể giảm giá thêm được ạ. Nhưng nếu bạn mua kèm 1 đôi tất thể thao Nike thì sẽ được tặng 1 túi chống sốc miễn phí ạ!"},{"speaker":"client","text":"Thế à... Mà mình không cần tất, có cách nào khác không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, đây là giá niêm yết rồi ạ. Nếu bạn muốn, em có thể gửi link sản phẩm cho bạn so sánh giá ở nơi khác để đảm bảo uy tín ạ."},{"speaker":"client","text":"Thôi được, mình nghĩ lại rồi nhé! Cảm ơn bạn nhiều."}]','fail',547),
('[{"speaker":"client","text":"Alo, mình đang cần mua một cái bàn làm việc mới, nhìn thấy sản phẩm gỗ thông 4 chân trên web có giá 1.200.000đ. Bạn có thể giảm giá cho mình không?"},{"speaker":"salebot","text":"Dạ chào chị ạ, sản phẩm bàn gỗ thông 4 chân hiện đang có giá 1.200.000đ, đây là mức giá ưu đãi nhất trong tháng chị nhé."},{"speaker":"client","text":"Thế à? Mình thấy bên kia bán có 1.000.000đ thôi, sao bên mình đắt vậy?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, sản phẩm của bên em là gỗ thông nguyên khối, bền hơn nhiều so với loại mỏng bên họ bán. Em có thể giảm còn 1.150.000đ được không ạ?"},{"speaker":"client","text":"1.150.000đ vẫn hơi cao, mình chỉ có 1.050.000đ thôi. Được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi chị ạ, mức giá thấp nhất em có thể hỗ trợ là 1.100.000đ thôi ạ. Nếu chị đồng ý, em sẽ giao hàng tận nơi trong hôm nay."},{"speaker":"client","text":"Thôi được, mình lấy vậy. Nhưng giao hàng phải nhanh nhé, mình đang cần gấp."},{"speaker":"salebot","text":"Dạ vâng chị, em xác nhận đơn hàng cho chị rồi ạ. Cảm ơn chị đã ủng hộ shop!"}]','fail',548),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác denim nữ này. Size S còn không nhỉ? Màu xanh navy ấy."},{"speaker":"salebot","text":"Dạ chào chị! Size S vẫn còn 2 chiếc màu navy ạ. Chị muốn ship tận nhà hay qua Grab?"},{"speaker":"client","text":"Ship tận nhà tiện hơn. Giá bao nhiêu vậy bot? Có giảm được không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 990k chị ạ, nhưng hôm nay khuyến mại 890k thôi. Đổi trả trong 7 ngày nếu không vừa size."},{"speaker":"client","text":"890k hơi đắt nhỉ, em giảm còn 850k đi nhé? Mình lấy luôn 2 cái."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, mức giá 890k đã là ưu đãi lắm rồi. Nếu chị lấy 2 cái thì tặng kèm 1 túi vải cotton luôn nha!"},{"speaker":"client","text":"Thôi được, deal luôn. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ trong 2-3 ngày chị nhé! Chị để lại địa chỉ và số điện thoại để shop liên hệ nha."}]','successs',549),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc đồng hồ thể thao cho con trai. Cháu mới 16 tuổi, hay chơi thể thao lắm."},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em gợi ý cho anh/chị mẫu đồng hồ Casio G-Shock GA-2100, rất bền, chống sốc tốt, phù hợp cho vận động viên trẻ. Giá chỉ 1.290.000đ thôi ạ!"},{"speaker":"client","text":"Ủa, hơi đắt nhỉ? Có giảm giá không? Mà có màu nào khác ngoài đen không?"},{"speaker":"salebot","text":"Dạ anh/chị có thể chọn màu xanh dương hoặc cam nữa ạ! Nếu anh/chị đặt ngay hôm nay, em có thể giảm còn 1.150.000đ cho anh/chị nha!"},{"speaker":"client","text":"Ok, mình chọn màu xanh dương đi. Ship trong ngày được không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ gửi mã giảm giá 50k vào đơn hàng của anh/chị luôn. Cảm ơn anh/chị đã mua sắm ạ!"}]','successs',550),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái điện thoại Samsung Galaxy S23 Ultra 5G trên trang web, nhưng không biết có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Còn hàng đầy đủ, màu đen và xanh dương. Bạn muốn mua không?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có thể giảm cho mình không? Mình thấy chỗ khác rẻ hơn 2 triệu đấy."},{"speaker":"salebot","text":"Dạ, giá niêm yết của bên mình là 28 triệu, nhưng nếu bạn mua ngay hôm nay thì mình có thể giảm 1 triệu cho bạn, được không ạ?"},{"speaker":"client","text":"Ừm, vậy mình tạm nhận 27 triệu nhé. Nhưng mình phải suy nghĩ thêm chút, để mai trả lời được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn cứ yên tâm, mình sẽ giữ hàng cho bạn đến 12h trưa mai. Cảm ơn bạn đã quan tâm!"}]','fail',551),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn phím cơ Keychron K8, có màu bạc không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu bạc vẫn còn sẵn, giao hàng trong 2 ngày. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Giá bao nhiêu nhỉ? Có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 2.490.000đ, giờ mình đang khuyến mại 5% cho khách hàng mới, còn 2.365.500đ thôi ạ!"},{"speaker":"client","text":"Ổn, mình lấy luôn. Đóng gói cẩn thận nhé!"},{"speaker":"salebot","text":"Dạ chắc chắn rồi ạ! Cảm ơn bạn đã mua hàng, chúc bạn một ngày vui vẻ!"}]','successs',552),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn làm việc này khá đẹp nhưng giá 5 triệu hơi đắt quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chị có thể chọn mẫu màu gỗ sồi hoặc màu trắng, hiện tại đang có khuyến mại 10% cho đơn hàng đầu tiên, còn 4.5 triệu thôi chị nhé!"},{"speaker":"client","text":"Ồ vậy à? Mình thích màu gỗ sồi, nhưng vẫn hơi cao so với ngân sách. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, đây là giá tốt nhất rồi ạ. Nếu chị mua kèm chiếc ghế văn phòng 2 triệu nữa, mình sẽ tặng kèm giá sách nhỏ 500k, tổng vẫn 7 triệu nhưng được đồ full bộ tiện lợi hơn!"},{"speaker":"client","text":"Thôi được, mình chọn full bộ vậy. Địa chỉ giao hàng là 123 Lê Lợi, quận 1, TPHCM. Bao lâu thì nhận được hàng?"},{"speaker":"salebot","text":"Dạ chị yên tâm, đơn hàng sẽ giao trong vòng 24 giờ. Em xin phép xác nhận lại thông tin: Full bộ bàn ghế + giá sách, tổng 7 triệu, giao tới 123 Lê Lợi, đúng không ạ?"},{"speaker":"client","text":"Đúng rồi, cám ơn bạn nhiều nhé!"}]','successs',553),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Màu ghi có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size M, L, XL còn hàng. Bạn muốn mình gửi link chi tiết không?"},{"speaker":"client","text":"Ừ, gửi đi. Mà giá bao nhiêu vậy? Đắt quá thì mình không mua đâu."},{"speaker":"salebot","text":"Dạ giá niêm yết 1.290.000đ, nhưng hôm nay giảm còn 990.000đ thôi ạ! Có voucher 5% nữa nè."},{"speaker":"client","text":"990k à? Đắt thế, mình thấy nơi khác bán 850k thôi."},{"speaker":"salebot","text":"Dạ ạ, mình có thể giảm xuống 950k nếu bạn lấy luôn hôm nay. Free ship luôn nha!"},{"speaker":"client","text":"Thôi cũng được, nhưng mình cần size L. Có không?"},{"speaker":"salebot","text":"Dạ size L vừa hết ạ, chỉ còn size M và XL thôi. Bạn lấy size khác không?"},{"speaker":"client","text":"Thôi thôi, để lần sau vậy. Cảm ơn nhé!"}]','fail',554),
('[{"speaker":"client","text":"Chào! Mình thấy cái bàn làm việc này đẹp quá, màu gỗ óc chó này có size nào khác không?"},{"speaker":"salebot","text":"Dạ có ạ! Ngoài size 120x60cm, mình còn size 140x70cm và 160x80cm. Bạn thích size nào nhất?"},{"speaker":"client","text":"Size 140x70cm thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ size 140x70cm là 3.800.000đ ạ. Đang có chương trình giảm 10% cho khách hàng mới đó!"},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm thêm không? Mình thấy bên kia bán 3.500.000đ thôi."},{"speaker":"salebot","text":"Dạ mức giá này đã là ưu đãi nhất rồi ạ. Nếu bạn mua kèm ghế văn phòng, mình giảm thêm 5% nha!"},{"speaker":"client","text":"Thôi không mua nữa, cảm ơn nhé. Mình thấy không hợp lý."}]','fail',555),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến nồi chiên không dầu Philips HD6220/90, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Nồi hiện đang có giá 1.990.000đ, giảm 20% từ 2.490.000đ. Bạn có muốn mình gửi link mua không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm thêm được không? Mình thấy bên kia bán 1.750.000đ đấy."},{"speaker":"salebot","text":"Dạ, mình xin lỗi vì giá không thể thấp hơn nữa ạ. Nhưng nếu bạn mua kèm phụ kiện (giỏ lưới + sách nấu) thì mình giảm còn 1.850.000đ, giao tận nơi miễn phí!"},{"speaker":"client","text":"Ok, mình nhận phụ kiện luôn. Bao lâu thì nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ trong vòng 2 giờ nếu bạn ở TP.HCM, hoặc ngày mai nếu ở tỉnh. Bạn có muốn đặt luôn không ạ?"},{"speaker":"client","text":"Đặt thôi! Mình gửi địa chỉ: 123 Lê Lợi, quận 1, TP.HCM. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn bạn đã mua hàng! Chúc bạn ngon miệng với những món ăn ngon từ nồi chiên. Hẹn gặp lại!"}]','successs',556),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc váy công sở màu xanh navy size 36, shop có không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập về 3 chiếc size 36, màu xanh navy chuẩn. Bạn muốn mình gửi ảnh chi tiết không?"},{"speaker":"client","text":"Gửi ảnh đi, mình muốn xem rõ chất vải và kiểu dáng trước đã."},{"speaker":"salebot","text":"Dạ, đây ạ! Ảnh chi tiết: vải thô nhẹ, kiểu suông vừa người, cổ tròn thanh lịch. Giá niêm yết 1.200.000đ, nay giảm còn 950.000đ thôi ạ."},{"speaker":"client","text":"950k hơi đắt, mình thấy shop khác bán 850k thôi. Bạn giảm thêm được không?"},{"speaker":"salebot","text":"Dạ, shop mình có chương trình tặng kèm khăn lụa trị giá 150k nếu bạn nhận hàng hôm nay. Như vậy chỉ còn 800k thôi ạ, bạn thấy sao?"},{"speaker":"client","text":"Ok, mình lấy 1 chiếc. Địa chỉ giao là 123 Lê Lợi, phường Bến Thành, quận 1. Bao nhiêu tiền ship vậy?"},{"speaker":"salebot","text":"Dạ ship nội thành 25k, bạn ạ. Tổng cộng 825k, mình sẽ gửi mã giảm giá 10k nữa nhé!"}]','successs',557),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc đồng hồ thông minh Xiaomi mi band 8, nhưng thấy giá trên web hơi cao, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện tại shop đang có chương trình khuyến mãi 10% cho đơn hàng đầu tiên nếu bạn mua kèm sạc không dây ạ."},{"speaker":"client","text":"Ồ, vậy giá cuối cùng là bao nhiêu thế? Mình chỉ mua mỗi chiếc mi band 8 thôi."},{"speaker":"salebot","text":"Dạ không ạ, chương trình khuyến mãi bắt buộc phải mua kèm sản phẩm khác ạ. Nếu không, giá vẫn là 890.000đ như trên web."},{"speaker":"client","text":"Thế à, vậy thôi. Cảm ơn nhé, mình sẽ xem shop khác vậy."}]','fail',558),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này. Size M có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh navy và đen đều còn size M. Bạn muốn giá gốc hay giảm giá 20% không?"},{"speaker":"client","text":"Giảm giá 20% thì bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 1.200.000đ ạ (giá gốc 1.500.000đ). Bạn có muốn mình gửi link thanh toán luôn không?"},{"speaker":"client","text":"Ok, mình chọn màu navy nhé. Giao trong 2 ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Mình sẽ gửi mã giảm giá 20% vào mail của bạn. Cảm ơn bạn đã mua sắm!"}]','successs',559),
('[{"speaker":"client","text":"Chào! Mình muốn mua chiếc áo khoác này, nhưng nhìn giá hơi cao quá. Có đợt sale nào sắp tới không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại shop đang có chương trình giảm 10% cho sản phẩm này nếu chị đặt trong hôm nay. Chị muốn dùng mã giảm giá không ạ?"},{"speaker":"client","text":"Mình thấy giá gốc cũng hơi đắt, 10% không đủ thuyết phục lắm. Giảm 20% đi thì mình mới quyết định."},{"speaker":"salebot","text":"Dạ em xin lỗi chị ạ, mức giảm 10% là mức tối đa shop có thể áp dụng cho chị lúc này rồi ạ. Nếu chị không hài lòng, em có thể tư vấn sản phẩm khác cùng mức giá ạ."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',560),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra, nhưng giá trên web hơi cao so với dự định. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào bạn! Sản phẩm này đang có chương trình khuyến mại 5% cho khách hàng mới, cộng thêm quà tặng sạc không dây trị giá 1 triệu nếu mua trong hôm nay."},{"speaker":"client","text":"5% thôi à? Mình thấy nơi khác giảm tới 8%. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ chúng tôi có thể giảm thêm 2% nữa nếu bạn chọn trả góp 6 tháng không lãi suất. Như vậy tổng giảm 7%, kèm quà tặng luôn nha!"},{"speaker":"client","text":"Ok, vậy mình nhận trả góp 6 tháng nhé. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu bạn ở TP.HCM, anh/chị có thể chọn nhận tại nhà hoặc tại điểm giao dịch gần nhất."},{"speaker":"client","text":"Tuyệt! Cảm ơn bạn nhé, mình chốt đơn đây."}]','successs',561),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc bàn làm việc gỗ óc chó cho phòng khách. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi có bàn gỗ óc chó nguyên khối, kích thước 120x60cm, giá 12 triệu. Bạn muốn xem ảnh sản phẩm không?"},{"speaker":"client","text":"Ảnh thì nhiều rồi, mình hỏi giá có thể giảm không? 10 triệu được không?"},{"speaker":"salebot","text":"Dạ ạ, chúng tôi đã chiết khấu tối đa rồi ạ. Nếu bạn mua kèm ghế gỗ thì giảm thêm 500k, 11,5 triệu thôi!"},{"speaker":"client","text":"Thế giao hàng mất bao lâu? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao tận nơi trong 3-5 ngày làm việc ạ. Nếu thanh toán online thì nhận ngay ưu đãi 2%!"},{"speaker":"client","text":"Vậy thôi, mình để đó suy nghĩ đã. Cảm ơn nhé!"}]','fail',562),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ Casio Edifice EFR-S567D-1A2V, nhưng mình thấy trên web giá hơi cao so với nơi khác. Bạn có thể giảm giá được không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Sản phẩm này đang có chương trình khuyến mại giảm 10% nếu thanh toán bằng thẻ tín dụng ngân hàng đối tác. Ngoài ra, mình có thể tặng anh/chị dây da miễn phí nếu mua trong hôm nay."},{"speaker":"client","text":"Thế à? Giá gốc là 3.990.000đ, giảm 10% còn 3.591.000đ, cộng dây da nữa thì mình nhận được luôn đúng không?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Anh/chị có thể chọn giao hàng trong ngày hoặc qua bưu điện đều được. Anh/chị muốn thanh toán thế nào ạ?"},{"speaker":"client","text":"Mình chọn giao trong ngày và thanh toán bằng tiền mặt khi nhận hàng nhé. Địa chỉ là 123 Lê Lợi, Quận 1, TP. HCM."},{"speaker":"salebot","text":"Dạ cảm ơn anh/chị! Đơn hàng sẽ được giao trong 2-3 tiếng tới. Anh/chị có thể theo dõi đơn hàng qua link mình gửi vào email nhé!"}]','successs',563),
('[{"speaker":"client","text":"Chào shop, mình là Nam, đang cần mua một chiếc điện thoại tầm 5-6 triệu để thay thế cái cũ. Bên mình có mẫu Samsung Galaxy A14 128GB không ạ?"},{"speaker":"salebot","text":"Chào anh Nam! Dạ bên mình có Galaxy A14 128GB giá 5.990.000đ, màu đen và xanh dương. Anh muốn mua không ạ?"},{"speaker":"client","text":"Mấy hôm trước em thấy nó có ưu đãi 5 triệu thôi mà, giờ hết rồi hả?"},{"speaker":"salebot","text":"Dạ thưa anh, ưu đãi 5 triệu chỉ áp dụng cho khách hàng mới đăng ký tài khoản từ tuần trước thôi ạ. Nhưng anh có thể dùng mã giảm 5% cho đơn từ 5 triệu trở lên đó!"},{"speaker":"client","text":"Thế à, vậy cuối tuần này shop có giảm nữa không? Mình chưa gấp lắm."},{"speaker":"salebot","text":"Dạ thưa anh, mình không cập nhật thông tin khuyến mại sớm hơn thế được ạ. Nếu anh muốn, mình có thể để lại số điện thoại để thông báo khi có chương trình mới nhé?"},{"speaker":"client","text":"Thôi vậy, cảm ơn nhé. Mình sẽ suy nghĩ thêm."}]','fail',564),
('[{"speaker":"client","text":"Chào shop! Mình thấy chiếc bàn phím cơ Keychron K8 có giá 2.500.000đ, nhưng trên web thấy giảm còn 2.200.000đ. Có đúng không vậy?"},{"speaker":"salebot","text":"Dạ không ạ, giá niêm yết vẫn là 2.500.000đ ạ. Hiện tại shop có chương trình khuyến mại 5% cho đơn hàng đầu tiên, nên giá sẽ là 2.375.000đ thôi ạ."},{"speaker":"client","text":"Ôi, vậy là vẫn mắc quá. Mình thấy shop khác bán chỉ 2.100.000đ kèm quà tặng luôn. Thôi mình không mua nữa, cảm ơn!"},{"speaker":"salebot","text":"Dạ không sao ạ! Nếu có nhu cầu sau, shop vẫn sẽ hỗ trợ ạ. Chúc bạn vui vẻ!"}]','fail',565),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có giảm giá gì không thế?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện sản phẩm đang khuyến mại 20% cho đơn hàng đầu tiên, giao trong 2h nếu chị ở HN."},{"speaker":"client","text":"Vậy giá sau giảm là bao nhiêu vậy? Mình thấy bên khác bán 1.800k thôi."},{"speaker":"salebot","text":"Dạ chị ơi, giá gốc 2.200k, khuyến mại còn 1.760k kèm quà tặng là 2 đầu bàn chải thay thế ạ!"},{"speaker":"client","text":"Ok, mình chọn màu trắng nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ chị vui lòng thanh toán trước 30% để xác nhận đơn hàng ạ. Chúng em sẽ gửi mã vận đơn qua Zalo ngay!"}]','successs',566),
('[{"speaker":"client","text":"Chào bạn, mình thấy bàn ghế gỗ óc chó trên web có mẫu này đẹp quá. Mình muốn mua nhưng lo sợ hàng kém chất lượng lắm."},{"speaker":"salebot","text":"Dạ thưa anh, sản phẩm của chúng em đều có chứng nhận chất lượng từ nhà sản xuất và bảo hành 2 năm ạ. Anh có thể yên tâm nhé!"},{"speaker":"client","text":"Thế bảo hành có chi tiết thế nào? Mình sợ sau khi mua xong không có ai hỗ trợ đâu."},{"speaker":"salebot","text":"Dạ bảo hành bao gồm sửa chữa miễn phí tại nhà hoặc gửi về xưởng nếu lỗi do nhà sản xuất ạ. Có hotline 24/7 để hỗ trợ anh luôn."},{"speaker":"client","text":"Vậy giá thế nào? Mình thấy trên web ghi 12 triệu, nhưng mình mua online có giảm giá không?"},{"speaker":"salebot","text":"Dạ ạ, giá niêm yết là 12 triệu nhưng hôm nay có chương trình khuyến mại giảm 10% cho đơn hàng đầu tiên trong ngày. Vậy còn 10.8 triệu thôi ạ."},{"speaker":"client","text":"10.8 triệu vẫn hơi cao, mình thấy bên kia bán rẻ hơn 1 triệu cơ. Không thể giảm thêm được à?"},{"speaker":"salebot","text":"Dạ ạ, em xin lỗi anh vì không thể giảm thêm nữa. Giá của chúng em đã được niêm yết công khai và cạnh tranh nhất rồi. Anh có thể tham khảo thêm mẫu khác nếu muốn ạ."},{"speaker":"client","text":"Thôi được, mình nghĩ lại đã. Cảm ơn bạn nhé!"}]','fail',567),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn phím cơ Keychron K8, mình là sinh viên nên ngân sách có hạn thôi. Có chương trình giảm giá gì không ạ?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Bàn phím Keychron K8 hiện có giá 1.990.000đ, nếu bạn đặt hàng trong hôm nay mình sẽ giảm thêm 5% cho sinh viên nha!"},{"speaker":"client","text":"Vậy thì mình lấy luôn nhé! Bao gồm phí ship không ạ? Mình ở quận 7, TPHCM."},{"speaker":"salebot","text":"Dạ phí ship trong nội thành chỉ 20.000đ thôi ạ, tổng cộng là 2.070.500đ. Bạn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xám nhé! Cảm ơn bạn nhiều nha."},{"speaker":"salebot","text":"Dạ không có gì ạ! Đơn hàng của bạn đã được xác nhận, chúc bạn một ngày tốt lành!"}]','successs',568),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000. Bạn có thể tư vấn cho mình không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc bàn chải điện Oral-B Pro 3000 của chị vẫn còn hàng ạ. Chị muốn chọn màu nào ạ? Trắng hay xanh dương?"},{"speaker":"client","text":"À mình thích màu trắng. Bao nhiêu tiền vậy bạn?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 1.990.000đ chị ạ. Nhưng hôm nay có chương trình khuyến mại, giảm còn 1.690.000đ thôi chị nhé!"},{"speaker":"client","text":"Ồ giá hơi cao nhỉ. Bạn có thể giảm thêm được không? Mình thấy nơi khác bán 1.500.000đ thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá này đã là ưu đãi nhất rồi ạ. Nếu chị mua kèm 1 hộp kem đánh răng Oral-B thì mình có thể giảm thêm 50.000đ nữa cho chị nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy cả bàn chải và kem đánh răng nhé. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Chị vui lòng để lại số điện thoại và địa chỉ giao hàng, mình sẽ gửi mã vận đơn ngay ạ. Cảm ơn chị đã mua hàng!"}]','successs',569),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc áo sơ mi linen kia. Chất liệu có thoáng mát không nhỉ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Áo được làm 100% linen nguyên chất, siêu thoáng mát và thấm hút tốt chị nhé. Size S, M, L, XL đều có sẵn."},{"speaker":"client","text":"Mình mặc size M thôi. Giá bao nhiêu vậy? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ size M giá 890k chị nhé. Hiện tại đang có chương trình khuyến mại 10% cho đơn hàng đầu tiên, nên chị chỉ cần thanh toán 801k thôi ạ!"},{"speaker":"client","text":"Ok mình lấy luôn. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được chị ạ! Chúng em sẽ giao trong 4-6 tiếng nếu chị ở Hà Nội, chị vui lòng cung cấp địa chỉ chi tiết để shop chuẩn bị nhé."}]','successs',570),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc áo khoác da của shop. Giá niêm yết 5 triệu rưỡi, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Hiện tại shop đang có chương trình giảm 10% cho đơn hàng đầu tiên trong hôm nay. Chỉ còn 4 triệu 950 nghìn thôi ạ!"},{"speaker":"client","text":"Ừm, mình thấy hơi đắt so với giá thị trường. Có thể giảm thêm không? 4 triệu 500 được không?"},{"speaker":"salebot","text":"Dạ không ạ, vì đây là sản phẩm da thật nên giá đã sát sườn rồi. Nếu anh/chị lấy 2 cái trở lên thì shop có thể giảm thêm 500k thôi ạ."},{"speaker":"client","text":"Thế à, tiếc quá. Mình chỉ cần 1 cái thôi. Cảm ơn bạn nhé!"}]','fail',571),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc áo khoác thể thao này, nhưng không biết size có vừa không?"},{"speaker":"salebot","text":"Chào bạn! Áo có size S, M, L, XL ạ. Bạn mặc size nào thường xuyên vậy?"},{"speaker":"client","text":"Mình mặc size M thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 890.000đ thôi ạ! Hiện đang giảm 20% cho sản phẩm này đó."},{"speaker":"client","text":"Có giảm nữa không? Mình thấy bên kia bán 750k thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá này đã là ưu đãi nhất rồi ạ. Nếu bạn mua kèm giày thể thao cùng hãng thì giảm thêm 5% nha!"},{"speaker":"client","text":"Thôi được, mình lấy áo thôi. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn để lại địa chỉ và sđt cho em nhé. Cảm ơn bạn đã ủng hộ!"}]','successs',572),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua điện thoại Samsung Galaxy S24 Ultra. Bạn có giảm giá gì cho khách hàng cũ không?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Bên em đang có chương trình khuyến mại ưu đãi cho khách hàng cũ: giảm 1 triệu nếu thanh toán qua ngân hàng đối tác. Anh/chị có nhu cầu đặt không ạ?"},{"speaker":"client","text":"Mình thấy giá hơi cao, nếu mình lấy trọn bộ (điện thoại + ốp lưng + sạc) thì có giảm thêm không?"},{"speaker":"salebot","text":"Dạ em có thể hỗ trợ anh/chị combo giảm 500k cho trọn bộ ạ. Nếu anh/chị đồng ý, em sẽ gửi mã giảm giá ngay sau khi thanh toán ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn đi. Bạn gửi mình link thanh toán nhé!"},{"speaker":"salebot","text":"Dạ em gửi anh/chị link thanh toán ngay đây ạ! Cảm ơn anh/chị đã mua hàng, chúc anh/chị một ngày tốt lành ạ!"}]','successs',573),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác thể thao Adidas này nhưng nhìn thấy giá hơi cao so với dự định. Có chương trình giảm giá nào không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại shop đang có chương trình giảm 20% cho sản phẩm này nếu chị thanh toán bằng thẻ ngân hàng trong hôm nay. Chỉ còn 1 ngày nữa thôi chị nhé!"},{"speaker":"client","text":"Ồ, vậy giá cuối cùng là bao nhiêu thế? Mình thích màu xanh dương này lắm."},{"speaker":"salebot","text":"Dạ giá gốc 1.290.000đ, sau giảm còn 1.032.000đ thôi chị. Size M, L, XL vẫn còn đủ ạ."},{"speaker":"client","text":"Ok, mình lấy size L. Bao ship phí thế? Mình ở Đà Nẵng."},{"speaker":"salebot","text":"Dạ ship nội thành Đà Nẵng 30k, ngoại thành 50k. Bạn chọn phương thức giao nào ạ?"},{"speaker":"client","text":"Ngoại thành nhé. Mình đặt luôn đây. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Đơn hàng của chị đã được ghi nhận. Chúc chị một ngày vui vẻ!"}]','successs',574),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ Casio G-Shock GA-2100. Màu xanh dương có không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Sản phẩm còn hàng nhưng giao trong 2 ngày vì phải nhập từ kho khác. Bạn có muốn đặt trước không?"},{"speaker":"client","text":"Hơi lâu nhỉ, mình cần trong tuần này. Có cách nào nhanh hơn không?"},{"speaker":"salebot","text":"Nếu bạn chịu thêm 50k phí ship, mình có thể giao trong ngày tại cửa hàng gần nhất. Hoặc giảm 10% nếu bạn lấy luôn hôm nay."},{"speaker":"client","text":"Thế ưu đãi 10% đi, mình lấy ngay. Bao lâu nhận được?"},{"speaker":"salebot","text":"Dạ 30 phút nữa bạn nhận tại cửa hàng 36 phố cổ nhé! Cảm ơn bạn đã mua sắm."}]','successs',575),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc áo này hiện đang khuyến mại 30% còn 899.000đ thôi chị nhé!"},{"speaker":"client","text":"Ui trời, đắt quá! Có giảm thêm được không? Mình thấy bên kia bán 650k thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá gốc chúng em đã chiết khấu tối đa rồi. Nếu chị mua 2 chiếc thì em giảm thêm 50k cho chị nha!"},{"speaker":"client","text":"Thế à... thôi được, mình chỉ mua 1 chiếc thôi. Ship tận nhà không? Mình ở xa lắm."},{"speaker":"salebot","text":"Dạ ạ, em giao tận nhà miễn phí chị nhé! Chị cứ thoải mái chọn size và màu ạ."},{"speaker":"client","text":"Ok, mình chọn size M nhé. Cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc chị vui vẻ ạ, hẹn gặp chị lần sau nhé!"}]','fail',576),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy A54. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Galaxy A54 đang có giá 9.990.000đ, chị muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh lam nhưng thấy giá hơi cao. Có đợt khuyến mại nào không?"},{"speaker":"salebot","text":"Dạ chị ơi, tuần này có giảm còn 8.990.000đ thôi ạ, giao hàng tận nơi trong 2 ngày."},{"speaker":"client","text":"Hơi tiếc là mình không mua được, vì mình đã mua chiếc điện thoại khác rồi. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không sao ạ, chúc chị mua sắm vui vẻ! Hẹn gặp chị lần sau nhé."}]','fail',577),
('[{"speaker":"client","text":"Chào bạn! Mình đang tìm mua chiếc áo khoác chống nước cho mùa đông này. Loại nào tốt nhất ạ?"},{"speaker":"salebot","text":"Dạ, mình giới thiệu với bạn mẫu áo khoác chống nước thương hiệu Uniqlo HEATTECH, vừa ấm vừa chống thấm mưa gió ạ. Giá từ 899k thôi!"},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm giá không? Mình mua 2 chiếc đấy!"},{"speaker":"salebot","text":"Dạ, nếu bạn mua 2 chiếc thì mình giảm còn 1.699k thôi! Còn kèm theo quà tặng là đôi tất chống trơn ạ."},{"speaker":"client","text":"Ok, vậy mình chọn màu đen nhé! Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn để lại địa chỉ, mình sẽ gửi đơn ngay bây giờ. Cảm ơn bạn đã mua sắm!"}]','successs',578),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi da nam hiệu Fossil, mẫu mới nhất. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào anh! Chúng mình có mẫu Fossil mới nhất 2024, màu nâu và đen. Anh thích kiểu dáng nào ạ?"},{"speaker":"client","text":"Mình thích màu nâu nhưng giá hơi cao so với túi cũ. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ anh yên tâm! Nếu anh mua trong hôm nay, mình giảm 10% cho anh luôn. Chỉ còn 2.290.000đ thôi ạ."},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Bạn gửi mình link thanh toán nhé."},{"speaker":"salebot","text":"Dạ vâng! Anh vui lòng check email để nhận link thanh toán. Cảm ơn anh đã mua sắm ạ!"}]','successs',579),
('[{"speaker":"client","text":"Chào, mình thấy đôi giày thể thao Nike Air Max 90 này đẹp nhưng giá 3 triệu hơi đắt nhỉ? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, đây là sản phẩm mới ạ, nhưng nếu bạn mua kèm vớ thể thao thì mình giảm còn 2.8 triệu thôi!"},{"speaker":"client","text":"Vớ thể thao ấy giá bao nhiêu vậy? Mình chỉ cần đôi giày thôi."},{"speaker":"salebot","text":"Dạ, vớ 100k ạ. Nếu không mua kèm, mình xin lỗi vì không thể giảm giá hơn được ạ."},{"speaker":"client","text":"Thế à... vậy thôi, mình không mua nữa. Cảm ơn nhé!"}]','fail',580),
('[{"speaker":"client","text":"Chào, mình thấy cái bàn làm việc này đẹp quá. Mẫu gỗ óc chó ấy nhỉ?"},{"speaker":"salebot","text":"Dạ vâng ạ, đây là bàn làm việc bằng gỗ óc chó nguyên khối, chất liệu cao cấp, chống cong vênh. Giá niêm yết 12 triệu, giao hàng miễn phí trong 3 ngày."},{"speaker":"client","text":"Ồ, đắt quá nhỉ. Mình thấy trên Shopee có cùng loại mà chỉ 9 triệu thôi. Bạn giảm giá được không?"},{"speaker":"salebot","text":"Dạ, sản phẩm của shop là chính hãng 100%, có bảo hành 2 năm. Mình có thể giảm nhẹ xuống 11 triệu, tặng luôn kèm ghế văn phòng nữa ạ!"},{"speaker":"client","text":"11 triệu vẫn hơi cao. Thôi mình đi xem nơi khác vậy. Cảm ơn nhé!"}]','fail',581),
('[{"speaker":"client","text":"Chào anh, mình đang muốn mua bàn ghế gỗ cho phòng khách. Mẫu này có sẵn không vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Mẫu bàn ghế gỗ sồi 5 chỗ ngồi hiện có 2 màu: nâu và trắng sữa. Chị muốn xem ảnh chi tiết không ạ?"},{"speaker":"client","text":"À, mình thấy giá hơi cao so với dự định. Có chiết khấu gì không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, giá đã niêm yết theo chính sách rồi ạ. Nhưng nếu chị mua trọn bộ 5 món thì giảm 5% luôn chị nhé!"},{"speaker":"client","text":"Thế giao hàng miễn phí không? Mình ở quận 12."},{"speaker":"salebot","text":"Dạ giao hàng nội thành 20km thì 50k chị nhé, ngoài ra phí vận chuyển sẽ cộng thêm. Chị có muốn đặt hàng luôn không ạ?"},{"speaker":"client","text":"Thôi mình nghĩ lại đã. Cảm ơn nhé!"}]','fail',582),
('[{"speaker":"client","text":"Anh ơi, em đang muốn mua chiếc áo khoác này nhưng thấy giá hơi cao quá. Có cách nào giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã được niêm yết theo chính sách của shop. Nhưng nếu bạn mua 2 sản phẩm cùng loại sẽ giảm 5% nha!"},{"speaker":"client","text":"Chà, vậy thì em cân nhắc thôi. Cảm ơn anh nhé!"}]','fail',583),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da của thương hiệu Coach. Có mẫu nào đang sale không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện mẫu Coach Willow Classic đang giảm 20% còn 4.800.000đ. Bạn muốn size nào?"},{"speaker":"client","text":"Mình thích size M nhưng hơi lo giá hơi cao. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ nếu bạn mua trong hôm nay, mình có thể giảm thêm 5% nữa thành 4.560.000đ luôn ạ. Còn 5 cái cuối."},{"speaker":"client","text":"Thế thì ok, mình lấy luôn. Ship tận nhà được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng cung cấp địa chỉ và số điện thoại để mình xác nhận đơn hàng nhé."}]','successs',584),
('[{"speaker":"client","text":"Chào bot! Mình thấy cái bàn ghế gỗ óc chó 4 chỗ ngồi này đẹp quá. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Bàn ghế gỗ óc chó 4 chỗ hiện đang khuyến mại 15 triệu/chiếc ạ. Giao hàng tận nơi trong 3 ngày."},{"speaker":"client","text":"Hơi đắt nhỉ. Bán 12 triệu được không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá sỉ đã chiết khấu rồi ạ. 13.5 triệu được không ạ? Mình sẽ tặng luôn bộ ghế da giả bò cao cấp ạ!"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Nhưng giao trong 2 ngày thôi nhé!"},{"speaker":"salebot","text":"Dạ không ạ, giao 3 ngày chắc chắn ạ. Cảm ơn chị đã mua hàng ạ!"}]','fail',585),
('[{"speaker":"client","text":"Chào shop, mình đang quan tâm bộ quần áo thể thao cho bé gái 10 tuổi. Có size 12-13 tuổi không ạ?"},{"speaker":"salebot","text":"Dạ chào bạn, bộ quần áo thể thao cho bé gái 10 tuổi thì size 12-13 tuổi vẫn còn hàng ạ! Màu sắc bạn thích là gì ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ bộ này giá 450k ạ, đã bao gồm phí ship nội thành. Bạn có muốn đặt luôn không ạ?"},{"speaker":"client","text":"Ồ, hơi đắt nhỉ. Có giảm giá không? Mình thấy shop hay khuyến mại lắm mà."},{"speaker":"salebot","text":"Dạ thật tiếc ạ, hôm nay không có khuyến mại. Nhưng nếu bạn đặt 2 bộ trở lên thì giảm 5% ạ!"},{"speaker":"client","text":"Thôi mình không mua nữa, cảm ơn nhé!"}]','fail',586),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Còn 2 sản phẩm tại kho. Bạn muốn màu trắng hay đen ạ?"},{"speaker":"client","text":"Mình thích màu trắng nhưng giá trên web hơi cao, có giảm giá không?"},{"speaker":"salebot","text":"Dạ hôm nay có chương trình khuyến mại 10% cho khách hàng mới ạ! Giá chỉ còn 1.350.000đ thôi."},{"speaker":"client","text":"Ừ, thế giao hàng trong bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, trừ phi bạn chọn dịch vụ giao nhanh thì 4-6 tiếng thôi ạ!"},{"speaker":"client","text":"Thôi mình không vội lắm, gửi thường thôi. Nhưng giá vẫn hơi cao, 1.350.000đ là chốt luôn à?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ, giá niêm yết đã được giảm tối đa rồi ạ. Nếu bạn không hài lòng, mình xin lỗi ạ!"}]','fail',587),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua máy xay sinh tố gia đình loại công suất 1000W. Có hàng không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Máy xay sinh tố Philips HR2118/00 1000W đang có khuyến mại 20% nè. Bạn muốn đặt ngay không?"},{"speaker":"client","text":"Mình thấy giá niêm yết 2.500.000đ, vậy giá khuyến mại bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá khuyến mại chỉ còn 2.000.000đ thôi ạ. Đi kèm còn tặng bộ cốc thủy tinh nữa nè!"},{"speaker":"client","text":"Hơi đắt so với dự định của mình. Bán rẻ hơn được không? 1.800.000đ có được không?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, mức giá này đã là ưu đãi nhất rồi. Nếu bạn mua kèm 1 sản phẩm khác thì có thể giảm thêm 5% nè!"},{"speaker":"client","text":"Thôi mình không mua nữa. Cảm ơn bạn nhé!"}]','fail',588),
('[{"speaker":"client","text":"Chào shop! Mình thấy chiếc bàn phím cơ Keychron K8 có giá 2.200.000đ thế có giảm giá gì không? Mình mua luôn 2 cái luôn ấy."},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại bàn phím này đang có chương trình khuyến mại 5% cho đơn hàng từ 2 sản phẩm trở lên ạ. Như vậy mỗi cái sẽ còn 2.090.000đ thôi."},{"speaker":"client","text":"Thế giao hàng có miễn phí không? Mình ở quận 7, TPHCM."},{"speaker":"salebot","text":"Dạ phí ship nội thành là 25.000đ nếu đơn dưới 500.000đ ạ. Còn trên 500.000đ thì free ship luôn nè."},{"speaker":"client","text":"Ủa vậy thôi à? Mình thấy trên web ghi free ship toàn quốc kìa?"},{"speaker":"salebot","text":"Dạ thật xin lỗi bạn, do hôm nay hệ thống gặp lỗi nên phí ship tạm thời chưa cập nhật. Nếu bạn đặt ngay bây giờ mình sẽ gửi mã giảm phí ship 100% ạ!"},{"speaker":"client","text":"Thôi được, mình tạm chấp nhận vậy. Nhưng mà giao hàng chậm quá thì mình không lấy đâu nha."},{"speaker":"salebot","text":"Dạ cam kết giao trong 24h ạ, cảm ơn bạn đã ủng hộ shop!"}]','fail',589),
('[{"speaker":"client","text":"Chào shop, mình thấy sản phẩm đồng hồ thông minh Xiaomi Smart Band 8 Pro có giá 1.290.000đ vậy. Bán có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn, sản phẩm này đang khuyến mại 10% cho khách hàng mua trong hôm nay, giá còn 1.161.000đ thôi ạ!"},{"speaker":"client","text":"À vậy à, nhưng mình thấy bên shop kia bán rẻ hơn 100k, shop có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá này là giá sốc rồi ạ, shop không thể giảm thêm được nữa ạ. Nếu bạn mua 2 sản phẩm sẽ tặng kèm dây da ạ!"},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',590),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc váy đen kiểu dáng vintage của shop. Size 36 có không vậy?"},{"speaker":"salebot","text":"Dạ, áo size 36 ạ, nhưng váy vintage thì shop chỉ còn size 38 thôi ạ. Bạn xem có size khác được không?"},{"speaker":"client","text":"Ủa size 38 thì hơi rộng quá, mình mặc vừa size 36 thôi. Có cách nào giảm giá không? Mình lấy luôn đi."},{"speaker":"salebot","text":"Dạ, shop có giảm 5% nếu bạn mua kèm túi xách ạ. Còn riêng váy thì không giảm được ạ."},{"speaker":"client","text":"Thế à, tiếc quá. Mình không cần túi xách đâu. Thôi thôi, mình nghĩ lại vậy. Cảm ơn nha!"}]','fail',591),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật của thương hiệu Coach. Bên mình có size M không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Túi Coach size M đang giảm giá 20% còn 8.990.000đ, giao hàng miễn phí trong 2 ngày."},{"speaker":"client","text":"Hơi đắt so với mình, có thể giảm thêm không? Mình thấy bên kia bán 8.500.000đ thôi."},{"speaker":"salebot","text":"Dạ, nếu bạn thanh toán bằng thẻ ngân hàng partner thì mình giảm thêm 500k nữa nhé! Còn 8.490.000đ thôi ạ."},{"speaker":"client","text":"Ok mình nhận vậy, gửi mình link thanh toán nhé!"},{"speaker":"salebot","text":"Dạ, đây ạ: [link thanh toán]. Cảm ơn bạn đã mua sắm cùng mình!"}]','successs',592),
('[{"speaker":"client","text":"Chào! Mình đang tìm nồi cơm điện loại 1.5 lít, tầm giá dưới 2 triệu thôi nhé."},{"speaker":"salebot","text":"Dạ vâng ạ! Chúng mình vừa có nồi Panasonic SR-DF101 1.5L giá 1.990.000đ, khuyến mại giảm còn 1.790.000đ nè!"},{"speaker":"client","text":"Ồ, vậy có bảo hành không? Mình lo lắm, đồ điện nhà mình hay hỏng lắm."},{"speaker":"salebot","text":"Dạ bảo hành chính hãng 12 tháng ạ, đổi mới 1 đổi 1 trong 30 ngày nếu lỗi nhà sản xuất. Mình cam kết chất lượng nhé!"},{"speaker":"client","text":"Thế giao hàng có mất phí không? Mình ở huyện đấy."},{"speaker":"salebot","text":"Dạ phí giao hàng ngoài nội thành 50k ạ, nhưng nếu bạn đặt trong hôm nay thì free ship luôn nè!"},{"speaker":"client","text":"Hôm nay mình không mua nữa, để suy nghĩ thêm. Cảm ơn nhé!"}]','fail',593),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé gái 10 tuổi. Bạn có size 130 không?"},{"speaker":"salebot","text":"Dạ có ạ! Bộ đồ thể thao màu hồng có size 130, còn 2 sản phẩm. Bạn muốn đặt trước không?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm giá không? Mình thấy trên mạng rẻ hơn 20%"},{"speaker":"salebot","text":"Dạ shop đang có chương trình khuyến mãi giảm 15% cho đơn hàng đầu tiên hôm nay ạ. Chỉ cần nhập mã TRESO15 là được!"},{"speaker":"client","text":"Thế à, được đấy. Mình lấy luôn đi. Bao gồm phí ship không?"},{"speaker":"salebot","text":"Dạ phí ship miễn phí cho đơn hàng trên 500k ạ. Bộ đồ của bạn là 450k sau giảm giá, cộng phí ship 30k. Tổng 480k thôi ạ!"},{"speaker":"client","text":"Ok, mình chọn màu hồng nhé. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ. Đơn hàng sẽ giao trong 2 giờ tới ạ!"}]','successs',594),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác jean của thương hiệu Levi''s, size M còn không ạ? Mình thấy trên web ghi hết size rồi!"},{"speaker":"salebot","text":"Dạ xin lỗi bạn, size M của mẫu này đã hết hàng rồi ạ. Chúng mình có size S, L và XL thôi. Bạn xem có size nào phù hợp không?"},{"speaker":"client","text":"Ôi tiếc quá... Mình chỉ mặc vừa size M thôi. Thôi vậy mình bỏ qua vậy, cảm ơn nha!"}]','fail',595),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua bộ quần áo thể thao cho bé nhà mình, bé 5 tuổi ấy. Bé nhà mình hay chạy nhảy nên cần thoáng mát. Bạn giới thiệu cho mình mẫu nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Em giới thiệu mẫu áo phông cotton thoáng khí của hãng ABC cho bé 5 tuổi ạ. Mẫu này có họa tiết siêu nhân rất dễ thương, giá 399k/chiếc. Chị muốn chọn size nào ạ?"},{"speaker":"client","text":"Size 5-6 tuổi ấy. Còn quần thì sao, có kèm không hay chị phải mua riêng?"},{"speaker":"salebot","text":"Dạ quần cũng cùng bộ ạ, giá 299k. Nếu chị mua cả bộ thì em giảm 50k cho chị nhé! Tổng chỉ 648k thay vì 698k ạ."},{"speaker":"client","text":"Ồ, giảm nhiều thế! Vậy mình lấy bộ luôn. Ship tận nhà trong hôm nay được không?"},{"speaker":"salebot","text":"Dạ được chị ạ! Em sẽ gửi mã giảm giá 10% cho chị trong tin nhắn luôn. Chị vui lòng cung cấp địa chỉ và số điện thoại để em xác nhận đơn hàng nha!"}]','successs',596),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác mùa đông này nhưng thấy giá hơi cao so với túi tiền của mình. Có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chị có thể đăng ký thành viên để nhận 5% giảm giá ngay hôm nay. Ngoài ra, nếu chị đặt hàng trong 2 giờ tới, shop sẽ tặng kèm khăn len trị giá 150k!"},{"speaker":"client","text":"Thế nếu mình mua 2 cái thì sao? Có ưu đãi gì hơn không?"},{"speaker":"salebot","text":"Dạ nếu mua 2 sản phẩm, chị sẽ được giảm thêm 10% nữa ạ! Tổng cộng là 15% giảm giá luôn đó chị."},{"speaker":"client","text":"Ok, mình chọn size M cho cả hai. Giao hàng trong hôm nay được không?"},{"speaker":"salebot","text":"Dạ được ạ! Chị vui lòng cung cấp địa chỉ và số điện thoại, shop sẽ giao trong vòng 3-5 tiếng tới ạ."}]','successs',597),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc đồng hồ Casio G-Shock GA-2100, nhưng giá trên web hơi cao so với shop khác. Bạn có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị, sản phẩm này đang có chương trình khuyến mại 15% cho đơn hàng đầu tiên hôm nay, anh/chị có muốn mua luôn không ạ?"},{"speaker":"client","text":"15% thôi à? Mình thấy shop kia bán rẻ hơn 500k nữa. Nếu giảm 20% mình sẽ mua ngay."},{"speaker":"salebot","text":"Dạ anh/chị thông cảm, mức giảm tối đa mình có thể hỗ trợ là 18% thôi ạ. Nếu anh/chị lấy luôn thì mình giao trong 2 giờ, anh/chị thấy sao?"},{"speaker":"client","text":"Ok, deal 18% đi. Mình chọn màu đen, giao đến 228 Điện Biên Phủ, Quận Bình Thạnh nhé."},{"speaker":"salebot","text":"Dạ cảm ơn anh/chị đã mua hàng! Đơn hàng của anh/chị sẽ được giao trong 2 giờ nữa. Chúc anh/chị một ngày tốt lành!"}]','successs',598),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Genius 9000, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu trắng và xanh dương đều còn 20 cái. Bạn muốn giao trong ngày hay nhận tại cửa hàng?"},{"speaker":"client","text":"Mình ở xa nên giao tận nhà thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 2.990.000đ thôi ạ, nhưng hôm nay có khuyến mại 10% nếu bạn thanh toán qua VNPay."},{"speaker":"client","text":"10% à? Thế còn giảm nữa không? Mình thấy bên khác bán 2.6 triệu."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, mức giá này đã là ưu đãi nhất rồi ạ. Nếu bạn mua kèm gói bảo hành 2 năm thì có thể giảm thêm 50k."},{"speaker":"client","text":"Thế à... thôi mình suy nghĩ thêm vậy. Cảm ơn bạn nhé!"}]','fail',599),
('[{"speaker":"client","text":"Chào shop, mình thấy cái bàn chải điện Philips Sonicare DiamondClean 9000 trên web, có hàng không thế?"},{"speaker":"salebot","text":"Dạ có ạ! Còn 2 sản phẩm cuối, màu trắng ngà và đen, giao trong 24h nếu bạn ở TP.HCM."},{"speaker":"client","text":"Mấy giờ giao được? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ, đơn hàng đặt trước 15h giao trong ngày, sau 15h giao vào ngày hôm sau ạ."},{"speaker":"client","text":"Vậy mình đặt thôi, nhưng khuyến mại gì không? Giảm 10% không?"},{"speaker":"salebot","text":"Dạ, hiện tại shop đang có chương trình tặng kèm 1 bộ bàn chải thay thế và 1 lọ dung dịch vệ sinh miễn phí ạ. Còn ưu đãi giảm giá chỉ áp dụng khi mua kèm sản phẩm khác ạ."},{"speaker":"client","text":"Thế à, tiếc quá. Mình chỉ mua mỗi cái bàn chải này thôi. Bao giờ có giảm giá nữa?"},{"speaker":"salebot","text":"Dạ, shop sẽ có đợt sale vào cuối tháng ạ, bạn có thể theo dõi hoặc để lại số điện thoại để nhận thông báo ạ. Cảm ơn bạn đã quan tâm!"}]','fail',600),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn phím cơ Keychron K8, giá trên web hơi cao quá nhỉ?"},{"speaker":"salebot","text":"Dạ chào ạ! Bạn mua trong hôm nay thì mình giảm 5% luôn cho bạn nhé, còn 2.350.000đ thôi!"},{"speaker":"client","text":"Thế ạ, mình cũng thích màu bạc. Có giao hàng tận nơi không?"},{"speaker":"salebot","text":"Dạ có ạ! Miễn phí giao nội thành, mình gửi đơn ngay bây giờ nhé?"},{"speaker":"client","text":"Ok, mình chọn thanh toán COD nhé, cảm ơn bạn!"}]','successs',601),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy S23 Ultra. Mình thấy trên web có khuyến mại không thế?"},{"speaker":"salebot","text":"Dạ vâng ạ! Hiện tại chúng tôi đang có chương trình tặng ốp lưng chính hãng và giảm 1 triệu khi thanh toán bằng thẻ tín dụng. Bạn muốn chọn màu gì ạ?"},{"speaker":"client","text":"Mình thích màu xanh lam. Còn giá bao nhiêu sau khi giảm thế?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 28 triệu, sau giảm còn 27 triệu ạ. Bạn có muốn mình hướng dẫn đặt hàng luôn không?"},{"speaker":"client","text":"Ok, mình đặt luôn. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn cung cấp địa chỉ để mình kiểm tra phí ship nhé. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',602),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái bàn chải điện Oral-B Genius X 10000 đang giảm giá, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Giá niêm yết 2.500.000đ, giờ chỉ còn 1.800.000đ thôi nè. Bạn muốn mua không?"},{"speaker":"client","text":"Ui 1.800.000 à? Mà mình thấy trên Shopee còn 1.600.000 đó bạn ơi..."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, đây là giá sốc cuối tuần thôi. Nếu bạn mua kèm kem đánh răng Oral-B 30ml thì em giảm thêm 100.000đ nha!"},{"speaker":"client","text":"Thế à... mình chỉ mua bàn chải thôi. Thôi để mình suy nghĩ lại vậy. Cảm ơn bạn nha!"}]','fail',603),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại tầm 10 triệu thôi. Có gì giới thiệu không?"},{"speaker":"salebot","text":"Dạ, em có Samsung Galaxy A34 5G giá 9.990.000đ, chip Snapdragon 695, màn hình AMOLED 120Hz, pin 5000mAh. Bạn thấy ổn không ạ?"},{"speaker":"client","text":"Mình thích nhưng giá hơi cao, có giảm được không? Mình thấy bên kia bán 9.5 triệu."},{"speaker":"salebot","text":"Dạ, em có thể giảm xuống 9.7 triệu nếu bạn mua kèm ốp lưng và dán màn hình. Còn 9.5 triệu thì em không đủ biên lợi nhuận ạ."},{"speaker":"client","text":"Ok, mình chọn ốp lưng nhé. Ship trong bao lâu vậy?"},{"speaker":"salebot","text":"Dạ, giao trong 2 giờ nếu bạn ở Hà Nội, phí ship 20k ạ. Bạn đồng ý thì em sẽ gửi link thanh toán luôn nhé!"},{"speaker":"client","text":"Được, mình thanh toán online luôn. Cảm ơn bạn nhé!"}]','successs',604),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác mùa đông này. Size L có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen đều còn size L. Bạn muốn chọn màu nào?"},{"speaker":"client","text":"Mình thích màu xanh dương. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ 1.899.000đ thôi ạ! Nếu bạn mua kèm khăn len thì được giảm 10% luôn."},{"speaker":"client","text":"Ồ, vậy mình lấy luôn cả khăn len nhé. Bao ship phí thế?"},{"speaker":"salebot","text":"Miễn phí ship trong 5km đầu ạ! Bạn để lại địa chỉ để mình báo giá chính xác nhé."},{"speaker":"client","text":"Mình ở 22 Nguyễn Huệ, quận 1. Nhận hàng trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Đơn hàng sẽ giao trong 2-4 tiếng tới. Bạn có nhu cầu thanh toán COD hay chuyển khoản?"},{"speaker":"client","text":"COD đi nhé. Cảm ơn bạn nhiều!"}]','successs',605),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, nhưng giá 3.500.000 chút nhỉ? Thấy bên kia bán 2.800.000."},{"speaker":"salebot","text":"Dạ chào bạn ạ! Bàn chải Oral-B Pro 3000 của shop đang khuyến mại 3.200.000 thôi ạ, có tặng kèm 2 đầu bàn chải thay thế luôn."},{"speaker":"client","text":"Ui, 3.200.000 vẫn hơi cao so với giá mình thấy. Mà mình có thẻ thành viên nên giảm thêm được không?"},{"speaker":"salebot","text":"Dạ thẻ thành viên thì được giảm 5% ạ, vậy còn 3.040.000 thôi. Để shop check lại khuyến mại nha, bạn chờ 1 chút nhé!"},{"speaker":"client","text":"Ok, mình chờ. Nhưng nếu không giảm nữa thì thôi, mình qua shop khác mua vậy."}]','fail',606),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc áo khoác mùa đông này, nhưng giá 1.200k hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ em hiểu ạ! Đấy là sản phẩm từ chất liệu chống nước cao cấp, giá niêm yết 1.200k nhưng bây giờ có chương trình giảm 20% cho khách hàng đầu tiên đó ạ!"},{"speaker":"client","text":"Vậy giao hàng mất bao lâu? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Dạ trong ngày hôm nay sẽ có shipper liên hệ ạ, nếu bạn ở nội thành thì giao trong vòng 2-3 tiếng thôi ạ. Còn nếu xa hơn thì 1-2 ngày thôi ạ!"},{"speaker":"client","text":"Ok, vậy mình chọn size M nhé. Nhưng mình thấy trên web ghi là hết hàng size M rồi mà?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ! Size M vừa hết hàng do lượng đơn cao ạ. Size L và size S vẫn còn ạ, bạn có thể chọn size khác không ạ? Hoặc để em kiểm tra kho xem có size M nào sót không nhé?"},{"speaker":"client","text":"Thôi được, mình chọn size L vậy. Nhưng 1.200k sau khi giảm 20% là 960k đúng không?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ! 960k thôi ạ. Bạn vui lòng để lại số điện thoại và địa chỉ nhận hàng để em xử lý đơn hàng cho bạn nhé!"},{"speaker":"client","text":"À mình không muốn nhập số điện thoại đâu, mình sẽ thanh toán bằng tiền mặt khi nhận hàng thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, shop mình chỉ hỗ trợ thanh toán online hoặc chuyển khoản thôi ạ. Bạn có thể thanh toán qua MoMo, VNPay hoặc chuyển khoản ngân hàng đều được ạ!"},{"speaker":"client","text":"Thế à? Vậy thôi, mình không mua nữa đâu. Thanks!"}]','fail',607),
('[{"speaker":"client","text":"Chào shop, mình thấy bộ chăn ga gối đệm cotton 100% của shop đang khuyến mại 30% vậy giá gốc của nó là bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Giá gốc của bộ chăn ga gối đệm cotton 100% là 2.999.000đ, giờ chỉ còn 2.099.000đ thôi ạ!"},{"speaker":"client","text":"Hơi đắt so với mình nghĩ, mình có thể trả 1.800.000đ được không? Mua luôn 2 bộ 1 lúc."},{"speaker":"salebot","text":"Dạ chúng em không thể giảm thêm nữa ạ, 2.099.000đ là giá tốt nhất rồi ạ. Nếu bạn mua thêm gối chống ngáy tặng kèm thì ưu đãi hơn nhé!"},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',608),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, nhưng giá trên web hơi cao so với mình nghĩ. Có ưu đãi gì không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Bàn chải điện Oral-B Pro 3000 hiện đang có chương trình khuyến mại 15% cho đơn hàng đầu tiên nếu anh/chị thanh toán qua thẻ ngân hàng."},{"speaker":"client","text":"15% à? Nhưng mình thấy trên Shopee giá cũng gần vậy thôi. Có giảm nữa không? Mình chỉ sẵn sàng trả tối đa 1,8 triệu thôi."},{"speaker":"salebot","text":"Dạ anh/chị thông cảm, đây là mức giá ưu đãi nhất rồi ạ. Nếu anh/chị mua kèm kem đánh răng Oral-B 3D White thì mình có thể giảm thêm 50k nữa, thành 1,85 triệu."},{"speaker":"client","text":"Thế à, tiếc quá mình không cần kem đánh răng. Vậy thôi, cảm ơn bạn nhé!"}]','fail',609),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc đồng hồ Casio G-Shock GA-2100, nhưng nhìn thấy giá hơi cao quá. Có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Đúng rồi ạ, giá niêm yết là 2.990.000đ, nhưng hôm nay mình đang có chương trình khuyến mại 10% cho sản phẩm này nếu anh/chị đặt ngay hôm nay."},{"speaker":"client","text":"10% hơi ít nhỉ, mình thấy bên kia bán có 15% luôn. Bạn có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, mức giảm tối đa mình có thể hỗ trợ là 12% thôi ạ. Nếu anh/chị đồng ý, mình sẽ gửi mã giảm giá qua email ngay sau khi thanh toán."},{"speaker":"client","text":"Thôi vậy, mình không giảm được nữa thì thôi. Cảm ơn bạn nhé!"}]','fail',610),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác thể thao này nhưng nhìn hơi đắt so với giá mình định. Bên mình có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Nếu bạn mua ngay hôm nay, mình có thể giảm 10% cho bạn nhé. Hoặc nếu đặt 2 chiếc trở lên, mình tặng luôn 1 chiếc khăn thể thao nữa."},{"speaker":"client","text":"Vậy mình lấy 1 chiếc thôi, 10% giảm giá thế nào?"},{"speaker":"salebot","text":"Dạ 10% trên giá niêm yết nhé! Bạn chọn màu nào ạ? Màu đen hay xanh navy?"},{"speaker":"client","text":"Mình chọn màu đen đi. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 30 phút ạ, phí ship nội thành là 20k. Bạn có muốn thanh toán online hay COD ạ?"},{"speaker":"client","text":"Mình thanh toán online nhé. Cảm ơn bạn!"}]','successs',611),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách Gucci mini GG từ hôm qua nhưng không thấy size S trên web. Có hàng không vậy?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, size S vừa hết hàng hôm nay. Size M vẫn còn 2 cái, bạn xem có ưng không ạ?"},{"speaker":"client","text":"Ui, tiếc quá. Mình thích size S lắm. Thế giá có giảm không? Mình thấy bên kia bán rẻ hơn 500k đấy."},{"speaker":"salebot","text":"Dạ em xin lỗi, giá niêm yết không thể giảm được ạ. Nhưng nếu bạn mua kèm phụ kiện hoặc đặt trước 2 ngày, mình có thể tặng kèm túi vệ sinh mini ạ."},{"speaker":"client","text":"Thế à... Mà mình không cần phụ kiện đâu. Thôi cứ để vậy, cảm ơn bạn nhé!"}]','fail',612),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua nồi cơm điện tử Cuckoo 5.5L. Có giảm giá gì không thế?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang khuyến mại 15% cho sản phẩm này, chỉ còn 4.290.000đ thôi ạ."},{"speaker":"client","text":"Ồ, rẻ hơn quảng cáo trên TV nhiều nhỉ. Còn bảo hành bao lâu vậy?"},{"speaker":"salebot","text":"Bảo hành chính hãng 2 năm ạ, tặng kèm gạo lứt miễn phí trong tháng đầu sử dụng luôn!"},{"speaker":"client","text":"Tuyệt vời! Vậy mình đặt luôn nhé. Giao trong 2 tiếng được không?"},{"speaker":"salebot","text":"Dạ được ạ! Địa chỉ mình ghi nhận là 123 Lê Lợi, Q.1, TP.HCM nhé. Cảm ơn khách!"}]','successs',613),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn học gỗ óc chó này đẹp quá, nhưng giá 5 triệu hơi mắc nhỉ?"},{"speaker":"salebot","text":"Dạ anh ơi, bàn gỗ óc chó chất lượng lắm ạ, bền và thẩm mỹ cao. Hiện tại shop có ưu đãi 5% cho đơn trên 3 triệu, vậy anh nhận 4.75 triệu nhé?"},{"speaker":"client","text":"4.75 triệu vẫn hơi cao, mình thấy bên kia bán 4.2 triệu thôi. Bớt 500k nữa đi nhé?"},{"speaker":"salebot","text":"Dạ anh thông cảm, giá nhập vào đã sát rồi ạ. Nếu anh mua kèm ghế gỗ óc chó nữa thì shop giảm thêm 200k, tổng 4.5 triệu được không ạ?"},{"speaker":"client","text":"Thôi được, mình lấy ghế luôn. Nhưng giao hàng tận nơi và lắp đặt miễn phí nhé!"},{"speaker":"salebot","text":"Dạ không được ạ, phí giao hàng ngoài nội thành 50k và lắp đặt 100k. Nếu anh chịu phí thì shop hỗ trợ ngay ạ."},{"speaker":"client","text":"Vậy thôi, mình không mua nữa. Thấy trên mạng nhiều chỗ rẻ hơn. Cảm ơn!"}]','fail',614),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao cho bé gái 10 tuổi. Có size 120 không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại shop đang có bộ quần áo thể thao màu hồng size 120 giá 450k. Bạn muốn mua không?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm giá không? Mình thấy bên kia bán 400k thôi."},{"speaker":"salebot","text":"Dạ shop báo giá 450k là giá niêm yết rồi ạ, nhưng nếu bạn mua 2 bộ trở lên thì giảm 10% cho bạn nhé!"},{"speaker":"client","text":"Thế à, thế mình mua 1 bộ thôi thì không giảm được à? Mình chỉ cần 1 bộ thôi."},{"speaker":"salebot","text":"Dạ không ạ, shop xin lỗi ạ. Nếu bạn muốn giá tốt hơn, mình có thể thông báo cho bạn khi có chương trình khuyến mại tuần sau nhé?"}]','fail',615),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy S24 Ultra. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Samsung Galaxy S24 Ultra hiện đang có sẵn màu đen và xanh dương. Anh/chị muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 29.990.000đ, nhưng hôm nay có chương trình khuyến mại giảm còn 27.990.000đ thôi ạ!"},{"speaker":"client","text":"Có giảm thêm nữa không? Mình thấy nơi khác rẻ hơn 1 triệu đó."},{"speaker":"salebot","text":"Dạ anh/chị thông cảm, đây là mức giá tốt nhất của mình rồi ạ. Nhưng nếu anh/chị mua kèm ốp lưng chính hãng chỉ 200k thay vì 500k, mình giảm luôn 200k cho anh/chị nhé?"},{"speaker":"client","text":"Ừ, vậy mình lấy luôn. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị vui lòng cung cấp địa chỉ và số điện thoại để mình xác nhận đơn hàng nhé. Cảm ơn anh/chị đã mua sắm cùng mình!"}]','successs',616),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc bàn phím cơ Keychron K8, nhưng giá 3 triệu hơi đắt quá nhỉ?"},{"speaker":"salebot","text":"Dạ em hiểu ạ, nhưng đây là phiên bản full size với switch Gateron Red siêu êm, ưu đãi giảm 500k nếu bạn ghép kèm mousepad nhé!"},{"speaker":"client","text":"Mình chỉ mua bàn phím thôi, 2.8 triệu có được không? Mình thấy bên kia bán rẻ hơn."},{"speaker":"salebot","text":"Dạ em xin lỗi, giá 3 triệu là chuẩn rồi ạ. Bên em có bảo hành 12 tháng và quà tặng kèm là wrist rest. Chị có thể cân nhắc thêm nhé!"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Giao hàng trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ gửi link thanh toán qua Zalo cho chị. Cảm ơn chị đã ủng hộ!"}]','fail',617),
('[{"speaker":"client","text":"Chào em, mình thấy điện thoại Samsung Galaxy A54 5G trên web có khuyến mại gì không? Mình đang phân vân giữa nó và A73."},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Galaxy A54 hiện đang giảm 10% cho đơn hàng đầu tiên, kèm quà tặng là ốp lưng chính hãng. Còn A73 thì ưu đãi trả góp 0%."},{"speaker":"client","text":"Mình nghe nói A73 pin tốt hơn, vậy giá chênh lệch nhiều không? Mình ngại trả góp lắm."},{"speaker":"salebot","text":"A73 đắt hơn khoảng 3 triệu anh ạ, nhưng pin 5000mAh so với 5000mAh của A54 thì chỉ hơn 10% thời lượng. Nếu anh không cần trả góp, A54 vẫn là lựa chọn tiết kiệm hơn."},{"speaker":"client","text":"Thế không khuyến mại gì nữa à? Mình thấy web ghi free ship nhưng có điều kiện gì không?"},{"speaker":"salebot","text":"Dạ free ship cho đơn trên 10 triệu thôi ạ. Đơn A54 của anh chưa tới, nhưng nếu anh chọn combo tai nghe Bluetooth thì đủ điều kiện ạ! Giảm thêm 200k nữa."},{"speaker":"client","text":"Ôi dào, mình chỉ cần điện thoại thôi. Thôi vậy mình nghĩ lại đã, cảm ơn em nhé!"}]','fail',618),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật của thương hiệu Coach, nhưng giá trên web hơi cao so với mình mong đợi. Bạn có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Túi Coach hiện tại đang được giảm 10% trong chương trình khuyến mại cuối tháng. Nếu chị lấy ngay hôm nay, mình còn hỗ trợ phí ship tận nhà trong nội thành nữa chị nhé!"},{"speaker":"client","text":"Vậy giá cuối cùng là bao nhiêu? Mình thấy trên web vẫn còn hơi cao so với các shop khác."},{"speaker":"salebot","text":"Dạ chị thông cảm, sản phẩm chính hãng 100% có tem chống hàng giả và bảo hành 2 năm. Nhưng nếu chị lấy 2 chiếc trở lên, mình giảm thêm 5% nữa nhé!"},{"speaker":"client","text":"Okay, vậy mình lấy 1 chiếc thôi. Bao ship bao nhiêu?"},{"speaker":"salebot","text":"Dạ ship nội thành chỉ 20k chị nhé! Tổng cộng sau khi giảm giá là 8.520.000đ, chị chuyển khoản hay thanh toán khi nhận hàng đều được ạ."}]','successs',619),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác thể thao của Nike cho con trai mình. Size L có không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen đều còn size L. Con bạn cao bao nhiêu ạ? Để mình tư vấn vừa vặn hơn."},{"speaker":"client","text":"Con mình 1m70, khá cao ạ. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ 2.499.000đ ạ, nhưng hôm nay có mã giảm 10% cho đơn trên 2 triệu. Bạn có muốn nhận luôn không?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Ship tận nhà chứ? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ có ạ! Ship nội thành 25k, giao trong 2-3 tiếng. Bạn có muốn thanh toán COD hay chuyển khoản ạ?"},{"speaker":"client","text":"COD được không? Mình thích kiểm tra hàng trước."},{"speaker":"salebot","text":"Dạ được ạ! Đơn của bạn đã ghi nhận. Cảm ơn bạn đã mua sắm ạ! 😊"}]','successs',620),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng thấy giá hơi cao quá. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc áo này đang có chương trình khuyến mãi 10% cho đơn hàng đầu tiên hôm nay chị nhé!"},{"speaker":"client","text":"10% thôi à? Mà mình nghe nói chỗ khác có chương trình 20% cho sản phẩm tương tự. Bạn có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ thật tiếc là chị, đây là mức giảm tối đa rồi ạ. Nhưng chị có thể nhận thêm quà tặng miễn phí nếu thanh toán bằng thẻ tín dụng của shop nè!"},{"speaker":"client","text":"Thế à... thôi được, mình tạm nhận vậy. Nhưng lần sau có chương trình hấp dẫn hơn thì nhớ báo mình nhé!"},{"speaker":"salebot","text":"Dạ vâng chị, em sẽ nhớ ạ! Cảm ơn chị đã ủng hộ shop, chúc chị một ngày tốt lành!"}]','fail',621),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn làm việc gỗ óc chó, có kích thước 120x60cm không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi đang có mẫu bàn óc chó nguyên khối, giao hàng tận nơi trong 3-5 ngày. Bạn muốn màu tự nhiên hay sơn bóng?"},{"speaker":"client","text":"Màu tự nhiên thôi. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ giá niêm yết 5.990.000đ, nhưng hôm nay có giảm còn 5.500.000đ cho đơn hàng đầu tiên. Bao gồm phí vận chuyển luôn nhé!"},{"speaker":"client","text":"Hơi đắt quá, mình thấy bên kia bán 5.200.000đ không giao hàng. Bạn giảm được không?"},{"speaker":"salebot","text":"Dạ ạ, nếu bạn lấy luôn hôm nay thì mình giảm xuống 5.300.000đ nhé! Đảm bảo chất lượng gỗ óc chó nguyên khối 100%."},{"speaker":"client","text":"Ok, vậy mình lấy. Địa chỉ giao là 123 Lê Lợi, Phường Bến Thành, Quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ ạ! Đơn hàng của bạn đã được ghi nhận. Cảm ơn bạn đã mua sắm tại cửa hàng chúng tôi. Chúc bạn một ngày tốt lành!"}]','successs',622),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ Casio để đi bơi, có loại nào chống nước tốt không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Casio A168W-1 có khả năng chống nước 50m, phù hợp lắm ạ. Giá 1.200.000đ thôi."},{"speaker":"client","text":"Ngon, nhưng mình thấy trên web khác có giá 1.050.000đ, bạn giảm được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá này đã là ưu đãi nhất rồi ạ. Nếu bạn mua kèm dây da thì giảm thêm 50k ạ!"},{"speaker":"client","text":"Thế à, thôi mình bỏ qua vậy. Cảm ơn nhé!"}]','fail',623),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc bàn chải điện cho bé nhà mình. Đang phân vân giữa Oral-B Kids 5000 và Philips Sonicare HX6321/02. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào bạn! Cả hai sản phẩm đều tốt cho trẻ em, nhưng Oral-B Kids 5000 có thiết kế ngộ nghĩnh hơn và giá cũng vừa phải hơn ạ. Còn Sonicare thì rung nhẹ hơn, phù hợp cho bé nhạy cảm."},{"speaker":"client","text":"Mấy giờ nữa thì giảm giá vậy? Mình thấy trên web ghi ưu đãi cuối tuần nhưng không rõ giờ cụ thể."},{"speaker":"salebot","text":"Dạ ưu đãi sẽ có vào 18h hôm nay ạ! Nếu bạn đặt ngay bây giờ, mình sẽ gửi mã giảm 10% trước khi chương trình bắt đầu ạ."},{"speaker":"client","text":"Thế à? Vậy mình chọn Oral-B Kids 5000 màu xanh dương đi. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, nếu bạn chọn giao nhanh thì 1 ngày nhận được ạ! Mình sẽ gửi link thanh toán qua Zalo ngay bây giờ ạ."},{"speaker":"client","text":"Ok, cảm ơn bạn nhé! Mình thanh toán luôn đây."}]','successs',624),
('[{"speaker":"client","text":"Chào shop, mình thấy chiếc máy xay sinh tố Philips HR2118/00 giá 1.200.000đ, nhưng hôm nay có deal gì rẻ hơn không? Mình mua cho mẹ dùng thôi."},{"speaker":"salebot","text":"Dạ chào chị! Hôm nay mình có ưu đãi giảm 15% cho sản phẩm này, chỉ còn 1.020.000đ thôi ạ. Kèm theo tặng kèm 1 cốc thủy tinh không vỡ."},{"speaker":"client","text":"15% thì hơi ít, chị thấy trên Shopee giảm tới 20% kèm quà tặng nhiều hơn. Bác có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, mình đã chiết khấu tối đa rồi ạ. Nhưng nếu chị mua 2 sản phẩm, mình giảm thêm 5% nữa nhé! Chỉ còn 969.000đ mỗi cái thôi."},{"speaker":"client","text":"Thế à? Vậy mình lấy 1 thôi, ship nhanh trong ngày được không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Chị check order tại đây nhé: [link]. Cảm ơn chị đã ủng hộ shop ạ!"}]','successs',625),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra 5G trên web có khuyến mãi không? Mình muốn mua tặng vợ nhân dịp sinh nhật."},{"speaker":"salebot","text":"Dạ chào chị! Chúng mình đang có chương trình tặng ốp lưng chính hãng kèm quà tặng trị giá 500k khi mua điện thoại ạ. Chị có muốn mình hỗ trợ đặt hàng luôn không?"},{"speaker":"client","text":"Ốp lưng kèm quà tặng thì giá bao nhiêu vậy? Mình thấy trên web ghi 25 triệu, nhưng mình nghe nói có thể giảm giá hơn không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 25 triệu, nhưng nếu chị đặt ngay hôm nay thì mình có thể giảm còn 23,5 triệu kèm quà tặng chị nhé! Có cả bảo hành 24 tháng nữa."},{"speaker":"client","text":"Thế giao hàng tận nhà trong ngày được không? Mình cần quà tặng vào ngày mai."},{"speaker":"salebot","text":"Dạ được ạ! Chị cứ yên tâm, mình sẽ hỗ trợ giao hàng nhanh trong ngày nếu chị đặt trước 16h hôm nay. Chị có muốn mình gửi link thanh toán luôn không?"},{"speaker":"client","text":"Ok, mình chọn màu đen nhé. Bao gồm cả ốp lưng và quà tặng luôn. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc chị sinh nhật vui vẻ, mình sẽ gửi xác nhận đơn hàng qua Zalo ngay sau khi thanh toán xong nhé!"}]','successs',626),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 5000, có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại đang khuyến mại 20% cho sản phẩm này, giá chỉ còn 2.400.000đ thay vì 3.000.000đ."},{"speaker":"client","text":"Ôi tốt quá! Mình lấy luôn đi. Có giao hàng tận nơi không?"},{"speaker":"salebot","text":"Dạ có ạ! Miễn phí giao hàng nội thành, mình sẽ gửi đơn ngay bây giờ. Bạn nhập địa chỉ giúp mình nhé!"},{"speaker":"client","text":"Ok, mình ở 123 Lê Lợi, quận 1. Cảm ơn bạn nhiều!"}]','successs',627),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra, mình thấy trên web có khuyến mại gì không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện sản phẩm đang có chương trình giảm giá 10% khi thanh toán bằng thẻ tín dụng ngân hàng Techcombank, và tặng kèm ốp lưng chính hãng nữa!"},{"speaker":"client","text":"Ồ, vậy giá cuối cùng là bao nhiêu thế? Mình nghe nói giá gốc là 25 triệu, có đúng không?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Sau khi giảm 10% thì giá còn 22.5 triệu, cộng ốp lưng tặng kèm. Bạn có thể chọn màu đen hoặc xanh dương nhé!"},{"speaker":"client","text":"Ok, mình chọn màu đen đi. Bao lâu thì nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ trong nội thành giao trong 2-3 giờ, còn ngoài tỉnh thì 1-2 ngày ạ. Bạn có thể chọn hình thức thanh toán COD hoặc chuyển khoản đều được!"},{"speaker":"client","text":"Cảm ơn bạn, mình chọn COD nhé. Địa chỉ nhận là 123 Lê Lợi, phường Bến Thành, quận 1, TP.HCM."},{"speaker":"salebot","text":"Dạ cảm ơn bạn đã mua hàng! Đơn hàng của bạn sẽ được xử lý trong vòng 30 phút nữa. Chúc bạn một ngày tốt lành!"}]','successs',628),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra trên web có khuyến mại gì không vậy? Mình đang phân vân nên mua hay không."},{"speaker":"salebot","text":"Dạ chào anh! Hiện tại sản phẩm đang có chương trình giảm 2 triệu cho đơn hàng trong hôm nay ạ. Nếu anh mua kèm ốp lưng chính hãng thì tặng luôn sạc nhanh 25W nữa!"},{"speaker":"client","text":"Thế giá cuối cùng là bao nhiêu vậy? Mình chưa chắc chắn lắm."},{"speaker":"salebot","text":"Dạ giá niêm yết 32 triệu, sau khi giảm còn 30 triệu ạ. Nếu anh đặt ngay bây giờ thì mình sẽ hỗ trợ ship 0đ trong 2h cho nội thành!"},{"speaker":"client","text":"Ok, mình quyết định mua luôn. Bao lâu thì nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ ạ! Em sẽ xử lý đơn ngay bây giờ, anh check mail để xác nhận đơn hàng nhé. Ship trong 2h và bảo hành 24 tháng ạ!"}]','successs',629),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn học gỗ óc chó này đẹp quá. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 5 triệu 500k ạ, giao hàng tận nơi miễn phí trong 3 ngày."},{"speaker":"client","text":"Mình mới có con nhỏ nên ngại chờ lâu quá. Có thể giảm giá không? 5 triệu thôi nhé?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã niêm yết rồi. Nếu bạn mua kèm ghế gỗ nhỏ thì giảm 100k nhé ạ."},{"speaker":"client","text":"Thôi vậy, mai mình quay lại mua vậy. Cảm ơn nhé!"}]','fail',630),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S24 Ultra 5G trên web, giá có đẹp không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Em gửi link ưu đãi hôm nay nhé: 28 triệu thay vì 32 triệu, kèm quà tặng là sạc không dây trị giá 1 triệu."},{"speaker":"client","text":"28 triệu hơi cao, mình có thể trả 25 triệu không?"},{"speaker":"salebot","text":"Dạ em xin phép kiểm tra lại với quản lý nhé! Anh/chị chờ 1 phút ạ."},{"speaker":"salebot","text":"Anh/chị ơi, quản lý vừa duyệt giảm xuống 26 triệu thôi ạ, không thể thấp hơn vì sản phẩm mới ra."},{"speaker":"client","text":"Ok, vậy mình lấy luôn, ship tận nhà luôn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn anh/chị! Em đã gửi thông tin đơn hàng qua email rồi ạ. Chúc anh/chị ngon miệng!"}]','successs',631),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua một chiếc điện thoại thông minh tầm 8-10 triệu thôi. Có sản phẩm nào mới và tốt không?"},{"speaker":"salebot","text":"Dạ chào bạn! Bên mình vừa về dòng Xiaomi Redmi Note 13 vừa rồi, cấu hình khủng, pin 5000mAh, giá chỉ 8,99 triệu thôi ạ!"},{"speaker":"client","text":"Ui, nghe ngon thật. Nhưng mình thấy trên mạng nó có giá 8,5 triệu thôi mà?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 8,99 triệu ạ, nhưng hôm nay có chương trình khuyến mại giảm còn 8,4 triệu thôi ạ! Còn kèm theo quà tặng là ốp lưng và dán màn hình nữa!"},{"speaker":"client","text":"Thế à? Ok mình lấy luôn đi, mình ở quận 1, giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn chọn màu xanh dương hay đen? Và địa chỉ giao hàng là bao nhiêu ạ?"}]','successs',632),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác nữ hiệu Zara, size M có không ạ? Mình thấy trên web là size M hết hàng nhưng không biết có nhầm không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Size M của mẫu áo khoác nữ Zara vừa hết hàng online nhưng cửa hàng chúng tôi có sẵn 2 chiếc size M tại cửa hàng 258 Lê Thánh Tông, chị có thể ghé mua hoặc đặt trước 1 chiếc ạ!"},{"speaker":"client","text":"À vậy à, mình đang ở quận 1, không tiện qua cửa hàng. Bạn có thể ship về nhà không? Giá ship thế nào ạ?"},{"speaker":"salebot","text":"Dạ chị ơi, ship nội thành quận 1 chỉ 25k, chị đặt trước 1 chiếc thì mình giữ hàng 24h cho chị ạ. Nếu chị nhận hàng không ưng, có thể trả lại miễn phí trong 7 ngày."},{"speaker":"client","text":"Ok, vậy mình đặt 1 chiếc size M nhé! Mà bạn có giảm giá gì không? Mình thấy trên web ghi khuyến mại 10% nhưng không rõ áp dụng không?"},{"speaker":"salebot","text":"Dạ chị ơi, khuyến mại 10% vẫn áp dụng được ạ! Chị đặt luôn thì mình tính luôn giá 1.439.000đ (giảm từ 1.599.000đ) cho chị. Nếu chị thanh toán bằng chuyển khoản ngân hàng, mình tặng luôn 1 chiếc khăn lụa trị giá 199k ạ!"},{"speaker":"client","text":"Hay quá, vậy mình chuyển khoản luôn nhé. Mình gửi thông tin sau nha!"},{"speaker":"salebot","text":"Dạ chị vui lòng gửi thông tin chuyển khoản + địa chỉ nhận hàng vào đây ạ, mình sẽ xác nhận và giao hàng trong 2h tới ạ! Cảm ơn chị đã mua sắm cùng shop ạ!"}]','successs',633),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc túi xách da cá sấu này. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Chiếc túi xách da cá sấu này đang có giá 3.500.000đ, chị nhé!"},{"speaker":"client","text":"Ồ đắt quá, có giảm được không? Mình thấy bên kia bán rẻ hơn 500k đó."},{"speaker":"salebot","text":"Dạ em xin lỗi chị ạ, nhưng đây là sản phẩm cao cấp da thật 100%, chất lượng đảm bảo. Em có thể giảm 200k thành 3.300.000đ, chị nhận không ạ?"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Đóng gói cẩn thận nhé, giao hàng tận nơi không?"},{"speaker":"salebot","text":"Dạ vâng chị! Em sẽ đóng gói cẩn thận và giao tận nơi trong 24h. Chị vui lòng cung cấp địa chỉ và số điện thoại ạ!"}]','successs',634),
('[{"speaker":"client","text":"Chào em, mình đang tìm bộ quần áo thể thao cho bé 10 tuổi. Có loại nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào chị! Chúng em có bộ quần áo thể thao size 12-14 (tương đương 10 tuổi) của thương hiệu Adidas, màu xanh dương và hồng, còn 5 cái ạ."},{"speaker":"client","text":"Mấy hôm nay thấy giảm giá không? Mình thấy giá hơi cao so với mấy chỗ khác."},{"speaker":"salebot","text":"Dạ chị thông cảm, hôm nay không giảm giá chị ạ. Nhưng nếu chị mua 2 bộ trở lên thì được tặng 1 đôi tất thể thao ạ."},{"speaker":"client","text":"Thế à... Mà bé nhà mình hơi mập, size 12-14 có vừa không nhỉ? Chị lo quá..."},{"speaker":"salebot","text":"Dạ chị yên tâm ạ, size 12-14 rộng rãi, bé mặc thoải mái lắm. Nếu không vừa chị cứ đổi trả trong 7 ngày không cần lý do ạ."},{"speaker":"client","text":"Thôi được, mình lấy 1 bộ vậy. Nhưng giao hàng tận nơi miễn phí chứ?"},{"speaker":"salebot","text":"Dạ có chị ơi, giao miễn phí trên 500k ạ. Bộ này 499k nên chị chỉ cần cộng thêm 1 sản phẩm nhỏ xíu thôi là được miễn phí ạ."},{"speaker":"client","text":"Mình không cần thêm gì nữa đâu. Thôi... thôi bỏ đi vậy. Cảm ơn em nhé."}]','fail',635),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có sẵn không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình đang có chương trình khuyến mại, chỉ 1.890.000đ thôi ạ (giá gốc 2.200.000đ)."},{"speaker":"client","text":"Hơi đắt quá nhỉ, có thể giảm xuống 1.700.000đ không? Mình thấy nơi khác bán rẻ hơn."},{"speaker":"salebot","text":"Dạ thưa anh, 1.800.000đ là giá tốt nhất rồi ạ! Nếu anh mua kèm 1 hộp bàn chải thay thế (290.000đ) thì mình giảm thêm 50.000đ nhé?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn 2 cái luôn. Ship miễn phí chứ?"},{"speaker":"salebot","text":"Dạ miễn phí ship cho đơn từ 2 triệu ạ! Anh để lại số điện thoại, mình gửi mã giảm giá 5% cho lần mua sau luôn nha."}]','successs',636),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000. Mình nghe nói nó tốt lắm nhỉ?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Bàn chải Oral-B Pro 3000 chính hãng thì đang có chương trình khuyến mại 20% cho đơn hàng đầu tiên đó bạn! Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh dương. Giá sau khi giảm là bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ sau khi giảm giá chỉ còn 1.990.000đ thôi ạ! Còn kèm theo 1 bộ bàn chải thay thế nữa đó."},{"speaker":"client","text":"Hơi đắt so với mình chút, mình có thể trả 1.850.000đ được không?"},{"speaker":"salebot","text":"Dạ vì là khách hàng mới nên mình sẽ hỗ trợ bạn 1.900.000đ thôi ạ, đây là giá tốt nhất rồi đó bạn!"},{"speaker":"client","text":"Ok, vậy giao trong ngày được không? Mình đang cần gấp."},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng để lại địa chỉ và số điện thoại, mình sẽ xử lý đơn hàng ngay!"}]','successs',637),
('[{"speaker":"client","text":"Chào em, mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra 256GB trên web, mình có thể trả góp không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Điện thoại này có hỗ trợ trả góp 0% lãi suất qua thẻ tín dụng hoặc trả góp 3-12 tháng qua đối tác tài chính. Anh/chị muốn chọn phương thức nào ạ?"},{"speaker":"client","text":"Mình thích trả góp 6 tháng, nhưng giá web là 28 triệu hơi cao so với nơi khác, em có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ anh/chị ơi, đây là giá niêm yết chính hãng từ Samsung, nhưng mình có voucher giảm 1 triệu cho đơn hàng hôm nay. Kèm theo quà tặng là sạc nhanh 25W nữa ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Phường Bến Nghé, Quận 1. Nhận hàng vào chiều nay được không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị vui lòng chọn phương thức thanh toán (trả góp 6 tháng hoặc thanh toán 1 lần) và cung cấp số điện thoại để xác nhận đơn hàng nhé."}]','successs',638),
('[{"speaker":"client","text":"Chào bot, mình thấy cái máy xay sinh tố này trên web có giá 1.200k, sao lại mắc thế? Bên mình không có ưu đãi gì à?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá niêm yết là 1.190k thôi ạ! Nếu bạn mua ngay hôm nay thì sẽ giảm 50k nữa thành 1.140k ạ."},{"speaker":"client","text":"1.140k vẫn hơi cao, mình thấy chỗ khác bán 1.050k kèm quà tặng nữa. Đừng có ép giá thế!"},{"speaker":"salebot","text":"Dạ em thật sự xin lỗi ạ, đây là giá tốt nhất rồi ạ. Nếu bạn chịu khó đợi 1 tuần nữa là có chương trình khuyến mại 10% ạ."},{"speaker":"client","text":"Thôi được, thôi được. Mấy giờ giao hàng vậy? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ giao trong 2-3 tiếng ạ, phí ship 20k ạ. Bạn có muốn đặt ngay không ạ?"},{"speaker":"client","text":"Không, thôi. Mình còn suy nghĩ thêm. Cảm ơn nhé!"}]','fail',639),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Philips Sonicare DiamondClean 9000. Giá trên web là 3.500.000đ, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại sản phẩm đang có khuyến mại 10% cho đơn hàng đầu tiên trong tháng, nên giá còn 3.150.000đ thôi chị nhé."},{"speaker":"client","text":"Hmm, mình thấy web khác có bán 2.900.000đ kia. Bên mình không có chênh lệch gì hết à?"},{"speaker":"salebot","text":"Dạ em xin lỗi chị, giá niêm yết của hãng là 3.500.000đ nên chúng em không thể giảm sâu hơn ạ. Nhưng sản phẩm kèm theo quà tặng là 5 đầu bàn chải thay thế nữa chị nhé!"},{"speaker":"client","text":"Thôi được, mình nhận hàng rồi tính. Địa chỉ giao hàng là 123 Lê Lợi, quận 1, TP.HCM. Bao giờ nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ chị vui lòng chuyển khoản 100% trước 18h hôm nay để được giao trong ngày ạ. Em sẽ gửi mã vận đơn qua tin nhắn ngay khi xác nhận thanh toán!"}]','fail',640),
('[{"speaker":"client","text":"Chào em, mình muốn mua chiếc váy thể thao nữ này của Adidas, size S và màu xanh dương còn không?"},{"speaker":"salebot","text":"Dạ chào chị, sản phẩm chị chọn vẫn còn hàng ạ! Size S màu xanh dương có sẵn, chị muốn giao trong ngày hay nhận hàng tận nơi?"},{"speaker":"client","text":"Giao trong ngày được không? Mình cần gấp lắm. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ giao nội thành trong ngày ạ, giá niêm yết 1.290.000đ, chị có thể thanh toán online hoặc COD đều được ạ."},{"speaker":"client","text":"Mình thấy trên web có giảm giá 10% không? Nếu được mình mua luôn."},{"speaker":"salebot","text":"Dạ chị ơi, hiện tại shop đang có khuyến mại 15% cho đơn hàng đầu tiên ạ! Vậy giá sau giảm chỉ còn 1.096.500đ thôi ạ."},{"speaker":"client","text":"Ồ, thế thì mình quyết định mua luôn! Địa chỉ giao là 123 Lê Lợi, phường Bến Nghé, quận 1 nha."},{"speaker":"salebot","text":"Dạ cảm ơn chị đã mua sắm ạ! Đơn hàng sẽ được giao trong 2-3 giờ tới ạ. Chúc chị một ngày vui vẻ!"}]','successs',641),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm bàn chải điện Oral-B cho gia đình. Loại nào tốt nhất vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Oral-B Genius X 2000N là model bán chạy nhất, có 6 chế độ đánh răng thông minh, phù hợp cho cả gia đình."},{"speaker":"client","text":"Ừm, mình thấy giá hơi cao so với ví mình. Bạn có giảm giá không?"},{"speaker":"salebot","text":"Dạ hiện tại shop đang có promo 5% cho đơn hàng trên 2 triệu, nếu bạn mua kèm kem đánh răng Oral-B Pro-Expert, mình có thể giảm thêm 100k nữa."},{"speaker":"client","text":"Thế thôi, mình chỉ lấy bàn chải thôi. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ, nhưng nếu bạn đổi ý thì mình vẫn giữ giá ưu đãi trong hôm nay nhé. Chúc bạn sức khỏe!"}]','fail',642),
('[{"speaker":"client","text":"Chào shop, mình thấy cái bàn học gỗ óc chó này đẹp quá, nhưng giá 5 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Chào chị ạ! Đúng là giá niêm yết là 5 triệu, nhưng hôm nay có chương trình giảm 10% cho đơn hàng đầu tiên, chị chỉ mất 4.5 triệu thôi!"},{"speaker":"client","text":"Thế giao hàng tận nơi được không? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ được chị ạ! Phí ship chỉ 30k, tổng cộng 4.53 triệu. Chị muốn nhận vào hôm nào?"},{"speaker":"client","text":"Ok, mình chọn giao ngày mai nhé. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chị vui lòng để lại số điện thoại để shop xác nhận đơn hàng nhé. Cảm ơn chị đã ủng hộ!"}]','successs',643),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn làm việc gỗ óc chó cho phòng khách. Có kích thước 120x60cm không?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu bàn gỗ óc chó nguyên khối, giao hàng tận nơi trong 3 ngày. Giá niêm yết 4.500.000đ, bạn có muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình thấy bên kia bán chỉ 4.200.000đ thôi."},{"speaker":"salebot","text":"Dạ thưa anh, sản phẩm gỗ óc chó nguyên khối nên giá hơi cao hơn chút. Nhưng anh đặt hôm nay thì mình giảm còn 4.300.000đ, tặng luôn kèm dầu bảo dưỡng gỗ 500ml ạ!"},{"speaker":"client","text":"Ừ, thế thì mình nhận. Bao gồm cả phí vận chuyển không?"},{"speaker":"salebot","text":"Dạ có ạ! Tổng cộng 4.300.000đ bao gồm phí vận chuyển nội thành. Anh vui lòng cung cấp địa chỉ nhận hàng để mình xử lý đơn hàng ngay nhé!"}]','successs',644),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc nồi cơm điện này nhưng không biết loại nào tốt nhất vậy?"},{"speaker":"salebot","text":"Dạ, nồi cơm điện Panasonic SR-DF1015 đang bán chạy nhất ạ! Có chức năng nấu cơm ngon, tiết kiệm điện và giá chỉ 1.890.000đ thôi."},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không ạ? Mình là sinh viên nên muốn tiết kiệm chút."},{"speaker":"salebot","text":"Dạ, nếu bạn mua trong hôm nay thì mình có thể giảm còn 1.750.000đ, kèm quà tặng là muỗng gỗ và sách dạy nấu ăn ạ!"},{"speaker":"client","text":"Ok, mình lấy vậy. Địa chỉ giao là 123 Lê Lợi, Quận 1, TPHCM nhé."},{"speaker":"salebot","text":"Dạ, đơn hàng của bạn đã được ghi nhận! Cảm ơn bạn đã ủng hộ, chúc bạn ngon miệng ạ!"}]','successs',645),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Chúng tôi đang có chương trình khuyến mại Galaxy S23 Ultra 5G với giá 28 triệu (giá niêm yết 32 triệu). Anh/chị muốn mua không ạ?"},{"speaker":"client","text":"28 triệu hơi cao, có thể giảm thêm không? Mình thấy nơi khác bán 26 triệu thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã ưu đãi lắm rồi ạ. Nhưng nếu anh/chị mua kèm phụ kiện như sạc nhanh + ốp lưng thì em có thể giảm thêm 500k cho anh/chị nhé!"},{"speaker":"client","text":"Thế nếu mình chỉ mua máy thôi thì sao? Hay mình lấy trọn bộ đi?"},{"speaker":"salebot","text":"Dạ nếu chỉ mua máy thôi thì em có thể giảm xuống 27 triệu ạ. Còn trọn bộ thì em cam kết giá tốt nhất ạ!"},{"speaker":"client","text":"Ok, mình lấy trọn bộ đi. Bao lâu giao hàng được ạ?"},{"speaker":"salebot","text":"Dạ giao hàng trong 2 giờ nếu anh/chị ở nội thành ạ. Anh/chị để lại địa chỉ và số điện thoại để em xác nhận đơn hàng nhé!"}]','successs',646),
('[{"speaker":"client","text":"Chào shop! Cho mình hỏi giá cái bàn ghế gỗ lim này thế nào? Mình thấy trên web ghi 15 triệu nhưng có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Bàn ghế gỗ lim này hiện đang khuyến mại 12 triệu thôi ạ, giảm 20% luôn đó!"},{"speaker":"client","text":"Ủa 12 triệu à? Mà mình thấy trên mạng giá còn rẻ hơn, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, giá này đã là ưu đãi nhất rồi ạ. Chất gỗ lim nguyên khối nên rất bền, giao hàng tận nơi miễn phí luôn ạ!"},{"speaker":"client","text":"Thế à... thôi được, mình cân nhắc đã. Cảm ơn nhé!"}]','fail',647),
('[{"speaker":"client","text":"Chào! Mình thấy chiếc bàn chải điện Oral-B Pro 3000 trên web có khuyến mại gì không vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Hiện sản phẩm đang giảm 20% còn 1.299.000đ, giao hàng miễn phí nếu chị đặt trong hôm nay."},{"speaker":"client","text":"Ồ, vậy tặng kèm có gì không? Mình nghe nói nó hay hết pin lắm."},{"speaker":"salebot","text":"Dạ không ạ, sản phẩm chỉ có bảo hành 24 tháng thôi chị nhé. Chị muốn mua không ạ?"},{"speaker":"client","text":"Hơi tiếc là không tặng kèm gì, mình sẽ suy nghĩ thêm. Cảm ơn nhé!"}]','fail',648),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua một chiếc điện thoại thông minh tầm 10 triệu thôi. Có gợi ý không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn có thể tham khảo Xiaomi Redmi Note 13 4G giá 9.990.000đ, cấu hình khủng, màn hình AMOLED nhé!"},{"speaker":"client","text":"Mình thấy 10 triệu hơi chênh, có giảm giá không? Mình thấy nơi khác bán 9.5 triệu đấy."},{"speaker":"salebot","text":"Dạ, vì là khách hàng mới nên mình có thể giảm còn 9.7 triệu cho bạn, giao hàng tận nơi miễn phí luôn ạ!"},{"speaker":"client","text":"Ok, thế mình mua luôn đây. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM nhé."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng của bạn đã được xác nhận, sẽ giao trong 2 giờ tới ạ. Chúc bạn một ngày vui vẻ!"}]','successs',649),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một đôi giày thể thao nam của Nike, size 42. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào anh! Chúng mình có sẵn mẫu Nike Air Max 270 size 42, màu đen hoặc trắng. Anh thích màu nào ạ?"},{"speaker":"client","text":"Mình thích màu đen nhưng thấy hơi đắt. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ hiện tại đang có khuyến mại 10% cho đơn hàng đầu tiên, cộng thêm quà tặng là tất thể thao. Anh nhận không ạ?"},{"speaker":"client","text":"Ổn, mình lấy vậy. Giao trong 2 ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh vui lòng cung cấp địa chỉ và số điện thoại để shop xử lý đơn hàng nhanh nhất."}]','successs',650),
('[{"speaker":"client","text":"Chào bot, mình muốn mua bộ ấm chén sứ cao cấp của shop. Bao nhiêu cái vậy?"},{"speaker":"salebot","text":"Dạ chào chị, bộ ấm chén sứ cao cấp 20 mảnh giá 1.200.000đ chị nhé. Đang có ưu đãi giảm 10% nếu chị mua trong hôm nay."},{"speaker":"client","text":"Ui, đắt quá! Mình thấy bên kia bán chỉ 900k thôi, sao shop lại cao thế?"},{"speaker":"salebot","text":"Dạ chị ơi, sản phẩm của shop là sứ cao cấp nhập khẩu từ Nhật, chất lượng đảm bảo hơn hẳn chị ạ. Nếu chị mua 2 bộ thì shop giảm thêm 5% nữa nè."},{"speaker":"client","text":"Thế à... Mà mình chỉ cần 1 bộ thôi. Được thì ship miễn phí nhé?"},{"speaker":"salebot","text":"Dạ tiếc quá, ship miễn phí chỉ áp dụng đơn từ 1.500.000đ chị ạ. Nhưng nếu chị đặt ngay bây giờ, shop sẽ tặng kèm khăn trà nhé!"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Nhưng giao trong 2 tiếng thôi nghe!"},{"speaker":"salebot","text":"Dạ không ạ, giao trong ngày thôi chị nhé. Địa chỉ của chị là...?"},{"speaker":"client","text":"Thôi thôi, mai mình quay lại mua vậy. Thanks bot."}]','fail',651),
('[{"speaker":"client","text":"Chào! Mình thấy sản phẩm điện thoại Samsung Galaxy S23 Ultra giảm giá nhiều quá, còn không? Mình đang cân nhắc mua."},{"speaker":"salebot","text":"Dạ có ạ! Máy màu đen và xanh dương đều còn hàng. Giá khuyến mại chỉ còn 22 triệu thôi ạ!"},{"speaker":"client","text":"22 triệu à? Mình thấy trên Shopee giá rẻ hơn 1 triệu đó! Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ, giá web mình đã ưu đãi nhất rồi ạ. Nếu bạn mua kèm ốp lưng hoặc sạc nhanh thì mình sẽ tặng thêm 1 triệu phí ship nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn đi. Địa chỉ mình là 123 Lê Lợi, quận 1, TPHCM. Giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng chuyển khoản 23 triệu vào số tài khoản 123456789 (Techcombank) nhé. Chúng tôi sẽ giao hàng ngay!"}]','successs',652),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc laptop gaming Acer Nitro 5, bạn có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Còn hàng phiên bản i5-12450H, RAM 16GB, 512GB SSD. Bạn cần màu nào ạ?"},{"speaker":"client","text":"Màu đen thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 22 triệu 500k ạ, đang có khuyến mãi giảm 500k nếu bạn đặt trong hôm nay."},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ nếu bạn mua kèm chuột gaming Logitech G203 giá 500k thì shop giảm còn 22 triệu ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn 2 sản phẩm đó. Ship bao lâu nhận được?"},{"speaker":"salebot","text":"Dạ giao trong ngày nếu bạn ở Hà Nội ạ, phí ship 20k. Bạn có thể thanh toán COD hoặc chuyển khoản ạ?"}]','successs',653),
