('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác mùa đông này nhưng nhìn hơi đắt. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện sản phẩm đang có chương trình giảm 15% cho đơn hàng đầu tiên, chỉ còn 1.299.000đ thôi ạ."},{"speaker":"client","text":"Ồ, vậy thì mình lấy luôn. Nhưng giao hàng trong 2 ngày được không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ được ạ! Nếu bạn chọn giao nhanh trong 48h sẽ mất thêm 30k phí, hoặc miễn phí giao trong 3-5 ngày. Bạn chọn cách nào?"},{"speaker":"client","text":"Miễn phí thôi, mình không gấp lắm. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Cảm ơn bạn đã mua sắm cùng shop. Chúc bạn một ngày vui vẻ!"}]','successs',656),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác da này nhưng thấy giá hơi cao so với mong đợi. Có ưu đãi gì không ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc áo khoác da này đang có chương trình giảm 15% cho đơn hàng đầu tiên, chị có thể dùng mã SALE15 khi thanh toán nha."},{"speaker":"client","text":"À vậy thì tốt quá! Nhưng mình thấy trên web ghi là giao trong 3-5 ngày, có cách nào giao nhanh hơn không?"},{"speaker":"salebot","text":"Dạ nếu chị ở TP. HCM thì mình hỗ trợ giao trong ngày luôn ạ! Chỉ cần chị chọn phương thức giao siêu tốc khi đặt hàng."},{"speaker":"client","text":"Ok, mình sẽ đặt luôn vậy! Cảm ơn bạn nhé."}]','successs',657),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại tầm trung để thay thế chiếc cũ. Nghe nói OPPO Reno11 có khuyến mãi gì không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại OPPO Reno11 đang giảm 1 triệu, kèm theo quà tặng là tai nghe không dây OPPO Enco Air3. Bạn muốn chọn màu gì ạ?"},{"speaker":"client","text":"Mình thích màu tím nhưng lo là giá có hơi cao. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ nếu bạn mua trả góp 0% trong 6 tháng thì mình có thể giảm thêm 500k nữa! Bạn thấy thế nào ạ?"},{"speaker":"client","text":"Ok, mình chọn màu tím và trả góp nhé. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 tiếng ạ, bạn vui lòng để lại địa chỉ và số điện thoại để mình xác nhận đơn hàng!"}]','successs',658),
('[{"speaker":"client","text":"Chào! Mình đang tìm mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G. Bạn có thể tư vấn cho mình không?"},{"speaker":"salebot","text":"Dạ chào bạn! Chúng mình đang có Galaxy S23 Ultra 5G phiên bản 256GB, màu đen và xanh lá. Bạn muốn mua không ạ?"},{"speaker":"client","text":"Mình thấy giá hơi cao so với dự tính, có thể giảm giá được không?"},{"speaker":"salebot","text":"Dạ ạ, mình có thể giảm 5% cho bạn, còn 22.990.000đ thôi. Đó là giá tốt nhất rồi ạ!"},{"speaker":"client","text":"22 triệu vẫn hơi đắt, mình thấy bên kia bán có 21 triệu. Thôi mình qua bên đó xem thế."},{"speaker":"salebot","text":"Dạ ạ, chúc bạn mua được sản phẩm ưng ý ạ!"}]','fail',659),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua đôi giày thể thao Nike Air Force 1, size 40 có không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Size 40 vẫn còn 3 đôi nha, màu trắng và đen. Anh/chị muốn chọn màu nào?"},{"speaker":"client","text":"Mình thích màu trắng nhưng giá hơi cao so với dự định. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, hôm nay có khuyến mãi 10% cho sản phẩm này nếu anh/chị thanh toán bằng ví MoMo ạ. Còn 1 tiếng nữa là hết khuyến mãi đó!"},{"speaker":"client","text":"Thế à? Ok, mình chọn màu trắng đi. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày làm việc ạ, phí ship 25k nếu anh/chị không lấy hàng tại cửa hàng. Anh/chị có muốn nhận hàng tận nơi không?"}]','successs',660),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc túi xách da thật tầm 3-4 triệu, có loại nào xịn xịn không?"},{"speaker":"salebot","text":"Dạ chào bạn! Mình có túi da thật nhập khẩu từ Ý, mẫu này giá 3.8 triệu, da bò nguyên tấm, chống xước tốt lắm ạ."},{"speaker":"client","text":"Ồ, xịn vậy. Nhưng mình thấy trên web có giảm giá không? Giảm 500k được không?"},{"speaker":"salebot","text":"Dạ không ạ, nhưng nếu bạn mua ngay hôm nay thì mình giảm còn 3.5 triệu thôi, giao tận nơi miễn phí luôn!"},{"speaker":"client","text":"Ok, mình chọn màu nâu nhạt nhé. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ trong 2 giờ ạ! Bạn để lại số điện thoại và địa chỉ, mình sẽ gửi thông tin xác nhận ngay."}]','successs',661),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc laptop cho con gái học đại học. Nó có thích chơi game nhẹ không nhỉ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng tôi có dòng Acer Aspire 5 vừa gọn nhẹ, đủ mạnh cho học tập và chơi game nhẹ như Liên Minh huyền thoại hay Valorant. Giá chỉ 12 triệu thôi chị nhé!"},{"speaker":"client","text":"12 triệu à? Đắt quá chị nhỉ, có giảm được không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, giá đã ưu đãi lắm rồi ạ! Nhưng nếu chị mua kèm chuột không dây tặng kèm, mình giảm còn 11 triệu 500k thôi!"},{"speaker":"client","text":"Thế à, ok chị lấy luôn ạ. Giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được chị! Em sẽ check kho ngay và gửi thông tin đơn hàng qua Zalo cho chị luôn nhé!"}]','successs',662),
('[{"speaker":"client","text":"Chào shop, mình muốn mua nồi cơm điện tử Kangaroo KG201, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ còn ạ! Nồi KG201 hiện đang giảm 20% còn 1.290.000đ thôi nè."},{"speaker":"client","text":"Ủa sao mắc thế? Mình thấy nơi khác bán 1.150.000đ cơ!"},{"speaker":"salebot","text":"Dạ shop mình có quà tặng kèm nồi là bộ muỗng gắp cơm, còn nơi khác chắc không có đâu ạ."},{"speaker":"client","text":"Thế à... thôi được, mình lấy vậy. Giao trong hôm nay được không?"},{"speaker":"salebot","text":"Dạ không ạ, giao từ thứ 2 tới ạ. Bạn để lại số điện thoại để shop liên hệ nhé!"},{"speaker":"client","text":"Thôi bỏ, mình không mua nữa đâu. Cảm ơn!"}]','fail',663),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc túi xách da thật này, nhưng giá 5 triệu hơi chát quá. Có thể giảm giá cho mình không?"},{"speaker":"salebot","text":"Dạ chào chị! Túi da thật này đang khuyến mãi 10% nên giá 4,5 triệu chị nhé. Nếu chị mua kèm ví da thì được free túi nhỏ luôn!"},{"speaker":"client","text":"Hmm, 4,5 triệu cũng tạm được. Nhưng mình thấy bên shop kia bán cùng sản phẩm có giá 4 triệu. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, sản phẩm này chất lượng da nguyên miếng 100% nên giá hơi cao. Nếu chị nhận hàng trong 2h tới thì mình giảm xuống 4,2 triệu cho chị nhé!"},{"speaker":"client","text":"Ok, vậy ship miễn phí luôn nhé! Mình lấy luôn 1 cái túi xách + 1 ví da."},{"speaker":"salebot","text":"Dạ chị vui lòng để lại địa chỉ và số điện thoại để shop xác nhận ạ! Chúc chị mua vui!"}]','successs',664),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua đôi giày thể thao Nike Air Max 270, size 42 có không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen đều còn, bạn muốn size chuẩn hay rộng hơn?"},{"speaker":"client","text":"Mình thích màu xanh dương, nhưng giá bao nhiêu vậy? Đã có khuyến mãi gì chưa?"},{"speaker":"salebot","text":"Dạ giá niêm yết 2.590.000đ, nhưng hôm nay giảm còn 2.390.000đ thôi ạ. Nếu bạn mua kèm tất thể thao giảm 10% nữa!"},{"speaker":"client","text":"Hơi đắt nhỉ, mình thấy bên khác bán 2.200.000đ kèm quà tặng luôn. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ thật tâm mình cũng muốn hỗ trợ, nhưng mức này đã là giá tốt nhất rồi ạ. Nếu bạn nhận hàng tại shop mình sẽ tặng luôn 1 chiếc tất thể thao cao cấp!"},{"speaker":"client","text":"Thế thôi, mình chọn màu xanh dương size 42 nhé. Địa chỉ giao 123 Lê Lai, Quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ cảm ơn bạn đã mua sắm ạ! Đơn hàng sẽ giao trong 2 giờ tới. Chúc bạn một ngày vui vẻ!"}]','fail',665),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng thấy giá hơi cao thế ạ. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, giá gốc 1.200.000đ nhưng hôm nay có khuyến mại giảm còn 999.000đ thôi ạ! Nếu bạn mua combo 2 cái sẽ giảm thêm 10% nữa."},{"speaker":"client","text":"Vậy giao tận nơi được chứ? Mình ở quận 10."},{"speaker":"salebot","text":"Dạ được ạ, phí ship 30.000đ, mình sẽ gửi mã giảm 50% phí ship cho bạn nhé!"},{"speaker":"client","text":"Ok, mình chọn size M, màu xanh dương. Thanh toán online được không?"},{"speaker":"salebot","text":"Dạ hoàn toàn được ạ! Mình gửi link thanh toán qua Zalo ngay nhé. Cảm ơn bạn đã mua sắm cùng shop!"}]','successs',666),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc đồng hồ Casio Edifice trên web có giảm giá không vậy? Mình thích kiểu dây da này lắm."},{"speaker":"salebot","text":"Dạ chào anh! Đúng rồi ạ, hôm nay đang có chương trình khuyến mại 15% cho mẫu này. Anh muốn chọn size dây nào ạ?"},{"speaker":"client","text":"Mình thích size M thôi. Giá sau giảm là bao nhiêu vậy?"},{"speaker":"salebot","text":"Sau giảm giá là 2.720.000đ anh nhé. Anh có muốn mình check mã giảm giá mới nhất không? Có thể tiết kiệm thêm 5% nữa."},{"speaker":"client","text":"Thế mình lấy luôn nhé! Ship tận nơi được không? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ được ạ! Anh chọn giao nhanh trong ngày nhé, phí ship 30.000đ. Anh có muốn thanh toán qua VNPay không?"},{"speaker":"client","text":"Ok, mình thanh toán online vậy. Cảm ơn bạn nhiều nha!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Anh vui lòng check tin nhắn điện thoại để xác nhận đơn hàng. Chúc anh một ngày tốt lành!"}]','successs',667),
('[{"speaker":"client","text":"Chào bot, mình thấy đôi giày thể thao Nike Air Force 1 giá 2,5 triệu trên web. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Giá niêm yết là 2,5 triệu nhưng hôm nay có khuyến mại 10% cho khách mới đó ạ!"},{"speaker":"client","text":"Ồ, vậy còn 2,25 triệu thôi à? Nhưng mình thấy trên Shopee có giá rẻ hơn 2 triệu luôn..."},{"speaker":"salebot","text":"Dạ... em xin lỗi ạ, giá trên web đã là giá tốt nhất rồi ạ. Nếu bạn mua kèm vớ tặng 1 đôi thì giá sẽ ổn hơn đó!"},{"speaker":"client","text":"Thôi bỏ đi, mình qua Shopee mua cho tiện. Cảm ơn!"}]','fail',668),
