('[{"speaker":"client","text":"Chào bạn, mình muốn mua cái nồi cơm điện này. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Nồi cơm điện này đang khuyến mại 1.299.000đ, giảm 15% so với giá gốc ạ."},{"speaker":"client","text":"Hơi đắt, có giảm nữa không? 1 triệu 1 được không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, giá đã ưu đãi lắm rồi ạ. Nếu chị mua kèm nồi hấp thì giảm 50k nữa nhé!"},{"speaker":"client","text":"Thôi thôi, mình không cần nữa đâu. Cảm ơn bạn nhé!"}]','fail',670),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào chị, bàn chải Oral-B Pro 3000 hiện có khuyến mại 15% cho đơn hàng đầu tiên chị ạ."},{"speaker":"client","text":"Ồ, thế giá còn bao nhiêu? Mình thấy trên shopee rẻ hơn 100k đấy."},{"speaker":"salebot","text":"Dạ giá niêm yết 2.990.000, chị có thể dùng mã giảm giá MUA15 để được 2.541.500 ạ. Còn shopee mình không rõ ạ."},{"speaker":"client","text":"Ui, thế cũng không rẻ hơn mấy. Thôi thôi, mình nghĩ lại vậy. Cảm ơn bot nha!"}]','fail',671),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra 5G trên web có khuyến mãi không vậy? Mình đang cần gấp."},{"speaker":"salebot","text":"Dạ chào anh chị! Chúng em đang có chương trình tặng kèm ốp lưng chính hãng và giảm 2 triệu đồng cho đơn hàng trong hôm nay ạ."},{"speaker":"client","text":"Giảm 2 triệu thôi à? Mấy hôm trước mình thấy giảm 3 triệu mà?"},{"speaker":"salebot","text":"Dạ thưa anh, chương trình hôm nay là ưu đãi đặc biệt từ nhà sản xuất ạ. Nếu anh đặt ngay thì còn được free ship nữa ạ!"},{"speaker":"client","text":"Thế không được nữa à? Mình cân nhắc chút rồi quay lại sau vậy."},{"speaker":"salebot","text":"Dạ vâng ạ, chúc anh chị ngày tốt lành! Nếu cần hỗ trợ gì thêm thì cứ phản hồi lại nhé ạ."}]','fail',672),
('[{"speaker":"client","text":"Chào anh, mình thấy cái bàn ghế gỗ óc chó này đẹp quá. Mà giá bao nhiêu vậy? Biết chắc là hàng chính hãng chứ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Bàn ghế gỗ óc chó này giá 12 triệu, chị có thể thanh toán trả góp 0% nếu muốn. Hàng thì 100% chính hãng nhập khẩu từ Ý luôn chị nhé!"},{"speaker":"client","text":"12 triệu à? Đắt quá, mình thấy bên khác bán rẻ hơn nhiều, có giảm giá được không?"},{"speaker":"salebot","text":"Dạ thưa chị, giá này đã là ưu đãi nhất rồi ạ. Chị có thể chọn màu sắc khác hoặc mua kèm phụ kiện để được giảm thêm 5% nha!"},{"speaker":"client","text":"Thế à... Mà mình chưa chắc chắn, để mình suy nghĩ thêm. Cảm ơn nhé!"}]','fail',673),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông cho bé gái 10 tuổi. Có size 12-13 không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập mẫu áo khoác ấm bằng vải chống nước, màu hồng và xanh dương. Size 12-13 vẫn còn 5 chiếc."},{"speaker":"client","text":"Mình thấy giá hơi cao, có thể giảm giá không? Mình mua luôn 2 cái."},{"speaker":"salebot","text":"Dạ, nếu bạn mua 2 chiếc thì mình giảm 10% cho mỗi chiếc nhé! Giá gốc 890k, giờ còn 800k/chiếc thôi."},{"speaker":"client","text":"Ok, vậy mình lấy luôn 2 chiếc màu hồng. Bao giờ giao được ạ?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ ạ, mình sẽ gửi link thanh toán qua Zalo ngay sau khi bạn xác nhận đơn."}]','successs',674),
('[{"speaker":"client","text":"Chào! Mình muốn mua chiếc áo khoác này, nhưng giá 1 triệu 5 có hơi đắt không nhỉ?"},{"speaker":"salebot","text":"Dạ áo khoác này chất liệu vải chống nước cao cấp, giá niêm yết là 1 triệu 8 nhưng hôm nay sale 20% còn 1 triệu 44 nhé!"},{"speaker":"client","text":"Ồ, giảm nhiều thế! Mình lấy size M thôi, có giao hàng tận nơi không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn để lại địa chỉ, mình gửi mã giảm thêm 5% cho đơn đầu tiên nha."},{"speaker":"client","text":"Ok, mình ghi địa chỉ rồi đây. Cảm ơn nhé!"}]','successs',675),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang khuyến mại 20% cho sản phẩm này, giá chỉ còn 1.990.000đ thôi ạ."},{"speaker":"client","text":"Ồ, vậy có tặng kèm hộp đựng không? Mình thấy trên web không rõ lắm."},{"speaker":"salebot","text":"Dạ có ạ, kèm theo hộp đựng và 1 đầu bàn chải thay thế luôn nha!"},{"speaker":"client","text":"Tốt quá, mình lấy luôn 1 cái. Ship trong ngày được không bạn?"},{"speaker":"salebot","text":"Dạ được ạ, mình sẽ xử lý đơn ngay bây giờ. Bạn để lại số điện thoại và địa chỉ nhé!"}]','successs',676),
