('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc túi xách da cao cấp của hãng Louis Vuitton, nhưng giá hơi cao so với túi mình hay dùng. Có giảm giá không?"},{"speaker":"salebot","text":"Chào chị! Túi LV này đang có chương trình khuyến mại 10% cho đơn hàng đầu tiên trong tháng chị ạ. Ngoài ra chị có thể chọn mua phiên bản cũ để tiết kiệm hơn 30% so với giá niêm yết."},{"speaker":"client","text":"Mình thích phiên bản cũ thôi. Liệu có bảo hành không? Và giao hàng trong bao lâu?"},{"speaker":"salebot","text":"Dạ có ạ! Phiên bản cũ được bảo hành 1 năm bởi đại lý ủy quyền. Giao hàng trong 3-5 ngày làm việc nếu chị ở TP.HCM. Chị có muốn đặt ngay không?"},{"speaker":"client","text":"Ok, mình chọn phiên bản cũ màu đen. Bao gồm hộp và giấy bảo hành đầy đủ chứ?"},{"speaker":"salebot","text":"Dạ tất nhiên rồi chị! Mọi thứ đều đầy đủ. Chị vui lòng cung cấp địa chỉ giao hàng và số điện thoại để mình xác nhận đơn hàng nhé."}]','successs',678),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua bàn ghế gỗ cho nhà mới. Có mẫu nào đẹp và bền không?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu bàn ghế gỗ óc chó nguyên khối vừa nhập về, 100% tự nhiên, chống mối mọt. Giá niêm yết 5 triệu, nay khuyến mại còn 4.2 triệu thôi ạ."},{"speaker":"client","text":"4.2 triệu à? Mà mình thấy trên mạng bán rẻ hơn, 3.8 triệu ấy."},{"speaker":"salebot","text":"Dạ, giá mình niêm yết đã ưu đãi lắm rồi ạ. Nếu bạn đặt luôn hôm nay, mình tặng thêm gối lưng ghế trị giá 300k nữa nè."},{"speaker":"client","text":"Thế à? Ok, mình chọn màu nâu nhạt đi. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao tận nhà trong 3 ngày ạ. Bạn để lại số điện thoại và địa chỉ, mình gửi mã vận đơn ngay!"}]','successs',679),
('[{"speaker":"client","text":"Chào shop! Mình thấy bộ quần áo thể thao này đẹp quá, nhưng giá 1 triệu rẻ quá nhỉ?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, sản phẩm này đang khuyến mại 50% nên giá đã là 1 triệu rồi ạ! Chất liệu vải co giãn tốt lắm ạ."},{"speaker":"client","text":"Thế à, nhưng mình thấy shop bên kia bán chỉ 800k thôi, không biết bên em có thể giảm nữa không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã là mức tốt nhất rồi ạ. Nếu bạn mua 2 sản phẩm trở lên thì giảm thêm 5% cho ạ!"},{"speaker":"client","text":"Ôi tiếc quá, mình chỉ cần 1 cái thôi. Thôi thôi, cảm ơn shop nhé!"}]','fail',680),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái bàn học thông minh này có vẻ hay. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Bàn thông minh này giá niêm yết 12 triệu, nhưng hôm nay có khuyến mại giảm còn 9,5 triệu thôi chị nhé!"},{"speaker":"client","text":"Ôi 9,5 triệu à? Đắt quá chị ơi, mình chỉ có 8 triệu thôi."},{"speaker":"salebot","text":"Dạ thôi chị thông cảm ạ, giá gốc đã rẻ lắm rồi. Chị có thể trả góp 0% trong 6 tháng cũng được ạ."},{"speaker":"client","text":"Thôi vậy mình không mua nữa. Cảm ơn nhé!"}]','fail',681),
('[{"speaker":"client","text":"Chào bot! Mình thấy cái bàn học gỗ sồi này đẹp quá, nhưng giá 5 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ em hiểu ạ, nhưng sản phẩm này làm từ gỗ sồi nguyên khối, bền 15 năm lận! Giảm còn 4.5 triệu cho bạn nhé?"},{"speaker":"client","text":"4.5 triệu vẫn hơi cao, mình thấy bên kia bán 4 triệu thôi. Có thể giảm nữa không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, đây là giá tốt nhất rồi ạ. Nếu bạn mua kèm ghế học nữa thì em giảm 200k nữa nhé?"},{"speaker":"client","text":"Thôi vậy, mình không cần ghế nữa. Cảm ơn bot nhé!"}]','fail',682),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này nhưng thấy giá hơi cao so với mong đợi. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ chào chị! Chiếc áo khoác này đang có chương trình khuyến mại 20% cho đơn hàng đầu tiên trong hôm nay. Nếu chị đặt ngay thì sẽ giảm thêm 10% nữa nha!"},{"speaker":"client","text":"Thế à? Vậy giá cuối cùng là bao nhiêu thế? Mình thấy 1 triệu 2 trông hơi đắt."},{"speaker":"salebot","text":"Dạ giá gốc 1 triệu 2, sau khi giảm 30% thì còn 840 ngàn chị nhé! Giao hàng miễn phí trong 24h nếu chị đặt trong hôm nay luôn."},{"speaker":"client","text":"Được thôi, mình lấy vậy. Bao giờ nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ chị đặt xong trong 5 phút nữa sẽ có nhân viên giao tới tận nơi ạ! Em gửi link thanh toán qua zalo cho chị nhé!"}]','successs',683),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác mùa đông này nhưng nhìn hơi đắt so với giá mình nghĩ. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, ạ! Hiện tại shop đang có chương trình khuyến mãi 10% cho đơn hàng trên 1 triệu, áo này giá niêm yết 990.000đ, ạ."},{"speaker":"client","text":"Mình thấy giá vẫn hơi cao, có thể giảm thêm không? Mình mua 2 áo thì sao?"},{"speaker":"salebot","text":"Dạ, nếu mua 2 áo ạ, shop có thể giảm thêm 5% nữa, thành 850.000đ/áo ạ. Đó là giá tốt nhất rồi ạ."},{"speaker":"client","text":"Thế không được nữa à? Mình chỉ mua 1 cái thôi, 800.000đ nhé?"},{"speaker":"salebot","text":"Dạ, ạ! Rất tiếc ạ, giá đã là ưu đãi nhất rồi ạ. Nếu không ưng, shop có thể giữ cho bạn 1 ngày để suy nghĩ ạ!"},{"speaker":"client","text":"Thôi được, mình bỏ qua vậy. Cảm ơn nhé!"}]','fail',684),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc đồng hồ Casio G-Shock GA-2100, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào anh chị! Đồng hồ Casio G-Shock GA-2100 hiện đang có giá 2.200.000đ ạ."},{"speaker":"client","text":"Ủa, trên web khác thấy nó có 2.000.000đ thôi mà?"},{"speaker":"salebot","text":"Dạ anh chị ơi, giá mình niêm yết trên web là 2.200.000đ ạ, nhưng nếu anh chị mua combo với dây da thì giảm còn 2.100.000đ nè."},{"speaker":"client","text":"Thế không giảm nữa à? Mình chỉ mua mỗi đồng hồ thôi."},{"speaker":"salebot","text":"Dạ anh chị thông cảm, mình không thể giảm thêm ạ. Nhưng giao hàng miễn phí trong 2h nếu anh chị ở nội thành nè!"},{"speaker":"client","text":"Thôi được, mình không mua nữa. Thanks!"}]','fail',685),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc đồng hồ thông minh Amazfit GTR 4, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại sản phẩm đang khuyến mại 15% cho đơn hàng đầu tiên, chỉ còn 3 ngày nữa thôi ạ!"},{"speaker":"client","text":"Ồ, thế giá gốc là bao nhiêu vậy? Mình muốn chắc chắn trước khi mua."},{"speaker":"salebot","text":"Dạ giá gốc 5.990.000đ, giờ còn 5.091.500đ ạ! Có kèm quà tặng là dây đeo da trị giá 200k nữa đó."},{"speaker":"client","text":"Hơi đắt so với dự tính, mình chỉ định 4 triệu thôi. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ không ạ, mức giá này đã là ưu đãi nhất rồi ạ. Nếu anh/chị mua thêm phụ kiện đi kèm thì có thể free ship thôi ạ!"},{"speaker":"client","text":"Thôi được, mình nghĩ lại vậy. Cảm ơn bot nhé!"}]','fail',686),
('[{"speaker":"client","text":"Chào shop! Mình đang quan tâm cái điện thoại Samsung Galaxy S23 Ultra 5G. Còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Còn hàng ạ, màu đen và xanh dương đều có sẵn. Bạn muốn mua không ạ?"},{"speaker":"client","text":"Mình thấy giá niêm yết 27 triệu, có giảm được không? Mình thấy bên kia bán 25 triệu thôi."},{"speaker":"salebot","text":"Dạ, shop mình đang có khuyến mại 5% cho đơn hàng đầu tiên hôm nay ạ. Thế là 25.65 triệu, bạn nhận luôn không ạ?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn đi. Ship nhanh không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ giao trong 2 giờ ạ! Bạn chọn màu nào vậy? Đen hay xanh dương ạ?"},{"speaker":"client","text":"Mình chọn màu đen nhé. Cảm ơn bạn nhiều!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn một ngày tốt lành. Đơn hàng của bạn sẽ được xác nhận trong vài phút nữa."}]','successs',687),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc máy xay sinh tố Philips HR1855, giá trên web hơi cao quá nhỉ?"},{"speaker":"salebot","text":"Dạ chào chị! Máy xay này đang khuyến mại 20% cho đơn hàng trong hôm nay, chị có thể nhận ngay ưu đãi này ạ."},{"speaker":"client","text":"Thế giá sau giảm có còn 1 triệu 5 không?"},{"speaker":"salebot","text":"Dạ đúng rồi chị! Giá gốc 1.875.000đ, sau giảm chỉ còn 1.500.000đ thôi ạ. Kèm quà tặng là cốc đo lường miễn phí."},{"speaker":"client","text":"Ok, vậy mình lấy luôn 1 cái. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ chị vui lòng để lại địa chỉ, mình sẽ giao trong 2 tiếng tới ạ. Cảm ơn chị đã mua sắm!"}]','successs',688),
