('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác thể thao Nike Air có màu xanh navy không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại áo khoác Nike Air màu xanh navy size S, M, L vẫn còn ạ. Chị muốn size nào ạ?"},{"speaker":"client","text":"Mình mặc size L, nhưng giá trên web hơi đắt, mình thấy bên kia bán 1 triệu rưỡi thôi. Bạn giảm được không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá 1.890.000đ là giá niêm yết của Nike ạ. Nhưng nếu chị mua ngay hôm nay, mình có thể giảm 5% cho chị, còn 1.795.500đ thôi ạ."},{"speaker":"client","text":"Cái 1 triệu rưỡi kia họ còn tặng kèm khăn lau nữa cơ. Mình thấy không xứng đáng đâu..."},{"speaker":"salebot","text":"Dạ em rất tiếc ạ. Nếu chị có nhu cầu, em có thể gửi link sản phẩm bên em để chị so sánh ạ. Chúc chị một ngày tốt lành!"}]','fail',717),
('[{"speaker":"client","text":"Chào shop, mình thấy bộ quần áo thể thao của các bạn trên web có ưu đãi không? Mình muốn mua 2 bộ nhưng giá hơi cao."},{"speaker":"salebot","text":"Dạ chào chị! Bên em đang có chương trình giảm 15% cho đơn từ 2 sản phẩm trở lên đó ạ. Nếu chị mua 2 bộ thì được tặng kèm 1 đôi tất thể thao luôn."},{"speaker":"client","text":"Vậy giá cuối cùng 2 bộ là bao nhiêu? Mình chỉ có 800k thôi."},{"speaker":"salebot","text":"Dạ giá niêm yết mỗi bộ 500k, sau giảm còn 425k x 2 = 850k. Nếu chị thêm 50k nữa là em giao tận nơi luôn chị nhé!"},{"speaker":"client","text":"Thôi được, mình chuyển khoản sau nhé. Nhưng nhớ giao kèm quà nha!"},{"speaker":"salebot","text":"Dạ em nhớ rồi ạ! Chị vui lòng cung cấp địa chỉ và sđt để em xác nhận đơn hàng nhé."}]','fail',718),
('[{"speaker":"client","text":"Chào em, mình muốn mua chiếc áo khoác dạ nữ hiệu Burberry có sẵn size M không vậy?"},{"speaker":"salebot","text":"Dạ chào chị, em xin lỗi chị ạ, size M của mẫu áo khoác dạ Burberry vừa bán hết rồi chị ơi. Chị có thể chọn size L hoặc S không ạ?"},{"speaker":"client","text":"Ơ, tiếc quá. Size L thì hơi rộng mình, thế còn size S thì sao?"},{"speaker":"salebot","text":"Dạ size S chị vẫn còn 2 chiếc nè, nhưng mẫu này hết size M nên chị có thể chọn size S hoặc chờ size M về mới giao chị nhé?"},{"speaker":"client","text":"Thế size S giá bao nhiêu vậy? Có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ size S chị là 12.990.000đ, chị có thể dùng mã giảm giá ''BURBERRY20'' để được giảm 20% nữa chị nhé!"},{"speaker":"client","text":"12 triệu rưỡi à, hơi đắt quá. Mình chỉ định giá dưới 10 triệu thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi chị, size S không giảm thêm được nữa ạ. Chị có thể tham khảo mẫu khác của Burberry giá 9.500.000đ không ạ?"},{"speaker":"client","text":"Thôi được, mình không mua nữa. Cảm ơn em nhé!"}]','fail',719),
('[{"speaker":"client","text":"Chào shop! Mình nhìn thấy bộ đồ lặn thể thao của hãng Decathlon, size L có không vậy? Mình cao 1m85, nặng 75kg ấy."},{"speaker":"salebot","text":"Dạ chào anh! Size L vẫn còn ạ, nhưng màu xanh dương và đen thôi ạ. Anh muốn giao trong ngày không?"},{"speaker":"client","text":"Hơi tiếc là không có màu mình thích. Còn size XL không? Mình thấy chật thì khó chịu lắm."},{"speaker":"salebot","text":"Dạ size XL hết rồi ạ, nhưng mình gửi link sản phẩm tương tự của hãng khác có size rộng hơn cho anh xem nhé?"},{"speaker":"client","text":"Thôi được, gửi đi. Nhưng giá có đắt không? Mình thấy đồ Decathlon rẻ mà."},{"speaker":"salebot","text":"Dạ sản phẩm thay thế tầm 1,2 triệu, rẻ hơn 200k so với đồ Decathlon ạ. Anh có muốn mình giảm thêm không?"},{"speaker":"client","text":"1,2 triệu à? Mình thấy trên web thấy đồ khác giá 900k thôi. Thôi để mình suy nghĩ lại rồi nhé."}]','fail',720),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao cho bé nhà mình, khoảng 5 tuổi. Bé trai lắm, hay chạy nhảy nên cần thoáng mát. Bạn có loại nào không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Chúng em có bộ quần áo thể thao cho bé trai 5 tuổi, chất liệu cotton thoáng mát, giá 299k/bộ. Màu xanh dương, đỏ, đen đều có ạ!"},{"speaker":"client","text":"Hơi đắt nhỉ, mình thấy trên shopee có bộ tương tự 250k thôi. Bạn giảm được không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, mình bán chính hãng nên giá hơi cao chút. Nếu anh/chị mua 2 bộ trở lên, em giảm còn 270k/bộ nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy 2 bộ luôn. Giao trong hôm nay được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ gửi đơn ngay. Anh/chị để lại số điện thoại và địa chỉ chi tiết nhé ạ!"}]','successs',721),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S24 Ultra. Mình thấy trên web có khuyến mãi không thế?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại Galaxy S24 Ultra đang giảm 5 triệu, giao hàng miễn phí trong 24h nếu anh/chị đặt trong hôm nay ạ!"},{"speaker":"client","text":"Ồ, vậy giá cuối là bao nhiêu thế? Mình thấy bên shop khác giá thấp hơn 1 chút."},{"speaker":"salebot","text":"Dạ anh/chị ơi, giá gốc 32 triệu nhưng giảm còn 27 triệu thôi ạ! Còn nếu anh/chị mua kèm ốp lưng chính hãng tặng kèm thì chỉ 28 triệu thôi ạ!"},{"speaker":"client","text":"Thế nếu mình lấy luôn gói bảo hành 2 năm thì sao? Bao nhiêu tiền?"},{"speaker":"salebot","text":"Dạ gói bảo hành 2 năm thêm 1 triệu, tổng cộng 29 triệu ạ! Anh/chị có muốn mình gửi link đặt hàng luôn không ạ?"},{"speaker":"client","text":"Ok, mình lấy luôn đi. Ship nhanh nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn anh/chị đã mua hàng! Đơn hàng sẽ giao trong 2h tới ạ. Chúc anh/chị ngày mới vui vẻ!"}]','successs',722),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Bàn chải điện Oral-B Pro 3000 hiện đang khuyến mại 2.499.000đ (giá gốc 3.200.000đ). Bạn có muốn đặt luôn không ạ?"},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm nữa không? Mình thấy shop khác bán 2.200.000đ."},{"speaker":"salebot","text":"Dạ shop mình không thể giảm thấp hơn vì đã áp dụng khuyến mại sớm nhất. Nhưng nếu bạn đặt trong 2 giờ nữa sẽ được tặng kèm 1 hộp kem đánh răng trị giá 199.000đ ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy 1 cái. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Địa chỉ giao hàng là gì vậy bạn? Chúng tôi sẽ giao trong 2-4 tiếng nếu bạn ở TP.HCM."}]','successs',723),
('[{"speaker":"client","text":"Chào shop, mình thấy cái bàn chải điện Oral-B Pro 3 3000 có giảm giá không vậy? Mình đang cân nhắc mua."},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện tại sản phẩm đang giảm 20% còn 1.200.000đ thôi ạ. Bạn có muốn mình check mã giảm giá thêm không?"},{"speaker":"client","text":"Ồ, thế à? Mà mình thấy giá bên shop khác rẻ hơn 50k kìa, có thể giảm nữa không?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, mức giá này đã là ưu đãi nhất rồi ạ. Bù lại giao hàng miễn phí trong 2h và bảo hành 2 năm luôn nha bạn!"},{"speaker":"client","text":"Thôi cũng được, mình order thôi. Nhưng giao trong 1h được không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ không ạ, tối đa 2h thôi ạ. Bạn có thể chọn giờ giao từ 10h sáng tới 8h tối nha."},{"speaker":"client","text":"À vậy thì thôi, mình để mai vậy. Cảm ơn nhé!"}]','fail',724),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác North Face màu xanh navy cỡ XL, có sẵn không vậy?"},{"speaker":"salebot","text":"Dạ chào anh! Áo khoác North Face màu navy cỡ XL còn 2 cái ạ. Anh muốn xem ảnh chi tiết hay đặt luôn ạ?"},{"speaker":"client","text":"Cho mình xem ảnh trước nhé, mình sợ size không vừa."},{"speaker":"salebot","text":"Dạ anh vui lòng chờ 1 chút, mình gửi ảnh sản phẩm qua nhé! (ảnh gửi kèm). Ngoài ra, sản phẩm này đang giảm 15% nên giá chỉ còn 2.390.000đ thôi ạ."},{"speaker":"client","text":"Ơ hay, mình thấy trên Shopee giá còn 2.190.000đ kìa, sao web mình lại đắt thế?"},{"speaker":"salebot","text":"Dạ anh thông cảm, đây là giá sỉ nên hơi cao hơn 1 chút. Nhưng anh mua 1 lần 2 cái thì mình giảm thêm 5% nữa nhé, chỉ còn 2.270.500đ/cái thôi ạ!"},{"speaker":"client","text":"Thôi được, mình lấy 1 cái vậy. Địa chỉ giao là 123 Lê Lợi, Phường Bến Thành, Quận 1 nhé."},{"speaker":"salebot","text":"Dạ cảm ơn anh! Đơn hàng đã được xác nhận, phí ship nội thành 30.000đ ạ. Anh vui lòng thanh toán trước 50% để xác nhận đơn nhé!"}]','successs',725),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại tầm trung. Có sản phẩm nào vừa chất vừa giá hợp lý không?"},{"speaker":"salebot","text":"Dạ, mình giới thiệu bạn chiếc Xiaomi Redmi Note 12 Pro 5G ạ! Cấu hình mạnh, màn hình 120Hz, giá chỉ 7 triệu thôi."},{"speaker":"client","text":"7 triệu hơi đắt, mình thấy trên Shopee có giá 6.5 triệu. Bạn có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ, mình xin lỗi ạ! Để mình kiểm tra lại, nếu bạn mua ngay hôm nay thì mình giảm xuống 6.8 triệu nha."},{"speaker":"client","text":"Ok, mình nhận 6.8 triệu. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng cung cấp địa chỉ và số điện thoại để mình xử lý đơn hàng nha."}]','successs',726),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc bàn học cho con gái, cháu sắp vào lớp 1. Bạn có loại nào phù hợp không?"},{"speaker":"salebot","text":"Dạ có ạ! Em giới thiệu bàn học thông minh chống cận cho bé 6-12 tuổi, giá 1.890.000đ, có chống cận và chống lóa màn hình."},{"speaker":"client","text":"Ồ, nghe hay đấy. Nhưng mình đang có ngân sách 1.500.000đ thôi. Bạn giảm giá được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi, sản phẩm này không giảm giá được nữa ạ. Nhưng nếu bạn mua kèm ghế học sinh 590.000đ thì giảm còn 1.990.000đ thôi!"},{"speaker":"client","text":"Thế à... mình suy nghĩ lại nhé. Cảm ơn bạn!"}]','fail',727),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn học gỗ sồi của shop khá đẹp. Mấy tiền thế?"},{"speaker":"salebot","text":"Dạ chào anh! Bàn gỗ sồi tầm 2.8 triệu ạ, giao tận nơi miễn phí nếu trên 2 triệu nha."},{"speaker":"client","text":"Ôi đắt quá, mình thấy bên kia bán có 2.5 triệu thôi, sao shop không giảm được chút?"},{"speaker":"salebot","text":"Dạ anh thông cảm ạ, giá chúng em đã ưu đãi lắm rồi ạ. Nếu anh mua kèm ghế gỗ thì giảm còn 2.6 triệu nha."},{"speaker":"client","text":"Thôi thôi, mình nghĩ lại rồi. Cảm ơn bot nha!"}]','fail',728),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G. Bạn có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu đen và xanh lá đều có sẵn. Bạn muốn giao hàng trong ngày hay nhận tại cửa hàng?"},{"speaker":"client","text":"Mình ở xa nên giao hàng tận nơi được không? Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ giao tận nơi ạ, phí ship 20k nếu trên 500k. Giá niêm yết 28.990.000đ, nhưng hôm nay có ưu đãi giảm 1 triệu cho khách hàng mới."},{"speaker":"client","text":"Giảm nhiều thế, vậy mình lấy luôn chiếc đen nhé. Thanh toán bằng tiền mặt hay chuyển khoản?"},{"speaker":"salebot","text":"Dạ chọn thanh toán tiền mặt ạ! Địa chỉ nhận hàng và số điện thoại để mình xác nhận đơn hàng nhé?"}]','successs',729),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm bàn phím cơ cho gaming. Mình nghe nói Keychron K8 khá ngon, nhưng giá trên web hơi cao. Bạn có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Keychron K8 hiện đang bán 2.299.000đ, nhưng nếu anh/chị đặt hàng trong hôm nay thì mình sẽ giảm 5% cho 5 khách đầu tiên ạ."},{"speaker":"client","text":"5% thôi à? Mình thấy trên Shopee giá còn 2.199.000đ kia kìa. Bạn có thể bằng giá đó không?"},{"speaker":"salebot","text":"Dạ không ạ, giá của mình đã là ưu đãi nhất rồi ạ. Nếu anh/chị không ưng thì mình xin lỗi ạ."},{"speaker":"client","text":"Thế thôi, cảm ơn bạn. Mình sẽ nghĩ lại."}]','fail',730),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc bàn phím cơ cơ, nhưng ngại đi ra ngoài lắm. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào bạn! Mình có bàn phím cơ Keychron K8 với switch Brown, giá 2.200.000đ, giao tận nhà trong 3 ngày. Bạn thích màu nào ạ?"},{"speaker":"client","text":"Màu xám xịn ấy, nhưng giá hơi cao. Có giảm được không?"},{"speaker":"salebot","text":"Dạ, mình có thể giảm còn 2.000.000đ nếu bạn mua kèm mousepad 100k. Còn 10 cái cuối cùng thôi!"},{"speaker":"client","text":"Thôi, mình không cần mousepad đâu. Giá 1.900.000đ được không?"},{"speaker":"salebot","text":"Dạ, mình xin lỗi ạ, giá đã là ưu đãi nhất rồi. Bạn có thể tham khảo sản phẩm khác không?"},{"speaker":"client","text":"Thôi vậy, mình nghĩ lại rồi. Cảm ơn bạn nhé!"}]','fail',731),
('[{"speaker":"client","text":"Chào bạn, mình đang muốn mua chiếc áo khoác này nhưng thấy giá hơi cao so với túi tiền của mình. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng mình đang có chương trình khuyến mại 10% cho sản phẩm này nếu chị mua trong hôm nay. Có thể áp dụng luôn ạ!"},{"speaker":"client","text":"10% thôi à? Mình thấy bên kia bán rẻ hơn 200k cơ. Có thể giảm thêm được không?"},{"speaker":"salebot","text":"Dạ em xin lỗi chị ạ, mức giá này đã là ưu đãi nhất rồi ạ. Nếu chị mua kèm phụ kiện như găng tay chống lạnh thì em có thể giảm thêm 5% nữa."},{"speaker":"client","text":"Thế à... mình suy nghĩ lại vậy. Cảm ơn bạn nhé!"}]','fail',732),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G, nhưng giá hơi cao so với túi tiền của mình. Có ưu đãi gì không ạ?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Em có thông tin ưu đãi 10% cho đơn hàng đầu tiên trong hôm nay nếu chị thanh toán bằng thẻ ngân hàng liên kết. Ngoài ra, giao hàng miễn phí trong 24h cho đơn trên 20 triệu."},{"speaker":"client","text":"Mình chỉ có 15 triệu thôi, vậy có giảm giá sâu hơn không? Mình thấy bên kia bán rẻ hơn 2 triệu đó."},{"speaker":"salebot","text":"Dạ em xin lỗi chị ạ, mức giá này là ưu đãi tối đa rồi ạ. Chị có thể chọn phiên bản cũ hơn là Galaxy S22 Ultra để tiết kiệm 5 triệu, giao hàng ngay hôm nay."},{"speaker":"client","text":"Thế ạ, vậy thôi. Cảm ơn bạn nhé, mình suy nghĩ lại đã."}]','fail',733),
