('[{"speaker":"client","text":"Chào bạn, mình thấy trên web có bàn ghế gỗ óc chó này, giá 5 triệu rẻ quá nhỉ?"},{"speaker":"salebot","text":"Dạ thưa anh, sản phẩm 100% gỗ óc chó nhập khẩu, giá gốc 6.5 triệu nhưng hôm nay sale 20% nên 5.2 triệu thôi ạ!"},{"speaker":"client","text":"Thế có thể giảm nữa không? 5 triệu chắc chắn được không?"},{"speaker":"salebot","text":"Dạ anh thông cảm, 5 triệu hơi thấp quá ạ. Nếu anh mua combo ghế + bàn kèm 2 ghế phụ thì em giảm còn 5.5 triệu trọn bộ ạ!"},{"speaker":"client","text":"Ok, thế giao hàng trong ngày được không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Em check kho ngay bây giờ, giao trong 2-3 tiếng thôi ạ. Anh để lại số điện thoại để em xác nhận đơn hàng nhé?"}]','successs',748),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác thể thao này của Nike, nhưng nhìn size chart hơi khó hiểu. Bạn giải thích giúp mình được không?"},{"speaker":"salebot","text":"Dạ chào bạn! Size S thường dành cho người nhẹ cân dưới 55kg, M là 55-65kg, L là 65-75kg. Bạn cân nặng bao nhiêu để mình tư vấn chính xác hơn nha!"},{"speaker":"client","text":"Mình 62kg, vậy size M có vừa không? Giá mình thấy hơi cao, có giảm giá không?"},{"speaker":"salebot","text":"Size M rất vừa cho bạn ạ! Hiện tại shop đang có khuyến mại 10% cho sản phẩm này trong hôm nay. Giá gốc 2.990.000đ, giờ chỉ còn 2.690.000đ thôi!"},{"speaker":"client","text":"Hay quá! Mình lấy luôn. Đóng gói cẩn thận giúp mình nhé, mình sợ hỏng."},{"speaker":"salebot","text":"Dạ chắc chắn ạ! Mình sẽ bọc màng chống sốc và gửi qua GHTK an toàn. Bạn để lại số điện thoại để shop gửi tracking nha!"}]','successs',749),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc bàn chải điện Philips Sonicare DiamondClean, nhưng không biết có giảm giá gì không thế?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại bàn chải này đang có chương trình khuyến mại 20% cho đơn hàng từ 2 triệu, chị có muốn mình hỗ trợ đặt hàng luôn không?"},{"speaker":"client","text":"À thế à? Mình thấy giá niêm yết 3.5 triệu, vậy mình mua 1 cái thì giá bao nhiêu?"},{"speaker":"salebot","text":"Dạ chị mua 1 cái thì giá sau giảm là 2.8 triệu chị nhé! Giao hàng miễn phí trong 2 giờ nếu chị ở TPHCM."},{"speaker":"client","text":"Ok, mình lấy luôn nhé. Địa chỉ giao là 123 Nguyễn Trãi, Quận 5, TPHCM. Cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc chị ngày mới vui vẻ. Đơn hàng của chị sẽ được giao trong 1-2 giờ tới. Cảm ơn chị đã mua sắm cùng shop!"}]','successs',750),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn làm việc gỗ óc chó này. Giá có thể giảm được không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chiếc bàn này đang có giá 3.500.000đ, chị có thẻ thành viên shop thì sẽ được giảm 5% luôn đó ạ."},{"speaker":"client","text":"Thế nếu mình mua kèm cái ghế văn phòng 1.200.000đ nữa thì sao?"},{"speaker":"salebot","text":"Dạ nếu chị mua combo thì em sẽ giảm thêm 10% cho cả bộ ạ! Thành 4.400.000đ thôi ạ. Giao miễn phí trong 2 giờ nếu chị ở nội thành."},{"speaker":"client","text":"Ok, mình lấy vậy. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ em xác nhận đơn hàng rồi ạ! Chị check mail để nhận mã vận đơn nhé. Cảm ơn chị đã ủng hộ shop!"}]','successs',751),
('[{"speaker":"client","text":"Chào em, mình đang tìm mua chiếc túi xách da này. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Túi da này hiện đang giảm giá 30%, còn 1.200.000đ thôi ạ."},{"speaker":"client","text":"Ôi vậy có được giảm thêm không? Mình thấy bên kia bán 900k thôi ấy..."},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá đã là ưu đãi nhất rồi ạ. Chị có thể chọn màu nâu hoặc đen ạ."},{"speaker":"client","text":"Thế à... Thế giao hàng có nhanh không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày ạ, nếu chị ở TPHCM thì giao trong ngày luôn ạ. Nhưng em xin lỗi chị, giá không thể giảm thêm rồi ạ."},{"speaker":"client","text":"Ừm... thôi vậy. Mình cân nhắc đã. Cảm ơn em nhé!"}]','fail',752),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc váy sơ mi trắng size M của shop. Còn hàng không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Vâng, váy sơ mi trắng size M còn 5 cái nè. Bạn muốn mua không?"},{"speaker":"client","text":"Mình thấy giá 599k hơi đắt, có giảm giá không? Mình thấy chỗ khác bán 450k thôi."},{"speaker":"salebot","text":"Dạ shop mình có khuyến mại 10% nếu bạn mua kèm giày ạ, tổng thành 539k. Hay bạn lấy luôn combo?"},{"speaker":"client","text":"Ok, mình lấy váy thôi. Ship bao lâu nhận được?"},{"speaker":"salebot","text":"Dạ ship nội thành 2-3 ngày, ngoại thành 5-7 ngày ạ. Bạn có thể chọn giao hôm nay không?"},{"speaker":"client","text":"Được, mình chọn giao hôm nay. Địa chỉ là 123 Lê Lợi, Q1, TP.HCM. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Tổng tiền 539k, shop sẽ gửi mã tracking qua Zalo ngay. Cảm ơn bạn đã mua sắm!"}]','successs',753),
('[{"speaker":"client","text":"Chào shop, mình đang tìm mua một chiếc điện thoại tầm trung mới. Có sản phẩm nào hay không?"},{"speaker":"salebot","text":"Dạ có ạ! Em giới thiệu chiếc Xiaomi Redmi Note 12 vừa ra mắt, cấu hình khủng, giá chỉ 4.990.000đ thôi!"},{"speaker":"client","text":"Ôi, 5 triệu hơi cao với mình. Có giảm giá không? Mình thấy trên shopee nó rẻ hơn kìa."},{"speaker":"salebot","text":"Dạ em có thể giảm 100k cho bạn nếu đặt hàng ngay trong hôm nay ạ! Còn kèm theo quà tặng là ốp lưng chống sốc nữa đó."},{"speaker":"client","text":"Thế à? Được thôi, mình lấy luôn đi. Bao lâu ship tới?"},{"speaker":"salebot","text":"Dạ giao tận nơi trong 2 tiếng ạ! Bạn để lại địa chỉ và số điện thoại để em xác nhận đơn hàng nha."}]','successs',754),
