('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc bàn phím cơ cho công việc. Bàn phím nào tốt nhất cho lập trình vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em khuyên dùng bàn phím Keychron K8, có switch Blue bền, gõ êm và phù hợp lập trình lắm ạ. Giá 1.890.000đ thôi ạ."},{"speaker":"client","text":"1.890k hơi đắt, có giảm giá không? Mình thấy bên khác bán 1.6tr thôi."},{"speaker":"salebot","text":"Dạ em có thể giảm còn 1.750.000đ ạ, nếu anh/chị mua kèm chuột không dây Logitech thì chỉ 1.950.000đ cả đôi ạ!"},{"speaker":"client","text":"Ok, mình lấy bàn phím thôi. Ship trong ngày được không? Giao đến 38 Võ Văn Tần, Q3."},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị vui lòng chuyển khoản trước 50% để shop xác nhận đơn ạ. Cảm ơn anh/chị đã mua hàng!"}]','successs',767),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua một chiếc túi xách da thật cho vợ. Giá tầm 2-3 triệu thôi, có không?"},{"speaker":"salebot","text":"Dạ có ạ! Em có túi da thật từ Ý giá 2.5 triệu, chất liệu da bò nguyên miếng, sang trọng lắm ạ."},{"speaker":"client","text":"2.5 triệu hơi đắt nhỉ, có giảm giá không? Em thấy trên mạng rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ em có voucher 5% cho khách mua online hôm nay, còn 2.375 triệu thôi ạ. Đi kèm quà tặng là hộp đựng da và khăn lau."},{"speaker":"client","text":"Ok, vậy mình lấy 1 cái màu nâu đậm. Giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Em gửi link thanh toán qua Zalo cho bạn nhé. Cảm ơn bạn đã mua sắm cùng shop!"}]','successs',768),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn học gỗ óc chó này đẹp quá, nhưng giá 4.5 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ thưa anh, sản phẩm này được làm từ gỗ óc chó nguyên khối 100% nhập khẩu, bền theo năm tháng lắm ạ. Em có thể giảm nhẹ còn 4.2 triệu nếu anh lấy luôn hôm nay nhé?"},{"speaker":"client","text":"Ok, mình lấy vậy. Ship tận nơi miễn phí chứ? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ có ạ! Ship miễn phí trong bán kính 10km, anh cứ yên tâm nhé. Đơn hàng sẽ giao trong 2-3 ngày làm việc. Anh vui lòng để lại số điện thoại và địa chỉ chi tiết ạ!"}]','successs',769),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc áo khoác da của shop. Mẫu màu đen có size M không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size M màu đen vẫn còn 3 chiếc. Bạn muốn mình gửi ảnh chi tiết hơn không?"},{"speaker":"client","text":"Ok, mình xem rồi. Giá niêm yết 2.500.000đ, có giảm giá không nhỉ?"},{"speaker":"salebot","text":"Dạ em có thể giảm 5% cho bạn nếu thanh toán bằng ví MoMo ạ. Còn 2.375.000đ thôi!"},{"speaker":"client","text":"Tuyệt vời! Mình chọn màu đen size M nhé. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2h nếu bạn ở TP.HCM, phí ship 20k ạ. Bạn xác nhận địa chỉ nhé!"}]','successs',770),
('[{"speaker":"client","text":"Chào bạn, mình thấy cái điện thoại Samsung Galaxy S24 Ultra có khuyến mãi không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại đang giảm 10% cho đơn hàng đầu tiên, giao hàng miễn phí trong 24h nếu bạn ở TPHCM."},{"speaker":"client","text":"10% thôi à? Mà mình thấy giá trên web nó hơi cao so với bên khác. Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ, mình có thể giảm thêm 3% nữa nếu bạn thanh toán bằng thẻ ngân hàng của chúng tôi ạ."},{"speaker":"client","text":"Ok, vậy thì mình chọn màu đen nhé. Địa chỉ giao là 123 Lê Lợi, Q1, TPHCM."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng của bạn đã được xác nhận, sẽ giao trong ngày hôm nay ạ."}]','successs',771),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ Casio Edifice cho sinh nhật vợ. Có mẫu EFR-S567D-1A2V không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu đó đang khuyến mại 20% trong tuần này, giá chỉ còn 3.200.000đ thay vì 4.000.000đ. Bạn muốn giao trong ngày không?"},{"speaker":"client","text":"Vậy giao trong ngày được không? Mình cần kịp sinh nhật vợ vào tối nay."},{"speaker":"salebot","text":"Dạ được ạ! Nếu bạn đặt trước 15h thì giao ngay trong buổi tối. Bạn chọn địa chỉ nào vậy ạ?"},{"speaker":"client","text":"Mình ở quận 10, địa chỉ 123 Lê Hồng Phong. Có thể giao sau 17h không?"},{"speaker":"salebot","text":"Dạ ổn ạ! Tổng tiền sau khuyến mại là 3.200.000đ, phí giao hàng nội thành 20.000đ. Bạn thanh toán COD hay chuyển khoản ạ?"},{"speaker":"client","text":"COD tiện hơn, cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Đơn hàng #EF12345 của bạn sẽ giao vào 18h30. Cảm ơn đã ủng hộ shop ạ!"}]','successs',772),
('[{"speaker":"client","text":"Chào anh, em thấy cái điện thoại Samsung Galaxy S24 Ultra có khuyến mãi gì không? Giá niêm yết hơi cao so với em."},{"speaker":"salebot","text":"Dạ chào chị, ạ! Hiện tại bên em đang có chương trình tặng kèm tai nghe AirPods Pro 2 trị giá 5 triệu khi mua S24 Ultra ạ. Chỉ cần thanh toán qua thẻ tín dụng của 1 số ngân hàng partner là được ạ!"},{"speaker":"client","text":"Thế giá cuối cùng là bao nhiêu vậy? Em thấy bên kia bán rẻ hơn 5 triệu luôn ấy."},{"speaker":"salebot","text":"Dạ chị ạ, do chương trình tặng kèm nên giá chỉ còn 29.990.000đ thôi ạ, rẻ hơn 1 triệu so với niêm yết. Nếu chị mua kèm ốp lưng và dán màn hình thì em có thể giảm thêm 200k nữa cho chị ạ!"},{"speaker":"client","text":"Ok, em chọn màu đen, ship trong ngày được không? Em ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Em chuẩn bị hàng luôn, giao trong 2 tiếng nữa là tới chị ạ. Thanh toán online hay COD chị ạ?"}]','successs',773),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái bàn học gỗ thông 4 chân này có giá 2 triệu rưỡi. Cậu có thể giảm cho mình không? Mình thấy trên Shopee nó rẻ hơn 100k đấy."},{"speaker":"salebot","text":"Dạ anh thông cảm ạ, giá niêm yết của bên em là 2 triệu 7 trăm, nhưng nếu anh mua luôn 2 sản phẩm trở lên thì em giảm còn 2 triệu 5 ạ!"},{"speaker":"client","text":"Thế à? Mà mình chỉ cần cái này thôi, không mua thêm đâu. Không giảm nữa à?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, đây là giá tốt nhất rồi ạ. Nếu anh quan tâm sản phẩm khác, em có thể tư vấn thêm ạ!"},{"speaker":"client","text":"Thôi được, mình bỏ qua vậy. Cảm ơn nhé!"}]','fail',774),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc máy xay sinh tố Philips HR1861/00. Có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện sản phẩm đang được giảm 20% từ 1.990.000đ xuống còn 1.590.000đ thôi ạ. Còn kèm quà tặng là cốc đựng sinh tố nha."},{"speaker":"client","text":"Ồ, vậy giao hàng trong bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày làm việc ạ. Nếu bạn ở TP.HCM thì có thể giao nhanh trong 1 ngày luôn nè."},{"speaker":"client","text":"Ok, mình đặt luôn vậy. Có thể thanh toán COD không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn vui lòng cung cấp địa chỉ giao hàng và số điện thoại để mình xác nhận đơn hàng nha."}]','successs',775),
('[{"speaker":"client","text":"Alo, mình thấy cái điện thoại Samsung Galaxy S24 Ultra trên trang này, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ còn ạ! Màu đen và xanh lá đều sẵn, giao trong 2 giờ nếu bạn ở TP.HCM."},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ có ạ! Nếu bạn mua trả góp 0% trong 6 tháng, giảm ngay 500k. Hoặc nếu thanh toán bằng VNPay, giảm thêm 200k nữa."},{"speaker":"client","text":"Thế trả góp 0% có phải đăng ký thẻ tín dụng không?"},{"speaker":"salebot","text":"Dạ không ạ! Bạn chỉ cần CMND/CCCD và số điện thoại đăng ký là được ạ."},{"speaker":"client","text":"Ok, mình chọn màu đen, giao đến 567 Lê Hồng Phong, Q.10, TP.HCM. Bao lâu nhận được?"},{"speaker":"salebot","text":"Dạ giao trong 1 tiếng ạ! Bạn vui lòng để ý điện thoại, shipper sẽ gọi trước khi giao. Cảm ơn bạn đã mua sắm ạ!"}]','successs',776),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc đồng hồ Casio G-Shock GA-2100-1A1 khá đẹp. Bao lâu nữa thì có hàng vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Hiện tại sản phẩm còn 2 chiếc cuối kho, giao hàng dự kiến vào ngày mai."},{"speaker":"client","text":"Mình thấy giá hơi cao so với quảng cáo trên web, có thể giảm được không?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 2.990.000đ, nhưng nếu bạn mua kèm dây da tặng thì giảm còn 2.790.000đ thôi ạ."},{"speaker":"client","text":"Thôi được, nhưng giao tận nơi và bảo hành đủ 2 năm nhé."},{"speaker":"salebot","text":"Dạ không ạ, chúng tôi chỉ bảo hành 1 năm thôi. Còn giao hàng tận nơi thì miễn phí trong bán kính 5km thôi ạ."},{"speaker":"client","text":"Vậy thôi, mình không mua nữa. Cảm ơn nhé!"}]','fail',777),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G. Mình thấy giá trên web là 25 triệu, có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn! Chúng tôi có khuyến mại 1 triệu cho đơn hàng trong hôm nay, nhưng chỉ còn 3 chiếc cuối thôi ạ."},{"speaker":"client","text":"Thế à? Mình chỉ có 24 triệu thôi, giảm thêm được không?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, giá đã là ưu đãi nhất rồi. Nếu bạn để lại số điện thoại, mình sẽ báo lại nếu có chương trình khác."},{"speaker":"client","text":"Thôi được, mình để lại số 0987654321. Cảm ơn nhé!"}]','fail',778),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm một chiếc áo khoác mùa đông cho bé trai 5 tuổi. Bên mình có size 6-7 tuổi không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Size 6-7 tuổi bên mình vừa hết hàng thưa anh/chị. Chúng mình có size 5-6 tuổi và 8-9 tuổi, anh/chị xem qua có phù hợp không ạ?"},{"speaker":"client","text":"Ừm, size 5-6 tuổi thì hơi nhỏ rồi. Thế size 8-9 tuổi thì giá bao nhiêu vậy? Mình thấy hơi đắt so với mức mình định chi thôi."},{"speaker":"salebot","text":"Dạ size 8-9 tuổi giá 499.000đ, ạ. Hiện bên mình đang có chương trình giảm 10% cho đơn hàng đầu tiên, nên còn 449.000đ thôi ạ!"},{"speaker":"client","text":"449k vẫn hơi cao so với mình. Có thể giảm thêm không? Mình thấy bên kia bán 420k cơ."},{"speaker":"salebot","text":"Dạ em xin lỗi, ạ! Đó là giá niêm yết rồi ạ. Nếu anh/chị mua 2 sản phẩm trở lên thì em có thể giảm thêm 5% cho anh/chị nhé!"},{"speaker":"client","text":"Thôi được, mình lấy 1 cái vậy. Nhưng giao hàng trong 2 ngày được không? Mình cần gấp."},{"speaker":"salebot","text":"Dạ không ạ, em xin lỗi anh/chị. Hiện giao hàng trong ngày chỉ áp dụng cho nội thành Hà Nội thôi ạ. Nếu anh/chị ở tỉnh khác thì mất 3-5 ngày ạ."},{"speaker":"client","text":"Vậy thôi, mình không mua nữa. Cảm ơn bạn!"}]','fail',779),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác này nhưng không biết size nào phù hợp nhỉ? Size M hay L nhỉ?"},{"speaker":"salebot","text":"Dạ chào bạn! Size M phù hợp với bạn nhất nếu bạn có chiều cao 1m65-1m70, còn size L thì rộng hơn 2cm ạ."},{"speaker":"client","text":"Vậy mình chọn size M nhé. Giá bao nhiêu thế? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ giá gốc 1.290.000đ, hôm nay mình giảm còn 990.000đ thôi ạ! Có kèm quà tặng là mũ len nếu mua trong hôm nay."},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Ship tận nơi chứ? Bao lâu nhận được?"},{"speaker":"salebot","text":"Dạ có ạ! Ship tận nơi trong 2-3 ngày, phí ship 30k nếu dưới 500k ạ. Bạn xác nhận địa chỉ nhận hàng nhé?"}]','successs',780),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác nữ này. Size S còn không ạ? Mình thấy nó khá đẹp nhưng không biết chất liệu thế nào."},{"speaker":"salebot","text":"Dạ chào bạn ạ! Size S vẫn còn ạ, chất liệu vải cotton pha polyester siêu thoáng mát, phù hợp mùa đông lẫn xuân thu đó bạn."},{"speaker":"client","text":"Vậy giá bao nhiêu thế? Mình thấy hơi đắt so với giá mình nghĩ."},{"speaker":"salebot","text":"Dạ giá niêm yết 1.990.000đ, nhưng bây giờ đang sale 15% nên còn 1.690.000đ thôi ạ. Nếu bạn mua 2 cái thì free ship luôn đó."},{"speaker":"client","text":"1.690k vẫn hơi cao so với ngân sách của mình. Bạn có thể giảm thêm không? Mình chỉ trả 1.4 triệu thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã là ưu đãi nhất rồi ạ. Nếu bạn thích thì có thể chọn màu khác, giá vẫn vậy ạ."},{"speaker":"client","text":"Thôi được, mình suy nghĩ lại vậy. Cảm ơn bạn nhé!"}]','fail',781),
('[{"speaker":"client","text":"Chào bot, mình muốn mua máy ảnh Canon EOS R50, nhưng thấy giá hơi cao quá. Có ưu đãi gì không?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Máy ảnh Canon EOS R50 hiện đang giảm 5% cho đơn hàng đầu tiên, kèm theo quà tặng 1 ống kính 18-45mm. Anh/chị muốn thanh toán bằng thẻ ngân hàng hay trả góp 0% không?"},{"speaker":"client","text":"Mình chọn trả góp 0% đi. Có giao trong ngày không?"},{"speaker":"salebot","text":"Dạ có ạ! Anh/chị ở đâu để mình kiểm tra kho giao nhanh nhất. Nếu nội thành thì giao trong 2-3 tiếng."},{"speaker":"client","text":"Mình ở quận 1, TPHCM. Địa chỉ là 123 Lê Lợi, phường Bến Nghé. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn anh/chị! Đơn hàng đã được xác nhận, anh/chị vui lòng kiểm tra email để nhận thông tin thanh toán. Chúc anh/chị một ngày tốt lành!"}]','successs',782),
('[{"speaker":"client","text":"Chào anh, mình đang tìm mua chiếc áo sơ mi nam hiệu Hugo Boss, size M có không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình vừa nhập lô mới, màu xanh dương và xám đều còn đủ size M. Bạn muốn mua không?"},{"speaker":"client","text":"Mình thích màu xanh dương nhưng giá hơi cao so với dự định. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ, hôm nay có chương trình khuyến mại 10% cho sản phẩm mới, bạn có thể chọn thêm phụ kiện miễn phí nếu mua trong hôm nay."},{"speaker":"client","text":"Thế thì được, mình lấy luôn áo xanh dương size M. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ, đơn hàng của bạn sẽ giao trong 2 tiếng nếu bạn ở nội thành. Bạn có muốn thanh toán COD không ạ?"},{"speaker":"client","text":"OK, mình chọn COD. Cảm ơn nhé!"}]','successs',783),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho mùa đông. Ở shop có loại mỏng nhẹ nhưng giữ nhiệt tốt không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Đây là sản phẩm mới ra, vải chống gió và thoát mồ hôi tốt, giá 1.299.000đ. Bạn muốn size nào?"},{"speaker":"client","text":"Size M nhé. Có giảm giá gì không? Mình thấy trên web ghi khuyến mại 20% nhưng không rõ điều kiện."},{"speaker":"salebot","text":"Dạ 20% là cho đơn từ 2 sản phẩm trở lên ạ. Nhưng hôm nay mình có ưu đãi đặc biệt: giảm 15% cho đơn từ 1 sản phẩm nếu thanh toán qua ví điện tử. Bạn chọn phương thức nào?"},{"speaker":"client","text":"Ok, mình chọn thanh toán qua MoMo. Vậy mình đặt luôn nhé, giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Đơn của bạn đã được xác nhận, tổng tiền 1.104.150đ (đã trừ 15%). Ship trong 2-4 tiếng, bạn check email nhé!"}]','successs',784),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này của thương hiệu The North Face. Size L có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh navy và đen đều còn size L. Bạn muốn giao trong 2 ngày hay nhận tại cửa hàng?"},{"speaker":"client","text":"Mình ở xa nên giao tận nơi thôi. Giá niêm yết 2.500.000đ, có giảm giá không?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang khuyến mại 10% cho đơn hàng đầu tiên, còn 2.250.000đ thôi. Bạn có muốn thanh toán bằng thẻ ngân hàng không?"},{"speaker":"client","text":"Ok, mình chọn màu xanh navy nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1, TPHCM."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng sẽ được giao trong 2 ngày. Bạn có muốn nhận mã giảm giá cho lần mua sau không?"}]','successs',785),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc điện thoại Samsung Galaxy A54 5G. Mình thấy giá trên web hơi cao so với dự định, có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện tại chúng tôi đang có chương trình khuyến mại giảm 10% cho sản phẩm này nếu anh/chị chọn thanh toán qua ví điện tử MoMo. Như vậy giá chỉ còn 8 triệu 990 nghìn thôi ạ!"},{"speaker":"client","text":"Ồ, vậy thì tốt quá! Mình có thể nhận hàng trong ngày hôm nay không?"},{"speaker":"salebot","text":"Dạ được ạ! Nếu anh/chị ở khu vực nội thành Hà Nội thì giao trong 2-3 tiếng, phí ship chỉ 15k thôi. Anh/chị có muốn đặt luôn không ạ?"},{"speaker":"client","text":"Được rồi, mình đặt luôn nhé! Mình chọn màu đen, địa chỉ giao là 123 Lê Lợi, phường Bến Thành, quận 1, TP.HCM."},{"speaker":"salebot","text":"Dạ cảm ơn anh/chị đã tin tưởng! Đơn hàng của anh/chị đã được ghi nhận, chúc anh/chị một ngày tốt lành!"}]','successs',786),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác gió này nhưng nhìn hơi mỏng, có đảm bảo giữ ấm không vậy?"},{"speaker":"salebot","text":"Dạ không ạ, sản phẩm này là chất liệu chống gió 100% polyester chống thấm nhẹ, phù hợp mùa thu đông. Bạn có thể mặc lớp áo bên trong nữa nè!"},{"speaker":"client","text":"Thế giá bao nhiêu vậy? Có giảm không?"},{"speaker":"salebot","text":"Dạ 1.299k ạ, nhưng hôm nay sale 20% nên chỉ 1.039k thôi! Mình còn tặng kèm túi chống bụi miễn phí nếu mua trong hôm nay."},{"speaker":"client","text":"Ok mình lấy màu xanh dương nhé. Ship bao lâu tới?"},{"speaker":"salebot","text":"Dạ trong 2-3 ngày ạ, mình sẽ gửi mã tracking qua zalo ngay khi giao hàng xong!"}]','successs',787),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện đang khuyến mại 20% cho sản phẩm này, giá gốc 2.500.000đ nay còn 2.000.000đ thôi."},{"speaker":"client","text":"Ôi, đắt quá! Bán 1,8 triệu được không?"},{"speaker":"salebot","text":"Dạ không ạ, giá đã chiết khấu tối đa rồi. Bạn có thể chọn trả góp 0% 3 tháng để dễ chi trả hơn không?"},{"speaker":"client","text":"Thế à... thôi mình không mua nữa, cảm ơn!"}]','fail',788),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc đồng hồ thông minh Galaxy Watch 5. Có màu xanh dương không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương vẫn còn hàng, giao trong 2 ngày. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy giá hơi cao so với quảng cáo, có giảm giá không?"},{"speaker":"salebot","text":"Dạ có ạ! Nếu bạn đặt ngay hôm nay thì mình giảm 5% cho bạn nhé. Chỉ còn 4,750,000đ thôi."},{"speaker":"client","text":"Ok, mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM. Nhận hàng trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng thanh toán trước 30% để xác nhận đơn hàng nhé. Cảm ơn bạn đã mua sắm!"}]','successs',789),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua áo khoác mùa đông cho bé gái 10 tuổi. Có size 12-13 tuổi không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng tôi đang có mẫu áo khoác chống nước màu hồng size 12-13 tuổi, giao hàng tận nơi trong 2 ngày."},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm giá cho khách lẻ không?"},{"speaker":"salebot","text":"Dạ có ạ! Nếu bạn mua ngay hôm nay, mình có thể giảm 10% cho đơn hàng đầu tiên, chỉ còn 890.000đ thôi ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn. Bao gồm phí ship không ạ?"},{"speaker":"salebot","text":"Dạ không ạ, phí ship 30.000đ ngoài. Bạn có muốn nhận hàng vào ngày mai không?"},{"speaker":"client","text":"Được, mình chọn giao vào ngày mai nhé. Cảm ơn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ, hẹn gặp lại!"}]','successs',790),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao nữ cho con gái 12 tuổi. Size 140-150, có hàng không?"},{"speaker":"salebot","text":"Dạ chào chị! Bộ quần áo thể thao nữ size 140-150 của hãng Nike có sẵn ạ. Chị muốn xem màu nào?"},{"speaker":"client","text":"Màu xanh dương nhạt đi bạn. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 890k, nhưng hôm nay có khuyến mại giảm 10% cho chị nhé!"},{"speaker":"client","text":"Hơi đắt quá, có giảm nữa được không? Mình thấy bên khác bán 750k thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, giá này đã ưu đãi lắm rồi ạ. Nếu chị mua kèm giày thể thao size 37 thì mình giảm thêm 50k nha!"},{"speaker":"client","text":"Thế à... thôi mình nghĩ lại đã. Cảm ơn bạn nhé!"}]','fail',791),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật của thương hiệu Gucci, nhưng giá trên web cao quá. Có cách nào giảm giá không?"},{"speaker":"salebot","text":"Chào chị ạ! Túi Gucci hiện đang có chương trình khuyến mại 15% cho đơn hàng từ 3 triệu trở lên, chị có thể chọn màu sắc ưa thích nhé."},{"speaker":"client","text":"15% thôi à? Mình thấy có chỗ bán rẻ hơn nhiều, chỉ 18 triệu thôi. Bạn có thể giảm xuống 17 triệu không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, Gucci là thương hiệu cao cấp nên giá niêm yết khá ổn, nhưng nếu chị đặt luôn hôm nay thì mình sẽ hỗ trợ thêm 500k phí ship tận nơi nhé!"},{"speaker":"client","text":"Vậy thôi, mình chọn màu đen. Đóng gói cẩn thận nhé, mình nhận vào chiều nay."},{"speaker":"salebot","text":"Dạ vâng chị, đơn hàng sẽ được giao trong 2 tiếng tới ạ! Cảm ơn chị đã ủng hộ."}]','successs',792),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác mùa đông này. Size L có không?"},{"speaker":"salebot","text":"Chào chị ạ! Size L vẫn còn 5 chiếc, chị có thể chọn màu đen hoặc xám nhé."},{"speaker":"client","text":"Mình thích màu đen nhưng giá hơi cao. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chị ơi, hôm nay có khuyến mại 10% cho sản phẩm này, chỉ hết hôm nay thôi ạ!"},{"speaker":"client","text":"Thế à? Vậy mình lấy luôn 1 cái. Ship bao lâu nhận được?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày chị nhé! Chị chọn phương thức thanh toán nào ạ?"}]','successs',793),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bàn chải điện Oral-B Genius X, có giảm giá gì không ạ? Mình thấy trên web ghi khuyến mại 20% nhưng giờ hết rồi à?"},{"speaker":"salebot","text":"Dạ chào chị ạ, bàn chải Oral-B Genius X hiện vẫn còn khuyến mại 20% cho đến hết tuần này chị nhé! Chị muốn màu nào ạ?"},{"speaker":"client","text":"À vậy à, chị thấy màu đen trông sang hơn. Nhưng chị thấy giá 2.490.000 vẫn hơi cao, có thể giảm thêm không? Chị thấy bên kia bán 2.200.000 thôi ạ."},{"speaker":"salebot","text":"Dạ em xin lỗi chị, mức giảm 20% là mức tối đa rồi ạ. Bên em cam kết sản phẩm chính hãng nên giá có phần ổn định hơn chị nhé. Chị có thể chọn trả góp 0% trong 3 tháng nếu muốn ạ!"},{"speaker":"client","text":"Thế à, vậy thôi chị không mua nữa. Cảm ơn shop nhé!"}]','fail',794),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua đôi giày thể thao Nike Air Max 90, size 42 có sẵn không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu đen và trắng vẫn còn size 42. Bạn muốn giao trong ngày hay nhận tại cửa hàng?"},{"speaker":"client","text":"Giao trong ngày được không? Mình cần gấp lắm vì mai phải đi công tác."},{"speaker":"salebot","text":"Dạ được ạ! Giá niêm yết là 3.200.000đ, nhưng do mua online bạn sẽ được giảm 5% còn 3.040.000đ. Bạn có muốn đặt luôn không?"},{"speaker":"client","text":"Ok, mình đặt luôn. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ trong 2-3 tiếng là giao tới tận nơi ạ! Bạn để lại địa chỉ và số điện thoại để mình xác nhận đơn hàng nhé."}]','successs',795),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông này. Mẫu này có size M không nhỉ?"},{"speaker":"salebot","text":"Dạ có ạ! Size M vẫn còn 5 chiếc. Bạn muốn mình gửi ảnh chi tiết sản phẩm không?"},{"speaker":"client","text":"Có ạ, gửi mình xem trước nhé. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 1.299.000đ ạ, đang giảm 20% từ giá gốc. Nếu bạn mua trong hôm nay, mình tặng luôn kèm mũ len nha."},{"speaker":"client","text":"Hơi đắt so với dự định. Bạn giảm thêm chút được không? Tối đa 1.1 triệu thôi."},{"speaker":"salebot","text":"Dạ mình check lại nhé! Được ạ, 1.150.000đ thôi, kèm mũ len luôn. Bạn nhận hàng trong 2 ngày không vấn đề gì chứ?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Phường Bến Thành, Quận 1."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng của bạn đã được xác nhận. Chúc bạn một ngày vui vẻ!"}]','successs',796),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua bàn chải điện Philips Sonicare DiamondClean, nhưng không biết loại nào tốt nhất cho nướu nhạy cảm?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Cho anh/chị em loại Sonicare DiamondClean 9000 nhé, có 5 chế độ massage, an toàn cho nướu, đang khuyến mại 20% nè."},{"speaker":"client","text":"Mình nghe nói loại này khá đắt, có cách nào giảm giá hơn không? Mình thấy trên shopee nó rẻ hơn 1 triệu."},{"speaker":"salebot","text":"Dạ anh/chị yên tâm! Em báo giá sỉ cho anh/chị 3.590.000đ thôi (giá niêm yết 4.490.000đ), giao tận nhà miễn phí, cam kết chính hãng 100%."},{"speaker":"client","text":"Ok, mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Phường 10, Quận 3, TPHCM. Có thể giao vào chiều nay không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị thanh toán online hay COD? Em gửi link thanh toán và xác nhận đơn hàng ngay bây giờ nha."}]','successs',797),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc đồng hồ Casio G-Shock GA-2100. Có hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Sản phẩm này hiện đã hết hàng rồi ạ. Có thể đặt trước hoặc chọn mẫu tương tự như GA-1100 ạ?"},{"speaker":"client","text":"Hết hàng à? Thế giá GA-1100 bao nhiêu vậy? Mình không thích kiểu dây nhựa lắm."},{"speaker":"salebot","text":"Dạ giá GA-1100 là 1.890.000đ ạ, giao ngay có sẵn. Còn mẫu GA-2100 phiên bản giới hạn sắp về trong tuần tới ạ!"},{"speaker":"client","text":"1.890.000 à? Đắt quá, mình thấy trên Shopee bán rẻ hơn 100k đó."},{"speaker":"salebot","text":"Dạ shop mình cam kết hàng chính hãng 100% ạ, Shopee có thể là hàng nhái ạ. Giá này là ưu đãi cho khách quen rồi ạ."},{"speaker":"client","text":"Thế à... thôi mình không mua nữa đâu. Cảm ơn nhé!"}]','fail',798),
('[{"speaker":"client","text":"Chào shop, mình đang quan tâm đến chiếc bàn làm việc thông minh này. Giá niêm yết 5 triệu có được giảm không ạ? Mình thấy bên kia bán rẻ hơn 100k."},{"speaker":"salebot","text":"Chào chị! Em xin lỗi vì sự chênh lệch giá ạ, do sản phẩm mới nhập về nên chưa có chiết khấu. Nhưng chị có thể chọn combo bàn + ghế giảm 200k, tổng 4.8 triệu nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy combo đi. Ship tận nơi được không? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ được chị! Ship nội thành miễn phí, giao trong 2-3 ngày ạ. Em gửi link thanh toán qua Zalo cho chị nhé?"}]','successs',799),
('[{"speaker":"client","text":"Chào shop! Mình thấy đôi giày thể thao Nike Air Force 1 giá 2,8 triệu trên web. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Đôi giày này đang khuyến mại 10% nếu bạn mua trong hôm nay, còn 2,52 triệu thôi."},{"speaker":"client","text":"10% hơi ít nhỉ, có thể giảm thêm được không?"},{"speaker":"salebot","text":"Dạ không ạ, mức này đã là ưu đãi nhất rồi. Nếu bạn mua kèm vớ thể thao thì tặng thêm 1 đôi nha."},{"speaker":"client","text":"Thôi vậy, mình không cần vớ đâu. Cảm ơn nhé!"}]','fail',800),
('[{"speaker":"client","text":"Chào! Mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, nhưng thấy giá hơi cao so với túi tiền của mình. Có ưu đãi nào không ạ?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại bàn chải Oral-B Pro 3000 có chương trình khuyến mại 10% giảm giá nếu bạn đặt ngay hôm nay. Nếu mua kèm kem đánh răng Oral-B, tặng thêm 1 tuýp nữa."},{"speaker":"client","text":"Mình chỉ cần bàn chải thôi. Nếu giảm thêm 15% thì mình mua liền luôn. Bao lâu giao hàng được?"},{"speaker":"salebot","text":"Dạ xin lỗi bạn, mức giảm tối đa mình có thể hỗ trợ là 12% thôi ạ. Nếu bạn không thể quyết định ngay, mình có thể giữ giá ưu đãi này trong 24 giờ nữa cho bạn."},{"speaker":"client","text":"Thế thì tiếc quá, mình sẽ suy nghĩ lại. Cảm ơn bạn nhé!"}]','fail',801),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc túi xách da thật này. Có màu gì thế?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Túi này có 3 màu: nâu đậm, đen và cognac. Anh/chị thích màu nào nhất?"},{"speaker":"client","text":"Mình thích màu nâu đậm. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ túi da thật này giá 2.490.000đ, nhưng hôm nay có khuyến mại 10% nếu mua online. Còn 2 cái cuối cùng thôi ạ!"},{"speaker":"client","text":"Hơi đắt, có thể giảm xuống 2 triệu không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm, đây là giá sỉ nên khó giảm hơn ạ. Nhưng nếu anh/chị mua kèm ví da mini thì mình giảm còn 2.200.000đ thôi!"},{"speaker":"client","text":"Ok, mình lấy túi nâu đậm + ví mini. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị để lại địa chỉ và số điện thoại, mình sẽ xác nhận đơn hàng ngay."}]','successs',802),
('[{"speaker":"client","text":"Chào bạn, mình đang quan tâm đến chiếc váy dạ hội màu đỏ từ thương hiệu này. Size L còn không ạ?"},{"speaker":"salebot","text":"Dạ còn ạ! Size L vừa hết size vừa rồi, nhưng mình có size XL cùng kiểu dáng, bạn xem được không?"},{"speaker":"client","text":"Size XL thì hơi rộng, bạn có size M không? Mình mặc vừa size M thôi."},{"speaker":"salebot","text":"Dạ tiếc quá, size M vừa hết hàng. Nhưng mình có chương trình giảm 10% nếu bạn chọn size XL, bạn thấy sao?"},{"speaker":"client","text":"10% thì cũng được, nhưng mình thích size M hơn. Bạn báo giá luôn cho mình luôn nhé."},{"speaker":"salebot","text":"Dạ giá gốc 2.500.000đ, giảm còn 2.250.000đ cho size XL ạ. Bạn lấy luôn không?"},{"speaker":"client","text":"Ok, vậy mình lấy size XL. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 ngày ạ, bạn chọn hình thức thanh toán nào?"},{"speaker":"client","text":"Mình thanh toán online nhé. Cảm ơn bạn!"}]','successs',803),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác nữ hiệu Zara này, nhưng thấy giá hơi cao quá. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Hiện sản phẩm chị đang xem đang trong chương trình khuyến mại cuối tháng ạ, giảm 15% cho đơn trên 500k. Chị có muốn thêm phụ kiện miễn phí không ạ?"},{"speaker":"client","text":"Ồ, vậy giá cuối là bao nhiêu vậy? Mình lấy size M thôi."},{"speaker":"salebot","text":"Dạ giá gốc 899k, sau giảm còn 764k ạ. Nếu chị lấy thêm khăn quàng (199k) thì free ship trong hôm nay luôn chị nhé!"},{"speaker":"client","text":"Thôi được, mình lấy áo thôi. Địa chỉ giao là 123 Lê Lợi, quận 1, TPHCM. Bao lâu nhận hàng vậy?"},{"speaker":"salebot","text":"Dạ 2-3 tiếng chị nhé! Em sẽ gửi mã tracking ngay khi xuất kho ạ. Cảm ơn chị đã mua sắm cùng chúng mình!"}]','successs',804),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G, nhưng giá trên web hơi cao quá. Có ưu đãi gì không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại mình có chương trình giảm giá 5% nếu bạn thanh toán bằng thẻ ngân hàng đối tác, và tặng kèm 1 chiếc ốp lưng chính hãng. Bạn có muốn áp dụng không?"},{"speaker":"client","text":"Ồ, vậy giá cuối cùng là bao nhiêu vậy? Mình trả trước bằng thẻ VCB có được không?"},{"speaker":"salebot","text":"Dạ giá sau khi giảm 5% là 21.800.000đ, giao hàng miễn phí trong 2h nếu bạn ở TP.HCM. Bạn có muốn đặt luôn không ạ?"},{"speaker":"client","text":"Ok, mình đặt luôn chiếc màu đen. Địa chỉ giao là 123 Lê Lợi, quận 1. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Đơn hàng #SA230515 của bạn đã được xác nhận. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',805),
('[{"speaker":"client","text":"Alo, mình muốn mua bộ quần áo thể thao cho bé gái 8 tuổi. Có size 120 không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình đang có mẫu áo thể thao cute hình công chúa đi kèm quần short. Giá niêm yết 499k, giảm còn 399k nếu mua full set."},{"speaker":"client","text":"Hơi đắt nhỉ, có giảm nữa không? Mình thấy chỗ khác bán 350k full set."},{"speaker":"salebot","text":"Dạ không ạ, đây là giá sốc cuối tuần rồi. Nếu bạn lấy 2 bộ trở lên thì mình giảm thêm 10k mỗi bộ nha!"},{"speaker":"client","text":"Thế à, tiếc quá mình chỉ cần 1 bộ thôi. Thôi vậy mai mình qua cửa hàng xem thử rồi quyết định vậy."},{"speaker":"salebot","text":"Dạ vâng ạ! Chúc bạn ngủ ngon, hẹn gặp sau nha!"}]','fail',806),
