('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc đồng hồ Casio G-Shock GA-2100, nhưng nhìn trên web không thấy size 200mm. Bạn có size đó không?"},{"speaker":"salebot","text":"Dạ có ạ! Size 200mm vẫn còn hàng, nhưng hơi hiếm nên mình khuyến mãi 5% cho bạn nhé!"},{"speaker":"client","text":"Thế giá bao nhiêu vậy? Mình thấy trên web giá niêm yết là 2.500.000đ."},{"speaker":"salebot","text":"Dạ giá niêm yết là vậy, nhưng mình giảm còn 2.350.000đ thôi ạ! Giao hàng miễn phí trong nội thành."},{"speaker":"client","text":"Ok, mình lấy vậy. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM. Bao lâu nhận được hàng?"},{"speaker":"salebot","text":"Dạ giao trong ngày ạ! Mình sẽ gửi mã tracking sau khi thanh toán xong. Cảm ơn bạn đã mua hàng!"}]','successs',811),
('[{"speaker":"client","text":"Chào! Mình thấy cái bàn ghế gỗ óc chó này đẹp quá, nhưng giá 12 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ không ạ! Đồ nội thất gỗ óc chó chất lượng như này giá vậy là ổn rồi. Nếu bạn mua combo ghế + bàn thì giảm 5% luôn nè!"},{"speaker":"client","text":"Thế combo có giao hàng tận nơi không? Mình ở xa lắm."},{"speaker":"salebot","text":"Dạ có ạ! Phí ship chỉ 50k thôi, giao trong 3-5 ngày. Còn nếu bạn lấy tại cửa hàng thì free ship luôn."},{"speaker":"client","text":"Ừm... để mình suy nghĩ thêm nhé. Cảm ơn nha!"}]','fail',812),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn làm việc gỗ thông này. Giá trên web là 2.500.000đ, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại shop đang có khuyến mại 15% cho sản phẩm này, giá chỉ còn 2.125.000đ thôi ạ. Bạn lấy không?"},{"speaker":"client","text":"À, mình thích lắm nhưng 2 triệu rưỡi thì chắc mình chưa mua ngay được. Có thể giảm thêm không? Mình thấy bên kia có giá 1.900.000đ."},{"speaker":"salebot","text":"Dạ, vì sản phẩm chất liệu gỗ thông nguyên khối nên giá hơi cao ạ. Nếu bạn mua kèm thêm ghế văn phòng giảm 5% nữa, mình có thể giảm xuống 2.000.000đ trọn bộ. Bên mình giao miễn phí trong 30 phút nếu bạn ở quận 1."},{"speaker":"client","text":"Ok, vậy mình lấy trọn bộ nhé. Bao giờ nhận được hàng?"},{"speaker":"salebot","text":"Dạ giao trong 30 phút ạ! Bạn vui lòng để lại số điện thoại và địa chỉ chi tiết để shop xác nhận đơn hàng nhé."}]','successs',813),
