('[{"speaker":"client","text":"Chào shop, mình đang tìm mua chiếc áo khoác da nữ hiệu Zara, size S. Màu đen có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size S màu đen còn 2 chiếc. Bên mình giao trong 3-5 ngày, phí ship 30k nếu dưới 500k nha."},{"speaker":"client","text":"Ôi 30k ship hơi đắt nhỉ, mình thấy chỗ khác ship 15k thôi. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ shop ưu tiên khách cũ nên giảm 10% thôi ạ. Còn 100k cho 2 sản phẩm nữa là free ship nha!"},{"speaker":"client","text":"Thế à, thế mình lấy thêm 1 cái túi xách mini đi. Nhưng mình thấy túi xách hơi nhỏ, có đảm bảo chất lượng không?"},{"speaker":"salebot","text":"Dạ túi xách Zara mini này chất lượng tốt lắm ạ! Da thật, chống nhòe mực. Chị cứ yên tâm nha."},{"speaker":"client","text":"Thế thôi, mình đặt 2 sản phẩm luôn. Nhưng chờ mình check lại giá tổng cộng bao nhiêu nữa nhé."}]','fail',817),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em vừa kiểm tra thấy Galaxy S23 Ultra 5G vẫn còn hàng ạ. Anh/chị muốn màu nào ạ? Black hay Green?"},{"speaker":"client","text":"Mình thích màu xanh lá, nhưng giá hơi cao so với dự định. Có giảm giá không ạ?"},{"speaker":"salebot","text":"Dạ em thấy hôm nay có chương trình khuyến mại ưu đãi 5% cho sản phẩm này ạ. Còn nếu anh/chị mua kèm ốp lưng chính hãng thì được tặng miễn phí sạc nhanh nữa ạ!"},{"speaker":"client","text":"Thế à? Vậy mình lấy luôn chiếc màu xanh lá đi. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ ạ! Anh/chị ở đâu ạ? Em sẽ check giao hàng tận nơi trong 2 giờ nếu anh/chị ở nội thành ạ. Thanh toán khi nhận hàng luôn tiện lắm ạ!"}]','successs',818),
('[{"speaker":"client","text":"Chào shop, mình đang quan tâm bộ quần áo thể thao nữ của hãng Nike, size S và M có không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Size S và M vẫn còn hàng chị nhé, nhưng mẫu này chỉ có 3 cái size M thôi chị thông cảm."},{"speaker":"client","text":"À vậy à, chán thật. Mình cần size M nhiều hơn, thôi đi chỗ khác vậy."},{"speaker":"salebot","text":"Dạ em xin lỗi chị vì không đủ size ạ! Chúc chị mua được sản phẩm ưng ý ở chỗ khác nhé."}]','fail',819),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc bàn chải điện Oral-B Pro 3000. Còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn! Sản phẩm này hiện đang hết hàng tạm thời, mình sẽ thông báo khi có hàng trở lại nhé!"}]','fail',820),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác dạ nữ màu đen của thương hiệu Zara, size S có không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Size S áo dạ nữ Zara hiện còn 2 sản phẩm thôi ạ. Chị muốn mình check mã màu khác không?"},{"speaker":"client","text":"Không, mình chỉ cần size S thôi. Giá niêm yết 1.990.000 đúng không? Có giảm giá gì không?"},{"speaker":"salebot","text":"Dạ đúng rồi chị ơi! Hiện tại shop có ưu đãi ship miễn phí cho đơn từ 2 triệu, chị mua thêm 1 sản phẩm khác nhé?"},{"speaker":"client","text":"Mình chỉ cần 1 cái thôi. Giảm 200k đi, mình lấy luôn!"},{"speaker":"salebot","text":"Dạ chị thông cảm, giá niêm yết shop không giảm được chị ơi. Nếu chị lấy thêm đồ khác thì shop có thể giảm 5% cho chị nè."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Thanks!"}]','fail',821),
('[{"speaker":"client","text":"Chào! Mình thấy chiếc bàn ghế gỗ óc chó 4 chỗ ngồi này đẹp quá, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Sản phẩm còn 5 bộ, giao tận nơi trong 3 ngày. Giá niêm yết 12 triệu nhưng hôm nay sale 10% cho khách đầu tiên."},{"speaker":"client","text":"Ồ, vậy giá cuối cùng là bao nhiêu thế? Mình thấy hơi đắt so với túi mình."},{"speaker":"salebot","text":"Dạ ạ, giá sau giảm là 10.8 triệu thôi ạ! Nếu bạn lấy kèm bộ rèm cùng chất liệu thì được giảm thêm 500k nữa."},{"speaker":"client","text":"Thế giao hàng ngoài tỉnh được không? Mình ở Đà Nẵng ấy."},{"speaker":"salebot","text":"Dạ được ạ, phí vận chuyển ngoài tỉnh là 300k. Nếu bạn đặt ngay hôm nay thì mình sẽ hỗ trợ phí ship nửa giá."},{"speaker":"client","text":"Hmm, cảm ơn nhé. Để mình suy nghĩ lại đã. Chúc bạn buổi tối vui vẻ!"},{"speaker":"salebot","text":"Dạ không sao ạ! Cảm ơn bạn đã quan tâm. Chúc bạn một ngày tốt lành!"}]','fail',822),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác chống nước của The North Face, size M có không?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu áo khoác chống nước The North Face Resolve 2 có sẵn size M, màu xanh lam và đen. Bạn muốn giao trong ngày không?"},{"speaker":"client","text":"Mình thấy giá hơi cao so với dự định, có giảm giá không?"},{"speaker":"salebot","text":"Dạ hiện tại có chương trình giảm 10% cho đơn hàng đầu tiên, kèm voucher 50k khi thanh toán bằng ví điện tử. Như vậy giá còn 2.250.000đ thôi ạ!"},{"speaker":"client","text":"Được rồi, mình chọn màu xanh lam nhé. Giao trong ngày được chứ?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn vui lòng cung cấp địa chỉ và số điện thoại để mình xử lý đơn hàng nhé."}]','successs',823),
