('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé gái 10 tuổi. Bạn có size 140 không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Mẫu áo thun + quần thể thao chống mồ hôi, màu hồng và xanh dương. Giá niêm yết 499k nhưng hôm nay sale 30% còn 349k thôi nè."},{"speaker":"client","text":"Ồ vậy ạ? Mình thấy mẫu áo hơi rộng, có size nhỏ hơn không?"},{"speaker":"salebot","text":"Dạ có ạ, size 130 vẫn còn 10 cái. Mình gửi link size 130 cho bạn nhé? Hoặc bạn muốn mình tư vấn thêm?"},{"speaker":"client","text":"Thôi được, mình lấy size 130 luôn. Bao ship phí thế?"},{"speaker":"salebot","text":"Miễn phí ship cho đơn trên 300k ạ. Bạn chọn thanh toán COD hay chuyển khoản?"},{"speaker":"client","text":"COD tiện hơn. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc bạn mua sắm vui vẻ. Có gì cần hỗ trợ cứ nhắn mình nha!"}]','successs',834),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác gió cho bé gái 9 tuổi, size 120. Có hàng không?"},{"speaker":"salebot","text":"Dạ chào chị, áo khoác gió size 120 thì hiện tại chỉ còn màu xanh dương thôi chị ạ. Chị muốn xem ảnh không?"},{"speaker":"client","text":"Mình thích màu hồng hơn, có không shop?"},{"speaker":"salebot","text":"Rất tiếc chị ơi, size 120 màu hồng đã hết hàng rồi. Chị có thể chọn size 128 hoặc màu xanh dương không ạ?"},{"speaker":"client","text":"Size 128 thì hơi to, mình không thích. Thôi chắc mình không mua nữa."}]','fail',835),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn ghế gỗ óc chó này đẹp quá, có loại nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ có ạ! Loại gỗ thông thường giá 5 triệu, còn loại óc chó này 8 triệu. Bạn muốn giảm giá không?"},{"speaker":"client","text":"8 triệu à? Đắt quá, mình chỉ có 6 triệu thôi. Có giảm được không?"},{"speaker":"salebot","text":"Dạ 6 triệu hơi thấp ạ, nhưng nếu bạn mua kèm ghế sofa mini thì mình giảm còn 7 triệu cho bộ."},{"speaker":"client","text":"Thế không được, mình chỉ cần bàn thôi. Thôi chào bạn nhé!"}]','fail',836),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc váy dạ hội màu đen size M, nhưng không biết có còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào chị, váy dạ hội màu đen size M hôm nay vừa hết ạ, chị có thể xem mẫu màu đỏ thẫm size L không? Cùng kiểu dáng và chất liệu."},{"speaker":"client","text":"Ồ, màu đỏ cũng đẹp nhưng mình thích màu đen hơn. Có cách nào lấy được size M không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, size M vừa hết nên không thể order riêng được ạ. Nếu chị muốn, mình có thể báo trước cho chị khi nào size M nhập về nhé?"},{"speaker":"client","text":"Thế à, vậy thôi vậy. Cảm ơn bạn nhé!"}]','fail',837),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn phím cơ Keychron K8, có màu xanh dương không?"},{"speaker":"salebot","text":"Chào bạn ạ! Dạ hiện tại bàn phím Keychron K8 màu xanh dương đã hết hàng rồi ạ. Mình xin lỗi vì sự bất tiện này."},{"speaker":"client","text":"Thế à? Màu đen thì sao? Mình có thể nhận hàng trong tuần này không?"},{"speaker":"salebot","text":"Dạ màu đen vẫn còn ạ! Giá niêm yết là 2.299.000đ, nhưng mình có thể giảm cho bạn 5% nếu mua ngay hôm nay ạ."},{"speaker":"client","text":"5% thôi à? Mình thấy chỗ khác có giảm 10% kèm quà tặng nữa đấy."},{"speaker":"salebot","text":"Dạ em thật lòng xin lỗi ạ, 5% là mức giảm tối đa em có thể hỗ trợ cho khách hàng mới ạ. Nhưng nếu bạn mua kèm chuột không dây Keychron M3 thì em có thể giảm thêm 3% nữa ạ."},{"speaker":"client","text":"Thế à... thôi được, mình sẽ suy nghĩ thêm. Cảm ơn bạn nhé!"}]','fail',838),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác da này nhưng giá hơi cao so với túi tiền của mình. Có thể giảm giá không?"},{"speaker":"salebot","text":"Dạ, áo khoác da này đang khuyến mại 10% cho đơn hàng đầu tiên. Nếu bạn mua 2 cái trở lên, mình có thể giảm thêm 5% nữa."},{"speaker":"client","text":"Mình chỉ mua 1 thôi, vậy 10% thôi à? Hay có cách nào khác để tiết kiệm hơn không?"},{"speaker":"salebot","text":"Dạ, bạn có thể đăng ký tài khoản và nhận voucher 5% ngay lập tức. Hoặc thanh toán bằng ví điện tử cũng được giảm 3% nữa ạ."},{"speaker":"client","text":"Vậy mình đăng ký thôi. Nhưng giá cuối cùng là bao nhiêu? Mình thấy trên mạng rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ, giá niêm yết là 2.500.000đ, sau khuyến mại còn 2.250.000đ. Mình không thể giảm thêm được rồi ạ, xin lỗi bạn nhé!"}]','fail',839),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác thể thao của Nike, size M có không?"},{"speaker":"salebot","text":"Dạ có ạ! Màu xanh dương và đen size M vẫn còn. Bạn muốn giao trong ngày không?"},{"speaker":"client","text":"Mình thấy giá hơi cao, có giảm giá không? Mình thấy chỗ khác rẻ hơn 100k."},{"speaker":"salebot","text":"Dạ, mình có voucher giảm 5% cho đơn trên 1 triệu. Bạn order ngay bây giờ nhé!"},{"speaker":"client","text":"Ok, mình lấy luôn. Ship phí thế nào?"},{"speaker":"salebot","text":"Miễn phí ship cho đơn trên 800k ạ. Bạn để lại địa chỉ và sdt để mình xác nhận nhé!"}]','successs',840),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác denim nữ này. Size S và M còn không ạ?"},{"speaker":"salebot","text":"Dạ chào chị! Size S còn 2 chiếc, size M hết rồi chị ơi. Chị có muốn chọn size S không ạ?"},{"speaker":"client","text":"À vậy size S giá bao nhiêu thế? Đã giảm giá chưa?"},{"speaker":"salebot","text":"Dạ size S giá niêm yết 890k, giờ đang sale 690k chị nhé. Nếu chị lấy luôn thì mình free ship nha!"},{"speaker":"client","text":"690k hơi đắt nhỉ, mình thấy bên kia bán 650k thôi. Bạn có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, giá mình đã chiết khấu hết mức rồi ạ. Nhưng nếu chị thanh toán bằng ví MoMo thì mình giảm thêm 10k nữa nha!"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Dạ chị vui lòng để lại địa chỉ, mình giao trong 2-3 ngày ạ. Cảm ơn chị đã ủng hộ!"}]','successs',841),
('[{"speaker":"client","text":"Chào bot, mình thấy cái nồi cơm điện này 1.5L của hãng nào vậy? Giá bao nhiêu?"},{"speaker":"salebot","text":"Dạ nồi cơm điện 1.5L này là của hãng Panasonic ạ, giá niêm yết 1.890.000đ, nhưng hôm nay ưu đãi còn 1.650.000đ thôi ạ!"},{"speaker":"client","text":"Hơi đắt nhỉ, có giảm thêm không? Mình thấy bên kia bán 1.550.000đ kia kìa."},{"speaker":"salebot","text":"Dạ không ạ, giá niêm yết của Panasonic không thể giảm thấp hơn ạ. Nhưng nếu bạn mua kèm nồi chống dính 2L giá 400k thì mình giảm 50k nữa cho bạn nhé!"},{"speaker":"client","text":"Thôi được, mình không cần kèm nữa. Cảm ơn nhé, bye!"}]','fail',842),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc điện thoại Samsung Galaxy S23 Ultra 5G, nhưng giá trên web hơi cao so với dự tính của mình. Có cách nào giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn! Hiện tại chúng mình đang có chương trình khuyến mại giảm 5% cho đơn hàng đầu tiên trong hôm nay. Ngoài ra, bạn có thể chọn trả góp 0% lãi suất nếu muốn."},{"speaker":"client","text":"Vậy nếu mình mua kèm ốp lưng và dán màn hình thì có được tặng quà gì không? Mình thấy bên kia có tặng sạc nhanh."},{"speaker":"salebot","text":"Dạ ạ! Nếu bạn mua kèm ốp lưng và dán màn hình, chúng mình tặng luôn cho bạn sạc nhanh chính hãng 25W kèm theo. Còn gì nữa không ạ?"},{"speaker":"client","text":"Ok, vậy mình lấy luôn chiếc điện thoại kèm combo ốp lưng + dán màn hình + sạc nhanh. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ đơn hàng của bạn đã được xử lý xong! Sản phẩm sẽ giao tới bạn trong vòng 2 giờ nếu bạn ở nội thành, phí ship miễn phí luôn nhé. Cảm ơn bạn đã mua sắm cùng chúng mình!"}]','successs',843),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc váy dạ hội màu xanh dương size M. Bạn còn Size M không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Size M vẫn còn hàng, nhưng hiện tại chỉ còn 1 chiếc thôi. Bạn muốn mình giữ hàng hay gửi ảnh trước cho bạn xem ạ?"},{"speaker":"client","text":"Gửi ảnh trước đi bạn, mình sợ size không vừa. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ váy này giá gốc 1.200.000đ, nhưng hôm nay sale 20% nên còn 960.000đ thôi ạ. Ảnh mình gửi kèm đây nè!"},{"speaker":"client","text":"Ôi trời, đẹp quá! Nhưng 960k hơi mắc nhỉ? Có thể giảm thêm không? Mình thấy chỗ khác 850k thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, 960k là giá đã chiết khấu rồi. Nếu bạn mua kèm khăn choàng thì em có thể giảm còn 920k cho bạn ạ!"},{"speaker":"client","text":"Thôi vậy, mình không cần khăn đâu. Để mình suy nghĩ lại đã. Cảm ơn bạn nhé!"}]','fail',844),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc váy đen của thương hiệu Zara, size M có không ạ? Mình thấy trên web ghi còn 1 cái thôi."},{"speaker":"salebot","text":"Dạ chào chị ạ! Size M vẫn còn 2 chiếc chị nhé. Em gửi link sản phẩm cho chị xem qua ạ."},{"speaker":"client","text":"Mình thấy giá 1.499k hơi đắt, có giảm giá không? Mình thấy bên kia bán 1.299k thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, sản phẩm này đang khuyến mại 20% nên giá gốc là 1.899k chị nhé. Em có thể giảm thêm 5% cho chị, còn 1.424k thôi ạ."},{"speaker":"client","text":"Ok, mình chọn size M nhé. Địa chỉ giao là 123 Nguyễn Huệ, Quận 1, mình nhận tiền mặt luôn nha."},{"speaker":"salebot","text":"Dạ chị vui lòng cung cấp số điện thoại để xác nhận đơn hàng ạ. Em sẽ gửi mã giảm giá 5% vào tin nhắn sau khi chị xác nhận ạ."}]','successs',845),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn làm việc gỗ óc chó này đẹp quá, nhưng giá 12 triệu hơi cao nhỉ?"},{"speaker":"salebot","text":"Dạ em hiểu ạ, sản phẩm chất liệu óc chó nguyên khối, chịu lực tốt, đảm bảo 10 năm sử dụng. Đã có 3 khách hàng mua giảm xuống 11 triệu rồi ạ."},{"speaker":"client","text":"Thế có giảm nữa không? 10 triệu thôi thì mình mua luôn."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá sàn của shop là 10.5 triệu thôi ạ. Nếu 10.5 triệu em có thể giao trong 2 ngày ạ."},{"speaker":"client","text":"Thế không được thì thôi, cảm ơn bot nha."}]','fail',846),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S24 Ultra 5G đang giảm giá trên web. Còn hàng không ạ?"},{"speaker":"salebot","text":"Dạ còn ạ! Máy màu đen và xanh dương đều có sẵn. Giảm 5 triệu cho đợt khuyến mại hôm nay luôn nè!"},{"speaker":"client","text":"Thế giá cuối có thể xuống thêm không? Mình thấy chỗ khác rẻ hơn 1 triệu đó."},{"speaker":"salebot","text":"Dạ, em check lại cho anh nhé! Anh có thể chọn hình thức thanh toán trả góp 0% không lãi suất không ạ?"},{"speaker":"client","text":"Ok, mình chọn trả góp. Vậy giao hàng vào ngày mai được chứ?"},{"speaker":"salebot","text":"Dạ được ạ! Anh vui lòng cung cấp địa chỉ và số điện thoại để em xác nhận đơn hàng nhé. Cảm ơn anh đã mua sắm cùng shop!"}]','successs',847),
('[{"speaker":"client","text":"Chào anh/chị ơi! Mình nhìn thấy bộ quần áo thể thao nữ của thương hiệu Nike trên web, size S còn không vậy? Mình cần gấp cho buổi tập cuối tuần."},{"speaker":"salebot","text":"Dạ chào chị ạ! Size S vẫn còn hàng ạ, nhưng chỉ còn 2 cái thôi chị nhé. Màu chị thích là xanh lá hay tím ạ?"},{"speaker":"client","text":"Mình thích màu xanh lá. Giá bao nhiêu thế? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.299.000đ, nhưng hôm nay có khuyến mại 20% cho chị, còn 1.039.200đ thôi ạ. Giao tận nơi trong 2h nếu chị ở TPHCM."},{"speaker":"client","text":"Ồ tốt quá! Mình lấy luôn nhé. Nhưng mình thấy trên mạng có nơi bán 900k thôi, sao của mình lại đắt thế?"},{"speaker":"salebot","text":"Dạ chị ơi, giá 900k là hàng xách tay không chính hãng chị nhé. Của mình là hàng chính hãng, full box, bảo hành 1 năm. Chị cứ yên tâm ạ!"},{"speaker":"client","text":"Thôi được, mình tin anh/chị. Mình đặt luôn nhé. Địa chỉ giao là 123 Lê Lợi, Quận 1, TPHCM. Số điện thoại là 0901234567."},{"speaker":"salebot","text":"Dạ chị vui lòng chuyển khoản 1.039.200đ vào số tài khoản 1234567890 (Techcombank) ạ. Chúng tôi sẽ giao hàng trong 1h và gửi mã vận đơn qua tin nhắn cho chị."}]','successs',848),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua giày thể thao Nike Air Force 1, có size 42 không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size 42 vẫn còn 5 đôi, bạn muốn màu nào ạ? Giá niêm yết 2,5 triệu."},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình thấy bên kia bán 2,2 triệu."},{"speaker":"salebot","text":"Dạ không ạ, giá niêm yết của Nike là vậy. Nhưng nếu bạn mua 2 đôi sẽ giảm 100k/đôi ạ."},{"speaker":"client","text":"Thế à, tiếc quá, mình chỉ mua 1 đôi thôi. Thôi không mua nữa, cảm ơn nhé!"}]','fail',849),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc bàn phím cơ Keychron K8, giá trên web là 2.500.000đ phải không?"},{"speaker":"salebot","text":"Dạ vâng ạ, nhưng hiện tại shop đang có khuyến mãi 10% cho sản phẩm này, nên giá chỉ còn 2.250.000đ thôi ạ!"},{"speaker":"client","text":"À vậy à, nhưng mình thấy bên Shopee bán giá 2.100.000đ kèm quà tặng nữa, không biết shop có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá của shop đã là ưu đãi nhất rồi. Nếu bạn mua kèm chuột không dây có thể giảm thêm 50.000đ nữa ạ."},{"speaker":"client","text":"Thế không được thì thôi, mình xem lại sau vậy. Cảm ơn nhé!"}]','fail',850),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc đồng hồ Casio Edifice EFR-S567D-1A2V. Bạn có sẵn không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Chiếc này còn mới 100%, giá niêm yết 2.990.000đ. Bạn muốn giao trong tuần hay nhận tại cửa hàng?"},{"speaker":"client","text":"Mình ở xa nên giao tận nơi được không? Tiền ship bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giao tận nơi được ạ! Ship nội thành 30.000đ, ngoại thành 50.000đ. Nếu bạn đặt trong hôm nay, mình sẽ giảm 5% giá sản phẩm luôn nhé!"},{"speaker":"client","text":"Vậy giảm còn bao nhiêu? Mình lấy luôn 1 cái nhé."},{"speaker":"salebot","text":"Dạ còn 2.840.500đ thôi ạ (giá sản phẩm 2.830.000đ + ship 10.500đ). Bạn để lại số điện thoại và địa chỉ nhé, mình xử lý đơn ngay!"}]','successs',851),
('[{"speaker":"client","text":"Chào shop! Mình nhìn thấy túi xách da giả Gucci trên web, nhưng giá 12 triệu hơi cao quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ em rất tiếc ạ, sản phẩm này là hàng xách tay nên không giảm giá được ạ. Nhưng mình có ưu đãi ship 0đ cho đơn trên 5 triệu đó!"},{"speaker":"client","text":"Thế 10 triệu được không? Mình lấy luôn 2 cái!"},{"speaker":"salebot","text":"Em xin lỗi ạ, mức giá này là cố định rồi. Nếu không ưng thì em có thể giới thiệu mẫu túi da tổng hợp giá 7 triệu 500k ạ!"},{"speaker":"client","text":"Thôi được, mình không mua nữa. Cảm ơn nhé!"}]','fail',852),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc điện thoại Samsung Galaxy A54 5G, bạn có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ, màu đen và xanh dương vẫn còn. Bạn muốn đặt luôn không?"},{"speaker":"client","text":"Mình thấy giá 12 triệu hơi cao, có thể giảm cho mình không?"},{"speaker":"salebot","text":"Dạ 11.5 triệu cho bạn được rồi, kèm theo quà tặng là sạc nhanh 25W."},{"speaker":"client","text":"Mình không chắc, để mình nghĩ thêm. Cảm ơn nhé!"}]','fail',853),
