('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn phím cơ Keychron K8 trên web có vẻ ổn, nhưng giá 2.499.000 hơi đắt quá nhỉ?"},{"speaker":"salebot","text":"Dạ, giá niêm yết là vậy nhưng hôm nay mình có ưu đãi giảm 10% cho đơn từ 2 triệu ạ! Còn 2.249.000 thôi ạ."},{"speaker":"client","text":"Thế giao hàng trong bao lâu vậy? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ, trong nội thành giao trong 2-4 tiếng ạ, nếu bạn chọn ship nhanh thì chỉ 1-2 tiếng thôi!"},{"speaker":"client","text":"Ok, mình chọn màu bạc nhé. Đặt luôn đây ạ."},{"speaker":"salebot","text":"Dạ cảm ơn bạn! Đơn hàng đã được ghi nhận, mình sẽ gửi mã tracking qua Zalo ngay ạ."}]','successs',872),
('[{"speaker":"client","text":"Chào shop, mình đang tìm mua một chiếc túi xách da thật cho vợ. Giá khoảng 3 triệu thôi được không?"},{"speaker":"salebot","text":"Dạ chào chị, túi da thật tầm 3 triệu thường là loại da bò non ạ. Shop có mẫu túi da bò nhập khẩu Đài Loan giá 2.8 triệu, chị thấy sao?"},{"speaker":"client","text":"2.8 triệu hơi sát rồi, mình có thể trả 2.5 triệu không? Mua luôn 2 cái luôn đó."},{"speaker":"salebot","text":"Dạ không ạ, giá sỉ tối thiểu 2.6 triệu cho 2 cái chị ơi. Miễn phí ship và tặng túi chống xước nha."},{"speaker":"client","text":"Thôi được, vậy ship trong 2 ngày được không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ không ạ, ship nhanh nhất là 3 ngày do hàng da nhập khẩu. Nếu chị chọn giao thường thì 2 ngày ạ."},{"speaker":"client","text":"Ôi tiếc quá, vậy thôi. Cảm ơn shop nhé!"}]','fail',873),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc lò nướng bánh đa năng Philips HD6060/00, còn hàng không ạ? Mình thấy trên web ghi khuyến mại 30% nhưng khi check ra không thấy giảm giá nữa."},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em xin lỗi vì sự bất tiện này. Thực tế sản phẩm hiện đang khuyến mại 30% đến hết ngày mai, anh/chị có thể check lại đơn hàng để xác nhận ưu đãi nhé!"},{"speaker":"client","text":"À vậy à, mình check lại rồi. Nhưng mình thấy giá trên web vẫn cao hơn bên Shopee 500k. Bên mình có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, giá chúng em đã cố gắng tối ưu nhất rồi ạ. Nhưng vì sản phẩm mới ra mắt nên chưa thể giảm sâu hơn. Nếu anh/chị mua kèm lò nướng mini Philips HD7769/00 (giá 1.2tr), em có thể giảm thêm 100k cho combo ạ!"},{"speaker":"client","text":"Ok, mình đồng ý combo đi. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ giao trong 2-3 ngày làm việc ạ! Anh/chị có thể chọn giao tận nơi hoặc đến lấy tại cửa hàng gần nhất. Em sẽ gửi mã giảm giá 100k vào tin nhắn sau khi thanh toán ạ!"}]','successs',874),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000. Có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Chào chị ạ! Hiện tại sản phẩm đang có chương trình khuyến mại 20% nếu chị đặt trong hôm nay. Chị muốn mua màu nào ạ?"},{"speaker":"client","text":"Mình thích màu trắng. Nhưng giá 1.290.000 còn hơi cao, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ chị ơi, đây là mức giá tốt nhất rồi ạ. Nhưng nếu chị mua kèm viên pin dự phòng (giá 150k) thì mình sẽ tặng luôn 1 bộ đầu bàn chải thay thế nữa!"},{"speaker":"client","text":"Thế à? Hay quá! Vậy mình lấy luôn bộ đó luôn. Ship trong bao lâu vậy?"},{"speaker":"salebot","text":"Dạ ship nội thành 2-3 ngày, ngoại thành 3-5 ngày ạ. Chị có thể chọn nhận hàng tận nơi hoặc đến lấy tại cửa hàng gần nhất. Chị chọn cách nào ạ?"},{"speaker":"client","text":"Mình nhận hàng tận nơi thôi. Cảm ơn bạn nhiều nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc chị có trải nghiệm chăm sóc răng miệng tuyệt vời cùng Oral-B. Hẹn gặp chị ạ!"}]','successs',875),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc áo khoác này của thương hiệu North Face, nhưng nhìn thấy giá hơi cao so với ngân sách của mình. Bạn có thể giảm giá được không?"},{"speaker":"salebot","text":"Dạ chào bạn ạ! Chiếc áo khoác North Face này đang được giảm 20% trong tuần lễ khuyến mại, giá chỉ còn 2.400.000đ thôi ạ. Nếu bạn đặt trước 30 phút nữa, mình có thể tặng thêm 1 chiếc tất thể thao miễn phí!"},{"speaker":"client","text":"Thế à? Mình thấy hợp lý hơn rồi. Nhưng mình chỉ có 2.200.000đ thôi. Bạn có thể giảm thêm chút không?"},{"speaker":"salebot","text":"Dạ thật tiếc, giá đã là ưu đãi nhất rồi ạ. Nhưng nếu bạn mua kèm chiếc mũ cùng thương hiệu, mình sẽ giảm thêm 50.000đ nữa cho bạn nhé!"},{"speaker":"client","text":"Được rồi, mình lấy cả bộ luôn. Vậy giao hàng trong bao lâu ạ?"},{"speaker":"salebot","text":"Dạ giao tận nhà trong 2-3 ngày ạ! Bạn có thể thanh toán qua momo, vnpay hoặc chuyển khoản đều được ạ. Cảm ơn bạn đã ủng hộ!"}]','successs',876),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn phím cơ Keychron K3, có màu trắng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! K3 màu trắng vẫn còn hàng, giao hàng miễn phí trong 24h nếu bạn ở TPHCM."},{"speaker":"client","text":"À mình ở Đà Nẵng, phí ship thế nào vậy?"},{"speaker":"salebot","text":"Dạ phí ship từ 30k-50k tùy theo trọng lượng, mình gửi bảng chi tiết qua tin nhắn nhé?"},{"speaker":"client","text":"Ok, mình chọn màu trắng nhé. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.990.000đ, nhưng hôm nay tặng kèm bàn chải vệ sinh phím miễn phí luôn ạ!"},{"speaker":"client","text":"Vậy mình lấy 1 cái, ship tận nơi luôn nhé. Cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Đơn hàng của bạn đã được xác nhận, chúc bạn một ngày vui vẻ!"}]','successs',877),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác thể thao này nhưng giá 1 triệu 2 có hơi đắt không nhỉ?"},{"speaker":"salebot","text":"Dạ khách thân thiết ạ, hôm nay mình có ưu đãi giảm 10% cho sản phẩm này, còn 1 triệu 80k thôi ạ!"},{"speaker":"client","text":"Ồ vậy thì ok, mình lấy luôn. Địa chỉ giao là 123 Lê Lai, Quận 1, TP.HCM nhé!"},{"speaker":"salebot","text":"Dạ mình ghi nhận đơn hàng ạ! Cảm ơn khách đã ủng hộ, chúc khách vui vẻ!"}]','successs',878),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua áo khoác mùa đông cho bé gái 10 tuổi, size 140. Bạn có mẫu nào phù hợp không?"},{"speaker":"salebot","text":"Dạ chào chị! Chúng tôi có mẫu áo khoác chống gió chống thấm ấm áp, màu hồng pastel size 140. Giá niêm yết 990k, hôm nay sale 10% còn 890k thôi ạ."},{"speaker":"client","text":"Mà mình thấy trên mạng có nơi bán 850k, bạn có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, giá chúng tôi đã ưu đãi rồi ạ. Nếu chị mua kèm mũ len size 140 nữa thì mình giảm thêm 20k cho cả bộ nhé?"},{"speaker":"client","text":"Ok, vậy mình lấy bộ áo + mũ luôn. Bao giờ giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu chị ở nội thành, chị vui lòng cung cấp địa chỉ để mình báo ship ạ!"}]','successs',879),
