('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao cho bé gái 12 tuổi. Có size từ 150-160 không?"},{"speaker":"salebot","text":"Dạ có ạ! Set áo thun + quần nỉ size 150-160 đang khuyến mại 300k, bạn muốn màu gì?"},{"speaker":"client","text":"Màu xanh dương và hồng có không? Mình thích tông nhạt thôi."},{"speaker":"salebot","text":"Dạ xanh dương hết size 160 rồi ạ, chỉ còn hồng size 150 thôi. Nếu bạn chờ 2 ngày có thể order size 160."},{"speaker":"client","text":"Hết size rồi à? Giá có giảm được không? Mình thấy bên kia bán 250k thôi."},{"speaker":"salebot","text":"Dạ 300k là giá sốc rồi ạ, nhưng nếu bạn lấy 2 set trở lên thì giảm còn 280k/set. Bên kia chắc chưa tính phí ship?"},{"speaker":"client","text":"Ừ, mình chỉ lấy 1 set thôi. Thôi không mua nữa, cảm ơn nhé!"}]','fail',929),
('[{"speaker":"client","text":"Chào em, mình muốn mua chiếc váy đầm này nhưng nhìn giá hơi cao quá. Bao nhiêu tiền vậy?"},{"speaker":"salebot","text":"Dạ chị ơi, sản phẩm này đang khuyến mại 20% còn 1.200.000đ thôi ạ. Chất liệu vải lụa nhập khẩu nên giá thế là hợp lý lắm chị nhỉ?"},{"speaker":"client","text":"1.2 triệu à? Mình thấy bên shop khác có cùng mẫu rẻ hơn 300k cơ. Có thể giảm nữa không?"},{"speaker":"salebot","text":"Dạ em xin lỗi chị, giá đã chiết khấu tối đa rồi ạ. Nếu chị mua kèm phụ kiện trang sức đi kèm thì em có thể tặng quà nhỏ ạ!"},{"speaker":"client","text":"Thôi được, mình không mua nữa. Cảm ơn nhé!"}]','fail',930),
('[{"speaker":"client","text":"Chào em, mình thấy cái bàn làm việc này đẹp quá! Còn hàng không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Bàn này còn hàng nha, màu gỗ tự nhiên và đen đều có. Giảm 10% nếu anh/chị mua trong hôm nay luôn!"},{"speaker":"client","text":"Mình thấy giá 2 triệu hơi đắt, có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ anh/chị thông cảm, giá gốc đã ưu đãi lắm rồi ạ! Nhưng được thôi, mình giảm xuống 1.8 triệu nha, kèm quà tặng là bộ dụng cụ vệ sinh bàn."},{"speaker":"client","text":"Thế giao tận nơi được chứ? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ được ạ! Phí ship 30k, tổng 1.83 triệu, giao trong 2 tiếng. Anh/chị xác nhận nhé?"},{"speaker":"client","text":"Ok, mình lấy vậy. Địa chỉ: 123 đường Nguyễn Văn Linh, quận 7. Cảm ơn nhé!"},{"speaker":"salebot","text":"Dạ cảm ơn anh/ch chị đã mua hàng! Đơn hàng sẽ được xử lý ngay. Chúc anh/chị một ngày tốt lành!"}]','successs',931),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua bộ quần áo thể thao nữ của Nike, size M có không ạ? Mình thấy trên web có giảm giá 30% nhưng chưa rõ còn hàng không."},{"speaker":"salebot","text":"Dạ có ạ! Size M vẫn còn đủ size, em kiểm tra thấy bạn may mắn được giảm 30% luôn nè. Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Mình thích màu xanh navy và hồng, nhưng màu hồng có size M không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Màu hồng size M còn 3 chiếc, bạn muốn đặt luôn không? Nếu đặt trong 2 giờ nữa sẽ được free ship nha."},{"speaker":"client","text":"Ok mình chọn màu hồng, ship tới 123 Lê Lợi, quận 1, mình trả tiền mặt khi nhận hàng nhé."},{"speaker":"salebot","text":"Dạ vâng ạ! Đơn hàng đã được xác nhận, bạn sẽ nhận hàng trước 8h tối nay. Cảm ơn bạn đã mua sắm cùng chúng tôi!"}]','successs',932),
('[{"speaker":"client","text":"Chào em, mình thấy chiếc bàn phím cơ Keychron K8 có ưu đãi gì không? Mình đang phân vân giữa màu xám và đen."},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Hiện Keychron K8 màu xám đang giảm 10% còn 1.890.000đ, màu đen 100% thôi ạ. Anh/chị muốn đặt màu nào?"},{"speaker":"client","text":"Mình thích màu xám nhưng giá hơi cao. Bên em có thể giảm thêm không? Mình thấy shop khác bán 1.750.000đ."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ! Đó là giá sốc của shop khác thôi ạ, em không thể giảm thêm được ạ. Nhưng giao nhanh trong 2h, anh/chị có thể nhận ngay hôm nay."},{"speaker":"client","text":"Thôi được, mình chọn màu xám vậy. Nhưng giao hàng muộn quá mình không nhận đâu nhé."},{"speaker":"salebot","text":"Dạ em cảm ơn anh/chị ạ! Đơn hàng sẽ được giao trong 1-2h nữa ạ. Chúc anh/chị một ngày tốt lành!"}]','fail',933),
('[{"speaker":"client","text":"Chào bot! Mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Giá niêm yết là 1.890.000đ, nhưng hôm nay có khuyến mại 10% nếu chị thanh toán qua ví MoMo ạ!"},{"speaker":"client","text":"Ồ, vậy giá còn 1.700.000đ thôi hả? Có bảo hành không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Bảo hành chính hãng 2 năm, kèm quà tặng là 2 đầu bàn chải thay thế. Chị có muốn đặt luôn không ạ?"},{"speaker":"client","text":"Ok, mình lấy 1 chiếc. Địa chỉ giao là 123 Lê Lợi, Q.1, TP.HCM."},{"speaker":"salebot","text":"Dạ chị vui lòng chuyển khoản 1.700.000đ qua số tài khoản 123456789 (Techcombank) nhé. Cảm ơn chị đã mua sắm cùng shop!"}]','successs',934),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua đồng hồ Casio A168WG-1AVDF, có còn hàng không ạ?"},{"speaker":"salebot","text":"Dạ chào chị! Đúng rồi ạ, sản phẩm này còn hàng. Chị muốn mua kiểu dáng hay màu sắc nào ạ?"},{"speaker":"client","text":"Mình thích kiểu dáng này rồi, nhưng giá niêm yết 1.200.000đ hơi cao, có giảm giá không?"},{"speaker":"salebot","text":"Dạ chị thông cảm, giá niêm yết là 1.200.000đ nhưng hôm nay có khuyến mại 5%, còn 1.140.000đ thôi ạ!"},{"speaker":"client","text":"Ok, mình nhận vậy. Bạn có giao hàng tận nơi không?"},{"speaker":"salebot","text":"Dạ có ạ! Chị cứ nhập địa chỉ, phí ship 20.000đ thôi ạ. Chị có muốn thanh toán COD không?"},{"speaker":"client","text":"Được, mình chọn COD nhé. Cảm ơn bạn!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Chúc chị vui vẻ, hẹn gặp lại!"}]','successs',935),
('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc áo khoác thể thao này, nhưng giá 1.200k hơi đắt quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, sản phẩm này đang khuyến mại 5% nếu bạn mua trong hôm nay, còn 1.140k thôi ạ!"},{"speaker":"client","text":"1.140k vẫn hơi cao, mình thấy bên shop khác bán 1.050k. Bạn có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ, chúng tôi không giảm thêm được nữa ạ. Nhưng giao hàng miễn phí trong 2h, tiện lợi lắm ạ!"},{"speaker":"client","text":"Thôi, thôi... để mình suy nghĩ thêm. Cảm ơn nhé!"}]','fail',936),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc laptop gaming ASUS TUF Gaming A15. Có hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Cấu hình AMD Ryzen 7 6800H, 16GB RAM, 512GB SSD, còn 2 sản phẩm cuối cùng. Bạn muốn giao trong ngày không?"},{"speaker":"client","text":"Mình thấy giá niêm yết 28 triệu, có thể giảm cho mình không? Mình thấy shop khác có giá 26 triệu."},{"speaker":"salebot","text":"Dạ ạ, vì đây là sản phẩm cuối cùng nên mình có thể giảm xuống 27 triệu thôi được không ạ? Đi kèm tặng mouse gaming luôn."},{"speaker":"client","text":"Ok, vậy giao trong hôm nay được không? Mình ở quận 1."},{"speaker":"salebot","text":"Dạ được ạ! Bạn cung cấp địa chỉ cụ thể và số điện thoại để mình xác nhận đơn hàng nhé."}]','successs',937),
('[{"speaker":"client","text":"Chào bot! Mình thấy cái bàn học thông minh Xiaomi Smart Study Desk 2 Pro có giảm giá không vậy? Mình đang phân vân mua."},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện sản phẩm đang ưu đãi 15% cho đơn hàng đầu tiên, giá còn 5.990.000đ (giá gốc 7.000.000đ). Chị muốn mua màu nào ạ?"},{"speaker":"client","text":"Ui 15% cũng được đấy. Nhưng mình thấy giá hơi cao, có thể giảm thêm được không bot?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, mức giảm này đã là ưu đãi tối đa từ nhà sản xuất rồi ạ. Ngoài ra nếu chị đặt qua app thì còn được tặng kèm bàn ghế gấp gọn trị giá 500.000đ nữa ạ!"},{"speaker":"client","text":"Hmm, thế không được. Thôi mình nghĩ lại rồi, cảm ơn bot nhé!"}]','fail',938),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn chải điện Oral-B Genius X, có hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Chúng mình còn hàng phiên bản trắng và đen, giao tận nhà miễn phí nếu đơn trên 500k nha!"},{"speaker":"client","text":"À, giá niêm yết 2.5 triệu, giờ có giảm không? Mình thấy bên khác bán 2.2 triệu thôi."},{"speaker":"salebot","text":"Dạ anh/chị thông cảm ạ, giá niêm yết đã là tốt nhất rồi. Nhưng nếu anh/chị nhận hàng hôm nay, mình sẽ tặng luôn 1 lọ nước súc miệng trị giá 150k ạ!"},{"speaker":"client","text":"Hmm, thế nếu mình mua combo luôn 2 bàn chải + 3 đầu thay thế thì sao?"},{"speaker":"salebot","text":"Dạ combo 2 bàn chải + 3 đầu thay thế giá 4.2 triệu ạ! Rẻ hơn 300k so với mua lẻ, anh/chị thấy sao?"},{"speaker":"client","text":"Ok, vậy giao vào chiều nay được không? Mình cần gấp lắm."},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị để lại số điện thoại và địa chỉ, mình sẽ xử lý đơn hàng ngay!"}]','successs',939),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc áo khoác mùa đông cho bé gái 10 tuổi. Size 140 có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Hiện tại bên mình có mẫu áo khoác chống thấm gió với giá 499k. Bé nhà bạn thích màu gì ạ?"},{"speaker":"client","text":"Màu hồng nhạt ấy, nhưng giá hơi cao nhỉ? Có giảm được không?"},{"speaker":"salebot","text":"Dạ em kiểm tra khuyến mại cho bạn nhé! Nếu bạn mua trong hôm nay thì mình giảm còn 449k thôi ạ."},{"speaker":"client","text":"Ok, vậy mình lấy 1 cái màu hồng size 140 nhé. Ship tận nhà luôn chứ?"},{"speaker":"salebot","text":"Dạ đúng rồi ạ! Chúng mình sẽ giao trong vòng 2 giờ nếu bạn ở nội thành. Cảm ơn bạn đã mua hàng!"}]','successs',940),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm cái bàn học gỗ cho bé 6 tuổi, có kích thước nhỏ gọn không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn, bàn gỗ thông đỏ mini 60x40cm thì sao ạ? Màu sắc có trắng, nâu gỗ và xanh dương."},{"speaker":"client","text":"Mình thấy hơi mỏng, chắc chắn không? Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ sản phẩm chịu tải 30kg, 100% gỗ thông đỏ, giá 1.290.000đ ạ. Nếu mua kèm ghế gỗ thì giảm 50k."},{"speaker":"client","text":"Ồ, đắt quá! Có giảm được không? Mình thấy bên kia bán 950k thôi."},{"speaker":"salebot","text":"Dạ giá sốc 990k nha bạn, mình không thể giảm hơn vì giá nhập từ xưởng ạ. Có miễn phí giao hàng nội thành không?"},{"speaker":"client","text":"Thôi vậy, cảm ơn nhé! Mình suy nghĩ lại đã."}]','fail',941),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc máy xay sinh tố này. Có giảm giá gì không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Máy xay sinh tố này hiện đang có chương trình giảm 15% nếu mua trong hôm nay, kèm theo quà tặng là cốc thủy tinh cao cấp."},{"speaker":"client","text":"Mình thấy giá niêm yết 2.500.000, vậy giảm xong còn bao nhiêu?"},{"speaker":"salebot","text":"Dạ sau khi giảm giá, sản phẩm còn 2.125.000 đồng ạ. Anh/chị có muốn mình hỗ trợ đặt hàng luôn không ạ?"},{"speaker":"client","text":"À mình nghĩ vậy hơi đắt, có thể giảm thêm không? Mình thấy nơi khác bán 1.950.000."},{"speaker":"salebot","text":"Dạ thật tiếc ạ, đây là giá tốt nhất từ nhà sản xuất. Nhưng nếu anh/chị mua 2 sản phẩm sẽ giảm thêm 5% nữa ạ!"},{"speaker":"client","text":"Thế à, mình chỉ cần 1 thôi. Thôi được, mình quyết định không mua nữa. Cảm ơn bạn nhé!"}]','fail',942),
