('[{"speaker":"client","text":"Chào bot, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, mình thấy nó khá đắt nhỉ?"},{"speaker":"salebot","text":"Dạ, giá niêm yết 2.490.000đ nhưng hôm nay có khuyến mại 20% còn 1.990.000đ thôi ạ!"},{"speaker":"client","text":"Hơi mắc so với mình, có giảm nữa không? Mình thấy bên kia bán 1.750.000đ kìa."},{"speaker":"salebot","text":"Dạ chúng em không thể giảm thêm được rồi ạ, nhưng kèm theo quà tặng là 3 đầu bàn chải thay thế nữa nè!"},{"speaker":"client","text":"Thôi được, ship tận nhà miễn phí chứ? Chứ mình không có thời gian ra bưu cục."},{"speaker":"salebot","text":"Dạ có ạ, giao tận nơi miễn phí, mình chỉ cần thanh toán online hoặc COD là được."},{"speaker":"client","text":"Thôi thôi, thôi mình không mua nữa đâu, cảm ơn nhé!"}]','fail',948),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua áo khoác mùa đông cho bé gái 12 tuổi. Có size 14-15 không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Size 14-15 vẫn còn 3 mẫu, bạn thích màu gì ạ? Màu hồng pastel hay xanh navy?"},{"speaker":"client","text":"Mình thích màu xanh navy thôi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 899k, nhưng hôm nay có khuyến mại 10% nếu mua online. Còn 809k thôi ạ!"},{"speaker":"client","text":"Hơi đắt quá, mình thấy bên kia bán 750k thôi. Có giảm nữa không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã là tốt nhất rồi. Nếu bạn mua 2 áo thì em có thể giảm thêm 5% nữa ạ!"},{"speaker":"client","text":"Thôi không mua nữa, cảm ơn bạn nhé!"}]','fail',949),
('[{"speaker":"client","text":"Chào shop, cho mình hỏi em laptop Asus Vivobook S14 có giảm giá không vậy? Mình thấy trên mạng giá chênh lệch quá trời."},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện bên mình đang có chương trình khuyến mại 5% cho sản phẩm này, giao hàng tận nơi miễn phí trong 24h nếu chị đặt hôm nay."},{"speaker":"client","text":"5% thôi à? Mình thấy chỗ kia bán có 10% cơ. Hay là shop có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, mức giá đã được niêm yết theo chính sách của hãng rồi ạ. Nhưng nếu chị mua kèm chuột không dây thì mình có thể tặng thêm túi đựng miễn phí ạ!"},{"speaker":"client","text":"Thế à... thôi được, mình cân nhắc đã. Cảm ơn nhé!"}]','fail',950),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác da nữ hiệu Zara này. Size S có không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size S vẫn còn 5 sản phẩm. Bạn muốn màu đen hay nâu?"},{"speaker":"client","text":"Mình thích màu đen nhưng giá 2.490.000₫ hơi đắt quá. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ thưa bạn, hôm nay là ngày 11/11 nên shop có ưu đãi 10% cho sản phẩm này. Còn 2.241.000₫ thôi ạ."},{"speaker":"client","text":"10% cũng không đủ. Mình thấy shop khác bán giá 1.990.000₫ kia. Nếu shop giảm 15% mình sẽ mua ngay."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, mức giá này shop không thể giảm thêm được rồi. Bù lại shop giao miễn phí toàn quốc và đổi trả trong 30 ngày ạ."},{"speaker":"client","text":"Thôi vậy, mình không mua nữa. Cảm ơn nhé!"}]','fail',951),
('[{"speaker":"client","text":"Chào bot, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000. Có hàng không vậy?"},{"speaker":"salebot","text":"Chào chị ạ! Dạ có ạ, hiện tại sản phẩm này đang có sẵn cả phiên bản trắng và đen. Chị muốn giao trong ngày hay nhận tại cửa hàng?"},{"speaker":"client","text":"Mình ở quận 1, giao trong ngày được không? Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ được ạ! Giao trong ngày miễn phí nếu đơn trên 500k. Giá niêm yết là 2.499.000đ, nhưng hôm nay có khuyến mãi giảm còn 2.299.000đ thôi chị."},{"speaker":"client","text":"Hơi đắt nhỉ, có thể giảm thêm không? Mình thấy bên kia bán 2.150.000đ đấy."},{"speaker":"salebot","text":"Dạ chị thông cảm, giá này đã ưu đãi lắm rồi ạ. Nếu chị mua kèm viên tẩy mảng bám (99k) thì mình giảm thêm 50k cho chị nhé?"},{"speaker":"client","text":"Thôi được, mình lấy luôn cả viên tẩy đi. Địa chỉ giao là 123 Lê Lợi, quận 1, số điện thoại 0901234567."},{"speaker":"salebot","text":"Dạ chị vui lòng ạ! Đơn hàng sẽ giao trong 2-3 tiếng tới ạ. Cảm ơn chị đã ủng hộ!"}]','successs',952),
('[{"speaker":"client","text":"Chào bot, mình thấy cái bàn ghế gỗ óc chó này đẹp quá. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ, bộ bàn ghế gỗ óc chó 4 ghế giá 12 triệu ạ, giao hàng tận nơi miễn phí trong bán kính 10km."},{"speaker":"client","text":"Ôi, đắt quá! Em giảm cho mình còn 10 triệu đi, mình thấy trên mạng rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ, 10 triệu hơi thấp ạ, chỗ mình bán nguyên liệu gỗ óc chó cao cấp nên giá hơi cao. Em có thể giảm xuống 11 triệu 500k, mình giao kèm khăn trải bàn miễn phí nha!"},{"speaker":"client","text":"11 triệu 500k vẫn hơi cao, mình chỉ có 11 triệu thôi. Thôi thôi, để mình suy nghĩ lại vậy."},{"speaker":"salebot","text":"Dạ, không sao ạ! Nếu quyết định mua, em vẫn giữ giá 11 triệu 500k cho bạn trong hôm nay nha. Cảm ơn bạn đã quan tâm!"}]','fail',953),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra 5G giảm giá khá nhiều trên web. Bạn có thể tư vấn giúp mình không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em thấy anh/chị quan tâm đến Galaxy S23 Ultra. Hiện sản phẩm đang giảm giá 15% chỉ còn 22 triệu đồng thôi ạ!"},{"speaker":"client","text":"22 triệu à? Mình nghe nói giá gốc là 28 triệu mà nhỉ? Có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ anh/chị thông thái quá! Em check lại thì giá gốc là 25 triệu, giảm còn 22 triệu ạ. Nếu anh/chị mua kèm ốp lưng khuyến mại, em có thể giảm thêm 500k nữa ạ!"},{"speaker":"client","text":"Thế à? Được rồi, mình lấy luôn đi. Ship trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Anh/chị vui lòng cung cấp địa chỉ và số điện thoại để em xử lý đơn hàng nhanh nhất ạ. Cảm ơn anh/chị đã mua sắm cùng shop!"}]','successs',954),
('[{"speaker":"client","text":"Chào bạn, mình đang cần mua một chiếc bàn phím cơ cho công việc văn phòng. Bạn có thể giới thiệu sản phẩm tốt nhất không?"},{"speaker":"salebot","text":"Dạ chào anh/chị! Em giới thiệu bàn phím cơ Keychron K8, có switch Gateron màu nâu, chống ồn tốt và bền bỉ ạ!"},{"speaker":"client","text":"À vậy giá bao nhiêu vậy? Đắt quá thì mình không mua đâu."},{"speaker":"salebot","text":"Dạ giá niêm yết 1.890.000đ, nhưng hôm nay em có khuyến mãi giảm 10% cho khách hàng mới ạ!"},{"speaker":"client","text":"Giảm 10% vẫn còn hơi cao. Bạn có thể giảm thêm không? Tối đa 1.500.000đ thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi, mức giá này đã là ưu đãi nhất rồi ạ. Nếu anh/chị mua kèm chuột không dây Keychron M1 thì em giảm thêm 50k nữa ạ!"},{"speaker":"client","text":"Thôi vậy cũng được, nhưng giao hàng trong 2 ngày có được không? Mình cần gấp."},{"speaker":"salebot","text":"Dạ em xin lỗi, giao hàng trong ngày hôm nay thôi ạ. Nếu anh/chị đặt ngay giờ này thì nhận được vào tối nay luôn ạ!"},{"speaker":"client","text":"Thôi vậy thôi, mình không tiện nhận hàng tối nay. Cảm ơn bạn nhé!"}]','fail',955),
('[{"speaker":"client","text":"Chào bạn, mình thấy bàn ghế gỗ lim này đẹp quá! Cái ghế có mấy màu vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Bàn ghế gỗ lim này có 3 màu: nâu sẫm, nâu nhạt và vàng nhạt. Anh/chị thích màu nào nhất?"},{"speaker":"client","text":"Mình thích màu nâu nhạt. Giá bao nhiêu vậy? Có giảm giá không?"},{"speaker":"salebot","text":"Dạ giá niêm yết là 12 triệu, nhưng hôm nay có chương trình khuyến mại giảm 10% cho đơn hàng đầu tiên. Còn 11 triệu 800k thôi ạ!"},{"speaker":"client","text":"Hơi đắt so với mình. Bạn có thể giảm thêm không? 10 triệu 500k được không?"},{"speaker":"salebot","text":"Dạ anh/chị thật sự quan tâm sản phẩm quá! Vì anh/chị là khách hàng đầu tiên hôm nay, mình giảm thêm 200k nữa nhé! Còn 10 triệu 600k, mình giao tận nhà luôn ạ!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn! Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ anh/chị đặt giờ này là 14h30, mình cam kết giao trước 18h hôm nay ạ! Cảm ơn anh/chị đã mua hàng!"}]','successs',956),
('[{"speaker":"client","text":"Chào! Mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Bao gồm 1 bàn chải, 1 đầu chải và hộp sạc. Bạn muốn chọn màu nào ạ?"},{"speaker":"client","text":"Màu xanh dương được không? Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 2.490.000đ ạ, nhưng hôm nay có giảm còn 2.290.000đ nếu bạn đặt ngay!"},{"speaker":"client","text":"Ôi, hơi đắt quá. Bạn giảm thêm được không? Tối đa 2 triệu thôi."},{"speaker":"salebot","text":"Dạ không ạ, giá đã chiết khấu rồi. Nhưng nếu bạn mua kèm 2 đầu chải phụ thì tặng 1 lọ nước súc miệng nha!"},{"speaker":"client","text":"Thôi được, vậy mình lấy thôi. Bao lâu giao hàng vậy?"},{"speaker":"salebot","text":"Dạ giao trong 3 ngày ạ. Bạn để lại số điện thoại để nhân viên liên hệ nhé!"}]','fail',957),
('[{"speaker":"client","text":"Chào shop, mình muốn mua đôi giày thể thao Nike Air Max 90, nhưng nhìn thấy giá hơi cao. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn, đôi Air Max 90 hiện tại đang có khuyến mại 15% nếu bạn thanh toán bằng thẻ ngân hàng trong hôm nay."},{"speaker":"client","text":"Thế giá cuối cùng là bao nhiêu? Mình thấy trên mạng có nơi bán rẻ hơn 200k."},{"speaker":"salebot","text":"Dạ giá gốc 2.490.000đ, sau khuyến mại còn 2.116.500đ, giao hàng miễn phí trong 24h. Chúng mình cam kết hàng chính hãng 100%."},{"speaker":"client","text":"Ôi, 2 triệu rưỡi vẫn hơi đắt so với mình. Thôi mình nghĩ lại đã, cảm ơn nhé!"}]','fail',958),
('[{"speaker":"client","text":"Chào em, mình thấy đôi giày thể thao Nike Air Max 90 trên web đang giảm giá 30%. Còn size 40 không em?"},{"speaker":"salebot","text":"Dạ chào anh! Size 40 vẫn còn ạ. Giá gốc 3 triệu, giờ chỉ còn 2,1 triệu thôi!"},{"speaker":"client","text":"Ồ, vậy có thể ship tận nhà không? Mình ở quận 7."},{"speaker":"salebot","text":"Dạ có ạ! Ship nội thành 25k, giao trong 2-3 giờ. Anh muốn thanh toán COD hay chuyển khoản?"},{"speaker":"client","text":"COD được không? Mình thích kiểm tra hàng trước."},{"speaker":"salebot","text":"Dạ được ạ! Anh vui lòng để lại số điện thoại và địa chỉ chi tiết nhé. Cảm ơn anh đã mua sắm cùng shop!"}]','successs',959),
('[{"speaker":"client","text":"Chào shop! Mình cần mua một chiếc điện thoại tầm 10 triệu thôi. Có mẫu nào xịn xịn không?"},{"speaker":"salebot","text":"Dạ chào anh! Em có Samsung Galaxy A34 5G giá 9,99 triệu, chip Snapdragon 695, màn hình AMOLED 120Hz, pin 5000mAh. Anh thích không?"},{"speaker":"client","text":"Cái A34 này có màu gì thế? Mình thích màu xanh dương."},{"speaker":"salebot","text":"Dạ anh ơi, màu xanh dương (Awesome Graphite) đang hết hàng ạ, nhưng màu xanh lá (Awesome Mint) và đen (Awesome Black) vẫn còn. Anh xem qua ảnh mẫu nhé!"},{"speaker":"client","text":"Thế màu đen giá bao nhiêu? Mình thích màu tối tối ấy."},{"speaker":"salebot","text":"Dạ màu đen 10,49 triệu anh nhé, anh có thể trả góp 0% trong 3 tháng. Anh đặt không?"},{"speaker":"client","text":"10 triệu rưỡi hơi đắt, em có thể giảm cho mình không? 9,5 triệu được không?"},{"speaker":"salebot","text":"Dạ anh thông cảm ạ, giá đã niêm yết rồi. Nhưng anh đặt trong hôm nay em bớt 100k cho anh nhé, còn 10,39 triệu thôi!"},{"speaker":"client","text":"Ok, thế mình lấy màu đen. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ anh nhé! Anh để lại số điện thoại và địa chỉ đi ạ?"}]','successs',960),
('[{"speaker":"client","text":"Chào! Mình muốn mua chiếc áo khoác nữ này, nhưng giá 999k hơi cao so với túi tiền mình. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào chị! Chị mua size nào ạ? Hiện tại shop đang có voucher 5% cho đơn trên 800k, chị có thể dùng nhé."},{"speaker":"client","text":"Vậy có thể giảm 10% không? Mình thấy bên kia bán rẻ hơn 100k."},{"speaker":"salebot","text":"Dạ không ạ, giá đã được niêm yết rồi chị ơi. Nhưng chị mua 2 sản phẩm cùng lúc thì giảm thêm 5% nữa nha!"},{"speaker":"client","text":"Thôi vậy thôi, mình chỉ mua cái áo thôi. Để mình suy nghĩ lại vậy."}]','fail',961),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao cho bé gái 10 tuổi. Bé cao 1m35, nặng 30kg. Bé thích màu hồng. Có size phù hợp không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng em có size 12-14 (tương đương 1m30-1m40) cho dòng đồ thể thao trẻ em. Màu hồng thì còn 3 mẫu: áo croptop, quần short và áo hoodie. Chị muốn đặt mẫu nào trước?"},{"speaker":"client","text":"Mình thấy áo croptop đẹp nhất. Giá bao nhiêu vậy? Có giảm giá cho khách sỉ không?"},{"speaker":"salebot","text":"Dạ áo croptop giá 320k, quần short 280k, hoodie 450k. Nếu chị mua full set thì được 950k thay vì 1.050k ạ. Ship nội thành 35k, ngoại thành 55k."},{"speaker":"client","text":"Mình chỉ mua áo thôi. 320k hơi đắt, có thể giảm xuống 280k không? Mình thấy bên shop kia bán 290k."},{"speaker":"salebot","text":"Dạ em xin lỗi chị ạ, giá niêm yết của hãng là 320k, shop em không có chính sách giảm giá riêng. Nhưng nếu chị mua kèm quần short thì em có thể hỗ trợ ship phí ạ."},{"speaker":"client","text":"Thôi được, mình không mua nữa. Cảm ơn nhé!"}]','fail',962),
('[{"speaker":"client","text":"Chào! Mình vừa thấy chiếc áo khoác da này trên web, chất liệu có bền không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Áo khoác da này làm từ da thật 100%, chống xước và bền tới 5 năm nếu bảo quản tốt chị nhé."},{"speaker":"client","text":"Vậy giá bao nhiêu vậy? Mình thấy hơi cao so với mấy chỗ khác."},{"speaker":"salebot","text":"Dạ chị ơi, giá niêm yết là 4.990.000đ, nhưng hôm nay có khuyến mại giảm còn 4.290.000đ thôi ạ. Còn nếu chị đóng thẻ sinh viên thì giảm thêm 5% nữa nè."},{"speaker":"client","text":"Ui, vậy cũng được. Nhưng mình thấy mấy chỗ khác bán 3.8 triệu thôi..."},{"speaker":"salebot","text":"Dạ chị thông cảm, mình cam kết chất lượng da thật 100%, còn mấy chỗ kia có thể là da giả hoặc mỏng lắm ạ. Đi kèm là chế độ bảo hành 1 năm miễn phí sửa chữa chị nhé."},{"speaker":"client","text":"Thế à... Mà mình không có thẻ sinh viên đâu. Thôi thôi, để mình suy nghĩ thêm đi."},{"speaker":"salebot","text":"Dạ không sao ạ! Nếu chị quyết định mua, mình sẽ giữ đơn hàng trong 24h để đảm bảo giá khuyến mại. Chúc chị ngày mới tốt lành!"}]','fail',963),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc bàn phím cơ cho công việc gõ văn bản. Bạn có sản phẩm nào gợi ý không?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Em có bàn phím cơ Keychron K3 siêu nhẹ, bấm êm, phù hợp gõ văn bản lắm ạ. Giá 1.500.000đ, giao trong 2 ngày."},{"speaker":"client","text":"Mình thấy hơi đắt, có giảm giá không? Mình thấy trên shopee giá 1.300.000đ có lắm."},{"speaker":"salebot","text":"Dạ anh/chị ơi, giá này đã ưu đãi lắm rồi ạ. Nếu mua kèm mouse Keychron M3 giá 500k nữa thì em giảm 100k cho anh/chị nha!"},{"speaker":"client","text":"Ok, mình lấy kèm mouse luôn. Địa chỉ giao là 123 Lê Lợi, phường Bến Nghé, quận 1."},{"speaker":"salebot","text":"Dạ em ghi nhận đơn hàng rồi ạ! Tổng tiền 1.900.000đ, giao trong 1-2 ngày. Cảm ơn anh/chị đã mua sắm cùng em ạ!"}]','successs',964),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua lò nướng điện Kangaroo KG5680, giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ chào chị, lò nướng KG5680 đang khuyến mại 1.990.000đ, giảm 200k so với giá niêm yết ạ!"},{"speaker":"client","text":"Ui, hơi đắt so với mình nghĩ. Có giảm nữa không? Mình thấy nơi khác bán 1.850.000đ đấy."},{"speaker":"salebot","text":"Dạ chị thông cảm, đây là giá sốc cuối tuần rồi ạ! Nhưng nếu chị đặt luôn bây giờ, mình tặng thêm khay nướng không dính miễn phí nha!"},{"speaker":"client","text":"Thôi được, mình lấy vậy. Ship tận nhà không? Có bảo hành không?"},{"speaker":"salebot","text":"Dạ có ạ! Ship nội thành 25k, ngoại thành 40k. Bảo hành chính hãng 12 tháng. Em gửi link thanh toán qua ZaloPay luôn nha chị!"}]','successs',965),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho mùa đông này. Còn size S không nhỉ?"},{"speaker":"salebot","text":"Dạ còn ạ! Size S vẫn còn 3 cái, nhưng màu xanh dương và đen thôi. Bạn thích màu nào ạ?"},{"speaker":"client","text":"Màu xanh dương đi. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ 499k ạ, đang khuyến mãi 25% nên còn 374k thôi. Bạn lấy luôn không ạ?"},{"speaker":"client","text":"Ồ, đắt quá nhỉ. Bán 350k được không?"},{"speaker":"salebot","text":"Dạ không ạ, giá sỉ mới được vậy. Còn 360k ạ, mình giao tận nhà luôn!"},{"speaker":"client","text":"Thôi kệ, mình không mua nữa. Cảm ơn nhé!"}]','fail',966),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm kiếm một chiếc bàn làm việc gỗ thông thoáng, giá tầm 3-4 triệu thôi. Có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ có ạ! Bàn gỗ thông 60x120cm giá 3.5 triệu, chất liệu thông mộc tự nhiên, chống mối mọt tốt. Bạn muốn màu gì ạ?"},{"speaker":"client","text":"Mình thích màu nâu nhạt. Có thể giảm giá xuống 3 triệu không? Mình mua luôn hôm nay."},{"speaker":"salebot","text":"Dạ 3.2 triệu em có thể hỗ trợ ạ! Đóng gói miễn phí, giao trong 2h nếu bạn ở TP.HCM. Bạn lấy luôn không ạ?"},{"speaker":"client","text":"Ok, mình lấy. Địa chỉ là 123 Lê Lợi, Quận 1. Bao giờ nhận được hàng?"},{"speaker":"salebot","text":"Dạ đơn hàng của bạn đã được xử lý! Bạn sẽ nhận hàng trước 16h hôm nay. Cảm ơn bạn đã mua sắm cùng shop ạ!"}]','successs',967),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua một chiếc điện thoại chống nước. Bạn có sản phẩm nào tốt không?"},{"speaker":"salebot","text":"Dạ có ạ! Em giới thiệu cho chị chiếc Samsung Galaxy A54 5G, chống nước IP67, giá 8 triệu 500k. Chị thấy thế nào?"},{"speaker":"client","text":"8 triệu rưỡi à? Mà mình thấy trên shopee có giá 8 triệu thôi, bạn có thể giảm được không?"},{"speaker":"salebot","text":"Dạ em có thể giảm xuống 8 triệu 200k cho chị, kèm quà tặng là ốp lưng chống sốc ạ! Có giao ngay luôn."},{"speaker":"client","text":"Ok, vậy mình đặt luôn nhé. Bao lâu thì nhận được hàng?"},{"speaker":"salebot","text":"Chị ở đâu ạ? Nếu nội thành thì 2 tiếng giao tới tận nhà, em sẽ gửi link thanh toán qua zalo cho chị ạ!"}]','successs',968),
('[{"speaker":"client","text":"Chào shop, mình muốn mua bộ quần áo thể thao cho bé 12 tuổi. Bên mình có size 140 không vậy?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Size 140 bên mình vẫn còn, nhưng chỉ có màu xanh dương thôi chị nhỉ."},{"speaker":"client","text":"À, bé nhà mình thích màu đỏ hơn. Có thể đổi size sau không hay bắt buộc mặc vào?"},{"speaker":"salebot","text":"Dạ không chị ạ, size 140 chỉ có màu xanh thôi. Màu đỏ thì phải size 130 chị nhé, nhưng size này hết hàng rồi."},{"speaker":"client","text":"Thế à, tiếc quá. Mình sẽ tìm chỗ khác vậy. Cảm ơn nhé!"}]','fail',969),
('[{"speaker":"client","text":"Chào mình, mình đang tìm mua chiếc áo hoodie của thương hiệu Nike, bạn có size L không vậy?"},{"speaker":"salebot","text":"Chào bạn! Dạ, size L vẫn còn 10 chiếc ạ, màu đen và xám đều có sẵn."},{"speaker":"client","text":"Ôi tốt quá! Mình thích màu đen. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ giá gốc 1.299.000đ, nhưng hôm nay sale 20% nên còn 1.039.000đ thôi ạ."},{"speaker":"client","text":"Hơi đắt so với mình, có thể giảm thêm không? Mình thấy shop khác có giá 950k."},{"speaker":"salebot","text":"Dạ em xin phép giảm xuống 999.000đ ạ, đây là giá tốt nhất rồi ạ. Giao hàng miễn phí luôn nha!"},{"speaker":"client","text":"Ok nha, mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, phường Bến Thành, quận 1 nha."},{"speaker":"salebot","text":"Dạ em đã ghi nhận đơn hàng! Cảm ơn bạn đã ủng hộ ạ. Chúc bạn một ngày vui vẻ!"}]','successs',970),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật của thương hiệu Gucci, nhưng giá trên web hơi cao so với mình nghĩ. Có chương trình giảm giá nào không ạ?"},{"speaker":"salebot","text":"Chào chị ạ! Chúng tôi đang có chương trình giảm giá 15% cho sản phẩm túi Gucci series 2023 nếu chị mua trong hôm nay. Ngoài ra, nếu chị thanh toán bằng thẻ ngân hàng của chúng tôi, chị sẽ được tặng 1 chiếc khăn lụa Gucci mini nữa!"},{"speaker":"client","text":"Wow, vậy giá cuối cùng là bao nhiêu thế? Mình chỉ có thể chi tối đa 15 triệu thôi."},{"speaker":"salebot","text":"Dạ, túi Gucci series 2023 giá gốc 18 triệu, sau khi giảm 15% còn 15,3 triệu. Nhưng nếu chị thanh toán bằng thẻ ngân hàng, tổng cộng chỉ 15 triệu thôi ạ (tặng kèm khăn lụa). Chị có muốn mình gửi link thanh toán không?"},{"speaker":"client","text":"Ôi, vậy thì mình quyết định mua luôn! Bao lâu thì nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ, chị sẽ nhận được hàng trong 2-3 ngày làm việc ạ. Mình sẽ gửi mã vận đơn qua email và tin nhắn cho chị ngay sau khi thanh toán thành công. Cảm ơn chị đã mua sắm cùng chúng tôi!"}]','successs',971),
('[{"speaker":"client","text":"Chào bot! Mình đang tìm mua đôi giày thể thao Nike Air Max 90 màu trắng, size 42. Có size này không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Size 42 vẫn còn 3 đôi màu trắng nha. Anh/chị muốn đặt luôn không ạ?"},{"speaker":"client","text":"Mình thấy giá 2,8 triệu hơi cao, có giảm được không? Mình thấy bên shop kia bán 2,5 triệu."},{"speaker":"salebot","text":"Dạ anh/chị thông cảm nha, giá gốc của Nike là 2,9 triệu nhưng hôm nay ưu đãi chỉ còn 2,7 triệu thôi ạ. Nếu anh/chị mua kèm 2 đôi vớ thể thao thì giảm còn 2,6 triệu nha!"},{"speaker":"client","text":"Thế nếu mình lấy luôn 2 đôi giày và 2 đôi vớ thì hết bao nhiêu?"},{"speaker":"salebot","text":"Dạ nếu vậy ạ, 2 đôi giày + 2 đôi vớ là 5,2 triệu thôi ạ. Giao tận nơi miễn phí luôn nha!"},{"speaker":"client","text":"Ok, mình lấy vậy. Địa chỉ giao là 123 Lê Lợi, Phường Bến Thành, Quận 1, TP.HCM. Bao lâu nhận được hàng?"},{"speaker":"salebot","text":"Dạ ạ, trong vòng 2 giờ là anh/chị nhận được hàng nha! Cảm ơn anh/chị đã mua sắm cùng shop ạ!"}]','successs',972),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc áo sơ mi kẻ caro này đẹp quá. Màu xanh dương có còn size L không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size L vẫn còn 5 chiếc. Bạn mặc thử ưng không thì mình tư vấn thêm nhé!"},{"speaker":"client","text":"Mình mặc vừa vặn, nhưng giá 999k hơi đắt nhỉ. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ ạ, hôm nay có deal 15% cho khách hàng mới. Còn 849k thôi ạ! Mua luôn không?"},{"speaker":"client","text":"Ok, mình lấy luôn. Bao lâu giao được?"},{"speaker":"salebot","text":"Dạ giao tận nơi trong 2 ngày ạ. Bạn để lại địa chỉ và sđt để mình xử lý đơn nhé!"}]','successs',973),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc bàn ghế gỗ óc chó cho phòng khách. Bạn có thể tư vấn cho mình không? Mình thích kiểu hiện đại nhưng vẫn sang trọng."},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng tôi có bộ bàn ghế gỗ óc chó kiểu hiện đại 5 chỗ ngồi, màu nâu tự nhiên rất sang trọng. Giá niêm yết 12 triệu, nhưng chị là khách hàng đầu tiên hôm nay nên mình giảm còn 11 triệu nhé!"},{"speaker":"client","text":"11 triệu à? Mình thấy vẫn hơi cao so với mong đợi. Bạn có thể giảm thêm không? Mình chỉ có 10 triệu thôi."},{"speaker":"salebot","text":"Dạ chị thông cảm, sản phẩm gỗ óc chó chất lượng cao nên giá hơi cao. Nhưng vì chị là khách hàng mới, mình giảm xuống 10.5 triệu nhé! Đi kèm là quà tặng là bộ rèm cửa cùng kiểu dáng."},{"speaker":"client","text":"Ok, mình đồng ý 10.5 triệu. Bạn giao trong 3 ngày được không? Mình đang cần gấp."},{"speaker":"salebot","text":"Dạ được chị ạ! Đơn hàng sẽ được giao trong 2 ngày làm việc kèm phiếu bảo hành 12 tháng. Chị vui lòng cung cấp địa chỉ và số điện thoại để mình xác nhận đơn hàng nhé!"}]','successs',974),
('[{"speaker":"client","text":"Chào shop! Mình đang tìm mua máy xay sinh tố loại nào tốt nhất trong tầm 3 triệu vậy?"},{"speaker":"salebot","text":"Dạ, trong tầm giá đó, mình gợi ý cho bạn máy xay sinh tố Philips HR2115/00 1.5L, giá 2.990.000đ, công suất 800W, phù hợp lắm ạ!"},{"speaker":"client","text":"Ôi, giá hơi cao so với dự định. Có loại nào rẻ hơn không?"},{"speaker":"salebot","text":"Dạ, mình có loại Electrolux ESB2000 500W giá 2.290.000đ, nhưng công suất thấp hơn, chỉ 500W thôi ạ."},{"speaker":"client","text":"Thế có bảo hành không? Nếu bảo hành tốt thì mình cân nhắc."},{"speaker":"salebot","text":"Dạ có ạ, bảo hành 12 tháng, giao hàng miễn phí trong 24h cho đơn trên 500k. Bạn lấy loại nào ạ?"},{"speaker":"client","text":"Thôi mình nghĩ vậy, mai mình quay lại mua vậy. Cảm ơn nhé!"}]','fail',975),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc túi xách da thật giá tốt. Bên mình có loại da bò nguyên miếng không?"},{"speaker":"salebot","text":"Dạ có ạ! Túi da bò nguyên miếng của thương hiệu Việt Nam, bảo hành 2 năm, giá niêm yết 2.500.000đ. Bạn muốn xem mẫu nào ạ?"},{"speaker":"client","text":"Mẫu màu nâu đậm ấy, nhưng giá hơi cao so với mình. Có thể giảm còn 2 triệu không?"},{"speaker":"salebot","text":"Dạ ạ, vì bạn mua sỉ lần đầu nên mình giảm còn 2.200.000đ, kèm quà tặng là dây vệ sinh da luôn ạ!"},{"speaker":"client","text":"Ok, mình lấy luôn. Giao hàng trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn để lại số điện thoại và địa chỉ, mình xác nhận đơn hàng ngay!"}]','successs',976),
('[{"speaker":"client","text":"Chào shop! Mình thấy chiếc điện thoại Samsung Galaxy S23 Ultra 512GB đang giảm giá 10% trên web. Còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ còn ạ! Máy đang khuyến mại đến hết ngày mai thôi chị ơi. Mà chị muốn màu đen hay xanh dương ạ?"},{"speaker":"client","text":"Mình thích màu đen. Giá cuối cùng bao nhiêu vậy? Có quà tặng kèm không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 28 triệu, khuyến mại 10% còn 25.2 triệu chị nhé. Đi kèm 1 tai nghe không dây trị giá 1 triệu ạ."},{"speaker":"client","text":"Ok, mình lấy luôn. Địa chỉ giao là 123 Lê Lợi, Quận 1, TP.HCM. Bao lâu nhận được hàng vậy?"},{"speaker":"salebot","text":"Dạ trong hôm nay chị nhé! Shop sẽ xác nhận đơn ngay và giao trong 2-3 giờ tới ạ."}]','successs',977),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé gái 12 tuổi. Bạn có sản phẩm nào phù hợp không?"},{"speaker":"salebot","text":"Dạ có ạ! Bộ đồ thể thao nữ của thương hiệu ABC size 12-14 tuổi đang khuyến mãi 30% trong tuần này. Bé nhà mình thích màu hồng hay xanh dương ạ?"},{"speaker":"client","text":"Màu hồng đi. Giá bao nhiêu thế?"},{"speaker":"salebot","text":"Dạ giá gốc 599k, giờ chỉ còn 419k thôi ạ. Đi kèm là dép thể thao tặng luôn nè!"},{"speaker":"client","text":"Đắt quá, giảm còn 350k được không?"},{"speaker":"salebot","text":"Dạ 380k là giá cuối rồi ạ, cộng thêm voucher 50k nếu mua trước 20h nay. Mình lấy luôn không?"},{"speaker":"client","text":"Ok, mình lấy vậy. Giao trong ngày được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn để lại địa chỉ và sđt, mình sẽ gửi mã vận chuyển ngay."}]','successs',978),
('[{"speaker":"client","text":"Chào em, mình đang tìm mua chiếc bàn chải điện Oral-B Pro 3000, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ chào anh/chị ạ! Bàn chải Oral-B Pro 3000 vẫn còn hàng, giao trong 2 giờ nếu anh/chị ở TP.HCM."},{"speaker":"client","text":"À mình thấy giá 2.990.000đ hơi đắt, có giảm giá không?"},{"speaker":"salebot","text":"Dạ em báo giá gốc từ nhà sản xuất, nhưng nếu anh/chị mua kèm kem đánh răng ưu đãi thì giảm còn 2.750.000đ ạ."},{"speaker":"client","text":"Thế không có khuyến mại gì nữa à? Mình thấy trên Shopee giá rẻ hơn."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá web chúng em đã cố định. Nếu anh/chị không hài lòng thì em xin phép kết thúc hội thoại ạ."}]','fail',979),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua chiếc điện thoại Samsung Galaxy S23 Ultra. Còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Màu đen và xanh lá đều còn. Bạn muốn mua không ạ?"},{"speaker":"client","text":"Giá bao nhiêu thế? Có khuyến mại gì không?"},{"speaker":"salebot","text":"Dạ 26 triệu ạ, đang giảm 2 triệu từ hôm nay. Còn ưu đãi trả góp 0% nữa nè!"},{"speaker":"client","text":"Ồ vậy thì được. Mình nhận hàng trong hôm nay được không?"},{"speaker":"salebot","text":"Dạ được ạ! Bạn để lại số điện thoại và địa chỉ, mình xác nhận đơn hàng ngay."}]','successs',980),
('[{"speaker":"client","text":"Chào shop! Mình muốn mua chiếc áo khoác thể thao Nike Essentials mới ra ấy. Size L có không ạ?"},{"speaker":"salebot","text":"Dạ chào bạn! Size L chúng mình còn 3 cái cuối tuần rồi ạ. Bạn muốn màu nào ạ? Đen, xanh navy hay xám?"},{"speaker":"client","text":"Mình thích màu xanh navy ấy. Giá bao nhiêu vậy?"},{"speaker":"salebot","text":"Dạ giá niêm yết 1.299.000đ, nhưng hôm nay shop đang có ưu đãi giảm 15% cho sản phẩm mới, còn 1.099.000đ thôi ạ!"},{"speaker":"client","text":"Hơi đắt nhỉ, có thể giảm thêm không? Mình thấy nơi khác giá 999k ấy."},{"speaker":"salebot","text":"Dạ em xin phép check lại ạ, nếu bạn lấy luôn hôm nay thì shop giảm tiếp 50k nữa nhé, còn 1.049.000đ thôi ạ! Còn kém 100k so với nơi khác nhưng chất lượng Nike đảm bảo lắm ạ."},{"speaker":"client","text":"Thôi được, mình lấy vậy. Ship có nhanh không? Mình cần gấp."},{"speaker":"salebot","text":"Dạ siêu tốc 2h trong nội thành ạ! Bạn để lại địa chỉ và số điện thoại để shop xác nhận đơn nhé. Cảm ơn bạn đã ủng hộ!"}]','successs',981),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé gái 10 tuổi. Bạn có size 120 không?"},{"speaker":"salebot","text":"Dạ có ạ! Bộ quần áo thể thao có đủ size từ 110-140. Màu sắc thì bé gái thích nhất là hồng và xanh dương, anh/chị chọn loại nào?"},{"speaker":"client","text":"Mình thích màu hồng nhưng giá hơi cao so với dự định. Có giảm giá không?"},{"speaker":"salebot","text":"Dạ, hôm nay có chương trình khuyến mại 10% cho đơn hàng đầu tiên. Nếu anh/chị lấy thêm giày thể thao cùng set thì được 15% luôn!"},{"speaker":"client","text":"Thế giày thể thao cho bé gái size 28 giá bao nhiêu?"},{"speaker":"salebot","text":"Dạ giày size 28 tầm 350k ạ. Nếu mua set quần áo + giày thì chỉ 900k thay vì 1tr1, tiết kiệm được 200k!"},{"speaker":"client","text":"Hơi đắt nhưng mình cân nhắc. Bạn gửi link chi tiết qua zalo 0987654321 nhé. Cảm ơn!"}]','fail',982),
('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc áo khoác này nhưng giá 1.200.000đ hơi đắt nhỉ, có giảm giá không?"},{"speaker":"salebot","text":"Dạ chào bạn, sản phẩm này đang khuyến mại 10% nếu mua trong hôm nay, còn 1.080.000đ thôi ạ!"},{"speaker":"client","text":"10% thì cũng được nhưng mình thấy bên kia bán rẻ hơn 100k, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, giá đã ưu đãi nhất rồi ạ. Nếu bạn mua kèm mũ len thì mình free ship luôn nhé!"},{"speaker":"client","text":"Thôi được, mình chỉ lấy áo thôi. Giao trong 3 ngày được chứ?"},{"speaker":"salebot","text":"Dạ không ạ, hôm nay hết ca giao rồi, giao sớm nhất là ngày mai ạ. Bạn có thể nhận vào 10h sáng không?"},{"speaker":"client","text":"Thôi không mua nữa, cảm ơn!"}]','fail',983),
('[{"speaker":"client","text":"Chào shop! Mình thấy bộ quần áo thể thao Adidas này đẹp quá, nhưng giá 1,2 triệu hơi mắc nhỉ?"},{"speaker":"salebot","text":"Dạ em hiểu ạ! Bộ này đang khuyến mại 10% nếu bạn mua kèm giày, tổng chỉ còn 1,1 triệu thôi ạ."},{"speaker":"client","text":"Mình chỉ mua quần áo thôi, không kèm giày. Có giảm nữa không?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, giá đã ưu đãi nhất rồi. Nếu bạn mua 2 sản phẩm trở lên sẽ giảm thêm 5% ạ."},{"speaker":"client","text":"Thế à... thôi mình suy nghĩ lại vậy. Cảm ơn nhé!"}]','fail',984),
('[{"speaker":"client","text":"Chào bạn, mình đang tìm mua bộ quần áo thể thao cho bé 12 tuổi. Còn size 140 không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Có đủ màu xanh, đỏ, đen. Giá niêm yết 450k/bộ, giao hàng tận nơi trong 2 ngày."},{"speaker":"client","text":"Mấy hôm nay mình thấy shop hay giảm giá, lần này có deal không?"},{"speaker":"salebot","text":"Dạ có ạ! Nếu bạn mua 2 bộ trở lên, mình giảm còn 400k/bộ thôi ạ."},{"speaker":"client","text":"Ừ, thế mình lấy 2 bộ thôi. Nhưng mình thấy quảng cáo giá 350k trên TikTok, shop có thể giảm hơn không?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, giá trên web đã là giá tốt nhất rồi ạ. Chúng mình cam kết không lừa đảo giá ạ."},{"speaker":"client","text":"Thôi được, mai mình quay lại mua vậy. Cảm ơn nhé!"}]','fail',985),
('[{"speaker":"client","text":"Chào bạn, mình thấy mẫu áo sơ mi linen này đẹp quá. Màu xanh dương có size L không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Size L còn 2 cái, nhưng màu xanh dương đã hết size XXL rồi ạ."},{"speaker":"client","text":"Thế à, tiếc quá. Mà giá bao nhiêu vậy bạn?"},{"speaker":"salebot","text":"Dạ 1.299.000đ thôi ạ, đang khuyến mại 20% nên rẻ hơn bình thường nhiều!"},{"speaker":"client","text":"Hơi đắt nhỉ, có thể giảm thêm không? Mình thấy chỗ khác bán 1 triệu thôi."},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, mức giá này đã là giá sốc rồi. Chúng em không giảm thêm được ạ."},{"speaker":"client","text":"Thôi thế thì thôi, cảm ơn bạn nhé!"}]','fail',986),
('[{"speaker":"client","text":"Chào bạn, mình muốn mua chiếc bàn chải điện Oral-B Pro 3000, có hàng không?"},{"speaker":"salebot","text":"Dạ có ạ! Chúng mình đang có chương trình khuyến mại giảm 10% cho sản phẩm này trong tuần này."},{"speaker":"client","text":"À vậy giá bao nhiêu sau khi giảm ạ?"},{"speaker":"salebot","text":"Dạ giá gốc là 2.500.000đ, sau giảm còn 2.250.000đ thôi ạ."},{"speaker":"client","text":"Hơi đắt, mình thấy bên khác giảm tới 20% luôn ấy."},{"speaker":"salebot","text":"Dạ em xin lỗi, đây là ưu đãi cao nhất rồi ạ. Nhưng nếu bạn mua kèm 1 hộp kem đánh răng Oral-B nữa thì sẽ được tặng thêm 1 bàn chải thay đầu."},{"speaker":"client","text":"Thế thôi, mình không mua nữa. Cảm ơn nhé!"}]','fail',987),
