('[{"speaker":"client","text":"Chào shop, mình muốn mua chiếc bàn chải điện Oral-B Genius X, nhưng giá hơi cao quá, có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ chào bạn, bàn chải điện Oral-B Genius X hiện đang khuyến mại 10% cho đơn hàng đầu tiên ạ. Giá chỉ còn 2.290.000đ thôi!"},{"speaker":"client","text":"10% thôi à? Mình thấy bên khác bán rẻ hơn 200k, có thể giảm thêm không?"},{"speaker":"salebot","text":"Dạ thật tiếc ạ, mức giảm này là cố định rồi. Nhưng bạn mua kèm kem đánh răng Oral-B Pro-Expert cũng được tặng thêm 1 tuýp ạ!"},{"speaker":"client","text":"Thế à, thôi vậy mình không mua nữa. Cảm ơn nhé!"}]','fail',989),
('[{"speaker":"client","text":"Chào bot, mình thấy chiếc bàn chải điện Oral-B Pro 3000 đang giảm giá 30% trên web. Mình có thể mua trả góp không?"},{"speaker":"salebot","text":"Dạ có ạ! Bạn có thể trả góp 0% từ 3-12 tháng nếu mua qua thẻ tín dụng ngân hàng đối tác. Bạn muốn chọn gói nào?"},{"speaker":"client","text":"Mình muốn trả góp 6 tháng thôi. Nhưng giá trên web là 2.490.000, sao mình thấy ở cửa hàng khác bán 2.200.000 vậy?"},{"speaker":"salebot","text":"Dạ ạ, giá trên web đã bao gồm quà tặng là 3 đầu bàn chải thay thế ạ. Còn cửa hàng có thể không có quà tặng hoặc chương trình khuyến mại tương đương ạ."},{"speaker":"client","text":"Thế à, mình thấy không hợp lý lắm. Chắc mình sẽ không mua nữa. Cảm ơn bot nhé!"}]','fail',990),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc váy len này khá đẹp nhưng giá 1 triệu 5 trông hơi đắt. Có giảm giá không vậy?"},{"speaker":"salebot","text":"Dạ em xin lỗi ạ, sản phẩm này đang ở mức giá niêm yết, nhưng nếu bạn mua 2 sản phẩm trở lên sẽ được giảm 10% ạ!"},{"speaker":"client","text":"Thế thì mình mua thêm một chiếc áo len nữa vậy. Tổng cộng bao nhiêu tiền?"},{"speaker":"salebot","text":"Dạ tổng cộng 2 triệu 7 trăm ngàn ạ, giao trong 2 ngày tại nhà bạn nhé!"},{"speaker":"client","text":"À, mình đổi ý rồi, thôi không mua nữa. Cảm ơn nhé!"}]','fail',991),
('[{"speaker":"client","text":"Chào! Mình thấy cái bàn học gỗ óc chó này đẹp quá, nhưng giá 5 triệu hơi đắt nhỉ?"},{"speaker":"salebot","text":"Dạ, giá niêm yết là 5 triệu nhưng hôm nay có ưu đãi 10% cho khách hàng mới ạ!"},{"speaker":"client","text":"10% thì còn 4.5 triệu à? Nhưng mình chỉ có 4 triệu thôi..."},{"speaker":"salebot","text":"Dạ, 4 triệu hơi thấp ạ. Bên em có bàn gỗ sồi giá 3.8 triệu, chất lượng cũng tốt lắm ạ!"},{"speaker":"client","text":"Thế 3.8 triệu thôi à? Để mình suy nghĩ lại rồi trả lời sau nhé."}]','fail',992),
('[{"speaker":"client","text":"Chào salebot, mình đang cần mua một chiếc điện thoại tầm trung cho con gái học cấp 3. Bạn có gợi ý gì không? Giá tầm 5-6 triệu thôi."},{"speaker":"salebot","text":"Dạ chào chị! Em thấy chiếc Xiaomi Redmi Note 12 4GB/128GB rất phù hợp ạ. Giá niêm yết 5,99 triệu, nhưng hôm nay có khuyến mại giảm còn 5,49 triệu kèm quà tặng là ốp lưng và dán màn hình."},{"speaker":"client","text":"5,49 triệu thì hơi chênh lệch so với dự định 5 triệu. Có thể giảm nữa không? Chị thấy giá trên Shopee rẻ hơn nhiều."},{"speaker":"salebot","text":"Dạ chị thông cảm, giá trên web em đã chiết khấu tối đa rồi ạ. Nhưng nếu chị lấy luôn bây giờ, em sẽ tặng thêm 1 bộ dây cáp sạc và gói bảo hành 2 năm miễn phí ạ!"},{"speaker":"client","text":"Thế à? Ok, chị lấy vậy. Bao lâu thì giao được?"},{"speaker":"salebot","text":"Dạ giao trong 2 giờ nếu chị ở Hà Nội ạ. Chị chọn màu xanh hay đen ạ?"},{"speaker":"client","text":"Màu xanh đi. Cảm ơn bạn nhé!"},{"speaker":"salebot","text":"Dạ không có gì ạ! Em chúc chị một ngày vui vẻ ạ."}]','successs',993),
('[{"speaker":"client","text":"Chào em, mình đang tìm mua chiếc áo khoác gió cho mùa đông này. Bên em có size L không ạ?"},{"speaker":"salebot","text":"Dạ có ạ! Size L vẫn còn hàng, em thấy mẫu này rất phù hợp với thời tiết lạnh hiện nay."},{"speaker":"client","text":"Màu xanh dương có không em? Mình thích màu này lắm."},{"speaker":"salebot","text":"Dạ có ạ! Em vừa kiểm tra kho, màu xanh dương size L vẫn còn 2 chiếc. Bạn muốn đặt không ạ?"},{"speaker":"client","text":"Giá bao nhiêu vậy em? Có khuyến mãi gì không?"},{"speaker":"salebot","text":"Dạ giá niêm yết 899k, nhưng hôm nay có chương trình giảm còn 750k thôi ạ. Nếu bạn mua kèm khẩu trang y tế tặng 1 hộp luôn."},{"speaker":"client","text":"Vậy mình lấy 1 chiếc áo thôi. Ship trong ngày được không em?"},{"speaker":"salebot","text":"Dạ được ạ! Em sẽ xử lý đơn hàng ngay bây giờ. Bạn để lại số điện thoại và địa chỉ để em xác nhận đơn nhé."}]','successs',994),
