('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn chải điện Oral-B mới về có giảm giá không vậy? Mình muốn mua cho mẹ dùng."},{"speaker":"salebot","text":"Dạ chào chị ạ! Hiện tại Oral-B Pro 3000 đang khuyến mại 30% cho chị nè, chỉ còn 1.299.000đ thôi ạ."},{"speaker":"client","text":"Ôi vậy đắt quá, mình thấy nơi khác bán 900k thôi mà?"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, giá gốc của em là 1.850.000đ, khuyến mại 30% nên mới 1.299.000đ thôi chị. Mà chị mua kèm hộp tặng 2 đầu bàn chải nữa nè!"},{"speaker":"client","text":"Thôi không rồi, cảm ơn bạn nhé. Mình thấy nơi khác rẻ hơn nhiều."}]','fail',997),
('[{"speaker":"client","text":"Chào bạn, mình thấy chiếc bàn chải điện Oral-B Pro 3000 đang giảm giá 30% trên web, còn hàng không vậy?"},{"speaker":"salebot","text":"Dạ có ạ! Giá gốc 2.500.000đ, giờ chỉ còn 1.750.000đ thôi. Bạn muốn đặt không?"},{"speaker":"client","text":"Mình thấy hơi đắt, có thể giảm thêm không? Mình thấy trên Shopee giá rẻ hơn 200k."},{"speaker":"salebot","text":"Dạ không ạ, đây là giá sàn từ nhà sản xuất. Nếu bạn mua kèm 2 bộ lông bàn chải thì mình có thể tặng 1 hộp vệ sinh miễn phí."},{"speaker":"client","text":"Thế à... thôi mình không mua nữa, cảm ơn!"}]','fail',998),
('[{"speaker":"client","text":"Chào shop! Mình thấy cái đồng hồ thông minh Xiaomi Smart Band 8 Pro trên web, mình muốn mua nhưng chưa biết có giao hàng tận nơi không?"},{"speaker":"salebot","text":"Dạ chào chị ạ! Chúng em giao hàng toàn quốc luôn chị nhé. Chị muốn giao vào ngày nào ạ?"},{"speaker":"client","text":"Giao trong tuần này được không? Mình cần gấp lắm!"},{"speaker":"salebot","text":"Được chị ơi! Đơn chị giao vào thứ 4 tuần này, phí ship 25k chị nhé. Còn màu chị muốn màu đen hay xanh dương ạ?"},{"speaker":"client","text":"Mình chọn màu đen thôi. Còn giá vậy có giảm được không? Mình thấy bên kia bán rẻ hơn 50k!"},{"speaker":"salebot","text":"Dạ chị thông cảm ạ, mình đã niêm yết giá cạnh tranh rồi. Nhưng nếu chị mua kèm sạc không dây 100k thì giảm 20k cho chị nhé!"},{"speaker":"client","text":"Ok, vậy mình lấy luôn cái sạc luôn. Tổng tiền bao nhiêu?"},{"speaker":"salebot","text":"Dạ tổng cộng 2.180.000đ chị nhé! Em gửi link thanh toán qua Zalo cho chị nha. Cảm ơn chị đã ủng hộ shop!"}]','successs',999);
